local P = LoreForeverPacks.Begin("LoreForever_Voice_Default_MoreQuests1")
P.transportVersion = 1
P.transport = {}
P.transport["quest:1001"] = {
  hash = "fa72cd",
  fullHash = "fa72cd",
  text = "Buzzbox 411. Along Darkshore’s coast, Buzzbox 411 needs thresher eyes to return to service. This Alliance errand comes through an eccentric, intoxicated gnome inventor, Wizbang Cranktoggle, who works through a mechanical relay network. After you help repair Buzzbox 827 farther south, gnome inventor Wizbang Cranktoggle’s voice crackles through the mechanical transmitter again. From somewhere safely out of sight, he directs adventurers north along Darkshore’s mist-laden beach to a damaged terminal called Buzzbox 411. His transmissions break with hiccups and muttered praise for crawler wine. He says local aquatic predators carry what his coastal apparatus needs to keep working. To restore Buzzbox 411, thresher eyes must be fed into its waiting hatch. Darkshore threshers, aggressive marine beasts, prowl the shallows off Auberdine, and their eyes have the properties Wizbang says are needed to recalibrate the device. The eyes jolt the apparatus back into operation, and the line opens for another assignment, delivered in an even slurrier voice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1001-58ab59cb4d9cefdae8bc/1-0000.mp3", duration = 64.0261224, start = 0},
  },
}
P.transport["quest:1002"] = {
  hash = "d7ffa2",
  fullHash = "d7ffa2",
  text = "Buzzbox 323. Wizbang Cranktoggle’s field research reaches Buzzbox 323, the third stop along Darkshore’s coast. You gather six Moonstalker fangs and place them in the machine north of Auberdine. Wizbang Cranktoggle’s voice crackles through the speaker after you operate Buzzbox 411 farther south. Heavy drinking muddles his directions, but he points you north of Auberdine, to Buzzbox 323 near a road bridge. His research calls for six Moonstalker fangs from the fierce hunters roaming Darkshore’s forests. Buzzbox 323 chatters with static and faint muttering before you begin. Place the requested fangs in its intake hopper, and the machine rattles violently, grinding the teeth into dust. Wizbang’s boozy voice returns through the transceiver to celebrate your delivery and point you toward the next machine in his scattered network.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1002-ca81b0a70fba9401ee70/1-0000.mp3", duration = 50.5730612, start = 0},
  },
}
P.transport["quest:1003"] = {
  hash = "1c9240",
  fullHash = "1c9240",
  text = "Buzzbox 525. Along Darkshore’s coast, Buzzbox 525 waits for the last of Wizbang Cranktoggle’s strange requests. The gnome’s scattered machines call for animal remnants and ever stranger materials. After Buzzbox 323 is serviced, its rattling speakers carry Wizbang Cranktoggle’s garbled instructions. His words slur through drunken chuckles and rambling directions, sending his helpers far south along Darkshore’s main road. He asks them to hunt grizzled thistle bears and place four thick scalps in Buzzbox 525’s compartment. The machine is concealed behind a fence in the brush beside the road.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1003-db2c57b4764866ee218c/1-0000.mp3", duration = 36.0228571, start = 0},
  },
}
P.transport["quest:102"] = {
  hash = "707b17",
  fullHash = "707b17",
  text = "Patrolling Westfall. Gnoll packs roam Westfall's grasslands, threatening the people who still live there. Captain Danuvin calls on volunteers from Sentinel Hill to hunt them, fearing they work with the thieves in the Deadmines. Sentinel Hill is Westfall's main defense, held by local volunteers rather than royal troops. With Stormwind sending no soldiers to protect the outer farmlands, the people formed the People's Militia. Captain Danuvin, once a farmer in Westfall, leads them and refuses to abandon his homeland. The militia depends on travelers who pass through to help hold its perimeter against the dangers gathering across the plains. Gnolls now threaten the refugees and squatters struggling to survive in Westfall. Danuvin's scouts believe the packs are working with bandits based in the Deadmines. He sends hunters to collect gnoll paws, hoping to curb the packs' growing patrols and break any cooperation between the beasts and the outlaws.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_102-8dfed6865aba2c2a9d85/1-0000.mp3", duration = 54.1779592, start = 0},
  },
}
P.transport["quest:103"] = {
  hash = "f8cb93",
  fullHash = "f8cb93",
  text = "Keeper of the Flame. At Westfall Lighthouse, Captain Grayson keeps watch over the coast. The spectral sailor seeks oil to keep the beacon burning after murlocs killed the living keepers, so ships can pass the reefs safely. Westfall Lighthouse stands on a rocky islet off the zone’s southwest shore, where its light once guided sailors through the Great Sea’s shallow waters. That duty ended when Old Murk-Eye led a murloc attack and killed the keeper and his family. Captain Grayson, a sailor who died in the waters by these rocks, now watches over the tower as a ghost. Death left him unable to stop the slaughter, but he will not let the lighthouse go dark. No living keeper remains to tend the flame, so Captain Grayson needs an unusual fuel. The rogue Harvest Watchers roaming Westfall’s abandoned farmlands carry flasks of machinery oil inside their rusted bodies. Grayson sends you ashore to recover the oil from these broken constructs. With it, the beacon can keep burning and guide other captains past the reefs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_103-499d1f247a2a5631d0e7/1-0000.mp3", duration = 63.5036735, start = 0},
  },
}
P.transport["quest:1061"] = {
  hash = "688b0d",
  fullHash = "688b0d",
  text = "The Spirits of Stonetalon. Unrest stirs among the spirits of Stonetalon, and Zor Lonetree sends Horde champions west to learn why. From Orgrimmar, they travel past the Crossroads and report directly to Seereth Stonebreak near Greatwood Vale. In Grommash Hold, Zor Lonetree listens to the natural world and feels deep distress from the Stonetalon Mountains. The elemental spirits of its rocky peaks are furious as logging tears into their forests. Horde shamans hear that unrest and fear the devastation in the western highlands will upset Kalimdor's spiritual balance. The Venture Company, an unscrupulous goblin syndicate, is cutting timber in Greatwood Vale. Its commercial crews use aggressive machinery, saws, and muscle to butcher the ancient woodland instead of harvesting sustainably. The Horde sent Seereth Stonebreak, a young shaman, to watch the forest from the frontier and rally defenders against the ravagers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1061-08ca1a3e03859a09fa9c/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["quest:109"] = {
  hash = "1019cf",
  fullHash = "1019cf",
  text = "Report to Gryan Stoutmantle. Westfall needs fighters, and Report to Gryan Stoutmantle sends you to answer the call. The crown leaves the outer farmlands to fend for themselves, so local defenders gather under Gryan Stoutmantle at Sentinel Hill. Westfall calls for skilled fighters from across the river. Brigands, gnolls, and hostile harvest golems are driving the farmlands into chaos. With no royal battalions answering, local volunteers must defend the realm. The road leads you to Gryan Stoutmantle in the stone tower atop Sentinel Hill. He leads the People's Militia, a force of farmers, retired veterans, and mercenaries formed in response to royal inaction. The farmlands face a bitter guerrilla war against lawlessness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_109-77624d5bf074e392f337/1-0000.mp3", duration = 40.9861224, start = 0},
  },
}
P.transport["quest:1097"] = {
  hash = "5fa8fe",
  fullHash = "5fa8fe",
  text = "Elmore's Task. Smith Argus sends you from Goldshire to Stormwind to help Grimand Elmore. The dwarven weaponsmith needs help with a delivery bound for his kin in Khaz Modan, and Argus trusts you to make the journey. In Goldshire, blacksmith Smith Argus watches for travelers he can trust with work beyond clearing wolves and kobolds. Grimand Elmore, a skilled dwarven weaponsmith in Stormwind, has asked for help with a delivery to his kin in Khaz Modan. Argus sees you as fit for the journey and sends you toward the city gates to answer Elmore's call. Stormwind and Ironforge depend on open trade and goodwill to keep both realms supplied and united. Argus says Elwynn Forest needs defenders, but honoring promises to the dwarves matters too. In northeastern Stormwind, the Dwarven District leads you to Elmore's shop, where a journey beyond the forest begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1097-55ef903ba7576c3812f7/1-0000.mp3", duration = 48.0914286, start = 0},
  },
}
P.transport["quest:1099"] = {
  hash = "1dc458",
  fullHash = "1dc458",
  text = "Goblins Win!. In Thousand Needles, a goblin race ticket pays off when the goblins come out ahead. A prize box comes back to whoever held the winning stub. The goblin race ticket is the stub that counts when the goblins win. Hold on to it, and a goblin prize box is yours once the result is in. The gnome ticket has a result of its own, for the other side of the race.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1099-b72035ece03a3225c74b/1-0000.mp3", duration = 22.0473469, start = 0},
  },
}
P.transport["quest:111"] = {
  hash = "f99a09",
  fullHash = "f99a09",
  text = "Speak with Gramma. Tommy Joe Stonefield seeks Gramma Stonefield's help to meet Maybell Maclure. Their families' bitter feud keeps the young lovers apart, and Tommy Joe hopes his grandmother can find a way for them to see each other. Tommy Joe Stonefield and Maybell Maclure keep their romance secret from their feuding families. The Stonefields and Maclures have fought over their farms for years, making their neighboring homesteads hostile ground. Tommy Joe wants to meet Maybell without provoking violence between their kin, so he turns to his grandmother for help. Gramma Stonefield stays indoors, but she knows the feud well. She understands that the families cannot truly unite while their bad blood remains. Still, she will not let their grudge crush young love. Rather than urge caution, Gramma begins looking for small chances to bring Tommy Joe and Maybell together.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_111-25beafb226df5a94454b/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["quest:112"] = {
  hash = "ad4757",
  fullHash = "ad4757",
  text = "Collecting Kelp. In Goldshire, Maybell Maclure seeks a way to visit Tommy Joe Stonefield unseen. William Pestle needs rare crystal kelp to brew an invisibility liquor for her. The feud between the Stonefield and Maclure families keeps Maybell Maclure and Tommy Joe Stonefield from meeting openly. Maybell wants to see her beloved without provoking an armed clash between their kin, so she seeks a way to cross the valley unseen. William Pestle, an herbalist and apothecary at the Lion's Pride Inn in Goldshire, plans to brew an invisibility liquor. The rare ingredients he needs are not in the inn's cupboards. Crystal kelp is the catalyst William Pestle needs for his brew. The fronds usually grow far out in saltwater oceans, but tribal murlocs have carried stashes inland to their crude camps along Crystal Lake, just east of Goldshire. Their peculiar instincts have led them to haul the marine plants to the freshwater shore. You need to recover enough fronds from the murlocs before returning to Goldshire with them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_112-e11bfb660e72d19fda6a/1-0000.mp3", duration = 59.0106122, start = 0},
  },
}
P.transport["quest:114"] = {
  hash = "961776",
  fullHash = "961776",
  text = "The Escape. Maybell Maclure waits for a way to slip away from her family and meet Tommy Joe Stonefield. You bring her William Pestle's Invisibility Liquor, brewed from crystal kelp gathered across the region. The Maclures and Stonefields have feuded for generations, leaving no room for courtship. Gramma Stonefield turns to William Pestle, an alchemist in the Lion's Pride Inn in Goldshire. With crystal kelp from nearby lakes, Pestle brews Invisibility Liquor strong enough to hide Maybell's escape from the Maclure homestead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_114-ae9354c73d543f3aefed/1-0000.mp3", duration = 30.6416327, start = 0},
  },
}
P.transport["quest:1141"] = {
  hash = "5fe4a7",
  fullHash = "5fe4a7",
  text = "The Family and the Fishing Pole. Gubber Blump and his heirloom Fishing Pole await a catch on Auberdine's docks. Hostile murlocs keep the town's small fishing boats ashore, so Gubber seeks help catching native Darkshore grouper from the coast. Gubber Blump takes pride in a family known for its skill with a fishing line. Night elves make up most of Auberdine, though dwarves and gnomes have settled around its docks and port. Gubber spends his days gazing over the Veiled Sea instead of digging into stone, hoping to bring in the local catch. Darkshore grouper thrive along the coast and make versatile food, but they can put up a lively fight on the line. Local fishermen usually row small boats into deeper waters to catch them. Now aggressive murlocs prowl the coast, and small boats no longer go out. Gubber fears the creatures are eating the local fish, so he asks travelers to fish from shore. Gubber gives a Blump Family Fishing Pole to anyone who brings him a hearty catch. He believes anyone who can land a batch of feisty groupers is worthy of his family's legendary anglers, including his cousin Graun Blump. For Gubber, handing over a family rod is the highest mark of respect.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1141-0c7703e9fb1a1ad84599/1-0000.mp3", duration = 67.4220408, start = 0},
  },
}
P.transport["quest:117"] = {
  hash = "c49c85",
  fullHash = "c49c85",
  text = "Thunderbrew. In Westfall, Grimbooze Thunderbrew is gathering what he needs for his next batch. Fresh hops keep his ale from turning thick as stew, and he shares kegs with those who help. Grimbooze Thunderbrew keeps his family's brewing tradition alive far from Dun Morogh. Even across Westfall's turbulent plains, he insists on the right ingredients: without proper hops, his current brew may turn into thick stew instead of refreshing ale. Grimbooze celebrates hops, barley, yeast, and malt in cheerful rhymes. With fresh hops, he finishes the fermentation on the spot. Those who supply him receive whole kegs of Thunderbrew Lager, a brew known for its forceful taste.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_117-26bf20fa19388eedbb2d/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["quest:1174"] = {
  hash = "93feba",
  fullHash = "93feba",
  text = "Gnomes Win!. In Thousand Needles, a gnome race ticket pays off when the gnomes come out ahead. A prize box comes back to whoever held the winning stub. The gnome race ticket is the stub that counts when the gnomes win. Hold on to it, and a gnome prize box is yours once the result is in. The goblin ticket has a result of its own, for the other side of the race.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1174-f595cc2b4b48a56bb1c1/1-0000.mp3", duration = 20.3493878, start = 0},
  },
}
P.transport["quest:119"] = {
  hash = "294212",
  fullHash = "294212",
  text = "Return to Verner. You carry fifty freshly forged horseshoes from Goldshire back to Lakeshire. Smith Argus has finished the order, and Verner Osgood is waiting across the border in Redridge. Smith Argus has forged fifty horseshoes for Lakeshire, and you carry them east from Goldshire. Redridge faces supply shortages and gnoll attacks. The iron shoes help keep horses and draft animals working on its rugged mountain roads. Verner Osgood is relieved when the horseshoes arrive, but Smith Argus has attached a bill to the crate. Verner is annoyed that the Goldshire smith expects payment. Redridge faces pressing dangers, leaving little time to argue over the charge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_119-b858fe533461a94341f2/1-0000.mp3", duration = 38.8179592, start = 0},
  },
}
P.transport["quest:12"] = {
  hash = "12210d",
  fullHash = "12210d",
  text = "The People's Militia. At Sentinel Hill, Gryan Stoutmantle tests your mettle for the People's Militia. Stormwind's throne is distracted, and its army is absent, so local volunteers defend Westfall from the Defias Brotherhood. You begin by driving outlaws from the northern fields and mines. Westfall once fed Stormwind, but outlaws, vagrants, and thieves now overrun the region. With the capital sending no royal soldiers to patrol the countryside, Gryan Stoutmantle organized the People's Militia at Sentinel Hill as a local defense force. He calls for decisive action to reclaim Westfall. Anyone seeking the militia's badge must prove they can fight and will protect innocent settlers. Before Stoutmantle trusts new recruits with deeper operations, he sends them against Defias forces near northern homesteads. Defias Trappers and Smugglers work openly near Jangolode Mine, Molsen Farm, and Furlbrow's Pumpkin Patch, pillaging stores and ambushing travelers. You can disrupt their foraging by driving them out, while showing Stoutmantle's scouts that you have the grit for a long fight against crime.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_12-62b462afbb1428216035/1-0000.mp3", duration = 64.3134694, start = 0},
  },
}
P.transport["quest:120"] = {
  hash = "452e94",
  fullHash = "452e94",
  text = "Messenger to Stormwind. Magistrate Solomon of Lakeshire is desperate for military aid as gnolls and Blackrock orcs encircle the town. Unable to spare garrison troops, he dispatches an adventurer to carry 'The State of Lakeshire' directly to General Marcus Jonathan in Stormwind City. Lakeshire stands on the brink of collapse. Gnoll packs contest every road, Blackrock orcs raid from the north, and the local guardsmen are stretched beyond their limits. Magistrate Solomon cannot afford to send fighting men on a days-long ride to the capital, leaving an independent traveler to carry his official plea for regular troops to the city gates. Delivering the magistrate's report brings an adventurer face-to-face with General Marcus Jonathan, commander of Stormwind's defense. While Jonathan respects Solomon's leadership and acknowledges the urgency, army protocol prevents him from mobilizing without a royal directive. The defense of Redridge must await formal consultation with the young King Anduin and the regency council.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_120-8ff3a8fc17eb20c9a4b1/1-0000.mp3", duration = 57.4432653, start = 0},
  },
}
P.transport["quest:121"] = {
  hash = "7757ec",
  fullHash = "7757ec",
  text = "Messenger to Stormwind. You carry General Marcus Jonathan's reply from Stormwind to Lakeshire, where Blackrock orcs and gnolls threaten the town. The capital offers no troops, leaving the settlement to face danger while Stormwind's leaders delay. You brought Magistrate Solomon's plea for reinforcements to General Marcus Jonathan in Stormwind. Now you carry his preliminary reply back to Redridge while he waits for approval from the throne. Without royal authorization, the General cannot commit the army. Lakeshire's citizens remain without city guards, and each day brings the settlement closer to falling under the Blackrock clan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_121-8f0343a5c53cc3e6946d/1-0000.mp3", duration = 33.7763265, start = 0},
  },
}
P.transport["quest:123"] = {
  hash = "848150",
  fullHash = "848150",
  text = "The Collector. An intercepted dispatch from gnoll raiders in Elwynn Forest lays out when gold shipments leave the abandoned mines. It is addressed to a figure called 'The Collector' and points to an organized operation near Stormwind's garrison. Riverpaw gnoll packs in western Elwynn Forest carry more than furs and crude weapons. Among them, a parchment called the Gold Pickup Schedule lays out dates and times for gold taken from local mines. The intercepted note directs each shipment to an overseer identified only as 'The Collector.' Marshal Dughan hears the news at the Lion's Pride Inn and learns that gold is still being mined and moved. Official mines across Elwynn have been closed for months because of gnoll attacks, kobold infestations, and roaming bandits. Gnolls carrying shipping schedules point to an organized criminal network stealing the kingdom's wealth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_123-45d2d1b132af32872925/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["quest:13"] = {
  hash = "bb8d92",
  fullHash = "bb8d92",
  text = "The People's Militia. Across Westfall, The People's Militia faces a growing Defias threat. Gryan Stoutmantle's volunteers now confront thieves who have moved beyond highway robbery to ransack Moonbrook and the Gold Coast Quarry, and the Militia calls for harsher retaliation. Defias attacks have grown from petty banditry on the roads into a wider threat. Defias Looters and Pillagers, who hurl fire, have overrun Westfall's economic centers. They occupy Moonbrook, strip the Alexston Farmstead, and have taken control of the Gold Coast Quarry. Gryan Stoutmantle sees the danger: if the brigands hold these places, Westfall may become impossible to reclaim without a formal royal army. Stormwind has sent Gryan Stoutmantle no soldiers or supplies, so he calls on the Holy Light and the resolve of Westfall's remaining farmers. The Militia's war of attrition depends on volunteers carrying the fight into Defias strongholds. Driving out the looters will deny the Brotherhood resources and show fearful residents that defenders still fight for Westfall's peace and prosperity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_13-21790108735d1757d234/1-0000.mp3", duration = 62.0669388, start = 0},
  },
}
P.transport["quest:132"] = {
  hash = "418760",
  fullHash = "418760",
  text = "The Defias Brotherhood. In Westfall, The Defias Brotherhood is building a network beyond banditry. Wiley the Black sends word of its ties to gnolls, kobolds, and goblins. Gryan Stoutmantle needs this intelligence to measure the full reach of the conspiracy choking Westfall. Wiley the Black says telling what he knows about the Defias could cost him his life. Along the edges of Redridge and Westfall, he has caught wind of an operation far greater than highway robbery. His sealed note describes how the Brotherhood has coordinated groups that are usually hostile to one another across the countryside. Wiley warns that the Defias has drawn an alarming network around itself. The red-masked outlaws have enlisted gnoll packs, kobold diggers, and goblin engineers instead of working alone. Together, their brutal muscle, burrowing labor, and mechanical cunning point to an enterprise beyond what the People's Militia first expected. Gryan Stoutmantle has little love for Wiley and openly laments that he did not leave the rogue to rot when he had the chance. Yet Westfall cannot afford pride. With Stormwind ignoring pleas for military aid, the People's Militia must take useful intelligence wherever it can find it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_132-0b9f5ef7e8382a5ecb4a/1-0000.mp3", duration = 68.8065306, start = 0},
  },
}
P.transport["quest:1338"] = {
  hash = "751157",
  fullHash = "751157",
  text = "Stormpike's Order. In Loch Modan, Mountaineer Stormpike is arranging a shield from Furen Longbeard. The armorsmith works far south in Stormwind City, so Stormpike asks a traveler to carry his order there. Mountaineer Stormpike wants a new shield, and he trusts only Furen Longbeard to forge it. The mountaineer is willing to pay well to place the commission in the smith’s hands, though Loch Modan and Stormwind City lie far apart. Stormpike wonders why Furen works so far from Ironforge and the Great Forge, where many dwarves make their home. He suspects Stormwind’s humans pay the smith a king’s ransom. When the order reaches Furen at his anvil, the armorsmith takes pride in hearing from the prestigious Stormpike clan and eagerly prepares to forge the shield.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1338-5a819d1fd0d1d400d041/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["quest:135"] = {
  hash = "26f7a3",
  fullHash = "26f7a3",
  text = "The Defias Brotherhood. In Westfall, the Defias Brotherhood's troubles reach Stormwind. Gryan Stoutmantle sends you to deliver Wiley's Note to Master Mathias Shaw, suspecting a link between the Defias and the old Stonemasons Guild. A mention of the Stonemasons in Wiley's communications catches Gryan Stoutmantle's attention. The builders rebuilt Stormwind City after the First War, but the guild has long been thought scattered or dissolved. If the Defias Brotherhood shares ties with them, Westfall's rural insurgency is more than a disorganized band of outlaws. From Sentinel Hill, Gryan Stoutmantle cannot confirm his suspicions. He sends you to Master Mathias Shaw, head of Stormwind's covert intelligence wing, SI:7. Shaw works from the Barracks in Old Town, gathering whispers and secrets from across the realm. He may be able to untangle the Defias Brotherhood's origins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_135-d50fe180a65231c77c90/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["quest:1358"] = {
  hash = "f4df3c",
  fullHash = "f4df3c",
  text = "Sample for Helbrim. At the Crossroads, Apothecary Helbrim awaits a wolf heart from across the sea. Apothecary Zinge sends it from the Undercity to support the Forsaken's research in central Kalimdor. Apothecary Zinge sends a Wolf Heart Sample from the Undercity to Apothecary Helbrim in the Barrens. The Royal Apothecary Society's experiments reach beyond the ruins of Lordaeron. After Apothecary Renferrel in Silverpine sent tainted organs, Zinge sought to extend their research across the world. Now a courier carries the sample overseas to Helbrim, an alchemist stationed in the Barrens' dry savanna. At the Crossroads, Apothecary Helbrim studies how Kalimdor's native beasts react to compounds from the Plaguelands. The wolf heart could show how those toxins affect local creatures. Helbrim believes that dissecting and testing it alongside them will help the Forsaken master poisons and unnatural afflictions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1358-16cad0b6bc015df4c284/1-0000.mp3", duration = 52.7412245, start = 0},
  },
}
P.transport["quest:136"] = {
  hash = "9aa9b6",
  fullHash = "9aa9b6",
  text = "Captain Sanders' Hidden Treasure. A battered parchment map sets Captain Sanders' Hidden Treasure in motion along Westfall's coast. The hunt begins with a search of the shoreline for the late captain's personal footlocker, then leads toward his hidden plunder across the region. Shipwrecks and the restless spirits of drowned sailors mark Westfall's western coast. Captain Sanders, an old seafarer, met a watery grave there. He left cryptic instructions so his hard-won fortune would not be lost to the Great Sea or taken by scavengers. A determined adventurer can retrace the trail he left behind.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_136-ef0c2cc6879fbb13f12d/1-0000.mp3", duration = 32.0783673, start = 0},
  },
}
P.transport["quest:138"] = {
  hash = "7d3e7b",
  fullHash = "7d3e7b",
  text = "Captain Sanders' Hidden Treasure. In Westfall, Captain Sanders' Hidden Treasure sends you inland after a clue found by the shore. The trail leads east from the coast toward a barrel near ruined stonework. Captain Sanders sends you inland after the first cipher is solved. The clue points away from the shore and up the rocky bluffs, toward Westfall's main roads. An old chimney among roadside ruins marks the next stop. A discarded barrel nearby hides another message, and the ruined farmstead gives Sanders a landmark for the trail.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_138-6a4293e0b6056ed0bb2b/1-0000.mp3", duration = 28.3689796, start = 0},
  },
}
P.transport["quest:139"] = {
  hash = "7d403c",
  fullHash = "7d403c",
  text = "Captain Sanders' Hidden Treasure. A broken barrel on Westfall's western shore holds Captain Sanders' Hidden Treasure clue. It sends you north toward an old jug beside a coastal windmill, another step along the late pirate's trail to his hidden riches. Captain Sanders scattered his directions along Westfall's western shore. Each clue leads only to the next container, never straight to the prize. You have to follow the trail from one barrel, chest, or jug to another across the bluffs to reach his plunder. From the broken barrel, the parchment points due north toward the sea cliffs. Beside an isolated windmill on the bluffs, an abandoned jug holds the next clue. Murlocs and Defias scavengers roam coastal Westfall, so the way north carries danger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_139-4618cef2651a931bd6f4/1-0000.mp3", duration = 41.0644898, start = 0},
  },
}
P.transport["quest:140"] = {
  hash = "234bb1",
  fullHash = "234bb1",
  text = "Captain Sanders' Hidden Treasure. A whiskey-soaked clue sends Captain Sanders' Hidden Treasure hunt west from Westfall's shore. The trail leads out across the Great Sea, away from the mainland's troubles, to a remote islet. Captain Sanders scattered clues along Westfall's coast for any adventurer bold enough to follow them. The last parchment came from the dregs of his favorite whiskey jug and gives the final bearing. The captain's words are clear: head west to the water's edge, then swim out into the waves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_140-57f4534cc2db8a118266/1-0000.mp3", duration = 26.9844898, start = 0},
  },
}
P.transport["quest:141"] = {
  hash = "78982a",
  fullHash = "78982a",
  text = "The Defias Brotherhood. Mathias Shaw sends a confidential report from Stormwind to Gryan Stoutmantle at Sentinel Hill. Shaw has investigated the former Stonemasons Guild to help Stoutmantle uncover the origins of the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_141-5519c3be7c3683acfa02/1-0000.mp3", duration = 12.042449, start = 0},
  },
}
P.transport["quest:143"] = {
  hash = "4ec9b4",
  fullHash = "4ec9b4",
  text = "Messenger to Westfall. Messenger to Westfall is an Alliance errand carrying an urgent plea from Magistrate Solomon in Redridge across Elwynn to Westfall. Facing total abandonment by the Stormwind military, Lakeshire's leadership seeks mutual aid from Gryan Stoutmantle's newly formed People's Militia. Magistrate Solomon finds Lakeshire in a desperate situation. The Redridge Mountains are besieged by Blackrock orcs and gnolls, yet the Stormwind Army has failed to arrive in force. Recognizing that Lakeshire cannot survive on town guards and irregulars alone, Solomon writes a formal plea for assistance. With regular royal reserves nowhere in sight, he turns his eyes west, having heard word of a citizen defense group forming beyond Elwynn Forest. The intended recipient of the dispatch is Gryan Stoutmantle, a veteran commander who has begun rallying volunteer fighters under the banner of the People's Militia. By sending a courier directly across the kingdom, Solomon hopes that Westfall's organized volunteers might spare troops to reinforce Lakeshire's borders until the Crown's armies finally mobilize. However, as messengers soon discover, Westfall is mired in its own catastrophic struggles against the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_143-773db9da96fee9da3cea/1-0000.mp3", duration = 70.7918367, start = 0},
  },
}
P.transport["quest:144"] = {
  hash = "77f9f3",
  fullHash = "77f9f3",
  text = "Messenger to Westfall. A letter from Westfall brings Magistrate Solomon a hard answer in Lakeshire. He asked Gryan Stoutmantle for soldiers to defend Redridge, but Westfall has been left to face its own troubles. Magistrate Solomon faces growing troubles in the Redridge Mountains without Stormwind's royal garrison. He looks to the southern frontier for help and writes to Gryan Stoutmantle, commander of the People's Militia in Westfall. Solomon hopes the volunteers at Sentinel Hill can spare fighters to strengthen Lakeshire's defenses. He does not know how hard pressed the western plains are. Gryan Stoutmantle refuses, though the answer weighs heavily on him. Westfall is fighting the Defias Brotherhood and marauding gnolls because the House of Nobles and the crown have abandoned the kingdom's breadbasket. The People's Militia formed so the people could survive. Its ranks lose good men each day, and Stoutmantle cannot spare a single fighter for Redridge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_144-b87c0d5ba024503551af/1-0000.mp3", duration = 53.995102, start = 0},
  },
}
P.transport["quest:1462"] = {
  hash = "4692e1",
  fullHash = "4692e1",
  text = "Earth Sapta. Earth Sapta is a replenishment ritual offered by Seer Ravenfeather in Camp Narache. Young shaman undertaking their initiation to commune with the spirits of the stone require this draught to open their inner sight. Should a novice lose or spill their prepared brew before finishing their rite, the seer prepares another to ensure their trial may continue. The path of the shaman begins with attuning the mortal senses to forces beyond physical sight. To perceive the elemental spirits of the land, an initiate must ingest a potent ritual brew known as a sapta. Infused with natural essences bound to the element of stone and soil, the Earth Sapta lifts the veil between the physical realm and the spiritual plane, allowing a novice to commune directly with the earth elementals of Mulgore. The spiritual arts demand discipline, but seasoned seers recognize that young initiates often falter or misplace sacred reagents while braving the wilds. Seer Ravenfeather keeps a steady vigil at Camp Narache, ensuring that any pupil who loses their brew before their communion at the stone monument can renew their preparation. With quiet patience, she provides another vessel so the novice may face the spirits unbroken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1462-37dfdf23a1bc7666c68c/1-0000.mp3", duration = 70.0081633, start = 0},
  },
}
P.transport["quest:1463"] = {
  hash = "c610c2",
  fullHash = "c610c2",
  text = "Earth Sapta. In the Valley of Trials, an initiate who loses the Earth Sapta can ask Canaga Earthcaller for another. The replacement gives the young shaman a chance to commune with the spirits of the land, along with a warning to guard sacred draughts carefully. A misplaced Earth Sapta can interrupt an initiate's communion with the spirits of stone and soil. Prepared through specific rituals, the elemental brew thins the veil between the physical realm and the spirits. When an initiate loses or spills it while traveling through Durotar, Canaga Earthcaller prepares another in good faith, but warns the novice to guard sacred gifts with greater care. Canaga Earthcaller watches over fledgling shamans emerging from the Den in the Valley of Trials. He understands that young orcs and trolls are prone to the chaos of early trials, but stresses that elemental spirits do not take kindly to negligence. Accepting a second sapta offers a small lesson in humility: power granted by the earth must be guarded and respected.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1463-469d1f30213e49a28c4e/1-0000.mp3", duration = 57.2604082, start = 0},
  },
}
P.transport["quest:147"] = {
  hash = "3a1a50",
  fullHash = "3a1a50",
  text = "Manhunt. Marshal Dughan sends you after a Defias bagman called the Collector in Elwynn Forest. The Collector works from the overrun Brackwell Pumpkin Patch and sends stolen gold from the forest's mines into the Brotherhood's coffers. Marshal Dughan sends you to Brackwell Pumpkin Patch after Elwynn's gnolls are found carrying a schedule for gold pickups. Defias bandits and gnolls have taken over the once quiet homestead. The Collector hides among its overgrown vines, skimming ore from the kingdom's mines and arranging shipments for the growing rebellion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_147-4159686ec5b338a463e1/1-0000.mp3", duration = 30.4065306, start = 0},
  },
}
P.transport["quest:1470"] = {
  hash = "b803c0",
  fullHash = "b803c0",
  text = "Piercing the Veil. Piercing the Veil is an introductory warlock trial given by Venya Marthand in Deathknell. It tests a freshly risen warlock's resolve by directing them to collect skulls from nearby mindless skeletons. Completing the task earns the novice the knowledge required to summon and bind an imp minion. Newly awakened Forsaken warlocks begin their journey in Deathknell under the instruction of Venya Marthand. She teaches that true strength lies not in raw brute force, but in knowledge and the precise mastery of chaotic powers. To prove they possess the focus and capability required to pierce the veil between worlds and subjugate nether beings, novices are dispatched to harvest the skulls of restless Rattlecage Skeletons roaming near Deathknell's abandoned smithy. Once the skeletal remains are secured, Venya considers the initiate ready to step beyond simple dark spells. The recovered materials serve as a rite of passage, demonstrating that the novice can overcome mindless undead and withstand the bleak realities of their craft. In return, Venya imparts the rituals needed to bend an imp to the summoner's command, warning that despite the demon's diminutive stature, its cunning and fire will make it a dangerous ally.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1470-f2a8ad3675ec22b31b00/1-0000.mp3", duration = 70.2432653, start = 0},
  },
}
P.transport["quest:1471"] = {
  hash = "3349c0",
  fullHash = "3349c0",
  text = "The Binding. The Binding is the culminating rite for Forsaken warlocks seeking to command a voidwalker. In the Magic Quarter of the Undercity, Carendin Halgar requires initiates to summon, conquer, and permanently subjugate a creature of the Void. Unlike minor imps, which are easily coerced into pacts with dark magic, creatures of the Void despise reality and possess formidable physical might. To earn the right to summon a voidwalker, an aspiring warlock in the Undercity must prove total mastery over it. In the shadowed enclave of the Magic Quarter, the Forsaken mentor Carendin Halgar provides the mystic runes required to tear a voidwalker from the Nether into the physical realm. The ritual takes place within the glowing summoning circle etched beneath the mentor's dais. Once the runes are activated, an unbound voidwalker materializes in fury. Subduing it is not an exercise in diplomacy; the summoner must break the entity through sheer arcane force and raw will. Only when the entity is thoroughly crushed does Carendin reveal the true formula of summoning, binding the creature's essence to the practitioner indefinitely.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1471-339cf1b4e558496a7dd1/1-0000.mp3", duration = 65.3583673, start = 0},
  },
}
P.transport["quest:1473"] = {
  hash = "80a3fe",
  fullHash = "80a3fe",
  text = "Creature of the Void. Creature of the Void is a pivotal rite of passage for Forsaken warlocks, tasking them with recovering a lost arcane text from the Scarlet Crusade. To learn how to summon and bind a chaotic voidwalker, an initiate must venture west into Tirisfal Glades and retrieve Egalin's Grimoire from hostile zealots. Within the dark alcoves of the Temple of the Damned in the Undercity, Carendin Halgar oversees the development of rising Forsaken summoners. When an acolyte proves competent enough to wield power beyond petty imps, Halgar directs them toward binding a creature forged from pure shadow and chaos: the voidwalker. Rather than relying on simple instinct, Forsaken practitioners base their summons on the meticulous research of Egalin, Halgar's own former master, who first penned the rituals necessary to subjugate these monstrous denizens of the void. Mastery of the voidwalker cannot be achieved without Egalin's Grimoire, which contains the precise methods for channeling such volatile magic. However, the precious tome was stolen by an agent of the Scarlet Crusade—a zealot named Perrine stationed in an outpost tower to the west. While Perrine and his crusaders likely viewed the grimoire as mere blasphemous contraband to confiscate and hoard, recovering it is essential if the Forsaken are to secure the ritual secrets before attempting to tear open the veil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1473-203629cae538fc7e524c/1-0000.mp3", duration = 78.1583673, start = 0},
  },
}
P.transport["quest:1478"] = {
  hash = "315946",
  fullHash = "315946",
  text = "Halgar's Summons. Halgar's Summons is a formal directive given to rising Forsaken warlocks who have reached a critical threshold in their dark craft. Master Carendin Halgar requires their presence in the Magic Quarter of the Undercity to begin rigorous advanced training. Answering his call sets the stage for summoning and binding dangerous entities from the Nether. When a warlock operating around Brill or the Tirisfal wilderness demonstrates adequate control over basic fel energies, word reaches the deeper subterranean halls of the Undercity. Senior practitioners such as Ageron Kargal serve as talent spotters, relaying notices to those who show genuine promise. To be summoned by Carendin Halgar is both a rare privilege and a perilous undertaking, indicating that basic imps and petty curses no longer suffice for the practitioner's education. Halgar oversees warlock rites from the shadowed reaches of the Magic Quarter, situated near the sinister altar known as the Temple of the Damned. Forsaken darkcasters operate without the squeamish moral restrictions of the living, yet even they demand rigorous discipline when dabbling in planar summonings. Halgar does not tolerate hesitation or sentimentality; his summons expects immediate deference and complete readiness to confront the hostile horrors of the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1478-e014545509978cc85bd6/1-0000.mp3", duration = 73.7436735, start = 0},
  },
}
P.transport["quest:1485"] = {
  hash = "5fa51a",
  fullHash = "5fa51a",
  text = "Vile Familiars. Near the Den, Vile Familiars threaten every warlock who seeks the power of demons. Ruzan asks you to prove your strength against them and bring back their heads. This is the humble, dangerous first step toward mastering fel power under the Horde’s watchful eyes. Warlocks live uneasily within Thrall’s new Horde. Demonic corruption and blood pacts once brought ruin to the orcs, leaving deep scars and distrust. Fel magic is tolerated in Durotar, but its practitioners are neither loved nor welcomed. Many warlocks live in seclusion, practicing in shadowed places like the Den, away from prying eyes. There, they teach the few initiates daring enough to follow their path. Ruzan asks you to prove your strength before he teaches you the dangerous rites for bending an imp to your will. Vile Familiars skulk near a cave northeast of the Den and hurl bolts of flame at those who approach. Slay these lesser demons and bring back their heads to show you can overcome the fiery creatures you hope to control. Only then can you face the danger of the magic you seek to command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1485-36f031fd46bcd7667660/1-0000.mp3", duration = 64.1567347, start = 0},
  },
}
P.transport["quest:1492"] = {
  hash = "f2470a",
  fullHash = "f2470a",
  text = "Wharfmaster Dizzywig. At Ratchet's pier, a crate of alchemy supplies waits for passage across the sea. Wharfmaster Dizzywig arranges its journey to the Old World aboard a ship bound for Blackwater Cove. A crate of potions and reagents waits at the Barrens port, bound for colleagues in the Old World. Caravans that might have carried it have already departed, so you are asked to take the secure shipment to Ratchet's water's edge. The port offers a route across the Great Sea between Kalimdor and the Eastern Kingdoms. Wharfmaster Dizzywig handles cargo on Ratchet's wooden piers. He tracks shipments in ledgers and manifests, then finds space aboard vessels sailing east across the Great Sea. This crate is booked for a ship bound for Blackwater Cove.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1492-18e9f46bfb4ea13225df/1-0000.mp3", duration = 43.5461224, start = 0},
  },
}
P.transport["quest:1498"] = {
  hash = "593bf1",
  fullHash = "593bf1",
  text = "Path of Defense. At the Far Watch Post, Uzzek prepares young Horde warriors to defend those who cannot defend themselves. He sends them to Thunder Ridge to prove their endurance against its electric beasts. At the Far Watch Post, Uzzek teaches young warriors that defense is part of the Horde's duty. The post lies on the border between the Barrens and Durotar. Uzzek says a warrior's highest calling is to stand between danger and those unable to defend themselves, taking the blows so the Horde can endure. Uzzek sends the novices to Thunder Ridge, north across the Southfury River in Durotar, to test their stamina and resolve. Thunder lizards and lightning hides roam the canyon. The initiates must survive the beasts' jolts and harvest their singed scales to show they have the fortitude to hold the front line.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1498-8b4d161c9c8d1ce7f21d/1-0000.mp3", duration = 43.9379592, start = 0},
  },
}
P.transport["quest:1499"] = {
  hash = "942942",
  fullHash = "942942",
  text = "Vile Familiars. In the Valley of Trials, Ruzan sends warlock initiates against vile familiars. After you slay them, you report to Zureetha Fargaze, who oversees the effort to curb the Burning Blade. Warriors and scouts in the Valley of Trials answer directly to Zureetha Fargaze, who sends them to curb the Burning Blade Coven. Warlock initiates first answer to Ruzan, their shadowy mentor. He demands proof that you can master lesser demons before sending you back to aid the Horde's defense. Your work serves both the warlocks and the safety of the Den. Zureetha Fargaze watches the northern cavern above the Valley of Trials. Vile familiars hide within, the weakest pets of the Burning Blade cultists. Their presence in the sacred training grounds insults the orcs and threatens the Valley. When you report your success, you show that those who practice fel magic remain ready to defend Durotar from corruption.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1499-839b9c8840062db9582e/1-0000.mp3", duration = 51.6963265, start = 0},
  },
}
P.transport["quest:15"] = {
  hash = "45c0db",
  fullHash = "45c0db",
  text = "Investigate Echo Ridge. Marshal McBride sends recruits north as kobolds gather at Echo Ridge Mine. The mine supplies ore and raw materials to Northshire Abbey and the Stormwind guard, and the growing threat puts both at risk. After early skirmishes with scattered vermin around Northshire's forested edge, scouts report a more organized threat. Kobolds have gathered in force at Echo Ridge Mine. Marshal McBride sends you north to face the workers at the entrance and learn how deeply they have settled in. Echo Ridge Mine supplies ore and raw materials to the Northshire brotherhood and the Stormwind guard stationed there. Kobolds have seized the tunnels, halting extraction and exposing the strain on local defenses. McBride asks you to cull ten workers, but the infestation runs deeper into the shafts than a surface patrol can reach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_15-3f400fdf5a544e7eb333/1-0000.mp3", duration = 46.4979592, start = 0},
  },
}
P.transport["quest:1501"] = {
  hash = "619f6a",
  fullHash = "619f6a",
  text = "Creature of the Void. In Orgrimmar, Gan'rul Bloodeye sends a young warlock after the stolen Tablet of Verga. The rogue Burning Blade cultists took it to their cavern at Skull Rock, and its runes are needed to summon a voidwalker. Gan'rul Bloodeye trains Horde warlocks in Orgrimmar's Cleft of Shadow. Thrall's new realm regards fel magic with deep wariness because of the orcish clans' dark history. Gan'rul says few true warlocks remain in the Horde, but their perilous skills are essential to its survival. To serve the Warchief, an initiate must learn more than the chaotic fire of an imp; they must command beings of pure shadow and endurance. The runes needed to summon a voidwalker are inscribed on the Tablet of Verga. The Burning Blade, a fanatical shadow cult, stole the relic and hides in a cavern at Skull Rock, right beneath the Warchief's nose. Gan'rul sends you into the cultists' den to recover the tablet and strike a bloody blow against the renegades who stain the name of all practicing warlocks.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1501-01c538fe3fe9557d23d2/1-0000.mp3", duration = 57.1036735, start = 0},
  },
}
P.transport["quest:1502"] = {
  hash = "2c5225",
  fullHash = "2c5225",
  text = "Thun'grim Firegaze. Atop Thorn Hill, Thun'grim Firegaze keeps to a reclusive life and a solitary forge. After their first lessons in defense, Horde warriors cross the Barrens to find him and seek steel fit for their growing skill. After you show skill in the defensive arts under veteran trainers like Uzzek, you are sent to sharpen your fighting with suitable steel. Ordinary armories can carry a frontline fighter only so far. True mastery calls for a personal weapon from a smith of renown. In the Barrens, Thun'grim Firegaze is that smith, an aging orc who has left settlement life behind to keep an isolated forge high above the plains. Thun'grim Firegaze lives atop Thorn Hill, a jagged rise east of the Crossroads where wild raptors and hostile quilboar roam. He spends his solitary hours shaping metal, far from the protection of town walls. Decades of gazing into blistering forge flames have ruined his eyesight, though his instincts remain sharp. When you climb the heights and disturb his solitude, Firegaze knows why: a warrior has come seeking forged steel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1502-6ee2e03f80d1c34c702e/1-0000.mp3", duration = 67.6310204, start = 0},
  },
}
P.transport["quest:1503"] = {
  hash = "1a8369",
  fullHash = "1a8369",
  text = "Forged Steel. Thun'grim Firegaze waits in the eastern Barrens for the steel stolen from his camp. He offers to forge a weapon for the warrior who brings it back. Thun'grim Firegaze keeps a smithy in the eastern Barrens, far from Orgrimmar. Years at the forge have dimmed his sight. The nearby Razormane quilboar used that weakness to steal an iron chest from his camp. Some snorted and made noise on one side to draw his gaze while others slipped in from the other and carried off his forged steel bars. Thun'grim is angry at the theft, but doubts the Razormanes can use the steel. Quilboar craft with stone, tusks, and thorny roots, not refined metal. The heavy chest remains near a broken wagon in their camp, untouched and useless to them. For Thun'grim, its steel is the stock he needs to forge weapons for young Horde warriors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1503-032ec652e88e8f779b17/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["quest:1504"] = {
  hash = "292936",
  fullHash = "292936",
  text = "The Binding. The Binding is the final initiation ritual in Orgrimmar for young Horde warlocks seeking command over a voidwalker. Under the direction of Gan'rul Bloodeye, the petitioner inscribes glyphs from the Tablet of Verga within Neeru Fireblade's summoning circle to call forth, subdue, and perpetually enslave a creature of the Void. For an initiate warlock lurking in the dark tunnels of the Cleft of Shadow, summoning an imp is merely child's play. Subduing a voidwalker is the first true test of willpower and arcane dominance. Warlocks do not form polite pacts or commune with these otherworldly horrors; they wrest them across dimensions through raw force and bind them in eternal servitude. Gan'rul Bloodeye demands that the initiate draw upon the glyphs transcribed from the Tablet of Verga, calling the monstrosity directly into Neeru Fireblade's ritual circle to break it in single combat. Overcoming the entity in physical and magical combat is only half the battle. As Gan'rul Bloodeye warns, a bound voidwalker never truly accepts its enslavement. Though it serves its master as a durable, shadowy bulwark in battle, it perpetually searches for lapses in concentration. A warlock must maintain an unwavering mental grip over their servant, for the moment discipline falters, the voidwalker will happily consume the soul of the one who bound it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1504-2b297f993016d3873836/1-0000.mp3", duration = 77.8971429, start = 0},
  },
}
P.transport["quest:1506"] = {
  hash = "74bb3a",
  fullHash = "74bb3a",
  text = "Gan'rul's Summons. Gan'rul's Summons is an urgent call delivered to young Horde warlocks by Ophek in Razor Hill. Senior warlock Gan'rul Bloodeye requires their immediate presence in the Cleft of Shadow to advance their training. It marks the first step toward mastering the dark art of summoning a voidwalker. Novice warlocks operating in Durotar do not remain unnoticed for long. Once a practitioner demonstrates sufficient mastery over their initial imp, word reaches the deeper subterranean recesses of Orgrimmar. Ophek, stationed out in Durotar, acts as a messenger for the senior dark casters, intercepting warlocks with an urgent demand to drop whatever they are doing and report to the Cleft of Shadow. Gan'rul Bloodeye oversees the training of nascent orc warlocks within the Horde. Operating out of the hidden caverns beneath Orgrimmar, he maintains a delicate balance between honing lethal fel power and keeping such dangerous arts shielded from the disapproving gaze of the Warchief. When Bloodeye calls an apprentice to his circle, it signals that simple fire spells and imps are no longer enough; it is time to bind a creature from the Twisting Nether.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1506-d2873d0573490311aed3/1-0000.mp3", duration = 65.9853061, start = 0},
  },
}
P.transport["quest:151"] = {
  hash = "9ede2f",
  fullHash = "9ede2f",
  text = "Poor Old Blanchy. Verna Furlbrow waits beside the road in Westfall with her stranded family and starving mare. Their wagon broke during an attempt to escape, leaving Old Blanchy exhausted. Verna asks you to gather oats from nearby abandoned farmsteads and feed the old horse. Verna and Farmer Furlbrow are stranded beside Westfall's main road. Bandits and rogue mechanical harvest golems have driven families like theirs from their homes. As the Furlbrows tried to haul their belongings to safety, their wagon broke down, leaving them marooned in open country. Old Blanchy has plowed and hauled for the Furlbrow family across many seasons. Now exhausted from pulling their overloaded cart and starved by the delay, the gentle mare is fading fast. Verna asks you to search nearby overrun farmsteads for sacks of oats, where hostile threshers and gnoll scavengers threaten. The grain could give the faithful animal a decent meal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_151-17377560e9da8a995d19/1-0000.mp3", duration = 54.7265306, start = 0},
  },
}
P.transport["quest:1516"] = {
  hash = "8fa928",
  fullHash = "8fa928",
  text = "Call of Earth. In the Valley of Trials, Canaga Earthcaller sets novice Horde shamans a test of endurance and patience. They hunt felstalkers to prepare a ritual sapta. A shaman begins by learning to bond with each element. For orcs and trolls, that path starts with earth, the bedrock of life, endurance, and patience. In the Valley of Trials, Canaga Earthcaller guides new shamans and teaches them that earth demands respect and steadfastness before it grants protection. The Burning Blade cult festers in ravines north of the Valley of Trials. Its dark magic summons felstalkers, corrupt hounds from beyond this plane. Hunting them tests whether a shaman can defend the land from unnatural decay. Canaga uses their hooves to brew an Earth Sapta, a sacred draft that opens mortal eyes to the elemental plane.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1516-5db1205291356e1c11c5/1-0000.mp3", duration = 46.1583673, start = 0},
  },
}
P.transport["quest:1517"] = {
  hash = "95f73d",
  fullHash = "95f73d",
  text = "Call of Earth. At Spirit Rock, Canaga Earthcaller guides young shaman through their first communion with the elements. They drink an Earth Sapta on sacred ground to see the Minor Manifestation of Earth. A sapta is a mystical draught known to only a few shaman masters. Made with elemental magic, it bridges mortal perception and the spiritual plane, granting Sapta Sight to the strong-willed. Because it binds the drinker's spirit directly to an element, tradition forbids drinking it outside consecrated holy ground. To commune with earth, you leave the Valley of Trials and climb the Hidden Path into Durotar's southern crags. Spirit Rock waits at the trail's end, an elevated sanctuary overlooking the rugged wasteland. Drink the sapta there, and you can perceive what ordinary eyes cannot: an elemental presence among the stone. The Minor Manifestation of Earth asks no bloodshed or submission. It asks only that you stand humbly before the world. Fire, water, and air bear turbulent, volatile, often chaotic spirits, while earth teaches steadiness. Mountains offer endurance, and plains teach boundless patience.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1517-71d1381e153fc03b58cd/1-0000.mp3", duration = 65.0710204, start = 0},
  },
}
P.transport["quest:1518"] = {
  hash = "867ec3",
  fullHash = "867ec3",
  text = "Call of Earth. In Durotar, a young shaman communes with a manifestation of the earth spirit. The initiate returns to Canaga Earthcaller with rough quartz and receives a first elemental totem. A novice shaman seeks communion with the earth through patience and humility, not brute strength. The Minor Manifestation of Earth grants the initiate a piece of rough quartz. The small stone proves the spirit has accepted the initiate’s pledge and remains a seed of power. You complete the trial by bringing the quartz to Canaga Earthcaller in the Valley of Trials. Canaga shapes it into an Earth Totem, the focus through which you channel the ground’s steadfast protection and strength. The rite begins your path through the four elemental disciplines and lays the foundation for a lifetime of communion with the natural world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1518-01dc381a6094b9919c2c/1-0000.mp3", duration = 43.0497959, start = 0},
  },
}
P.transport["quest:152"] = {
  hash = "8ab18d",
  fullHash = "8ab18d",
  text = "The Coast Isn't Clear. Along Westfall's western shore, shipwrecked sailors face murloc tribes on the beaches. Captain Grayson at the Westfall Lighthouse calls for help clearing the coast so survivors can reach land safely. Westfall's western coast has claimed countless ships. Reefs, sudden squalls, and jagged rocks break vessels against the shoals. Survivors may cling to wreckage and crawl ashore, hoping for rescue. But murloc tribes control the beaches and show no mercy to castaways. Captain Grayson tends the Westfall Lighthouse from a lonely outcropping southwest of the mainland. Death has bound him to the post, yet he remains watchful over passing ships and sailors in need. Murlocs make the shore deadly, from Coastrunners in the north to Tidehunters, Warriors, and Oracles in the south. Grayson calls on travelers to clear the coastline.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_152-ec67e23f55872ff4b314/1-0000.mp3", duration = 48.0914286, start = 0},
  },
}
P.transport["quest:1520"] = {
  hash = "ce31c9",
  fullHash = "ce31c9",
  text = "Call of Earth. This sacred rite marks a tauren shaman's spiritual attunement to the element of earth. By drinking an Earth Sapta at a holy rock east of Camp Narache, initiates peer beyond physical senses to commune directly with a Minor Manifestation of Earth. A sapta is a carefully concocted ceremonial potion crafted by shamanic elders to bind an initiate's mortal spirit directly to a primal element. Prepared with ancestral magic, only a select few among the tauren preserve the secrets of its brewing. When imbibed at a designated sacred site, the draught expands the imbiber's mind, piercing the veil between the physical realm and the spiritual plane so the elements can be witnessed in their raw form. East of Camp Narache stands Kodo Rock, a looming stone pillar that serves as a holy sanctuary. Consuming the sapta here reveals the Minor Manifestation of Earth awaiting the pilgrim. Unlike the volatile, fiery, or raging aspects of nature encountered later along the shaman's path, the spirit of earth asks only that the initiate approach in quiet humility, granting the mountain's enduring strength and the plains' calm patience to all who honor the land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1520-bb66990e3e20c041e43d/1-0000.mp3", duration = 67.2653061, start = 0},
  },
}
P.transport["quest:1521"] = {
  hash = "4ad49f",
  fullHash = "4ad49f",
  text = "Call of Earth. This rite concludes a young tauren shaman's initial communion with the spirits of the land in Mulgore. After drinking the Sapta of Earth and speaking directly with a spirit manifestation, the initiate receives a fragment of raw stone to bring home. Returning to Camp Narache marks the fledgling mystic's formal bond with the first of the four elements. Upon communing with the Minor Manifestation of Earth atop the crags near Red Cloud Mesa, the spirit yields a simple Rough Quartz. Though plain in appearance, the stone represents an elemental pact and the endurance of stone itself. The spirit reminds the young shaman that patience and strength are the core virtues demanded by the earth, promising that mutual respect will grant harmony with the land. Returning to Camp Narache, Seer Ravenfeather uses the gifted quartz to fashion the shaman's very first Earth Totem. Far more than a decorative symbol of status, the totem serves as a permanent physical and spiritual anchor. Through this carved focus, the initiate channels the grounding, protective magic of the earth itself, taking the first true step along the fourfold elemental path.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1521-e06b9b08ad0816c62884/1-0000.mp3", duration = 67.1085714, start = 0},
  },
}
P.transport["quest:1524"] = {
  hash = "e9ab2c",
  fullHash = "e9ab2c",
  text = "Call of Fire. In the Barrens, an aspiring shaman begins the second trial in the search for communion with fire. Kranal Fiss sends the initiate across the Southfury River to a secluded mountaintop shrine in Durotar, carrying the unlit Torch of the Dormant Flame. Kranal Fiss entrusts the shaman with the Torch of the Dormant Flame. Raw mystical strength alone cannot meet fire’s demands; the trial calls for temperance, focus, and respect. The torch is both ritual instrument and proof to the shrine’s keeper that the bearer has been judged ready to attempt the trial. The shrine lies across the Southfury River, among Durotar’s southern crags. A weathered stone carved with a fire rune marks an obscure path that climbs toward one of the region’s highest peaks. At the summit, the Shrine of the Dormant Flame is watched by Telf Joolam, a troll hermit. He turns away curious travelers and treasure hunters, keeping the sacred brazier from ordinary eyes until a petitioner arrives with the unlit torch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1524-d8a5d456bdadb4727f20/1-0000.mp3", duration = 57.9134694, start = 0},
  },
}
P.transport["quest:1525"] = {
  hash = "796d98",
  fullHash = "796d98",
  text = "Call of Fire. Telf Joolam sends a shaman across Durotar and the eastern Barrens for a Fire Sapta's ingredients. The draught prepares an initiate to perceive and speak with fire spirits. A Fire Sapta opens a shaman’s senses to the Eternal Flame. Like the draught for earth, it lets a shaman see and speak with spirits hidden from mortal sight. Telf Joolam sends initiates across Durotar and into the eastern Barrens to gather ingredients bound to heat and flame. Razormane quilboar spellcasters in the eastern Barrens carry fire tar, made in their earthy rituals. Burning Blade cultists carry the other needed ingredient in Dustwind Cave, in the ravines northeast of Razor Hill. The cultists use fire for destruction and demonic chaos, while the reagents in their pouches hold a natural tie to the element.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1525-4f8388e90a8d1aeb2918/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["quest:1526"] = {
  hash = "e9d969",
  fullHash = "e9d969",
  text = "Call of Fire. Atop Durotar's peaks, a shaman faces the trial that attunes them to fire. Telf Joolam guides the initiate to drink fire sapta, confront a Minor Manifestation of Fire, and claim its glowing ember to light the ceremonial torch. Fire spirits hide from untrained eyes on Durotar's summit. To see them, you drink fire sapta, a draught made from reagents gathered across the barrens and coast. It sharpens your senses to the unseen, revealing minor spirits and manifestations among the summit crags. A Minor Manifestation of Fire waits atop the mountain. Once the sapta takes hold, the spirit knows you can see it and awaits your challenge. Fire answers strength and decisive action, so you strike without delay. The longer the fight lasts, the more fiercely the elemental fire burns.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1526-8189452ee1466006b2b3/1-0000.mp3", duration = 49.4497959, start = 0},
  },
}
P.transport["quest:153"] = {
  hash = "d07966",
  fullHash = "d07966",
  text = "Red Leather Bandanas. At Sentinel Hill, Red Leather Bandanas mark the fight against the Defias Brotherhood. Scout Galiaan offers a reward for the red cloth masks worn by the outlaws, as the People's Militia struggles to track them across Westfall. Across Westfall, the red bandana marks the Defias Brotherhood. The gang draws cutpurses, looters, and traitors from many walks of life, but its members rally beneath the same crimson sign. Scout Galiaan and the People's Militia at Sentinel Hill collect the bandanas as proof that bandits have fallen. The cloth also helps them follow the Defias as their fronts shift across the countryside. Stormwind has denied Westfall proper military support, so the People's Militia depends on seasoned observers like Scout Galiaan to chart Defias activity. Galiaan watches outlaw patrols from Sentinel Hill. Passing adventurers and militia volunteers take on the dangerous work of bringing down the highwaymen who have driven honest farmers from their land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_153-5e32bff82044c4a44d66/1-0000.mp3", duration = 56.8685714, start = 0},
  },
}
P.transport["quest:155"] = {
  hash = "7e8917",
  fullHash = "7e8917",
  text = "The Defias Brotherhood. In Westfall, the People's Militia seeks the Defias Brotherhood's hidden base. A turncoat agrees to guide Alliance champions there in exchange for protection. The road passes through Moonbrook, where Edwin VanCleef's inner sanctum lies hidden. Gryan Stoutmantle's fight against the Defias Brotherhood reaches a turning point when a captured brigand agrees to talk. His former brothers may execute or assassinate him, so the Defias Traitor bargains with the People's Militia. Escort him safely through hostile territory, and he will reveal where Edwin VanCleef and his ringleaders hide. The thieves' network silences those who speak out, and the turncoat needs armed protection along the road.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_155-690d9681a709069c9ab4/1-0000.mp3", duration = 40.5681633, start = 0},
  },
}
P.transport["quest:1579"] = {
  hash = "a97631",
  fullHash = "a97631",
  text = "Gaffer Jacks. In Auberdine, Wizbang Cranktoggle needs his lost gaffer jacks back. The gnome inventor tossed a box of hardware into the sea during his voyage from Ironforge, and anglers can search for it along Darkshore's coast. Wizbang Cranktoggle crossed the Great Sea from Ironforge to find quiet in Darkshore. The gnome inventor drank too much on the voyage. Leaning over the rail in a drunken haze, he lost a crate of specialized metal parts called gaffer jacks in the water near Auberdine. Wizbang says gaffer jacks are essential precision tools. Without them, he cannot properly tune his stintle pegs or continue his delicate tinkering. Unwilling to wade into the cold surf himself, he asks local anglers to cast along Darkshore's shore and fish up the scattered parts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1579-399cc7878065b3d4cad9/1-0000.mp3", duration = 43.3893878, start = 0},
  },
}
P.transport["quest:1580"] = {
  hash = "604663",
  fullHash = "604663",
  text = "Electropellers. In Darkshore, Wizbang Cranktoggle asks anglers to recover his lost electropellers. He lost the prototype parts in freshwater streams after a mishap with an explosive duck decoy. Wizbang Cranktoggle spends an evening searching inland Darkshore for a place to test his latest invention. The gnome tinkerer, stationed in Auberdine, has built a self-propelled, exploding duck decoy. After drinking too much, he blacks out and wakes hours later back in town with singed hair and an empty pack. His bag of electropellers has fallen into one of the coastal rivers. Wizbang asks local fishermen to dredge Darkshore's freshwater streams because he does not want to brave the wilds himself. Anglers fishing the Wildbend River and Cliffspring River can snag the buoyant metal parts alongside local fish. With the components recovered, the gnome can resume his erratic waterfowl experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1580-3ea265dc636f0aea1cff/1-0000.mp3", duration = 51.0432653, start = 0},
  },
}
P.transport["quest:1581"] = {
  hash = "f8d204",
  fullHash = "f8d204",
  text = "Elixirs for the Bladeleafs. Syral Bladeleaf seeks help keeping her family’s busy trade supplied in Dolanaar. Her husband spends nearly all his time brewing, and fresh elixirs could ease his workload while earning the brewer uncommon herbs. Dolanaar draws travelers, sentinels, and druids moving through Teldrassil. Syral Bladeleaf and her husband have built a flourishing herb and alchemy trade to serve them. Demand keeps her husband bent over vials and cauldrons for nearly all his hours, leaving the couple little time together. Syral turns to passing herbalists and brewers to ease her husband’s workload. She asks for Elixirs of Lion's Strength and Minor Defense, offering freshly gathered, uncommon herbs in exchange. For a fledgling alchemist practicing beneath the Great Tree, the exchange brings a bundle of herbs and a chance to turn common forest flora into coveted regional flora.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1581-5b62616d78a354ac091c/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["quest:1582"] = {
  hash = "617d39",
  fullHash = "617d39",
  text = "Moonglow Vest. In Darnassus, Lotherias needs leather gear for young adventurers setting out across Kalimdor. She offers the pattern for a Moonglow Vest in return for shipments of embossed leather goods. In Darnassus, leatherworkers work to outfit sentinels and young scouts. Night elves and allied wanderers leave Teldrassil for the wilds of Kalimdor, where sturdy armor is in demand. Lotherias is among the master leatherworkers supplying them with gear. Lotherias asks apprentices to bring matched embossed gloves, boots, and cloaks as proof of their skill. Those who meet her order earn her trust, and she teaches them a night elf pattern for the Moonglow Vest, made to protect while allowing free movement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1582-bcc9fd7ec49a5f17b510/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["quest:1598"] = {
  hash = "7fb27d",
  fullHash = "7fb27d",
  text = "The Stolen Tome. In Northshire Valley, a novice human warlock is sent to recover a forbidden tome and prove their skill. Drusilla La Salle hopes to claim Powers of the Void from the Defias, whose camp lies in the vineyards. Warlocks in Stormwind's lands hide their craft and keep prying eyes from their research. Northshire Abbey guards forbidden grimoires in its archives. Drusilla La Salle, the warlock mentor on the abbey grounds, covets Powers of the Void but cannot risk suspicion from the clerics and paladins by entering the library's protected wing herself. An abbey novice joins the Defias Brotherhood and steals several valuable texts on his way out. He flees to the Northshire Vineyards and takes refuge around the Defias campsite. The thieves stash their prize in a field tent, unaware of the danger in the book's dark arts. Recovering the tome tests a novice warlock's nerve and opens the way to darker knowledge. Braving the bandit camp and returning the text satisfies Drusilla's ambition and proves the pupil is ready. She rewards the pupil with the dark rites to summon and bind an imp, the first demon an apprentice learns to command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1598-23c85ac13de24fbac3ef/1-0000.mp3", duration = 67.5004082, start = 0},
  },
}
P.transport["quest:1599"] = {
  hash = "6dda3f",
  fullHash = "6dda3f",
  text = "Beginnings. Beginnings is a rite of passage for fledgling Alliance warlocks starting in Dun Morogh. Under the begrudging tutelage of Alamar Grimm, novices are dispatched to harvest magical feather charms from nearby Frostmane troll novices to prove their competence before mastering the art of summoning an imp. Within the safe haven of Anvilmar, dark magic is not openly celebrated, but it is tolerated out of necessity. Alamar Grimm, an established warlock, conducts his occult research in relative discretion. When new practitioners show raw promise, Grimm is asked by unnamed parties who have taken an interest in the recruit to step away from his studies and assess the recruits personally. Before granting a novice the secrets to enslaving lesser demons, Grimm requires practical proof of both physical endurance and magical affinity. Nearby Frostmane troll novices, gathering in a cave southwest of Anvilmar, carry primitive feather charms infused with subtle primal magics. Harvesting these charms proves the aspiring warlock can conquer a magical adversary, while also providing Grimm with curious specimens for his ongoing research. Returning with the charms satisfies Grimm that the novice has sufficient will to survive. The trial culminates in teaching the summoning of the imp, the warlock's most foundational minion. Grimm offers a stern warning alongside the ritual: despite their diminutive stature, imps wield chaotic fire magic that can easily overpower an undisciplined master.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1599-8b06ff71a46335d64a07/1-0000.mp3", duration = 88.1371429, start = 0},
  },
}
P.transport["quest:16"] = {
  hash = "2ede7d",
  fullHash = "2ede7d",
  text = "Give Gerard a Drink. At the Maclure Vineyards, Gerard Tiller works long days in the fields and needs fresh spring water. He trades apples for water brought by passing travelers. Elwynn Forest's farms supply grain, fruit, and vegetables to Stormwind's townsfolk and garrisons. Tending crops under the open sky is hot, demanding work. Gerard Tiller spends long days in the dirt at the Maclure Vineyards, keeping pests away and managing the harvest. With little time to return to town wells, he relies on passing recruits to bring clean spring water so he can keep working. Gerard trades provisions instead of coin. Travelers with extra flasks of Refreshing Spring Water can exchange them for fresh apples from the orchard. The kingdom stretches its resources to maintain order and feed its army, so direct barter between smallholders and recruits remains a practical way to get by in rural Elwynn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_16-8ff2b141288ed3998ba5/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["quest:1638"] = {
  hash = "9ca340",
  fullHash = "9ca340",
  text = "A Warrior's Training. In Goldshire, A Warrior's Training sends young warriors to Stormwind for lessons in battlefield endurance. Lyria Du Lac directs them to the Pig and Whistle Tavern in Old Town, where veteran Harry Burlguard offers seasoned instruction. After aspiring fighters show reliable command of the fundamentals against threats across Elwynn Forest, their trainers see little more for Goldshire drillmasters to teach. Lyria Du Lac sends recruits into Stormwind, toward the gritty district of Old Town. Veteran fighters gather there to share combat experience far from the royal garrison’s rigid ways. Harry Burlguard, an aged battle veteran, keeps his quarters at the Pig and Whistle Tavern. He tests a warrior’s mettle with tavern grit and practical stamina instead of parade-ground drills. Before teaching defensive maneuvers that help soldiers survive dangerous campaigns, Harry expects new arrivals to match his appetite for drink and face local brawlers in the tavern.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1638-a47fb680161996b6ff6c/1-0000.mp3", duration = 52.5061224, start = 0},
  },
}
P.transport["quest:1639"] = {
  hash = "d39095",
  fullHash = "d39095",
  text = "Bartleby the Drunk. In the Pig and Whistle Tavern, Bartleby the Drunk faces a test set by Harry Burlguard. An aspiring Alliance warrior must take Bartleby's prized mug before Harry will teach deeper combat skills. Harry Burlguard asks for proof of a novice's backbone before teaching deeper combat skills in the Pig and Whistle Tavern. Across the room, Bartleby nurses his drinks at the far end of the counter. Harry wants you to take the man's mug, knowing Bartleby would rather fight than surrender his ale. The challenge puts a warrior's resolve to the test. Soldiers, laborers, and rough locals fill the Pig and Whistle, where polished manners count for little. Bartleby mocks newcomers as too prissy for a tavern scuffle instead of answering politely. The exchange leads to a brawl on the floorboards, where a warrior's training in Stormwind begins with a test of basic barroom fighting.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1639-5665899902b6bd9c9f13/1-0000.mp3", duration = 47.4383673, start = 0},
  },
}
P.transport["quest:1640"] = {
  hash = "37f089",
  fullHash = "37f089",
  text = "Beat Bartleby. In Stormwind, Bartleby guards the mug a young warrior must claim. The instructors send recruits to face him in a bare-knuckle fight and earn the vessel for their training. Stormwind's warrior instructors expect recruits to face combat without excuses or grand ceremony. As part of their formal training, young warriors must retrieve a particular mug from Bartleby, a notorious drunkard who lounges in the city. He scoffs at polite requests and swears no one will take his prized drinkware without prying it from his cold, dead fingers. For a fledgling warrior, words soon give way to a fistfight. Bartleby boasts that he will fight to the death, but a thorough thrashing is enough to sober him. Once beaten, his bravado gives way to bruised admiration. He recognizes that his opponent is tougher than they appear and yields peacefully, letting the victor claim the mug and complete the trial at the training hall.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1640-92855e5b535da48bbe6b/1-0000.mp3", duration = 53.995102, start = 0},
  },
}
P.transport["quest:1641"] = {
  hash = "44cc01",
  fullHash = "44cc01",
  text = "The Tome of Divinity. In Stormwind, The Tome of Divinity guides young paladins through a solemn rite. Under Duthorian Rall's care in the Cathedral of Light, you face teachings on virtue, devotion, and the duties that come with the Holy Light. Duthorian Rall guides those who answer the paladin's calling in the Cathedral of Light. Early training teaches martial discipline and the order's rites, but advancement asks for a deeper commitment to the spirit. The trials ask you to look beyond battle and weigh the moral duties of a paladin. Stormwind faces dangers within its borders and beyond, and its people need defenders who understand that duty. Receiving the Book of Divinity binds you to service and self-sacrifice. Duthorian asks you to study the holy text and learn what the Light demands of its defenders. Its lessons prepare paladins to oppose the Scourge's creeping horrors and protect common folk. Righteous power must answer to virtue and compassion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1641-410f3ca0a21279583733/1-0000.mp3", duration = 51.3567347, start = 0},
  },
}
P.transport["quest:1645"] = {
  hash = "744c34",
  fullHash = "744c34",
  text = "The Tome of Divinity. The Tome of Divinity marks an essential milestone in a dwarven paladin's training within Ironforge. Bestowed by Tiza Battleforge in the Hall of Mysteries, this holy text begins a trials-based journey meant to test an initiate's devotion to the Light and their readiness to defend Azeroth against dark forces like the Scourge. Paladin mentors across the eastern kingdoms direct promising initiates to Ironforge's Hall of Mysteries once they demonstrate mastery of martial and spiritual fundamentals. Under the watchful eye of Tiza Battleforge, young dwarven paladins are introduced to the solemn principles that separate a simple warrior from an ordained champion of the Holy Light. Taking up this task represents a conscious pledge toward lifelong self-sacrifice, duty, and spiritual discipline. Accepting this charge places a Book of Divinity into the hands of the novice. This text outlines the expectations, virtues, and spiritual tenets required to wield sacred energies effectively against wicked threats. Studying its teachings is merely the introductory step; the scripture serves as a foundational guide before the initiate is sent forth across Khaz Modan and beyond to embody its lessons in real acts of faith.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1645-f32da3d74f9b263389ef/1-0000.mp3", duration = 67.84, start = 0},
  },
}
P.transport["quest:1665"] = {
  hash = "2a18e5",
  fullHash = "2a18e5",
  text = "Bartleby's Mug. In Stormwind, Bartleby's Mug marks a young warrior's trial of grit. After besting Bartleby in the Pig and Whistle Tavern, you claim his drinking mug for your trainer, Harry Burlguard. Harry Burlguard tests young warriors with a brawl in Old Town. He asks you to take down Bartleby, a stubborn drunk at the bar of the Pig and Whistle Tavern. Once subdued, Bartleby reluctantly gives up his prized drinking mug, but first takes one final swig to drain the dregs. Returning the mug to Harry Burlguard completes your novice trial. Burlguard sees that you can persuade through sheer force and recognizes your readiness for defensive mastery. He points you onward to further battlefield instruction with Marshal Haggard, a seasoned veteran in Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1665-2c0e78379e7ae165a5e4/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:1666"] = {
  hash = "528b1c",
  fullHash = "528b1c",
  text = "Marshal Haggard. At Eastvale, Marshal Haggard keeps the arms he gathered over a lifetime of service. Harry Burlguard sends novice warriors from Stormwind City to meet the retired marshal and seek better weapons. Stormwind's novice warriors need more than skill to face danger beyond the city. Harry Burlguard sends promising fighters east through Elwynn Forest to find Marshal Haggard, a retired officer who served the realm for years. Haggard gathered a personal armory over a lifetime in the field, and his home near the Eastvale Logging Camp holds weapons for young warriors seeking better arms. Marshal Haggard lives in a secluded manor near the Eastvale Logging Camp. Years of service have weakened his failing sight, and he sometimes mistakes approaching travelers for prowling riverpaw gnolls. Though age keeps him in this quiet corner of eastern Elwynn, Stormwind's guards and trainers still respect the old marshal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1666-5c88d833b39469f39e35/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["quest:1667"] = {
  hash = "073eaa",
  fullHash = "073eaa",
  text = "Dead-tooth Jack. A stolen badge puts Marshal Haggard's authority in Defias hands. The retired officer lives in eastern Elwynn Forest, where Dead-tooth Jack tricked him into surrendering his official insignia. Jack wore a Stormwind tabard in the dark and posed as Marshal Dughan. Haggard needs the badge back before the Defias Brotherhood can use it to impersonate Stormwind officials. Marshal Haggard lives in an isolated cottage on Elwynn's eastern ridges. One night, a figure in a Stormwind tabard approached, claiming official business and asking for Haggard's old marshal's badge. Believing he was handing it to a fellow officer, Haggard complied. The stranger laughed in his face and vanished into the woods. The thief was a Defias rogue called Dead-tooth Jack. Marshal Haggard has retired, but his old badge still carries the legal weight of Stormwind. Defias bandits are creeping across Elwynn, Westfall, and Redridge, and the badge could help them pass guard checkpoints, redirect patrols, or take command of supplies. Jack retreated to a camp to the south and left the badge locked in a strongbox. Haggard needs it recovered before the Defias can cause serious harm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1667-1a7f3665868852dafc12/1-0000.mp3", duration = 69.355102, start = 0},
  },
}
P.transport["quest:1679"] = {
  hash = "a77203",
  fullHash = "a77203",
  text = "Muren Stormpike. Muren Stormpike is an introductory quest for developing Alliance warriors, given once a recruit proves their basic mettle in Dun Morogh. Directed by Granis Swiftaxe in Kharanos, the young fighter travels into the mountain city of Ironforge to seek formal instruction in martial discipline. Meeting Muren marks the beginning of deeper training in tactical stances and dwarven military traditions. After cutting their teeth against local threats in the snowy valleys of Dun Morogh, warrior novices catch the eye of Granis Swiftaxe in Kharanos. Recognizing that crude skirmishing can only take a brawler so far, Swiftaxe sends promising fighters to the heart of dwarven martial prowess: the Military Ward of Ironforge. There, within the echoing halls of the forge-city, senior combatants oversee the formal schooling of those bound for battle. Upon reaching the Hall of Arms, recruits are introduced to Muren Stormpike, a seasoned veteran of a storied dwarven clan. Muren cares little for tavern tales and demands proof that his new charges can withstand real combat. Reporting to him opens the pathway toward mastering the defensive arts, learning to absorb and control enemy aggression, and earning well-crafted iron armaments fit for true front-line duty.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1679-97d58fe69b7b073b4a9f/1-0000.mp3", duration = 70.2955102, start = 0},
  },
}
P.transport["quest:1681"] = {
  hash = "8abe1b",
  fullHash = "8abe1b",
  text = "Ironband's Compound. Ironforge smith Tormus Deepforge seeks vengeance for his mentor, Sturgy Ironband, whose remote teaching outpost in eastern Dun Morogh fell to a sudden and bloody assault. The slaughter followed the arrival of a rare umbral ore shipment, which immediately drew the violent attention of the Dark Iron dwarves. Sturgy Ironband was revered across Ironforge as an unmatched instructor of the smithing craft. From his secluded compound south of Helm's Bed Lake, he instructed promising pupils far from the crowded anvils of the Great Forge. That peaceful enterprise ended abruptly when one of his students acquired an unfamiliar mineral dubbed umbral ore. Intrigued by its properties, Ironband resolved to experiment with the sample, entirely unaware that possessing it had marked his school for ruin. Shortly after the umbral ore reached the compound, hostile Dark Iron dwarves launched a ruthless surprise attack against the outpost. The assailants showed no mercy, slaughtering Sturgy Ironband and every apprentice under his care before occupying the grounds. Tormus Deepforge, one of Ironband's surviving proteges based in the capital, refuses to let the massacre stand, dispatching Alliance travelers to avenge his teacher and recover the cursed ore that brought destruction to the encampment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1681-82c161a5cfeb3c7ac6cd/1-0000.mp3", duration = 74.9453061, start = 0},
  },
}
P.transport["quest:1683"] = {
  hash = "86d6bb",
  fullHash = "86d6bb",
  text = "Vorlus Vilehoof. In Darnassus, young night elf warriors face a trial set by Elanaria. They must hunt a satyr who has defiled a hidden moonwell near the Ban'ethil Barrow Den. Elanaria asks you to prove your dedication and discipline before she teaches advanced martial techniques. She needs more than words from those who defend Kalimdor. A guardian must face corruption and cleanse the sacred boughs of Teldrassil. Your trial leads to Vorlus Vilehoof, a satyr hiding at a moonwell in the mountains southeast of Ban'ethil Barrow Den. Satyrs were once ancient betrayers, twisted by demonic influence, and they hate sacred Kaldorei relics. Vorlus bathes in the moonwell, fouling its blessed waters and mocking the grace of Elune.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1683-e2a951434eff8f4da6e5/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["quest:1685"] = {
  hash = "b0a4b0",
  fullHash = "b0a4b0",
  text = "Gakin's Summons. A summons delivered to promising Alliance warlocks by Remen Marcot on behalf of Gakin the Darkbinder. It directs fledgling practitioners down into the crypts beneath the Slaughtered Lamb in Stormwind's Mage Quarter to begin their next stage of dark occult training. Demonology is strictly outlawed across the civilized districts of Stormwind, yet dark arts persist right under the noses of the city guard. When a warlock displays sufficient proficiency with their introductory imps, word quietly travels to senior practitioners. Remen Marcot delivers the message with deliberate discretion, urging initiates to keep the meeting place quiet and head into the shadowy recesses beneath the Mage Quarter. Behind the modest facade of the Slaughtered Lamb tavern lies a network of damp cellars and hidden catacombs. Here, shielded from prying Kirin Tor mages and the Cathedral's inquisitors, Gakin the Darkbinder oversees the instruction of Stormwind's warlocks. The summons serves as the gateway to commanding a voidwalker, a rite requiring dangerous stolen reagents and perilous summoning circles.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1685-9257f2b885de0b32f66d/1-0000.mp3", duration = 63.8171429, start = 0},
  },
}
P.transport["quest:1686"] = {
  hash = "62c542",
  fullHash = "62c542",
  text = "The Shade of Elura. At Auberdine, Elura's shade guards a sunken ship and its Elunite ore. Elanaria sends young night elf warriors into the waters to lay the captain to rest and recover her medallion and ore for a weapon forged by Smith Mathiel. Long ago, a ship carrying rare Elunite ore struck jagged coastal rocks near the Auberdine lighthouse and sank. The captain, Elura, cursed her own soul in despair and out of unwavering duty. Bound to the wreck beneath the waves, her shade guards the lost cargo from anyone who would disturb it. Elanaria sends young night elf warriors into Darkshore's surf to defeat Elura, recover her medallion, and salvage the ore. They need both the medallion and ore to put the captain to rest and bring the metal to Smith Mathiel's forge. The work tests their martial skill and respect for the fallen, and provides the ore for a crafted weapon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1686-8bf2d437e3dd2790ee90/1-0000.mp3", duration = 51.6179592, start = 0},
  },
}
P.transport["quest:1688"] = {
  hash = "3c48d8",
  fullHash = "3c48d8",
  text = "Surena Caledon. Beneath the Slaughtered Lamb in Stormwind, Gakin seeks his former pupil and a bloodstone choker. He sends an aspiring warlock after Surena Caledon, who betrayed him to join the Defias Brotherhood. Beneath the Slaughtered Lamb in Stormwind's Mage Quarter, Gakin the Darkbinder teaches novices the forbidden arts of fel summoning. He once took a young woman named Surena Caledon as his pupil. He admired her natural magical talent and her beauty. Surena left her studies and Gakin's favor, then fled Stormwind with her lover, Erlan Drudgemoor, to join the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1688-d13c14bdd97b0cb7e1ab/1-0000.mp3", duration = 33.9330612, start = 0},
  },
}
P.transport["quest:1689"] = {
  hash = "b0ff8d",
  fullHash = "b0ff8d",
  text = "The Binding. In Stormwind, Gakin the Darkbinder puts a novice warlock through a final trial. With his recovered Bloodstone Choker, you draw a voidwalker into a hidden circle and force it to submit. Beneath the Slaughtered Lamb in Stormwind's Mage Quarter, forgotten catacombs run beyond the watchful gaze of the Silver Hand and Kirin Tor magistrates. Gakin the Darkbinder teaches novice warlocks that dark magic demands more than channeling power; they must also dominate otherworldly beings. You have recovered Gakin's stolen Bloodstone Choker from Surena Caledon. Now he asks you to call a voidwalker into the summoning circle beneath the tavern. A voidwalker will not bargain with you. The power in the Bloodstone Choker opens a rift and draws the shadow creature into the mortal world. You must batter it with magic and force until its will breaks, proving you can command it. Once defeated, the voidwalker's essence binds to you, giving you a durable, shadowy protector that can endure punishment in the battles ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1689-9b70efc6b905f569e621/1-0000.mp3", duration = 60.1338776, start = 0},
  },
}
P.transport["quest:1692"] = {
  hash = "267662",
  fullHash = "267662",
  text = "Smith Mathiel. In Darnassus, sacred ore is on its way to the forge. After you recover elunite from the shipwreck off Auberdine, Elanaria sends you to Mathiel to have it shaped into a weapon for the Kaldorei. Elanaria sends you across Darnassus's Warrior's Terrace with the elunite ore you recovered from the haunted shipwreck off Auberdine. The warrior trainer packs it in a sturdy case and directs you to Mathiel, one of the capital's finest smiths. He can shape the metal into a weapon worthy of your calling. Mathiel treats smithing as a craft of devotion. Elunite bears the sacred blessing of Elune, the Moon Goddess, and he accepts the case as an honor. He will shape the holy metal into arms to defend the young boughs of Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1692-c0fd34991b6874ee455c/1-0000.mp3", duration = 42.9714286, start = 0},
  },
}
P.transport["quest:1693"] = {
  hash = "d6fb57",
  fullHash = "d6fb57",
  text = "Weapons of Elunite. In Darnassus, Weapons of Elunite brings a young warrior's early rite of passage to its close. After recovering ore blessed by Elune, you bring it to Mathiel to forge arms for a defender of Kalimdor. Night elf warriors defend Teldrassil and the kaldorei people. Promising young warriors gather elunite, a mineral blessed by the Moon Goddess, rather than relying on mundane steel alone. Its ore calls for a smith skilled in metalcraft and mindful of Elune's gift. Smith Mathiel works in Darnassus, shaping blessed elunite into weapons of war. He considers the work an honor, not routine metalcraft. When you bring him the ore, he fashions arms to suit your style and rewards your service with weapons blessed by your goddess.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1693-46ae1ce192eb37c29ae3/1-0000.mp3", duration = 44.8, start = 0},
  },
}
P.transport["quest:170"] = {
  hash = "3051af",
  fullHash = "3051af",
  text = "A New Threat. A New Threat is an early combat assignment issued by Balir Frosthammer in Coldridge Valley. Dwarven mountaineers have been caught off-guard by a sudden surge of troggs bursting out across Dun Morogh, threatening local settlements and camps. Coldridge Valley was long regarded as a protected haven for young dwarven warriors and mountaineers training in Dun Morogh. That peace shattered when subterranean Rockjaw troggs began clawing their way to the surface in startling numbers. Reports quickly reached Anvilmar that troggs were swarming the frozen lake and surrounding foothills, disrupting daily patrols and cutting off vital supply routes through the valley pass. The crisis peaked when the creatures mounted a coordinated assault on a dwarven encampment to the west, forcing the mountaineers to retreat and abandon their posts. Shorthanded and unable to spare full battle regiments from Ironforge, Balir Frosthammer has turned to newly recruited adventurers to cut through the Rockjaw ranks and secure the hills before the beasts push straight to Anvilmar's doorstep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_170-5377cf3e6639d5df06cf/1-0000.mp3", duration = 59.3502041, start = 0},
  },
}
P.transport["quest:1715"] = {
  hash = "0a6963",
  fullHash = "0a6963",
  text = "The Slaughtered Lamb. This errand directs novice gnome warlocks out of Ironforge to seek advanced instruction in human lands. With King Magni Bronzebeard keeping a vigilant watch on dark practitioners within the dwarven mountain, mentors must rely on Stormwind's hidden networks to complete their disciples' training. Before the fall of Gnomeregan, aspiring warlocks in Khaz Modan studied under their own tinker-mages and demonic scholars deep within the techno-city. The disaster that drove the gnomes into exile scattered those institutions. The surviving practitioners found themselves cramped into Ironforge's gloomy, subterranean caverns, operating under the distrustful eye of King Magni Bronzebeard and the dwarven guard. Unable to practice demonic arts openly or cultivate dangerous rituals in such tight quarters, senior instructors like Lago Blackwrench have little choice but to send their students away. The destination for these expatriate students is the Slaughtered Lamb, an unassuming tavern nestled in Stormwind's Mage Quarter. Beneath its taproom, concealed behind twisting stone passages and descending stairs, lies a subterranean sanctum where human warlocks gather in shadows. Overseen by seasoned summoners like Gakin the Darkbinder, the cove provides the space and dark paraphernalia required to teach novices how to summon and bind minor demons without drawing the immediate wrath of city marshals. While Stormwind's coven welcomes capable hands, the influx of refugee novices creates friction. Human mentors already walk a knife's edge to avoid detection from the city's paladins and authorities. Gakin and his colleagues find their clandestine sanctuary increasingly crowded by practitioners sent south from Khaz Modan. The steady stream of dwarven-mountain traffic risks blowing the lid on their discreet operation, yet neither side possesses an easier alternative.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1715-532101b6ec3d66951b64/1-0000.mp3", duration = 106.057143, start = 0},
  },
}
P.transport["quest:176"] = {
  hash = "aa514c",
  fullHash = "aa514c",
  text = "Wanted: \"Hogger\". Wanted: \"Hogger\" is an Alliance bounty posted outside Goldshire for the head of a massive, savage gnoll chieftain. Hogger prowls the southwestern woods of Elwynn Forest and has violently thwarted every attempt by the local authorities to bring him down. While Elwynn Forest struggles with banditry and kobold infestations, the gnoll tribes in the south have grown bolder and more organized under the brute leadership of Hogger. Towering over typical Riverpaw gnolls, Hogger has established camp near the Forest's Edge, ambushing travelers and overpowering the local militia patrols sent to subdue him. With the Stormwind Army stretched thin and unable to spare regular forces to police the outskirts of the capital, Marshal Dughan took the unusual step of posting an open bounty on the beast. Taking down Hogger requires venture into deeply hostile gnoll territory, and his ferocity has earned him a reputation as the deadliest threat facing novice adventurers in Elwynn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_176-c71f062bfc992df3c7df/1-0000.mp3", duration = 54.2040816, start = 0},
  },
}
P.transport["quest:179"] = {
  hash = "d45394",
  fullHash = "d45394",
  text = "Dwarven Outfitters. Dwarven Outfitters is an introductory survival task in Coldridge Valley offered by Sten Stoutarm. In exchange for culling local wolves and gathering their tough meat for winter rations, fresh recruits are rewarded with sturdy gloves to ward off frostbite in Dun Morogh's biting cold. The high mountain pass of Coldridge Valley is brutally cold, and unprepared travelers quickly learn that standard kit is no match for the elements. Standing outside Anvilmar, Sten Stoutarm offers a straightforward frontier bargain to new recruits: venture into the snowy drifts, hunt down the prowling wolves, and bring back cuts of tough meat to help supply the outpost. In return, he provides proper cold-weather gloves to ensure young adventurers keep all ten fingers. While wolves represent a perpetual hazard to dwarven scouts and fledgling gnomes training in the valley, they are also a vital resource. Their meat sustains the garrison stationed at Anvilmar, and culling their numbers keeps the paths between the local encampments somewhat safer. Stoutarm's arrangement serves a double purpose—testing a recruit's ability to handle the local wildlife while stockpiling food for the bitter nights ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_179-35a186582d404f9b3655/1-0000.mp3", duration = 68.075102, start = 0},
  },
}
P.transport["quest:18"] = {
  hash = "be51b1",
  fullHash = "be51b1",
  text = "Brotherhood of Thieves. Deputy Willem sends recruits across Northshire's eastern river to face the Defias Brotherhood. Their red burlap bandanas give Stormwind its first tangible evidence of the brigands' organized presence in the valley. Northshire Valley has long been a safe haven in Elwynn Forest, guarded by Stormwind and used to train recruits and Clerics of the Holy Light. Recently, discipline along its perimeter has frayed. Vagrants and thieves have crossed the eastern river, lurking near the woods and making small camps close to the abbey. Deputy Willem maintains local order, but the guards cannot spare the manpower to watch every corner of the valley without volunteers. These outlaws are coordinated and wear matching attire. They call themselves the Defias Brotherhood, and their red burlap bandanas mark their allegiance. Deputy Willem sends recruits to drive back the brigands and recover their masks, hoping to curb their advance and learn how deeply the Defias have reached into the kingdom's heartland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_18-d7f4f3c92e15f5191f54/1-0000.mp3", duration = 56.6334694, start = 0},
  },
}
P.transport["quest:1818"] = {
  hash = "7b554a",
  fullHash = "7b554a",
  text = "Speak with Dillinger. Speak with Dillinger is a Horde military directive issued in Brill. Austil de Mon, the warrior trainer at the Gallows' End Tavern, dispatches able-bodied fighters to Deathguard Dillinger at the west end of the village to take on a hazardous combat mission in service of Lady Sylvanas. Within the Gallows' End Tavern in Brill, the warrior trainer Austil de Mon keeps a watchful eye out for promising combatants willing to serve the Dark Lady. When the Deathguards require capable hands, de Mon directs unproven adventurers out of the tavern and into the field. Deathguard Dillinger, who oversees security on the western edges of Brill, has requested someone with martial competence for an urgent task. Brill sits squarely on the front line of Tirisfal Glades, where the Forsaken must constantly prove their martial dominance against hostile threats. Dillinger's post near the village graveyard puts him in prime position to manage local incursions. For the young warrior, reporting to Dillinger is more than a simple errand: it is a formal test of combat prowess and political loyalty to the newly forged Forsaken nation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1818-a06df3c90271719cf9a8/1-0000.mp3", duration = 64.1044898, start = 0},
  },
}
P.transport["quest:1819"] = {
  hash = "1c5f6d",
  fullHash = "1c5f6d",
  text = "Ulag the Cleaver. Ulag the Cleaver is a rite of passage for young Forsaken warriors in Tirisfal Glades. Deathguard Dillinger tasks you with releasing and executing an enslaved Scourge warrior bound inside a northern mausoleum, testing your martial resolve and earning the respect of the Deathguard. When the Scourge swept across Lordaeron, the Forsaken managed to capture a peculiar undead warrior who named himself Ulag the Cleaver. While Ulag possessed a conscious, lucid mind, his spirit remained inextricably dominated by the psychic thrall of the Lich King. Seeking to understand how the Scourge binds free will, the Forsaken kept him restrained under a magical seal beneath a mausoleum north of Brill, hoping to break the entity's spiritual chains. All efforts to sever Ulag from the Lich King's mental grip ended in failure. Recognizing that true freedom could only come through destruction, Deathguard Dillinger repurposed the captive as a trial of combat for rising Forsaken warriors. By disturbing the skull stone trigger outside the crypt, a warrior breaks the protective wards, releases Ulag from his imprisonment, and grants him release at the edge of an axe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1819-54d5a1835b80dd4f7def/1-0000.mp3", duration = 67.4220408, start = 0},
  },
}
P.transport["quest:182"] = {
  hash = "c1d836",
  fullHash = "c1d836",
  text = "The Troll Cave. Assigned by the mountaineer Grelin Whitebeard, this mission dispatches adventurers to cull young Frostmane trolls gathering in the southern caves of Coldridge Valley. With the Ironforge Senate preoccupied by an escalating trogg crisis, lone scouts and willing recruits must handle border skirmishes before the trolls establish a permanent foothold. While Ironforge's regular forces are consumed with repelling rock-jawed trogg incursions across the snowfields, the southern approaches cannot be left unguarded. Grelin Whitebeard and his brother Senir were deployed by the mountain authorities to assess whether the native ice trolls posed an immediate danger to the heartland. Perched on a bluff overlooking the frozen valley, Grelin maintains a solitary watch on their movements. Grelin's reconnaissance revealed that the local Frostmane clan had begun settling in a deep cave along the southern ridgeline of Coldridge Valley. Believing full military mobilization would be an unnecessary waste of dwarven manpower, the scout favored hiring capable local volunteers to cull the aggressive whelps. Thinning their young fighters serves to disrupt their encampment before the Frostmane can mount coordinated raids against nearby dwarven homesteads.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_182-67f2c60d591e7d199018/1-0000.mp3", duration = 68.1534694, start = 0},
  },
}
P.transport["quest:1820"] = {
  hash = "612b37",
  fullHash = "612b37",
  text = "Speak with Coleman. Speak with Coleman is a transitional task in Tirisfal Glades offered to champions who have proven their worth against the Scourge. Deathguard Dillinger directs capable warriors from the town square to the local tavern to assist Coleman Farthing with personal and factional vendettas. After assisting in the containment of severe local threats—such as laying to rest dangerous Scourge remnants like Ulag the Cleaver—adventurers earn the personal trust of Deathguard Dillinger. As one of the sentinels watching the roads into Brill, Dillinger judges who is capable of handling more than routine perimeter patrols and points capable fighters toward citizens in need of specialized service. Not every conflict in Tirisfal Glades is fought on high command orders from the Undercity. Across the ruined kingdom of Lordaeron, surviving undead carry deep grudges tied to the lands, families, and fortunes they left behind. Coleman Farthing bides his time within the Gallow's End Tavern, seeking an instrument of vengeance to strike back at the threats lingering near former settlements like the Agamand Mills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1820-932c5bf91fa0d0a3f018/1-0000.mp3", duration = 57.7567347, start = 0},
  },
}
P.transport["quest:1821"] = {
  hash = "b979ec",
  fullHash = "b979ec",
  text = "Agamand Heirlooms. Coleman Farthing tasks adventurers with plundering the Agamand Family Crypt at the northern end of Agamand Mills. Driven by bitter resentment over his mortal demise, he seeks to strip his former masters of their ancestral weapons and erase their final remnants of dignity. Before the Third War devastated Lordaeron, Coleman Farthing served the wealthy and influential Agamand family at their expansive mills in Tirisfal Glades. Whatever occurred during the fall of their estate, Farthing blames his former lords entirely for his death. Now raised into undeath among the Forsaken, he views the Agamands' downfall with spiteful satisfaction, rejoicing that the once-proud dynasty has been reduced to mindless minions enslaved to the Lich King. To completely extinguish what remains of the family's prestige, Farthing sends adventurers into the Agamand Family Crypt nestled beneath the northern bluffs of the mills. Within its haunted stone halls, the restive dead wander alongside lingering Scourge. Farthing demands the extraction of four storied relics—the Agamand family sword, axe, dagger, and mace—ensuring their bloodline's legacy is stripped of every remaining shred of honor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1821-760524456a184cb25045/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["quest:183"] = {
  hash = "951aee",
  fullHash = "951aee",
  text = "The Boar Hunter. The Boar Hunter is an early errand given by the dwarf hunter Talin Keeneye in Coldridge Valley. A surge in the local crag boar population has made the woods overly dangerous, and young recruits are tasked with culling the aggressive beasts so seasoned hunters can track in peace. Coldridge Valley is typically a quiet, protected training ground for young mountaineers and scholars of Ironforge. However, the wildlife often grows restless and overabundant in the harsh winter climate. Talin Keeneye, a veteran hunter stationed outside Anvilmar, notices that the aggressive small crag boars have multiplied so rapidly that they pose a genuine threat to anyone wandering the snow-covered trails. Hunting is a cornerstone of dwarven life, providing meat, hide, and essential fieldcraft practice. Yet when game becomes a nuisance that attacks on sight, culling is required to restore balance. By trimming the crag boar numbers across the valley slopes, young adventurers prove their combat readiness while giving local hunters room to pursue their sport without getting overwhelmed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_183-1db518ede704fb05d624/1-0000.mp3", duration = 61.2832653, start = 0},
  },
}
P.transport["quest:184"] = {
  hash = "1ea5bf",
  fullHash = "1ea5bf",
  text = "Furlbrow's Deed. The Furlbrows flee their farm as Defias bandits carry their land grant through Elwynn Forest. Returning the deed to Farmer Furlbrow near the Westfall border preserves the couple’s claim to their stolen homestead. Defias bandits in Elwynn carry a land deed signed by Theodore and Verna Furlbrow. A crude note on its back says they drove the elderly farmer from his property, then carried the document across the river into Elwynn to copy it and forge claims to other seized land. The note says the Furlbrows were stranded just over the border, beside the road, after their wagon broke. The Defias have driven dozens of families from their ancestral land in Westfall. With Stormwind’s army absent and the realm’s resources strained, the Brotherhood uses force and false claims to seize the kingdom’s breadbasket. Theodore and Verna are leaving their farm for safety, but their lawful deed preserves their claim if order ever returns to the province.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_184-bdc883776eea65a949f8/1-0000.mp3", duration = 55.1967347, start = 0},
  },
}
P.transport["quest:1858"] = {
  hash = "2b233d",
  fullHash = "2b233d",
  text = "The Shattered Hand. In Orgrimmar, Therzok tests rogues seeking a place in the Shattered Hand. He asks them to open Tazan's recovered satchel with a key taken from an unwitting accomplice. After retrieving Tazan's locked satchel, you find it useless without the key. The Shattered Hand demands skill, not brute force against the complex lock. Therzok sends you to Gamon, a tauren drunkard who frequents Orgrimmar's tavern. Gamon is easily distracted and once helped Tazan, making him a fitting mark for quiet theft. Take the key from Gamon without alerting the tavern, then open the satchel and claim Tazan's logbook. Bring the stolen contents to Therzok in the Cleft of Shadow to meet the Shattered Hand's standards. A clean job earns you formal recognition as one of its operatives.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1858-f048f1f22c1b5d48b879/1-0000.mp3", duration = 44.3297959, start = 0},
  },
}
P.transport["quest:1859"] = {
  hash = "065ee5",
  fullHash = "065ee5",
  text = "Therzok. In Orgrimmar, Therzok waits for a promising rogue from Durotar. Kaplak has seen your skill with violence and stealth and sends you to the Cleft of Shadow to meet a Shattered Hand operative. Kaplak draws promising young rogues aside when they begin making a name for themselves in Durotar. The new Horde honors Thrall, but not all its servants fight openly beneath his banner. Word of a fighter skilled in violence and stealth, willing to bend the rules of open warfare, reaches the underground guild in Orgrimmar. Kaplak sends you beneath Orgrimmar's red stone cliffs to the Cleft of Shadow. Therzok waits in its gloom, out of sight of the city's grunts. There, lone cutpurses and ambushers are brought into the Shattered Hand, the Horde's covert network of daggers in the dark.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1859-bc53b25169a56d37cf75/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["quest:1860"] = {
  hash = "92a7b4",
  fullHash = "92a7b4",
  text = "Speak with Jennea. In Goldshire, Zaldimar Wefhellt sends novice mages to Stormwind for further instruction. He directs apprentices who have advanced beyond basic training in Elwynn Forest to Jennea Cannon in the Wizard's Sanctum. Zaldimar Wefhellt sends you from Goldshire to Stormwind City as your training advances. Your time learning elementary spells from local tutors in Elwynn's hamlets has run its course. In the Mage Quarter, the Wizard's Sanctum is where the kingdom's senior mages pursue arcane study and instruction. They coordinate magical matters across the realm. Zaldimar says your report concerns the security of Elwynn Forest and Stormwind, not only your studies. In Stormwind, you report to Jennea Cannon, a mage who oversees local assignments. She is cautious about sharing grand secrets with a newly arrived apprentice, but your report begins your service to the wizarding order.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1860-bb5522a0ee013628746f/1-0000.mp3", duration = 52.7412245, start = 0},
  },
}
P.transport["quest:1861"] = {
  hash = "a0a697",
  fullHash = "a0a697",
  text = "Mirror Lake. Novice Alliance mages in Stormwind's Mage Quarter are sent to sample Mirror Lake's waters for magical contamination. Jennea Cannon sends them southwest of the city gates to test the waterfall spray. Azeroth's arcane currents were shaken by conflicts from the opening of the Dark Portal through the Third War and the battle at Mount Hyjal. Those shocks tore ancient currents from their stable channels. In Stormwind's Wizard's Sanctum, magi like Jennea Cannon watch the changes closely. They fear that displaced arcane power could reach the wilderness and corrupt local ecosystems. Mirror Lake lies beneath the cliffs southwest of the Stormwind gates and is a primary natural reservoir fed by mountain falls. The surrounding countryside depends on its waters. Jennea sends novice mages with a glass flask to the waterfall's base, where they collect fresh spray. The Sanctum can then use scrying and reagent tests to learn whether wild magic is seeping into the public water supply.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1861-3b0fa020508bd2ac550b/1-0000.mp3", duration = 57.364898, start = 0},
  },
}
P.transport["quest:1879"] = {
  hash = "c1aea6",
  fullHash = "c1aea6",
  text = "Speak with Bink. \"Speak with Bink\" is an Alliance summons directing novice mages from Dun Morogh to the capital city of Ironforge. Dispatched by Magis Sparkmantle, the call sends promising spellcasters to assist Bink, an arcane researcher working out of the Hall of Mysteries. Novice mages training in the cold crags of Dun Morogh eventually catch the eye of Magis Sparkmantle. Recognizing when an apprentice has outgrown the rudimentary exercises around Kharanos, Sparkmantle passes along word from his colleague, Bink. The request is specific and uncompromising: Bink requires an arcane specialist and refuses to trust the matter to anyone who cannot wield magic. The assignment carries young mages into Ironforge's Mystic Ward, where scholars, priests, and arcanists convene beneath the soaring stone vaults of the Hall of Mysteries. Here Bink conducts her studies, evaluating arriving apprentices with sharp-eyed scrutiny. In her view, raw potential is merely a beginning; an undisciplined spellcaster quickly becomes a hazard rather than an asset in arcane matters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1879-aba7aa9d9daa577cf8bc/1-0000.mp3", duration = 62.6416327, start = 0},
  },
}
P.transport["quest:1881"] = {
  hash = "8ee6f7",
  fullHash = "8ee6f7",
  text = "Speak with Anastasia. Speak with Anastasia is an introductory summons directing promising Forsaken mages to Anastasia Hartwell in the Undercity. Dispatched by mage trainer Cain Firesong, the young caster is called to the Magic Quarter to undertake critical work for the magi of the Forsaken. This brief summons sets the stage for investigations out into the blighted lands of Tirisfal Glades. As nascent spellcasters hone their early talents under the guidance of Cain Firesong in Brill, they are soon directed into the capital. The mages of the Forsaken maintain a dedicated enclave within the Magic Quarter of the Undercity, organizing both arcane scholarship and strategic defensive efforts across Lordaeron. Cain Firesong acts as an evaluator, filtering out mere novices and sending those who demonstrate genuine talent directly to senior practitioners who require capable field hands. Anastasia Hartwell stands among the prominent mage instructors within the Undercity. Rather than leaving promising students to study trivial incantations in safety, she wastes little time pressing them into service for the Forsaken's territorial and practical interests. Answering her summons is both a rite of passage for arcane practitioners and an induction into the shadowy, pragmatic magical pursuits that define the post-Scourge undead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1881-4b8eaafd9b004652027a/1-0000.mp3", duration = 72.437551, start = 0},
  },
}
P.transport["quest:1882"] = {
  hash = "f3376b",
  fullHash = "f3376b",
  text = "The Balnir Farmstead. \"The Balnir Farmstead\" is an early rite of passage for young Forsaken mages, directed by Anastasia Hartwell in the Undercity's Mage Quarter. Initiates are sent to eastern Tirisfal Glades to gather snapdragons from an abandoned farmstead sitting dangerously close to the border of the Plaguelands. The floral samples serve as barometers for the encroaching magical corruption spreading from the Scourge-blighted east. While the Royal Apothecary Society frequently studies the effects of necromancy and decay, the mages of the Forsaken maintain their own watchful eye on the borderlands. Anastasia Hartwell tasks novice spellcasters with travelling to the Balnir Farmstead in eastern Tirisfal Glades. Snapdragons native to the farm's gardens are naturally sensitive to shifting magical currents, absorbing ambient energies from the soil and atmosphere. By examining these blooms, arcane scholars in the Undercity can measure whether the corruptive contagion of the Lich King's domain has seeped past the bulwark into Tirisfal proper. The Balnir Farmstead sits near the fringes of the glades, uncomfortably near the blight-scarred wilderness of the Western Plaguelands. The Forsaken recognize that the Lich King's plague is an unruly and destructive power that actively rots the land itself. Although the Forsaken harness their own dark arts, uncontained Scourge corruption threatens their territorial borders and security. Anastasia intends to pass the gathered snapdragons along to the apothecaries, uniting arcane observation with alchemical investigation to defend Lordaeron's reclaimed heartland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1882-3d0587850e1bd779ea40/1-0000.mp3", duration = 90.5404082, start = 0},
  },
}
P.transport["quest:1885"] = {
  hash = "9c2d6c",
  fullHash = "9c2d6c",
  text = "Mennet Carkad. Mennet Carkad is an introductory rogue quest in the Undercity that brings promising operatives into the fold of the Deathstalkers. Directed by Marion Call, aspiring assassins are summoned to report directly to Mennet Carkad deep within the Rogues' Quarter. Within the dark corridors of the Undercity, word travels quietly among the Forsaken's covert operatives. When a scout or assassin catches the eye of the higher leadership, an invitation is issued. Marion Call passes down word that Mennet Carkad, a prominent figure among the rogue handlers, has taken personal notice. Given the lethal reputation of the Forsaken intelligence apparatus, ignoring such a directive is not considered a viable option. Mennet Carkad waits in the shadowy alcoves of the Rogues' Quarter, watching over recruits and evaluating their readiness. Those who heed his call are not simply joining an ordinary guild of thieves; they are being tested for entry into the Deathstalkers, the dreaded espionage and assassination arm of the Forsaken. Swift obedience is merely the first baseline test for anyone seeking to serve the Dark Lady from the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1885-95c8ee205924eea8cbcb/1-0000.mp3", duration = 64.1567347, start = 0},
  },
}
P.transport["quest:1886"] = {
  hash = "00ffc5",
  fullHash = "00ffc5",
  text = "The Deathstalkers. This task marks the trial for initiates seeking entry into the Deathstalkers, the covert and lethal arm answering to Lord Varimathras in the Undercity. Assigned by Mennet Carkad in the Rogues' Quarter, the mission demands ruthless initiative to intercept a traveling messenger. Completing it opens the door to deeper clandestine schemes within the Forsaken realm. The Deathstalkers do not admit just anyone into their ranks. Operating directly under dreadlord Varimathras, this secretive order acts as both the secret police and elite assassination corps of the Forsaken. To earn their notice, a hopeful agent must demonstrate cunning, discretion, and an unhesitating willingness to eliminate targets. In the shadowy corners of the Rogues' Quarter, handler Mennet Carkad sets an initiation trial designed to weed out the weak or overscrupulous.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1886-6b9ab5e6fa4e58590db3/1-0000.mp3", duration = 48.404898, start = 0},
  },
}
P.transport["quest:1898"] = {
  hash = "13f010",
  fullHash = "13f010",
  text = "The Deathstalkers. This covert assignment sends an undercover operative into the Undercity's shadowy underbelly to interrogate an unwitting conspirator. Acting under orders handed down from Lord Varimathras, you pose as an expected messenger to uncover treason within the Forsaken's own capital. The Deathstalkers do not merely eliminate external threats to the Forsaken; they maintain a ruthless vigil over their own citizens. Acting on suspicions harbored by Lord Varimathras, Deathstalker Mennet Carkad sets an infiltration plan in motion. Armed with a forged or acquired letter of introduction belonging to Astor Hadren, you are tasked with slipping past the suspicions of a local merchant named Andron Gant.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1898-70d2fbcae2592c6f7503/1-0000.mp3", duration = 40.3330612, start = 0},
  },
}
P.transport["quest:1899"] = {
  hash = "eb2f55",
  fullHash = "eb2f55",
  text = "The Deathstalkers. This errand continues the Deathstalkers' deception of the informant Andron Gant in the Undercity. Still believing you are the messenger he was expecting, Gant hands over a ledger meant for his secret contacts, and the operative delivers it instead to Mennet Carkad in the Rogues' Quarter. The exchange marks the transition from simple inquiries to deeper, more covert operations on behalf of the Forsaken state. The Deathstalkers do not rely solely on brute force or shadow magic; their operations depend heavily on mundane ledgers, recorded names, and meticulous surveillance. Andron Gant, operating out of the Undercity, hands over a personal ledger crammed with intelligence, believing it bound for the mysterious employers he secretly serves. Taken in by the operative's disguise, Gant even asks that the same courier be sent in the future, never suspecting that his ledger is headed straight to the Deathstalkers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1899-ac85c37225049cca1125/1-0000.mp3", duration = 52.1404082, start = 0},
  },
}
P.transport["quest:1941"] = {
  hash = "ecd993",
  fullHash = "ecd993",
  text = "Manaweave Robe. In Stormwind, Wynne Larson presents the Manaweave Robe as a proud showcase for her family’s shop. She has woven the enchanted garment from fine materials for a commission that is now complete. Larson Clothiers serves spellcasters in Stormwind’s Mage Quarter with garments made to channel volatile energies. Fine magical robes call for rare materials, careful needlework, and threadwork that holds through mystic resonance. Wynne Larson takes pride in each piece that leaves her shop, where every robe worn into the field carries the Larson name. The manaweave robe offers comfort, mobility, and practical resilience for travel through contested lands. Once the needed components are delivered, Wynne Larson weaves the final stitch herself and presents the finished garment as a fine example of Larson tailoring, meant to draw admiration and spread the shop’s name across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1941-7b367d18b2530908731c/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["quest:1961"] = {
  hash = "8ff504",
  fullHash = "8ff504",
  text = "Gathering Materials. Gathering Materials is a rite of passage for aspiring Horde mages training in the Undercity. Assigned by Anastasia Hartwell, the task sends apprentices into Silverpine Forest to claim arcane gems from the wizards of Dalaran, assembling the components needed to weave their first true mage's robes. Within the arcane cloisters of the Magic Quarter, novice mages must prove their mastery over more than just raw incantations. To earn their first true robes—a formal mantle marking their station and personal worth—initiates are directed by Anastasia Hartwell to harvest the raw components required for enchanted weave: a bolt of simple linen and a set of potent Dalaran mana gems. The mana gems cannot simply be purchased or manifested; they must be torn from Dalaran mages stationed across Silverpine Forest, particularly near Ambermill. Anastasia Hartwell remarks with cold detachment that while Dalaran's arcane philosophies mirror their own, sentimental hesitation has no place in the Undercity. In the eyes of the Forsaken, if those living wizards lack the strength to defend their relics, they forfeit both their treasures and their lives. Once gathered, the cloth and gems are delivered to Josef Gregorian, a tailor residing in the Magic Quarter. While Gregorian readily admits he lacks the magical talent to gauge the pristine quality of Dalaran's enchanted stones, he possesses the rare artisan skill needed to weave their raw power directly into the fabric of the robes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1961-dbbd6885e90720a96558/1-0000.mp3", duration = 85.3942857, start = 0},
  },
}
P.transport["quest:1963"] = {
  hash = "78347d",
  fullHash = "78347d",
  text = "The Shattered Hand. Therzok tests rogues in Orgrimmar who seek entry to the secretive Shattered Hand. Their trial sends them after Tazan, a troll smuggler, and his locked satchel. The Shattered Hand works from the Cleft of Shadow beneath Orgrimmar. The order of assassins and thieves follows old orcish traditions. Warchief Thrall rules the young Horde with honor, diplomacy, and caution, but the Shattered Hand's leaders believe restraint weakens their people. They seek to restore martial supremacy through covert violence, using knives and poison when a battlefield charge may fail.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1963-d975adaf6ecb3341185c/1-0000.mp3", duration = 31.5297959, start = 0},
  },
}
P.transport["quest:1978"] = {
  hash = "67364e",
  fullHash = "67364e",
  text = "The Deathstalkers. This errand marks the formal induction of a capable operative into the ranks of the Deathstalkers, the Forsaken order of assassins and spies. Tasked with delivering Andron's Ledger directly to the dreadlord Varimathras, the courier brings proof of the Syndicate's covert activities to the highest tier of Undercity leadership. After unearthing incriminating records from Andron Gant, Mennet Carkad officially welcomes the operative into the Deathstalkers. The organization serves as Lady Sylvanas's eyes, ears, and daggers throughout Lordaeron, relying on intelligence networks, ruthless efficiency, and stealth to eliminate threats before they surface. Gaining formal recognition within the order is a major milestone for any aspiring rogue or scout in the Undercity. Because of the sensitive nature of the intelligence, the ledger is delivered directly to Varimathras in the Royal Quarter of the Undercity. The nathrezim commander oversees Forsaken tactical intelligence under Sylvanas Windrunner. Pleased with the Deathstalkers' initiative, Varimathras welcomes the operative's demonstrated capability, noting that his intelligence division can always make use of someone who delivers results.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_1978-98dea217ac1d9e42cd25/1-0000.mp3", duration = 67.1085714, start = 0},
  },
}
P.transport["quest:21"] = {
  hash = "b3d67c",
  fullHash = "b3d67c",
  text = "Skirmish at Echo Ridge. In Northshire Valley, recruits strike at kobolds in Echo Ridge Mine. Marshal McBride ordered the attack after scouts found the mine overrun. Marshal McBride sends recruits against the kobolds in Echo Ridge Mine. Scouts found the mine overrun, and the garrison fears the creatures will strengthen their hold if left alone. The kobolds dig through the tunnels, gather stolen resources, and multiply. Recruits must thin their numbers to protect Northshire Valley, with its farms and spiritual retreat. New recruits are sent into the mine because the Stormwind Army is stretched thin. Garrison forces guard the southern borders, while unrest is rumored across Elwynn. Officers like McBride must call on willing hands. A recruit who proves reliable at Echo Ridge earns the army’s respect and is ready for more difficult work elsewhere in the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_21-1e4907b6a05635c88ff1/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["quest:2118"] = {
  hash = "c51327",
  fullHash = "c51327",
  text = "Plagued Lands. Corruption is spreading through Darkshore, where Tharnariun Treetender hopes to save the afflicted wildlife. He asks travelers to calm a rabid thistle bear with an enchanted relic and bring it back alive. A creeping sickness twists Darkshore’s beasts into maddened, aggressive versions of themselves. Thistle bears suffer most, their rabid frenzy threatening travelers and the coast’s fragile balance. Night elf sentinels often answer with steel, while druids seek to understand the sickness and heal its cause. Tharnariun Treetender refuses to kill the corrupted beasts without first trying to save them. He made a trap called Tharnariun’s Hope. Set on the forest floor, its soothing light briefly calms a raging thistle bear. Pacified, the bear follows the traveler back to Tharnariun’s outpost for study.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2118-626e1770c6f983767ce8/1-0000.mp3", duration = 46.8897959, start = 0},
  },
}
P.transport["quest:2138"] = {
  hash = "acb292",
  fullHash = "acb292",
  text = "Cleansing of the Infected. In Darkshore, Tharnariun Treetender faces a hard choice over the infected thistle bears. His attempt to cure one has failed, and he asks you to kill the rabid beasts before they harm other creatures or spread the sickness. Tharnariun Treetender has searched for a remedy to the sickness spreading through Darkshore's wildlife. He tried to cleanse a captured bear, but the thistle bears remain diseased and violent. Now he asks you to put them down. He fears they will maul other creatures and carry the sickness farther into the ancient woodlands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2138-2cdd450f987ec33f3b1f/1-0000.mp3", duration = 30.6416327, start = 0},
  },
}
P.transport["quest:2139"] = {
  hash = "42681f",
  fullHash = "42681f",
  text = "Tharnariun's Hope. In Darkshore, Tharnariun Treetender's work against the wildlife sickness reaches a grim turning point. After travelers put down infected beasts across the woodlands, he sends an Alliance champion after the rabid Den Mother northeast of Auberdine. After the Third War, an unnatural rabid sickness began afflicting Darkshore's wild creatures. Tharnariun Treetender, stationed in Auberdine, spent days asking travelers to put down infected beasts and ease the forest's suffering. But killing rabid thistle bears treated only a symptom. Tharnariun decided the source among the local bears had to be removed: their matriarch, the Den Mother. After the Den Mother's death, Tharnariun offers profound thanks, though melancholy shadows his words. For the kaldorei, raising weapons against woodland creatures is agonizing. Dark forces press against their new home, and many despair or seek shelter. The defenders of Auberdine accept the heavy moral burden of protecting their wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2139-6dd9a0940d01dca1241e/1-0000.mp3", duration = 58.7493878, start = 0},
  },
}
P.transport["quest:2159"] = {
  hash = "aeb630",
  fullHash = "aeb630",
  text = "Dolanaar Delivery. Travelers leave Shadowglen with a parcel of herbs bound for Dolanaar. Porthannius, occupied with the druids, asks them to carry it south, marking their first venture beyond the sheltered glade. Porthannius asks travelers heading south from Shadowglen to carry a bundle of freshly harvested herbs along the forest path. He is occupied with pressing business alongside the druids tending the glade, and cannot leave to handle the errand himself. The bundle goes south as young adventurers prepare to leave the training grounds for the wider reaches of Teldrassil. The southern road from Shadowglen leads to Dolanaar, a foremost night elf settlement on Teldrassil's great boughs. Innkeeper Keldamyr oversees hospitality, rest, and supplies for wanderers, sentinels, and druids. When he receives the herbs on Porthannius's behalf, he urges young adventurers to rest their minds and spirits before facing the corruption spreading across the world tree.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2159-e43055f2260cbac91b6f/1-0000.mp3", duration = 54.3869388, start = 0},
  },
}
P.transport["quest:2160"] = {
  hash = "725f42",
  fullHash = "725f42",
  text = "Supplies to Tannok. Supplies to Tannok is an errand entrusted to fledgling adventurers departing Coldridge Valley through the dangerous mountain pass into greater Dun Morogh. The gnome tinkerer Hands Springsprocket sends a crate of needed provisions to Tannok Frosthammer at the Thunderbrew Distillery inn in Kharanos, bypassing the trogg-infested trails that have severed routine trade. Coldridge Valley is traditionally the proving ground and sanctuary for young Ironforge dwarves and exiled Gnomeregan survivors, but recent events have strained its connection to the rest of Dun Morogh. Trogg incursions have overrun Coldridge Pass, leaving the mountain defile perilous to cross. Mountaineers are spread thin guarding settlements and defensive perimeters, delaying scheduled supply escorts for days on end. Hands Springsprocket, a gnome waiting by the mouth of Coldridge Pass, found himself saddled with a crate of vital inn supplies meant for Kharanos without any safe way to deliver it personally. Recognizing that hearty adventurers are already preparing to brave the perilous pass, he enlists outward-bound travelers to carry the cargo to Tannok Frosthammer, the assistant at the bustling Thunderbrew inn. Reaching Kharanos marks an adventurer's entry into the broader world of Dun Morogh. Tannok Frosthammer eagerly receives the delivery, noting that word from Anvilmar has been scarce ever since the troggs disrupted travel through the pass. Delivering the goods restores a fragile line of communication and trade between the two isolated dwarf communities.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2160-117f6878ac91aa2bb019/1-0000.mp3", duration = 84.3755102, start = 0},
  },
}
P.transport["quest:2161"] = {
  hash = "07af20",
  fullHash = "07af20",
  text = "A Peon's Burden. Ukor waits on the trail outside the Valley of Trials with a load he cannot carry home. The recruits in the red canyon refused his provisions, and now he asks travelers to return them to Razor Hill. Ukor set out from Razor Hill with provisions for the fresh recruits training in the red canyon. He believed they needed the food, but the taskmasters turned him away. They keep supplies lean because they believe meager rations teach young Horde warriors discipline and endurance. Innkeeper Grosk later explains that this hardship is part of their training. Ukor reached the pass, but fears the return trip across Durotar. Scorpids, venomous spiders, and prowling boars haunt the rocky trail. He has no weapons or armor, and lacks the fighting spirit expected of an orcish grunt. Waiting along the path, he asks travelers leaving the proving grounds to carry his heavy provisions back to the inn in Razor Hill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2161-2338fd10475032dd884e/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["quest:2178"] = {
  hash = "a735c5",
  fullHash = "a735c5",
  text = "Easy Strider Living. In Auberdine, Alanndarian Nightsong offers to share her strider stew recipe with hunters who bring her foreststrider meat. Auberdine's coastal folk make use of the wildlife around them. Alanndarian Nightsong has her own recipe for hearty strider stew, made from the tall foreststriders that roam Darkshore's woods. She asks you to hunt the birds and bring back their meat before she shares her cooking. Foreststriders range through the woodlands and beaches north and south of Auberdine. Their sharp beaks and quick tempers make them dangerous when provoked, but their meat makes a rich stew. Bring fresh meat to Alanndarian, and she will share her recipe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2178-6b1061d2590e33ca8f59/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["quest:218"] = {
  hash = "ff0578",
  fullHash = "ff0578",
  text = "The Stolen Journal. The Stolen Journal is an early Alliance quest in Dun Morogh where Grelin Whitebeard tasks adventurers with entering the troll cave in Coldridge Valley to reclaim his stolen notebook. To recover it, you must defeat the formidable troll leader Grik'nir the Cold. Reclaiming the journal allows Grelin to finalize his appraisal of the troll threat within Coldridge Valley. Grelin Whitebeard has been observing the Frostmane trolls encroaching on Coldridge Valley, keeping detailed notes on their habits and sudden aggression. During the unrest, an unusually imposing troll made off with his personal journal and retreated into the depths of their den. For Grelin, the loss is not merely sentimental; the notebook contains the bulk of his reconnaissance, leaving his official assessment stalled until it is recovered from the cavern. The brute responsible for taking the journal is Grik'nir the Cold, a powerful Frostmane troll marked with distinctive body and facial paint who holds court in the heart of the valley's troll cave. Slaying Grik'nir breaks the immediate local leadership of the cave's trolls and secures Grelin's journal. With the leader dispatched, Grelin feels confident enough to report that the valley's troll situation is manageable, sending his finished findings on to his brother Senir.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_218-1a6fd0e11308ec751a72/1-0000.mp3", duration = 70.8702041, start = 0},
  },
}
P.transport["quest:22"] = {
  hash = "ba05ce",
  fullHash = "ba05ce",
  text = "Goretusk Liver Pie. At the Saldean Farm in Westfall, Salma Saldean prepares a pie amid hard times. Bandits have ravaged the breadbasket of the kingdom, and local homesteaders hunt aggressive boars to feed their families. Westfall was once Stormwind's fertile breadbasket, but hard times have fallen on the land. Neglected roads, roving outlaws, and overgrown fields make daily life a struggle for the few settlers who remain. At the Saldean Farm, Salma Saldean works to keep a sense of home despite the dangers around her. A traditional meat pie offers one of the few modest comforts for homesteaders trying to preserve their way of life. Goretusks roam Westfall's plains in great numbers, their tough hides and vicious tusks making them dangerous. They threaten lone farmhands, yet provide vital meat to families cut off from regular trade. Salma's recipe calls for crushed rosemary, minced garlic, chopped dill, and simmering gravy. With careful preparation, the pungent organs of these hardy beasts become a rich, savory meal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_22-83a09c86f572a26ea1fd/1-0000.mp3", duration = 61.0220408, start = 0},
  },
}
P.transport["quest:2205"] = {
  hash = "a6bcc2",
  fullHash = "a6bcc2",
  text = "Seek out SI: 7. In Goldshire, Keryn Sylvius sends new rogues toward SI: 7. A sealed package carried to Stormwind City brings them before Master Mathias Shaw, who leads the crown's covert intelligence network. At the Lion's Pride Inn in Goldshire, rogue trainer Keryn Sylvius wastes no time praising newcomers. She thinks fresh initiates look more like cheese delivery hands than covert agents, yet gives them a sealed delivery for the capital. The trip tests their reliability as couriers and quietly vets scouts for wider service to the realm. SI: 7 works from the southeastern corner of Old Town in Stormwind City. The worn district holds the command center of Stormwind Intelligence, Section 7, where Master Mathias Shaw oversees the kingdom's covert operations. Shaw receives the package with dry skepticism and judges whether the traveler has the grit for real espionage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2205-03e68f56a9aa418086e7/1-0000.mp3", duration = 54.0212245, start = 0},
  },
}
P.transport["quest:2206"] = {
  hash = "db6992",
  fullHash = "db6992",
  text = "Snatch and Grab. Master Mathias Shaw sends agents to Jerod's Landing for shipping intelligence. The Defias Brotherhood uses the river dock to move supplies in secret. Master Mathias Shaw tests aspiring operatives who seek a place in Stormwind's covert intelligence wing. He asks for finesse and stealth, not brute force. SI:7 agents take down key figures quietly and recover important papers without drawing the realm into open scandal. Each new operative must prove they can work unseen. Jerod's Landing lies on the river in southern Elwynn, south of Goldshire and just east of the Maclure Vineyards. The Defias Brotherhood seized the once-quiet dock and made it an illicit route. Smuggled arms, supplies, and contraband cross the water from Redridge toward Westfall, beyond the reach of royal road patrols. Master Mathias Shaw warns agents that capture, compromise, or death leaves them without the Crown's support. Stormwind and its spymasters will deny knowing they ever existed. Recovering the Defias Dockmaster's schedule gives SI:7 proof of the Brotherhood's supply lines while keeping Stormwind's official involvement hidden.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2206-5425eb0437c1a66fec4e/1-0000.mp3", duration = 67.84, start = 0},
  },
}
P.transport["quest:224"] = {
  hash = "f9648e",
  fullHash = "f9648e",
  text = "In Defense of the King's Lands. Mountaineer Cobbleflint guards the southern tower in the Valley of Kings, desperately seeking aid against the encroaching Stonesplinter troggs. With Ironforge's military stretched thin across distant fronts, the defense of Loch Modan's southern passes falls to passing Alliance volunteers. The massive dwarven monuments carved into the mountains of the Valley of Kings loom over a garrison under severe strain. Mountaineer Cobbleflint and his fellow guards stationed at the southern watchtower face an ever-growing invasion of troggs erupting from the rock. With much of King Magni Bronzebeard's regular army dispatched abroad to support Alliance commitments, the home front relies heavily on local patrols and hired blades to prevent the province from being overrun. The subterranean threat originates within Stonesplinter Valley, a craggy ravine carving into the southern peaks of Loch Modan. Troggs and their scouts have burrowed surface-ward in massive numbers, carving out fortified camps along the valley floor. Left unchecked, their scouting parties threaten the critical roads connecting Loch Modan to the southern passes, forcing the Mountaineers to wage a continuous war of attrition.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_224-7e708f639b5cb8a66423/1-0000.mp3", duration = 65.28, start = 0},
  },
}
P.transport["quest:2242"] = {
  hash = "a43589",
  fullHash = "a43589",
  text = "Destiny Calls. Syurna sends you to learn what Sethir the Ancient knows of Teldrassil's corruption. The satyr waits near the Oracle Glade, beyond the reach of those who tried force or diplomacy. Teldrassil's growing sickness troubles the night elf leaders in Darnassus. Syurna, the rogue trainer, needs someone subtle; armed patrols have died trying to reach Sethir the Ancient. The satyr roosts on a remote bough near the Oracle Glade and has turned away force and diplomacy alike. To learn what he knows, you need to enter his lair and take his personal possessions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2242-41948523ed6d56ff0f4d/1-0000.mp3", duration = 34.1681633, start = 0},
  },
}
P.transport["quest:2259"] = {
  hash = "238ee9",
  fullHash = "238ee9",
  text = "Erion Shadewhisper. Jannok Breezesong sends promising rogues from Teldrassil to Darnassus. At the Cenarion Enclave, Erion Shadewhisper points them toward work beyond the forests. Jannok Breezesong sends you from Teldrassil to find Erion Shadewhisper in Darnassus. You need not worry about being sent to the exacting trainer Syurna. Erion waits in the Cenarion Enclave, where he handles work that calls for a quieter touch. Erion Shadewhisper marks a change for rogues in night elf lands. Teldrassil's forests can no longer contain your duties. Erion sends capable hands into a wider, more dangerous world, toward work across the sea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2259-242514e350a39869520b/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["quest:2260"] = {
  hash = "146392",
  fullHash = "146392",
  text = "Erion's Behest. Across the Great Sea, Erion's Behest carries a summons to promising night elf rogues in Darnassus. Erion Shadewhisper sees their growing skill in stealth and sends them to Stormwind City to report to Stormwind Intelligence. Night elf rogues in Teldrassil's shadow train under mentors such as Erion Shadewhisper. When one shows exceptional talent, word reaches beyond the World Tree. Through Erion, Stormwind Intelligence, known as SI:7, invites the rogue across the Great Sea to the human capital. The journey leads from northern Kalimdor through the docks of Darkshore or the Wetlands to Stormwind City. In the capital, you make your way to SI:7 headquarters in Old Town and report to Renzik \"The Shiv.\" He assesses newcomers and opens the way to advanced espionage, poison mastery, and covert operations for the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2260-006e16800b7254b46405/1-0000.mp3", duration = 48.1697959, start = 0},
  },
}
P.transport["quest:2281"] = {
  hash = "070ac6",
  fullHash = "070ac6",
  text = "Redridge Rendezvous. Promising Alliance rogues are sent east from Stormwind’s intelligence headquarters to train in Lakeshire. SI:7 wants them ready for dangerous field work under seasoned operatives. Renzik 'The Shiv', SI:7’s second-in-command in Stormwind, warns that untrained rogues rarely survive dangerous operations. Sending raw recruits into hostile territory brings casualties instead of intelligence. SI:7 sends promising agents east to the Redridge Mountains, where they train under Lucius, stationed among Lakeshire’s docks. Lakeshire offers an ideal ground for clandestine training. Gnolls and Blackrock orcs threaten the frontier town, while its piers give Lucius cover to test a rogue’s stealth, reflexes, and lockpicking without attracting townspeople or guards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2281-6fc2f03be75a409b1d7e/1-0000.mp3", duration = 44.7216327, start = 0},
  },
}
P.transport["quest:2300"] = {
  hash = "0fb8c9",
  fullHash = "0fb8c9",
  text = "SI:7. In Goldshire, Keryn Sylvius sends promising young rogues toward Stormwind's hidden ranks. Recruits report to Renzik \"The Shiv\" in Old Town, where they enter Master Mathias Shaw's service. Keryn Sylvius watches local recruits from the Lion's Pride Inn in Goldshire. When a rogue proves cunning and capable against the growing Defias threat, Sylvius passes along a message from headquarters. The order is plain: report to Renzik \"The Shiv\" without delay. The recruit leaves Elwynn's fields for the covert heart of Stormwind. Behind an unassuming barracks in Old Town, SI:7 keeps its headquarters. Master Mathias Shaw commands the agency, whose work includes covert operations, reconnaissance, and assassination across the kingdom and beyond. Renzik \"The Shiv,\" Shaw's sharp-tongued second-in-command, assesses promising agents before sending them into dangerous work beyond the reach of the kingdom's formal military.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2300-99416827af1b682b083c/1-0000.mp3", duration = 55.1183673, start = 0},
  },
}
P.transport["quest:233"] = {
  hash = "d80792",
  fullHash = "d80792",
  text = "Coldridge Valley Mail Delivery. Coldridge Valley Mail Delivery is a simple courier task entrusted to recruits by Sten Stoutarm at Anvilmar. With mountain passes often choked with snow and troggs pressing nearby, carrying fresh correspondence out to the camps along the frozen lake keeps the valley's isolated defenders connected. Life in Coldridge Valley is secluded even in the calmest of seasons. When winter couriers successfully navigate the mountain pass with mail from the rest of Dun Morogh, the missives pile up quickly at Anvilmar. Sten Stoutarm, busy managing local supply concerns and security, relies on wandering recruits to carry these bundles down the western road rather than letting vital tidings languish in the hall. The intended recipient, Talin Keeneye, keeps watch by the frozen lake to the west, observing trogg movements and dangerous wildlife. Even out in the cold, word from Ironforge and surrounding outposts remains precious. However, mail sorting under harsh mountain conditions is rarely flawless, and letters bound for different scouts often travel together in a single bundle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_233-839b14ac9e7ee4a03a29/1-0000.mp3", duration = 60.7346939, start = 0},
  },
}
P.transport["quest:234"] = {
  hash = "700b0c",
  fullHash = "700b0c",
  text = "Coldridge Valley Mail Delivery. This errand completes a courier run across the snowy drifts of Coldridge Valley. Passing the dispatch from mountaineer Talin Keeneye down the southeastern road ensures that Grelin Whitebeard stays connected to the dwarven capital. Even in an isolated basin like Coldridge Valley, news and formal correspondence must travel. While Anvilmar serves as the administrative heart of the valley, field scouts and sentries stationed along the trails rely on foot couriers to relay dispatches between the high passes and Ironforge. Grelin Whitebeard maintains a small camp down the road to the southeast of Talin Keeneye's post. Enduring freezing drifts and constant trogg harassment, veteran mountaineers stationed at these remote watchpoints depend on regular missives to stay informed of broader affairs across Dun Morogh and the kingdom beyond.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_234-21f1d06738fb35a72b7b/1-0000.mp3", duration = 47.5167347, start = 0},
  },
}
P.transport["quest:2378"] = {
  hash = "43e6f8",
  fullHash = "43e6f8",
  text = "Find the Shattered Hand. In Orgrimmar, the Shattered Hand awaits a promising Forsaken rogue from Tirisfal Glades. The Deathstalkers send the initiate across the sea to Durotar to learn specialized arts from the clan. Mennet Carkad has seen a rogue prove their worth in Tirisfal Glades. The Forsaken train their own covert order, the Deathstalkers, and their alliance with the Horde opens a path to learn darker arts. He directs promising rogues to seek the Shattered Hand in Orgrimmar, joining Lordaeron’s undead operatives with Kalimdor’s orcish assassins. The journey ends beneath Orgrimmar in the Cleft of Shadow, where warlocks, rogues, and demon-binders work out of sight. Shenthul, a Shattered Hand trainer, awaits there. The gruff troll judges the newly arrived undead agent with harsh skepticism. Reputation alone will not satisfy him; he wants to see whether the envoy has real cunning or has wasted the voyage across the Great Sea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2378-0e00fcb9550d5134117d/1-0000.mp3", duration = 54.2302041, start = 0},
  },
}
P.transport["quest:2379"] = {
  hash = "e85d14",
  fullHash = "e85d14",
  text = "Zando'zan. In Orgrimmar's Cleft of Shadow, promising rogues begin training with the Shattered Hand. Trainer Shenthul sends his chosen initiate to meet Zando'zan and enter the Horde's covert ranks. Orgrimmar's rulers know brute strength cannot win every war. Beneath the city, the Cleft of Shadow houses the Shattered Hand, a covert guild that handles espionage, sabotage, and theft for the Horde. When rogue trainer Shenthul sees promise in an initiate, he sends them to report to Zando'zan for dedicated operative training. Zando'zan does not grant respect to every inexperienced rogue who enters the cavern. Meeting him marks a formal initiation into the finer clandestine arts, beginning with stealth, subterfuge, and thievery. His training bridges the distance between rough street cutpurses and organized intelligence operatives, preparing rogues for fieldwork beyond the safety of the capital's red canyon walls.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2379-26abbc29afd0d91f2d77/1-0000.mp3", duration = 54.3869388, start = 0},
  },
}
P.transport["quest:2380"] = {
  hash = "fc1410",
  fullHash = "fc1410",
  text = "To Orgrimmar!. Kaplak sends a young rogue from Razor Hill to Orgrimmar. There, you are to find Shenthul in the Cleft of Shadow and enter the Shattered Hand's network. Kaplak sends you north from Razor Hill to Orgrimmar. Your budding skills have caught the notice of more prominent handlers, though they remain unpolished. The red crags of Durotar are behind you as you make for the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2380-8c82ffa8e41dff71a75c/1-0000.mp3", duration = 22.4391837, start = 0},
  },
}
P.transport["quest:2381"] = {
  hash = "781398",
  fullHash = "781398",
  text = "Plundering the Plunderers. Wrenix the Wretched sends new Shattered Hand rogues against the Southsea Freebooters near Ratchet. Aboard the Tide Razor, they face pirates, locked strongboxes, and a dangerous guardian before claiming the Southsea Treasure. Wrenix the Wretched, a goblin contact in Ratchet, tests aspiring Shattered Hand operatives. He sends rogues south along the Barrens coast to a cove where the Tide Razor lies at anchor, crewed by Southsea Freebooters. They must board without being seen, enter the pirates’ den where cutpurses train, pick the strongboxes in the hold, and bring back the plunder.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2381-c57a0ac063681388e38a/1-0000.mp3", duration = 34.0114286, start = 0},
  },
}
P.transport["quest:2382"] = {
  hash = "d37968",
  fullHash = "d37968",
  text = "Wrenix of Ratchet. In Orgrimmar, Wrenix of Ratchet draws Horde rogues toward a goblin port far to the south. Zando'zan sends them to aid Wrenix the Wretched, a disreputable goblin in Ratchet. In Orgrimmar's Cleft of Shadow, the rogue guild works out of winding crevices, largely unseen. Zando'zan, a troll who speaks in wild ramblings, greets operatives with ominous portents. His visions include Warchief Thrall struck down by poison and blade. He gives no explanation for the prophecy, and quickly sends agents south to the port town of Ratchet in the Barrens. Ratchet lies on the Barrens coast, east of the Crossroads. Scoundrels, mercenaries, and tinkerers gather in the neutral port, where Wrenix the Wretched makes his home. Wrenix has little patience for Zando'zan's eccentric ways. He says the troll's earlier recruits met grim ends in the bay, among its hungry predators.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2382-44af4f851cb53075cbf2/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["quest:239"] = {
  hash = "8cb8ca",
  fullHash = "8cb8ca",
  text = "Westbrook Garrison Needs Help!. Marshal Dughan sends available adventurers west to Westbrook Garrison, the outpost at Elwynn Forest's border with Westfall. Stormwind's army is stretched thin across the kingdom, while Deputy Rainer and his guards face growing pressure from Riverpaw gnolls and wandering thieves without regular reinforcements. Westbrook Garrison guards the western edge of Elwynn Forest, where settled woodland meets Westfall's troubled plains. Gnoll warbands and bandits grow bolder along the waterways and western roads, and the small garrison has asked for more men. Marshal Dughan and Goldshire's administration have no Stormwind soldiers to spare. Local commanders must hire traveling mercenaries and wandering adventurers. Deputy Rainer and his men face the Riverpaw gnolls, whose raiding parties harass travelers and nearby homesteads. The pack operates in the borderlands between Elwynn and Westfall. With Stormwind distracted by political and military troubles, the gnolls press deeper into inhabited territory. Westbrook Garrison guards against their unchecked advance into the heart of the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_239-ffb3c0b22a6cd5dcbefe/1-0000.mp3", duration = 61.675102, start = 0},
  },
}
P.transport["quest:2399"] = {
  hash = "b168bb",
  fullHash = "b168bb",
  text = "The Sprouted Fronds. At Denalan's garden by Lake Al'Ameth, the planted frond has taken root and sprouted. Travelers can see the new growth among the garden beds. You find Denalan's garden near Lake Al'Ameth, where the botanist studies Teldrassil's peculiar plants. After a shimmering frond is planted, new fronds rise from the soil in his planter, ready to be gathered and examined. Teldrassil is young and vast, and its plant life grows quickly. Night elf herbalists find that growth fascinating and troubling. The shimmering fronds and their offshoots show how quickly life takes hold on the World Tree's boughs, though its vitality can be hard to predict.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2399-f40c4c0d94674fe66508/1-0000.mp3", duration = 39.8628571, start = 0},
  },
}
P.transport["quest:2438"] = {
  hash = "36050c",
  fullHash = "36050c",
  text = "The Emerald Dreamcatcher. In Dolanaar, Tallonkai Swiftroot asks you to recover a cherished heirloom from his abandoned home in Starbreeze Village. Gaerolas Talvethren, the druid warden, gave him the Emerald Dreamcatcher, which he left behind when corrupted Gnarlpine furbolgs overran the settlement. Recovering it keeps its gentle nature magic from falling into foul hands. Gaerolas Talvethren gave Tallonkai a rare druidic talisman. The warden watches over the sleeping druids within Ban'ethil Barrow Den. Crafted to channel the serene currents of the Emerald Dream, the amulet draws on that pure spiritual energy to bring peace and fortune to its bearer. Such gifts go only to a trusted few whose lives are bound to the forest's care. Starbreeze Village was peaceful until the Gnarlpine furbolgs succumbed to violent madness. They drove the villagers from their ancestral homes. During the fearful flight, Tallonkai left his most treasured possession hidden inside his dresser in the village's southeastern quarter. He could not reclaim it on his own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2438-f1aa0b4e14030e53081e/1-0000.mp3", duration = 60.9959184, start = 0},
  },
}
P.transport["quest:2459"] = {
  hash = "5707f1",
  fullHash = "5707f1",
  text = "Ferocitas the Dream Eater. Tallonkai Swiftroot in Dolanaar sends you after a stolen emerald in northern Teldrassil. The jewel was pried from his damaged heirloom dreamcatcher by Gnarlpine furbolgs north of Starbreeze Village, and now hangs from their leader, Ferocitas the Dream Eater. Tallonkai Swiftroot felt relief when the dreamcatcher recovered from the corrupted wilds came back to him, then dismay at its ruined state. The sacred artifact had been vandalized, its emerald centerpiece pried from the woven frame. Night elves spoke of Gnarlpine mystics north of Starbreeze Village, fallen under the influence of a furbolg leader named Ferocitas the Dream Eater. He wore a brilliant green stone around his neck. In Ferocitas's clutches, the sacred gem was useless and perverse, so Tallonkai sent defenders to take it back. The Gnarlpine furbolgs in Teldrassil's northern reaches were once peaceful neighbors. Corruption seeping into the World Tree drove them into frenzy and madness. Their mystics once practiced harmonious nature rites, but began drawing on distorted magical energies. Travelers can track down Ferocitas by cutting through the mystics guarding his woodland enclave. The jewel can then be returned to Tallonkai, so his dreamcatcher may be made whole and balance restored to the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2459-e5f72e7ccf093a251c21/1-0000.mp3", duration = 72.96, start = 0},
  },
}
P.transport["quest:2498"] = {
  hash = "57a7f7",
  fullHash = "57a7f7",
  text = "Return to Denalan. At Lake Al'Ameth, Return to Denalan carries Rellian's alarming news to the botanist studying corruption in Teldrassil. After examining the mossy tumors on timberlings, you head south to help Denalan with his discovery. Rellian Greenspyre studies the mossy tumors afflicting Teldrassil's timberlings when urgent word arrives from his colleague Denalan. At his camp beside Lake Al'Ameth, Denalan has finally isolated the cause of these unnatural growths on the forest's nature spirits. Rellian recognizes the gravity of this discovery and sends you south at once to lend a hand.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2498-07b5df67bfd57ba3296e/1-0000.mp3", duration = 31.8693878, start = 0},
  },
}
P.transport["quest:2499"] = {
  hash = "6d9ec9",
  fullHash = "6d9ec9",
  text = "Oakenscowl. Along Lake Al'Ameth, blight spreads from a corrupted timberling called Oakenscowl. Denalan asks you to end the threat. The maddened creature dwells in a cave on the lake's southern bank. Timberlings tend the boughs of Teldrassil, and Oakenscowl once led them. Now corruption runs through the world tree, reaching humble wildlife and ancient protectors alike. A massive growth swells across Oakenscowl's bark, driving the timberling mad. Where it once guarded the forest, blight now takes hold. Oakenscowl hides in a cavern on Lake Al'Ameth's southern shore. Its presence poisons the nearby water and woodland beasts. Denalan cannot face the creature alone, so he seeks its destruction to cut off the corruption and study the strange growth afflicting the lake's spirits.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2499-6361310715291b0d06d4/1-0000.mp3", duration = 45.7665306, start = 0},
  },
}
P.transport["quest:2518"] = {
  hash = "9112ae",
  fullHash = "9112ae",
  text = "Tears of the Moon. At the Temple of the Moon, Priestess A'moora mourns Lady Sathrah's madness. Once cherished by Elune, the great spider has become dangerous, and the Sisterhood seeks to end her suffering and recover her sacred spinnerets. In Darnassus's Temple of the Moon, Priestess A'moora grieves for Lady Sathrah. Sathrah was once blessed by Elune. Beneath the night sky, she wove delicate silver webs that caught the evening mist on Teldrassil's boughs. The Sisterhood of Elune gathered and kept the shimmering dew from those webs, which held healing powers for their sacred ministrations.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2518-89a879fdf90f71892141/1-0000.mp3", duration = 33.4628571, start = 0},
  },
}
P.transport["quest:2519"] = {
  hash = "493e5a",
  fullHash = "493e5a",
  text = "The Temple of the Moon. In Darnassus, Sister Aquinne calls for aid to a suffering ancient creature in Teldrassil. The Sisterhood of Elune needs help, and this is the opening call to a solemn ritual of mercy. Sister Aquinne asks for help in the Temple Gardens. As a devoted servant of Elune, she speaks for her order: a venerable forest creature is suffering, and the Sisters cannot attend to it alone. Sister Aquinne sends you southeast to the Temple of the Moon. Priestess A'moora coordinates the rituals and practical duties needed to address Teldrassil's troubled wildlife, preparing allies to carry out a sorrowful act of mercy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2519-a845233920614470a128/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["quest:2520"] = {
  hash = "1c5ee5",
  fullHash = "1c5ee5",
  text = "Sathrah's Sacrifice. At the Temple of the Moon, Sathrah's Sacrifice gives a fallen creature's spirit a final rite. You carry Lady Sathrah's spinnerets to Elune's sacred waters, where the Priesthood seeks to cleanse her soul of corruption. Priestess A'moora asks you to perform a final rite after Lady Sathrah is slain. The great spider fell to the dark madness spreading across Teldrassil, which twisted her peaceful nature into mindless aggression. The Priesthood of Elune seeks to redeem her fallen essence, not treat her death as a simple culling. You place her silvery spinnerets in the fountain at the heart of the Temple of the Moon. Its consecrated waters wash away the corruption and grant her release.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2520-d5e6e2b23b39b48730d3/1-0000.mp3", duration = 40.9077551, start = 0},
  },
}
P.transport["quest:2541"] = {
  hash = "33396e",
  fullHash = "33396e",
  text = "The Sleeping Druid. Oben Rageclaw lies asleep in Ban'ethil Barrow Den, but his spirit is caught in the Emerald Dream. Gnarlpine shamans have drawn it from his body and set his flesh moving through the den. Night elf druids sleep in barrow dens across Kalimdor while their spirits wander the Emerald Dream. Their bodies rest in stone alcoves, safe through centuries of slumber. Teldrassil's corruption has driven the Gnarlpine furbolgs to desperate savagery. In Ban'ethil Barrow Den, Gnarlpine shamans found a way to breach Oben Rageclaw's sacred rest and draw his living spirit from his sleeping body.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2541-b7cf0514271eac8fcd69/1-0000.mp3", duration = 34.6644898, start = 0},
  },
}
P.transport["quest:2561"] = {
  hash = "da3e75",
  fullHash = "da3e75",
  text = "Druid of the Claw. Oben Rageclaw’s spirit waits in the barrows beneath Teldrassil, unable to rest. The Gnarlpine furbolgs have bound his body with a dark enchantment, and you can break that bond by destroying his soulless shell. Oben Rageclaw was resting in the barrows beneath Teldrassil when the corrupted Gnarlpine furbolgs laid a voodoo enchantment over his sleeping body. The magic tore his spirit from his mortal flesh and trapped it in the Emerald Dream. Now his spirit lingers nearby, unable to rest or reclaim his body.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2561-fdcc53da5bb88052380e/1-0000.mp3", duration = 30.6416327, start = 0},
  },
}
P.transport["quest:26"] = {
  hash = "d73c2b",
  fullHash = "d73c2b",
  text = "A Lesson to Learn. Mathrengyl Bearwalker sends young druids from Darnassus to Moonglade to learn the ways of water. There, they meet an elder of the Cenarion Circle and begin training in their aquatic aspect. Mathrengyl Bearwalker guides young night elf druids as they practice among Darnassus’s boughs. When an initiate shows a firm bond with nature and readiness for greater responsibility, Mathrengyl sends them toward mastery of the waters. Cenarius’s gifts demand focus, and learning to cross the depths without drowning calls for guidance from the Cenarion Circle’s elders. The initiate leaves Darnassus for Moonglade, an ancient sanctuary beneath Mount Hyjal. In Nighthaven, Dendrite Starblaze waits as an elder mentor of the Cenarion Circle. Starblaze judges whether young shapeshifters are ready for the trials that lead to aquatic form. Mastering water takes both physical resilience and mental resolve.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_26-dc8e91f0a55e48579659/1-0000.mp3", duration = 51.0432653, start = 0},
  },
}
P.transport["quest:267"] = {
  hash = "5b53b9",
  fullHash = "5b53b9",
  text = "The Trogg Threat. The Trogg Threat is an Alliance quest issued by Captain Rugelfuss at the Southern Gate of Loch Modan. With the local Ironforge Reserve called away to support Alliance battlefronts, the remaining defenders are stretched thin against the hostile trogg tribes in the hills. Adventurers are tasked with culling the troggs and returning with their stone teeth to relieve pressure on the mountain pass. The defensive line guarding the southern approach into Loch Modan is in a precarious state. The regular dwarven mountaineers and Ironforge Reserve regiments have been dispatched to reinforce broader Alliance war fronts, leaving Captain Rugelfuss and a skeleton garrison stationed at the southern guard tower. Constrained by strict orders not to abandon the gate, Rugelfuss cannot mount an active offensive into the highlands, leaving nearby settlers and travelers vulnerable to ambushes. Troggs residing in the surrounding crags pose an escalating danger to Khaz Modan. Left unchecked, their numbers swell quickly, threatening to overrun dwarven outposts. To buy time and thin the menace, Rugelfuss calls upon wandering adventurers to assault the troggs directly in their hillside warrens and present severed stone teeth as physical confirmation of the deed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_267-7e95b0f1d15c29b5e584/1-0000.mp3", duration = 71.4187755, start = 0},
  },
}
P.transport["quest:2751"] = {
  hash = "4fdaeb",
  fullHash = "4fdaeb",
  text = "Barbaric Battlements. In Orgrimmar, Orokk Omosh seeks someone to carry on his family's forge craft. With no heirs, he asks an aspiring smith to prove a sure hand with bronze before sharing his knowledge. Orokk Omosh works the anvils of Orgrimmar under the weight of his family's past. For twenty generations, the Omosh line has shaped ore into weapons and armor for the Horde. Orokk has no kin and cannot sire children, and he sees himself as a failure to that line. With the family craft at risk of ending, he sets bloodline pride aside and seeks an apprentice to carry its smithing traditions forward. Orokk will not share his secrets with an untested smith. He asks for two patterned bronze bracers, two bronze greatswords, and two sharp beast claws as proof of basic skill at the anvil. To him, blacksmithing is no idle luxury: its highest honor is armor and steel stained with enemy blood. Meeting his demands may persuade the old smith that the Omosh legacy can live on through an apprentice, and earn a chance to learn more of the craft.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2751-83b633d38884be357dba/1-0000.mp3", duration = 60.8653061, start = 0},
  },
}
P.transport["quest:2753"] = {
  hash = "278cba",
  fullHash = "278cba",
  text = "Trampled Under Foot. In Orgrimmar's Valley of Honor, Orokk Omosh puts smiths through an advanced blacksmithing trial. Forging green iron armor tests their endurance and teaches them to make heavy iron boots, with the Omosh bloodline's secret techniques at stake. Orokk Omosh trains armorsmiths in Orgrimmar through hard physical trials. He sees metalworking as more than heating ore and shaping it; the work honors his ancestral clan and tests a smith's endurance. This is the third trial in his chain, and repeated crafting of tempered green iron armor is meant to build muscle and discipline. Smiths who bring Orokk the requested green iron gear earn rare praise from the gruff armorsmith. He compares an artisan who endures the work to his grandfather, Chief Gorokk of Omosh. In exchange for the armor, Orokk teaches the ancestral design for sturdy iron boots, made so Horde warriors can crush their enemies beneath their heels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2753-fbb2ebd9753c0b54d544/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["quest:2755"] = {
  hash = "f093ae",
  fullHash = "f093ae",
  text = "Joys of Omosh. After an adventurer's great help, Orokk Omosh shares a family tradition in Orgrimmar. The veteran blacksmith brushes off his tears as soot, then performs the Omosh dance of joy to pass down an unusual piece of family heritage. Near Orgrimmar's scorching forge, Orokk Omosh is known for heavy hammer blows, not tears. The burly blacksmith has received great help from you, and the kindness overwhelms him. He stubbornly blames a stray bit of soot in his eye rather than admit he is weeping. Before you part, Orokk says he must share one last secret of the Omosh family. He performs the vigorous, exhausting Omosh dance of joy for his apprentice, then teaches the apprentice to strike with an iron fist.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2755-56a80a51efa88ff82a2a/1-0000.mp3", duration = 42.475102, start = 0},
  },
}
P.transport["quest:282"] = {
  hash = "f497c4",
  fullHash = "f497c4",
  text = "Senir's Observations. Having gathered vital intelligence on local threats in Coldridge Valley, Grelin Whitebeard entrusts you with carrying his findings to his brother, Senir Whitebeard, out in Kharanos. However, leaving the sheltered valley requires passing through a tunnel recently overrun by hostile troggs, guarded by Mountaineer Thalos. Grelin Whitebeard spent considerable effort documenting the troll activity stirring around Coldridge Valley. When his journal was pilfered and subsequently recovered, it became clear that the collected intelligence was far too critical to trust to an inexperienced apprentice. Looking to bypass intermediate hands, Grelin selects a seasoned adventurer to convey his report directly to his brother, Senir Whitebeard, who conducts operations outside the valley in Kharanos. Leaving Coldridge Valley is no longer a simple trek down the main road. The eastern tunnel connecting the valley to the wider snowy plateau of Dun Morogh has been violently overrun by burrowing troggs. To prevent unwary civilians from wandering into a deathtrap, the Ironforge guard has stationed Mountaineer Thalos just outside the passage. Only travelers carrying urgent, official business are granted leave to push past the sentry post and brave the subterranean gauntlet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_282-a3c78b448652c22df09a/1-0000.mp3", duration = 69.8253061, start = 0},
  },
}
P.transport["quest:287"] = {
  hash = "83b32b",
  fullHash = "83b32b",
  text = "Frostmane Hold. Frostmane Hold is an Alliance recon mission assigned by Senir Whitebeard in Kharanos. Having tracked the hostile Frostmane trolls to their heavily guarded cavern stronghold near Iceflow Lake, Senir enlists adventurous scouts to brave the interior, eliminate their headhunters, and supply vital intel for his scouting reports. Stationed in Kharanos, mountaineer and scout Senir Whitebeard was tasked with monitoring the encroaching Frostmane troll threat across Dun Morogh. While he successfully traced the aggressive tribes back to their primary cavern dwelling southwest of Brewnall Village, the sheer volume of armed trolls gave him pause. Reluctant to step foot inside alone and falling severely behind on his official reports, Senir hires passing adventurers to venture into the icy recesses on his behalf. The stronghold sits carved into the western peaks overlooking Iceflow Lake, a freezing redoubt packed with hostile ice trolls. To fulfill Senir's mission, scouts must fight their way deep through the subterranean tunnels, cull the fierce Frostmane Headhunters stationed along the ledges, and map the interior layout. Surviving the delve provides the critical intelligence Senir requires to finalize his findings for Ironforge's military commanders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_287-d5d741b2ce6953c8fc38/1-0000.mp3", duration = 71.915102, start = 0},
  },
}
P.transport["quest:291"] = {
  hash = "4fb9b9",
  fullHash = "4fb9b9",
  text = "The Reports. Carry Senir Whitebeard's report on the Frostmane trolls from Kharanos to Senator Barin Redstone in Ironforge. Senir warns that the senator is sour and asks you not to mention who helped gather the information. After daring reconnaissance deep inside Frostmane Hold, Senir Whitebeard drafts an urgent report detailing the growing troll threat facing Dun Morogh. Stationed out of Kharanos, the mountaineer needs a courier to deliver these intelligence findings directly to Senator Barin Redstone in Ironforge. Eager to preserve his own reputation in the eyes of the government, Whitebeard cheerfully advises his runner not to mention who actually did the hazardous legwork out in the snowy crags.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_291-e0a0618a539507f76dae/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["quest:2950"] = {
  hash = "75d896",
  fullHash = "75d896",
  text = "Nogg's Ring Redo. In Orgrimmar, Nogg works to improve a ring recovered from Gnomeregan. He asks for rare materials and information about Dark Iron dwarves, eager to prove goblin craft superior to gnomish design. You bring a cleaned gold ring from Gnomeregan to Nogg's workshop in the Valley of Honor. The goblin engineer takes one look at its modest gnomish craft and offers a bargain. Bring raw materials and a modest fee, and he will add an intricate lattice of silver and moss agate to the band, meant to amplify the magic within it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2950-41df78ffb9457101f35f/1-0000.mp3", duration = 32, start = 0},
  },
}
P.transport["quest:2997"] = {
  hash = "605816",
  fullHash = "605816",
  text = "Tome of Divinity. The Tome of Divinity is an introductory summons calling young dwarven paladins from their field duties in Dun Morogh to the mountain city of Ironforge. Dispatched by Azar Stronghammer, the initiate is directed to seek guidance from Tiza Battleforge high in the Hall of Mysteries. It marks the formal beginning of a paladin's deeper trials in service to the Holy Light. While dwarven initiates begin their training protecting the snowbound villages and roads of Dun Morogh, martial prowess alone does not make a paladin. Azar Stronghammer recognizes when a defender has grown ready for deeper spiritual instruction. Rather than continuing standard martial drills, he sends promising candidates into the heart of Ironforge to begin their true initiation under the city's revered holy elders. The summons directs the initiate to the Mystic Ward, climbing into the quiet chambers of the Hall of Mysteries. There, surrounded by sacred relics and solemn study, stands Tiza Battleforge. As one of the most respected dwarven champions of the Light, she tests incoming paladins on their readiness to embrace self-sacrifice, mercy, and the heavy moral duties of their holy calling.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2997-8c0eebc94908ca7adfa9/1-0000.mp3", duration = 66.56, start = 0},
  },
}
P.transport["quest:2998"] = {
  hash = "a0a670",
  fullHash = "a0a670",
  text = "Tome of Divinity. A summons bearing the Tome of Divinity calls promising paladins from Elwynn to Stormwind. Answering Brother Wilhelm's call begins the sacred trials needed to master resurrection through the Holy Light. Novice paladins in Elwynn Forest spend their early days helping locals and testing their strength against wolves, Defias bandits, and kobolds. When an initiate shows martial discipline and devotion to the Holy Light, mentors such as Brother Wilhelm send a personal summons. Leaders of the paladins take note of promising students and direct them to leave the local chapels behind and report straight to the kingdom's spiritual heart. In Cathedral Square, Stormwind's Cathedral of Light is the supreme sanctuary of the kingdom's priesthood and the Knights of the Silver Hand. Duthorian Rall resides there and oversees those sworn to the Order. Beneath its soaring vaulted ceilings, high-ranking paladins set formal trials from the Tome of Divinity before each initiate. The challenges test compassion, fortitude, and a willingness to sacrifice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2998-3cf953dca8ea00d86efb/1-0000.mp3", duration = 58.644898, start = 0},
  },
}
P.transport["quest:2999"] = {
  hash = "76bfc1",
  fullHash = "76bfc1",
  text = "Tome of Divinity. Tome of Divinity is a rite of passage quest offered to young dwarven paladins serving in Dun Morogh. Directed by Brandur Ironhammer, the paladin trainer in Ironforge's Hall of Mysteries, an initiate is sent upstairs to speak with the respected paladin trainer Tiza Battleforge. It marks the transition from basic martial training into the deeper spiritual duties and sacred vows of the Holy Light. While novice paladins spend their early days defending Anvilmar and Kharanos from troggs and frost trolls, their duties eventually call for deeper devotion. Brandur Ironhammer, recognizing that an initiate has proven their martial discipline, advises them to take a break from their work in the snowy passes and seek guidance upstairs in his own Hall of Mysteries in Ironforge. There, senior paladins oversee the spiritual maturation of the order. Tiza Battleforge stands as one of the most revered paladins among the Ironforge dwarves. It is her responsibility to instruct initiates on the true burdens of the Light, moving past simple swordplay and hammer swings to teach compassion, justice, and self-sacrifice. Seeking her out begins the formal study of the Tome of Divinity, a sacred process aimed at granting a paladin the ability to resurrect the fallen.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_2999-b3411581b07f24d7b43e/1-0000.mp3", duration = 73.7436735, start = 0},
  },
}
P.transport["quest:3000"] = {
  hash = "899ee9",
  fullHash = "899ee9",
  text = "Tome of Divinity. This errand directs dwarven paladins wandering abroad to return home to Ironforge to further their sacred calling. Offered by Lord Grayson Shadowbreaker in Stormwind, it points fledgling champions toward Tiza Battleforge, one of the most respected instructors in the Hall of Mysteries. Returning home marks the beginning of their formal trials with the Tome of Divinity. While dwarven paladins frequently aid the kingdom of Stormwind and venture throughout human territories, their spiritual and martial roots remain anchored in Khaz Modan. Lord Grayson Shadowbreaker, recognizing when a dwarf's training in the field has progressed enough, advises them to return to the heart of Ironforge. There, their own people oversee the profound spiritual obligations expected of a full Knight of the Silver Hand. Upon returning to the mountainous capital, the paladin is directed to the Mystic Ward. Deep within the Hall of Mysteries, atop its upper level, resides Tiza Battleforge. She serves as a venerated mentor to the younger generation of dwarven paladins, preparing them to shoulder the burden of the Holy Light through the sacred trials recorded in the Tome of Divinity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3000-ec732b7be816f2edad16/1-0000.mp3", duration = 64.4702041, start = 0},
  },
}
P.transport["quest:3065"] = {
  hash = "cd50f2",
  fullHash = "cd50f2",
  text = "Simple Tablet. In the Valley of Trials, a marked parchment sends you to Frang after you prove yourself against local beasts. The warrior trainer waits outside the Den. After you prove you can face the Mottled Boars, Gornek hands you a parchment marked specifically for you. Durotar is harsh, and the Horde quickly gives its fighters guidance. The parchment directs you to Frang, the veteran warrior trainer outside the Den. Frang shelters in the shade outside the Den and watches recruits arrive from the red scrubland. With a seasoned eye, he judges each new arrival before teaching the fundamentals, whether with a heavy axe or a spear. He prepares each recruit to defend the young Horde's fragile settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3065-e5555b66a87d9c5830fc/1-0000.mp3", duration = 41.1428571, start = 0},
  },
}
P.transport["quest:308"] = {
  hash = "56ef8f",
  fullHash = "56ef8f",
  text = "Distracting Jarven. Down in the cellar of Thunderbrew Distillery, guard Jarven Thunderbrew finds himself surrounded by barrels he is forbidden to touch. Craving a taste of the family craft, he asks a passing adventurer for a mug of Thunder Ale to help sharpen his wits on duty. Jarven Thunderbrew is tasked with keeping watch over the deep stores of Thunderbrew Distillery in Kharanos. Despite being surrounded by the finest stout in Dun Morogh, he works under strict family orders not to dip into the stock while on guard. The temptation proves too much, prompting him to enlist passing travelers to fetch him a pint of potent Thunder Ale from the taps upstairs. Jarven insists that a good drink will only hone his senses and bolster his watch. Whether indulging a guard on duty is wise remains an open question, but among the hardy dwarves of Dun Morogh, few can fault a Thunderbrew for wanting a taste of his own kin's world-famous brew.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_308-b2ed9b4feb1ed436b198/1-0000.mp3", duration = 55.04, start = 0},
  },
}
P.transport["quest:3082"] = {
  hash = "43d53d",
  fullHash = "43d53d",
  text = "Etched Tablet. Gornek sends a carved tablet to hunters in the Valley of Trials. It bears Jen'shan's mark and calls them to begin training in the wilderness. Gornek brings novice hunters a carved tablet after they prove themselves against the boars near the Den. The stone bears Jen'shan's mark. She is a skilled troll huntswoman stationed nearby, and the message shows that seasoned hunters have noticed the young recruit's grit. The lesson now moves beyond surviving the local dangers and toward disciplined training in the wild. Jen'shan teaches that orcs and trolls have a long history within the Horde. Orcs brought renowned traditions of warriors and shamans, while the Darkspear trolls carried ancient skills in stalking, tracking, and survival. Those skills helped the orcs endure life on Azeroth. As Jen'shan trains new hunters, the two peoples continue to share what they know, bound by respect for the hunt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3082-e921ff0d0bb98b6adc44/1-0000.mp3", duration = 49.9983673, start = 0},
  },
}
P.transport["quest:3083"] = {
  hash = "6a4552",
  fullHash = "6a4552",
  text = "Encrypted Tablet. In the Valley of Trials, Gornek gives a coded summons to aspiring rogues. It sends them to Rwag in the Den, where rogue instruction meets the Shattered Hand. Gornek gives an Encrypted Tablet to each initiate who proves their mettle against the local wildlife. Its message is written in cipher, a fitting test and precaution for those trained in stealth, poison, and subterfuge. The summons directs the recruit into the Den to meet Rwag, who trains the Horde’s rogues, thieves, and cutpurses. Inside the Den, initiates find Rwag, an agent aligned with the Shattered Hand. He tells new rogues the guild will not dictate their every breath, but the Hand holds him accountable if an apprentice fails to perform. The fledgling Horde is surrounded by foes and relies heavily on silent scouts and agile cutpurses to gather intelligence and eliminate threats from the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3083-1eb2f327aa7cc3a720e3/1-0000.mp3", duration = 51.6179592, start = 0},
  },
}
P.transport["quest:3084"] = {
  hash = "22d087",
  fullHash = "22d087",
  text = "Rune-Inscribed Tablet. In the Valley of Trials, new shamans receive a summons from Shikrik. It calls promising initiates to formal training in the spirits and the elements: earth, fire, water, and air. Gornek gives fledgling shamans a carved stone tablet after they prove their early discipline in the dusty training grounds of the Valley of Trials. Its runes carry an invitation from Shikrik, the local shaman trainer. The summons tells each initiate they are ready to look beyond physical combat and heed the deeper currents of the natural world. Shamanism holds a sacred place in the revitalized Horde. Shikrik teaches that shamans draw power from the four elements and strength from ancestral spirits. They follow Warchief Thrall's example as spiritual guides and sources of wisdom for their communities. Across Durotar, they protect the settlements taking root.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3084-258f4f5c3b5923e369eb/1-0000.mp3", duration = 47.0465306, start = 0},
  },
}
P.transport["quest:3085"] = {
  hash = "5d9fc0",
  fullHash = "5d9fc0",
  text = "Hallowed Tablet. In the Valley of Trials, a message from Ken'jai reaches young priests after their first test. The tablet calls them to learn how Darkspear priests commune with the spirits. After you prove yourself against the boars under Gornek's watch, he gives you an inscribed stone called the Hallowed Tablet. Its message bears Ken'jai's mark. The Darkspear mystic waits outside the Den, where he watches over newcomers drawn to faith and spiritual magic. Darkspear priests among the Horde seek communion with spirits and loa, unlike human and dwarven priests who follow the Holy Light across the sea. Ken'jai welcomes you to Durotar and teaches that your power grows through spiritual discipline. He will instruct you in greater rites as your bond with the spirits matures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3085-c10800393b80756ece8d/1-0000.mp3", duration = 41.9265306, start = 0},
  },
}
P.transport["quest:3086"] = {
  hash = "043c52",
  fullHash = "043c52",
  text = "Glyphic Tablet. In the Valley of Trials, a Glyphic Tablet sends young Horde mages to Mai'ah. Gornek passes it to them after they prove their strength, and the troll trainer waits outside the Den. You have proved your strength against the Valley of Trials' wildlife, and Gornek gives you an inscribed tablet. Mai'ah, the valley's mage trainer, sent it. She asks you to find her by the Den's entrance when you are ready to begin your arcane studies. Mai'ah speaks plainly about the power mages wield and the danger that comes with it. She warns that their greatest threat is magic's unseen pull toward corruption, not rival warriors or enemy races. Humility and patience matter, she says, because unchecked sorcery can make a mage believe they have mastered more than they have.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3086-755a6957743d21b02431/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["quest:3087"] = {
  hash = "71c8a2",
  fullHash = "71c8a2",
  text = "Etched Parchment. In the Valley of Trials, Etched Parchment calls a young hunter to Jen'shan. Gornek delivers it after the initiate's first blooding, opening the way to wilderness training in Durotar. After proving themselves against mottled boars, hunters in the Valley of Trials receive an etched parchment from Gornek. Jen'shan, a skilled Darkspear hunter, sent the note after watching new arrivals from the edges of the encampment. It welcomes the initiate to formal training and recognizes the instincts needed to master Durotar's untamed beasts and harsh land. Reporting to Jen'shan marks the move from recruit to dedicated stalker. She warns that hunting is no easier than the arcane arts or ancestral shamanism. Mastering Durotar's predators, maintaining ranged weapons, and surviving on unforgiving land all demand discipline. Jen'shan sends her apprentices to aid the valley's other inhabitants and test their abilities before returning to learn more advanced survival techniques.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3087-d0cca7bf5c0fa789e10c/1-0000.mp3", duration = 56.084898, start = 0},
  },
}
P.transport["quest:3088"] = {
  hash = "8e9261",
  fullHash = "8e9261",
  text = "Encrypted Parchment. In the Valley of Trials, Encrypted Parchment sends proven novice orc rogues into the Den. Its cipher points them to Rwag, an agent of the Shattered Hand. Gornek passes the coded parchment to novice orcs who have proved themselves against the local wildlife. Other trainers recruit pupils openly in the clearing, but rogue instructor Rwag sends his summons by cipher. The message directs you beyond the sunlit camp and deep into the cavern called the Den. Inside the Den, you find Rwag keeping watch among the rock. Warlocks lurk deeper in the cave, and he tells you he watches recruits for the Shattered Hand. While orcish society prizes open honor and glory in battle, the Shattered Hand works as the Horde's hidden network of spies, cutthroats, and gatherers of intelligence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3088-79a9e98e14d9834f3a5b/1-0000.mp3", duration = 45.0612245, start = 0},
  },
}
P.transport["quest:3089"] = {
  hash = "790d76",
  fullHash = "790d76",
  text = "Rune-Inscribed Parchment. At the Valley of Trials, a rune-marked summons calls new shamans to Shikrik. Gornek delivers the parchment, which begins their formal training in communion with spirits and elements. After proving their survival skills against local wildlife, new orc shamans receive a rune-inscribed parchment from Gornek, overseer of the Valley of Trials. Its mystical writing comes from Shikrik, the valley's shaman trainer, who asks to meet the newly arrived initiate. Meeting Shikrik begins a shaman's sacred duty to the Horde. She teaches that shamans serve as conduits for ancestral spirits and wielders of elemental wrath. Under her guidance, new shamans learn to channel spiritual energies, mend wounds, and call upon Kalimdor's natural forces.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3089-e3204e759aeb7e293491/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["quest:3092"] = {
  hash = "2c52f5",
  fullHash = "2c52f5",
  text = "Etched Note. The Etched Note is a formal summons directed to promising young tauren hunters in Camp Narache. Delivered on behalf of the trainer Lanka Farshot, the message calls the novice forward to begin mastering the practical and spiritual arts of the wild. While training amidst the bluffs of Red Cloud Mesa, young tauren showing an aptitude for marksmanship and tracking are passed an etched message. Handed down through Grull Hawkwind, the note carries word that Lanka Farshot has taken notice of the youth's bloodline and raw capability, urging them to formalize their study beneath his watchful eye. To the Shu'halo, a hunter is far more than a simple scout or warrior. Hunters sustain the tribes through their quarry, protect nomadic encampments, and live in close balance with the beasts of Kalimdor. By calling the novice into training, Lanka sets the groundwork for mastering weapons, understanding the creatures of Mulgore, and eventually undertaking the ancient art of taming wild companions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3092-3ce78ebe2cb84ccee489/1-0000.mp3", duration = 57.364898, start = 0},
  },
}
P.transport["quest:3094"] = {
  hash = "1d0c27",
  fullHash = "1d0c27",
  text = "Verdant Note. The Verdant Note is a formal summons delivered to promising young tauren in the Red Cloud Mesa. Entrusted by Grull Hawkwind, the message bids budding protectors of the wilds to seek out the druidic mentor Gart Mistrunner at Camp Narache. Young tauren stepping into their responsibilities on the Red Cloud Mesa are quickly singled out for their natural gifts. Grull Hawkwind passes along this missive on behalf of a messenger sent by Gart Mistrunner. The note acts as an invitation into the ancient fold of tauren druidism, calling the initiate away from basic village errands to heed the whispering balance of the plains. Upon answering the summons, Gart Mistrunner warns the fledgling druid that ancestral and natural spirits have grown restless across Mulgore. Tauren druids are tasked to act as living avatars of nature, keeping harmony with the will of the Earthmother regardless of distant rivalries. While night elves also practice druidic arts, Gart cautions that their pride blinds them to the tauren's own deep-seated bond with the natural realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3094-53287df2ddaf9cd246c3/1-0000.mp3", duration = 57.7567347, start = 0},
  },
}
P.transport["quest:3096"] = {
  hash = "90a31a",
  fullHash = "90a31a",
  text = "Encrypted Scroll. The Encrypted Scroll is a discreet summons delivered to freshly awakened Forsaken rogues in Deathknell. Passed along by Shadow Priest Sarvis, the cipher directs the recruit to David Trias, a rogue mentor operating quietly out of the local inn. While newly raised Forsaken battle mindless zombies in the cemetery, the settlement's leadership takes note of those with particular inclinations toward stealth and subterfuge. Shadow Priest Sarvis passes this sealed parchment to promising scouts once their initial readiness is proven. Stamped with the discreet seal of David Trias, it serves as an early introduction to the shadowy network operating beneath the Forsaken hierarchy. David Trias watches the crossroads and inn of Deathknell, scouting prospects for future clandestine operations. Rather than seeking common thieves or reckless cutpurses, the Forsaken require disciplined covert operatives to serve the fledgling kingdom. Trias hints that capable rogues may eventually catch the eye of the Shadowstalkers, a dedicated cadre within the Forsaken who prize cunning, precision, and absolute loyalty to the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3096-c366dfdfb5ae23f0fd1d/1-0000.mp3", duration = 64.6269388, start = 0},
  },
}
P.transport["quest:3097"] = {
  hash = "0fdf48",
  fullHash = "0fdf48",
  text = "Hallowed Scroll. The Hallowed Scroll is an introductory summons directed to newly awoken Forsaken priests in Deathknell. Handed over by Shadow Priest Sarvis, the missive calls the novice to Dark Cleric Duesten inside the shattered village chapel to learn how the undead wield faith after death. As newly awakened undead stagger from the graves of Deathknell, their minds are often reeling from the trauma of the plague, death, and sudden liberation from the Lich King's grip. For those who were once devout followers of the Holy Light in life, confusion runs exceptionally deep. While fledgling undead battle the mindless Scourge haunting the settlement's perimeter, Shadow Priest Sarvis intercepts incoming messages. Bearing the mark of Dark Cleric Duesten, the hallowed scroll bids newly risen priests to abandon their wandering and report to the desecrated town chapel. Upon delivering the scroll, a novice encounters the harsh theology of Forsaken priesthood. Dark Cleric Duesten pulls no punches: the Holy Light abandoned them in death, ancestral spirits are hollow tales, and planar demons have no interest in their plight. Instead, Forsaken clergy teach that sheer willpower and radical self-reliance are the only true sources of salvation. Under Duesten's tutelage, newly risen practitioners learn to channel both divine discipline and shadow, wielding power not out of devotion to distant gods, but out of absolute conviction in their own survival.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3097-1072b8f0984c75d670db/1-0000.mp3", duration = 81.8416327, start = 0},
  },
}
P.transport["quest:3098"] = {
  hash = "8cda9a",
  fullHash = "8cda9a",
  text = "Glyphic Scroll. The Glyphic Scroll is an official summons delivered to newly awakened Forsaken mages in Deathknell. Bearing the seal of the mage trainer Isabella, the parchment directs promising practitioners of the arcane to seek her out in the desecrated village church to hone their volatile powers. When a freshly raised Forsaken demonstrates an affinity for arcane magic while culling mindless Scourge around Deathknell, they quickly catch the attention of their elders. Delivered by hand, the Glyphic Scroll is marked with the arcane sigil of Isabella, the local mage instructor. It bids the newly risen practitioner to report to her station within the ruined church, recognizing that unregulated magical aptitude poses as much danger to the Forsaken as it does to their enemies. Within the ruined chapel of Deathknell, Isabella instructs fledglings that death has not exempted them from the perils of the arcane. While mortality has stripped away their physical frailties, the volatile pull and corrupting nature of magic linger just as fiercely. For the Forsaken, pursuing arcane dominance is not merely an intellectual pursuit, but an instrument of survival and vengeance—a means to reclaim their destiny and obliterate any who challenge their fragile reclamation of Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3098-f77926ddd532b48125ca/1-0000.mp3", duration = 71.9934694, start = 0},
  },
}
P.transport["quest:310"] = {
  hash = "5e95a7",
  fullHash = "5e95a7",
  text = "Bitter Rivals. Bitter Rivals is an early Alliance quest in Dun Morogh born from the fierce competition between two proud dwarven brewing families. Marleth Barleybrew sends an adventurer to infiltrate the Thunderbrew Distillery in Kharanos and tamper with their rival's stock. Few things in Khaz Modan stir passions as quickly as a pint of ale. The Barleybrews have long bristled under the shadow of the famed Thunderbrew Distillery in Kharanos. While Marleth Barleybrew begrudgingly concedes that Thunderbrew craft is respectable, she cannot stomach the notion that it is the only renowned vintage in Dun Morogh. To shake up the local palate, she devises a plan to swap a cask of Thunder Ale with her own fiery concoction, Barleybrew Scalder. Carrying out the scheme requires slipping directly beneath the noses of Kharanos patrons. Beneath the kitchen of the distillery lies the basement storeroom where aging casks await tapping. Because the Thunderbrews keep a guard posted near their most prized reserve, a would-be saboteur must find a way to lure the watchman away before secretly substituting the barrels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_310-83d011a081c6ec534577/1-0000.mp3", duration = 62.2236735, start = 0},
  },
}
P.transport["quest:3103"] = {
  hash = "024a2d",
  fullHash = "024a2d",
  text = "Hallowed Letter. The Hallowed Letter is a formal summons given to promising young priests by Marshal McBride on behalf of Northshire Abbey's resident trainer, Priestess Anetta. It marks the start of a fledgling priest's formal mentorship in the tenets of the Holy Light amidst a troubled and vulnerable world. After proving their mettle against the kobold camps around Northshire, novitiate priests are handed a missive bearing the sacred seal of Priestess Anetta. Delivered through Marshal McBride, the letter serves as an invitation to begin serious study of the Holy Light within the abbey's quiet halls. When presented with the letter, Priestess Anetta impresses upon her new pupil the grim state of the realm. Lingering threats from the Burning Legion cast long shadows across Azeroth, while the continents struggle with fresh wounds and unrest. In her eyes, taking up the mantle of a priest is not merely an academic devotion, but an urgent moral responsibility to bring healing and solace to a suffering world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3103-d307a19b751cbd5233bf/1-0000.mp3", duration = 55.4318367, start = 0},
  },
}
P.transport["quest:3104"] = {
  hash = "d9bd66",
  fullHash = "d9bd66",
  text = "Glyphic Letter. A sealed summons reaches novice human mages in Northshire Valley, sent by Marshal McBride. Khelden Bremen calls promising spellcasters to Northshire Abbey to begin their arcane tutelage. Marshal McBride gives the rune-marked letter to an aspiring apprentice who has proved capable by helping him against local vermin. Khelden Bremen, Northshire's resident mage trainer, wrote it. He watches new recruits arriving at the abbey for signs of magical discipline and talent. Northshire Abbey has long been a sanctuary of the Holy Light, but Stormwind's dangers call for practitioners of every discipline. The letter brings you upstairs to Khelden Bremen. He offers no easy praise. Instead, he warns that mastering arcane power means defying natural limits, earning both profound respect and deep fear from ordinary folk.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3104-24309b50765a48c33dfe/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["quest:3105"] = {
  hash = "918f1e",
  fullHash = "918f1e",
  text = "Tainted Letter. At Northshire, Tainted Letter calls novice human warlocks away from the Abbey guards for instruction in the fel arts. Drusilla La Salle entrusts it to Marshal McBride, who delivers it to her recruits. Novice warlocks receive a letter from Marshal McBride after proving themselves against the kobold menace. While priests and paladins study openly in Northshire Abbey, warlocks must tread carefully. Drusilla La Salle's insignia marks the letter, which directs each fledgling spellcaster to her secluded post outside the abbey's main walls before taking on other duties. Drusilla warns that warlocks walk a precarious path under the watchful eyes of Stormwind's guards, whom she calls 'pathetic mundanes.' Drawing power from the Twisting Nether and communing with demons always risk corruption. She counsels patience, prudence, and firm self-control when handling those dark energies, but says caution must not extinguish a warlock's ambition.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3105-f9fb3ffe97c48f70c660/1-0000.mp3", duration = 54.3869388, start = 0},
  },
}
P.transport["quest:3106"] = {
  hash = "dc4a64",
  fullHash = "dc4a64",
  text = "Simple Rune. Simple Rune is an introductory task given to novice dwarven warriors in Coldridge Valley. Passed along by Sten Stoutarm on behalf of the warrior trainer Thran Khorman, it directs fresh recruits inside Anvilmar to begin their martial training. As young recruits clear pests and prove their grit around Coldridge Valley, veteran scouts keep a watchful eye out for promising fighters. Sten Stoutarm delivers an inscribed stone—a simple rune—handed off to him by Thran Khorman. This summons calls martial hopefuls from the snowy valley paths into the warm forge-hall of Anvilmar to formally pledge themselves to the warrior's trade. Reporting to Thran offers an immediate glimpse into the harsh realities facing modern Dun Morogh. The veteran trainer speaks frankly about the kingdom's shifting landscape: displaced gnomes seeking refuge after catastrophic explosions destroyed Gnomeregan, fellow dwarves wielding foreign arcane arts or taking up human devotion to the Holy Light, and an ever-present menace of subterranean troggs clawing at the mountain borders. In Thran's eyes, solid martial discipline remains the bedrock required to withstand it all.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3106-ed976d199b37e2d32329/1-0000.mp3", duration = 67.2653061, start = 0},
  },
}
P.transport["quest:3107"] = {
  hash = "74c5ee",
  fullHash = "74c5ee",
  text = "Consecrated Rune. The Consecrated Rune is an introductory summons delivered to fledgling dwarven paladins in Coldridge Valley. Passed along by Sten Stoutarm on behalf of Bromos Grummner, it marks an initiate's formal induction into the Knights of the Silver Hand. While novice adventurers clear out troggs and wolves around Coldridge Valley, the local leaders keep a close eye on those who display a gift for divine martial prowess. Sten Stoutarm delivers this inscribed rune to young paladins, instructing them to seek out Bromos Grummner inside the warmth of Anvilmar. It serves as both an invitation and an official notice that raw potential must now be tempered with discipline. Though the Knights of the Silver Hand originated among the humans of Lordaeron, Ironforge dwarves embraced the philosophy of the Holy Light with fierce devotion. Bromos Grummner welcomes initiates into the brotherhood, reminding them that dwarven paladins now share the solemn duty of protecting Azeroth. Grounded in sacrifice, tradition, and martial virtue, the order demands that recruits take up hammer and faith in equal measure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3107-2625e9309e1c4fb43c36/1-0000.mp3", duration = 62.6416327, start = 0},
  },
}
P.transport["quest:3108"] = {
  hash = "0b60dd",
  fullHash = "0b60dd",
  text = "Etched Rune. The Etched Rune is a written summons delivered to novice dwarven hunters assisting the guard in Coldridge Valley. Passed on by Sten Stoutarm, the inscribed stone directs fledgling trackers to seek out Thorgas Grimson inside Anvilmar to formally begin their martial and wilderness training. While helping Sten Stoutarm deal with nearby threats around Coldridge Valley, promising dwarven hunters are handed an inscribed stone tablet known as the Etched Rune. Rather than delivering spoken orders or simple parchment, dwarven mentors favor carved runes to impart formal missives. The rune instructs the recipient to take stock of their early work and present themselves indoors at Anvilmar for deeper instruction in the art of the hunt. Presenting the rune to Thorgas Grimson marks a hunter's entry into formal discipline. Thorgas stresses that mountaineering and survival in Khaz Modan demand deep respect for the harsh environment: reading tracks in bitter snowdrifts, maintaining one's weapon and ammunition, and understanding the wild beasts that roam the crags. The etched stone serves as the hunter's first step from a lone wanderer with a gun into an apprentice of Anvilmar's veteran pathfinders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3108-1a9eb2fa4a0fe2cdf1da/1-0000.mp3", duration = 67.1085714, start = 0},
  },
}
P.transport["quest:3109"] = {
  hash = "fbaa54",
  fullHash = "fbaa54",
  text = "Encrypted Rune. The Encrypted Rune is a coded missive delivered to aspiring rogues taking their first steps in Coldridge Valley. Passed along by Sten Stoutarm, the etched message directs promising shadows into Anvilmar to report to the rogue trainer, Solm Hargrin. While assisting Sten Stoutarm out in the snowy passes of Coldridge Valley, sharp-eyed rogues receive a curious etched stone. Sten admits the piece was slipped to him to hand over, suspecting it came directly from Solm Hargrin. Rather than shouting out across the courtyard for potential scouts and scoundrels, Solm uses an encrypted rune to test a novice's discretion and summon them indoors. Inside Anvilmar, Solm Hargrin welcomes newly arrived operatives to the craft. He offers to teach the maneuvers, strikes, and subtle arts that keep an operative breathing and lining their pockets with coin. Beyond sharpening their daggers, Solm reminds dwarven rogues to look out for their displaced gnomish allies, who are still recovering from the catastrophic fall of Gnomeregan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3109-a5b41b4af349877c64e2/1-0000.mp3", duration = 60.5518367, start = 0},
  },
}
P.transport["quest:311"] = {
  hash = "cdf622",
  fullHash = "cdf622",
  text = "Return to Marleth. Return to Marleth marks the mischievous conclusion to a heated brewing feud in Dun Morogh. Having infiltrated the Kharanos cellar and swapped in a keg of Marleth's fiery Scalder, an adventurer returns to Brewnall Village with a prize barrel of Thunder Ale as indisputable proof. Dwarven rivalries are rarely settled with diplomacy when there is ale on the line. Marleth Barleybrew of Brewnall Village harbors a fierce competitive grudge against the distillers of Kharanos, creators of the famed Thunder Ale. After having her potent 'Scalder' slipped into the Thunderbrew cellar unnoticed, Marleth demands evidence of the feat. Hoisting a genuine barrel of Thunder Ale from beneath their noses serves as both trophy and leverage. Hauling the heavy keg back across the snowswept ridges to Brewnall Village finishes the caper. Marleth is thrilled to see the plan succeed, gleefully reveling in outsmarting Kharanos's guards and cellar masters. While harmless on the surface, the stunt cements the fierce, uncompromising pride that different dwarven families pour into their signature recipes across Dun Morogh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_311-7638f6b44693dbdc7a84/1-0000.mp3", duration = 63.5036735, start = 0},
  },
}
P.transport["quest:3110"] = {
  hash = "1c620c",
  fullHash = "1c620c",
  text = "Hallowed Rune. Hallowed Rune is an introductory quest for fledgling dwarven priests in Coldridge Valley. Sten Stoutarm passes along an inscribed rune from priest trainer Branstock Khalder, summoning the novice inside Anvilmar to deepen their connection with the Holy Light. While assisting Sten Stoutarm with clearing the immediate threats outside Anvilmar, a newly arrived priest catches the eye of the settlement's spiritual guide. Branstock Khalder entrusts Sten with a hallowed rune inscribed with prayers and guidance, directing the young adventurer to step inside the sturdy halls of Anvilmar to formally begin their sacred studies. Though dwarven culture often emphasizes martial fortitude and heavy plate, the Holy Light remains a cornerstone of Ironforge society. In Coldridge Valley, holy casters play a vital role alongside warriors and hunters in shielding the enclave from aggressive trogg incursions and dangerous wildlife creeping through the snow drifts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3110-5a4788625d583f2c8744/1-0000.mp3", duration = 54.3085714, start = 0},
  },
}
P.transport["quest:3112"] = {
  hash = "dc8a39",
  fullHash = "dc8a39",
  text = "Simple Memorandum. The Simple Memorandum is a missive delivered to aspiring gnome warriors starting out in Coldridge Valley. Passed along by Sten Stoutarm outside, it directs newly trained fighters into Anvilmar to meet Thran Khorman, who has pledged to prepare them for reclaiming Gnomeregan. While clearing out the troggs and boars troubling Coldridge Valley for mountaineer Sten Stoutarm, a young gnome warrior receives a brief message slipped into the dwarf's hands. Recognizing the potential in the refugee recruit, veteran trainer Thran Khorman uses the memorandum to call the newcomer into Anvilmar's central hall to begin proper martial instruction. Though dwarven trainers might occasionally tease gnome warriors about their diminutive stature, Thran Khorman takes their struggle seriously. Sympathizing with the loss of Gnomeregan, Thran likens the gnomes' plight to how dwarves would feel if Ironforge fell to the Dark Irons. In honoring his word, he pledges to instruct exile fighters in the arts of warfare until they are ready to win back their home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3112-25a6a504adf76b057ded/1-0000.mp3", duration = 56.2416327, start = 0},
  },
}
P.transport["quest:3113"] = {
  hash = "99055b",
  fullHash = "99055b",
  text = "Encrypted Memorandum. The Encrypted Memorandum is an introductory summons directed at fledgling gnome rogues arriving in Coldridge Valley. Passed through Sten Stoutarm, the disguised note quietly directs new operatives to seek out Solm Hargrin inside Anvilmar. While newcomer gnomes assist the mountaineers of Coldridge Valley with local trogg threats, Sten Stoutarm delivers a folded piece of parchment passed to him in confidence. Posing superficially as an official memorandum, the note is an invitation to meet Solm Hargrin, the resident rogue trainer stationed inside Anvilmar. The message reflects the uneasy reality facing the gnomes after the sudden fall of Gnomeregan. Displaced from their subterranean home, gnome survivors must share close quarters with their dwarven hosts in Dun Morogh. Solm Hargrin recognizes that rogues draw suspicion when items vanish, and he advocates for unspoken solidarity among practitioners of the craft to ensure their mutual survival.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3113-e0ef653806fcf47d1aa3/1-0000.mp3", duration = 55.5102041, start = 0},
  },
}
P.transport["quest:3114"] = {
  hash = "cedb72",
  fullHash = "cedb72",
  text = "Glyphic Memorandum. Glyphic Memorandum is an introductory task directing novice mages in Coldridge Valley to their local trainer inside Anvilmar. Entrusted to mountaineer Sten Stoutarm, the missive summons budding arcane practitioners to seek out the eccentric gnome Marryk Nurribit to begin their formal spellcraft studies. While assisting mountaineer Sten Stoutarm with early duties across Coldridge Valley, newly arrived mages find themselves summoned by local arcane authority. Sten receives a written memorandum addressed to the fledgling spellcaster and passes it along, advising them to take a moment to read its contents and head inside the warmth of Anvilmar to meet its author. The author of the memorandum is Marryk Nurribit, a gnome mage trainer stationed inside Anvilmar. Rather than drowning his pupil in dense theoretical lectures, Marryk offers straightforward, grounded advice: stay out of serious trouble, save coin for training and tavern drinks, and strictly avoid the radioactive disaster that is fallen Gnomeregan. With basic expectations set, Marryk stands ready to tutor newcomers in the arcane arts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3114-77ecbdf6512d8f038a8a/1-0000.mp3", duration = 61.9885714, start = 0},
  },
}
P.transport["quest:3115"] = {
  hash = "4d510d",
  fullHash = "4d510d",
  text = "Tainted Memorandum. Tainted Memorandum is an introductory quest for fledgling gnome warlocks taking their first steps in Coldridge Valley. Passed quietly through Sten Stoutarm, the missive summons the neophyte to the shadows of Anvilmar to meet Alamar Grimm, who preaches self-reliance through dark power rather than trust in their dwarven hosts. Even in the frozen outpost of Coldridge Valley, the practice of the dark arts is met with deep suspicion. While helping Sten Stoutarm deal with local threats, young gnome warlocks receive a slipped note. Sten delivers it reluctantly, giving voice to the uneasy truce that allows warlocks in Alliance lands: 'watch yerself... your kind ain't too trusted 'round these parts.' Upon answering the note, the warlock meets Alamar Grimm lurking inside the halls of Anvilmar. Grimm does not mince words regarding the gnomes' plight. To his eyes, conventional tinkering and ordinary magic failed Gnomeregan utterly, driving their people to near extinction and leaving them stranded as second-class refugees dependent on dwarf goodwill. Rather than praying to the Holy Light or putting faith in dwarven politics, Grimm urges his pupil to summon and master fiends who offer unconditional obedience.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3115-048265cf0270ef957436/1-0000.mp3", duration = 69.7469388, start = 0},
  },
}
P.transport["quest:3116"] = {
  hash = "74f738",
  fullHash = "74f738",
  text = "Simple Sigil. In Shadowglen, Alyissia calls young night elf warriors to defend their people. Conservator Ilthalaine carries her summons as the Kaldorei face changes across Teldrassil and beyond. After you prove your basic survival skills against Shadowglen's restless wildlife, Conservator Ilthalaine gives you an inscribed sigil. The token formally marks your move into combat training. It carries a request from Alyissia, the warrior trainer at Aldrassil, asking you to dedicate your strength to defending your people. Alyissia sets your training against a time of rapid change and danger. In only a few years, the night elves have raised the World Tree Teldrassil, seen a taint spread through forest beasts near and far, and reconnected with ancient lands once thought lost, including Feralas. The Kaldorei need capable defenders against these perils. Alyissia prepares young Kaldorei for more than combat. She urges you not to judge outsiders who arrive on Teldrassil by their race. Some travelers may not act from pure generosity, but allies are vital to the Kaldorei's defense. As you take up the work of protecting your people, she asks you to offer them reasonable trust.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3116-58fd9399d256c5d516cc/1-0000.mp3", duration = 70.9485714, start = 0},
  },
}
P.transport["quest:3117"] = {
  hash = "923432",
  fullHash = "923432",
  text = "Etched Sigil. In Shadowglen, the Etched Sigil calls young night elf hunters to Aldrassil. Through Conservator Ilthalaine, Ayanna Everstride summons them to meet their trainer and begin learning archery and beastcraft. After young kaldorei hunters help defend Shadowglen, Conservator Ilthalaine gives them an inscribed token. A messenger brought it from their mentor, Ayanna Everstride. The sigil directs each novice up into Aldrassil’s high boughs, where the trainers watch over the canopy. Meeting Ayanna begins a hunter’s training on Teldrassil. She teaches novices marksmanship and how to understand Kalimdor’s wild creatures. A hunter must respect their beast companions and meet the world’s unseen dangers with awareness and humility.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3117-5a420b31eb21e6a88766/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:3118"] = {
  hash = "3e661f",
  fullHash = "3e661f",
  text = "Encrypted Sigil. In Shadowglen, a coded summons calls new night elf rogues to begin their training. Conservator Ilthalaine carries it for Frahun Shadewhisper, who also warns of the fragile peace across Kalimdor. While young night elves study nature's balance under Conservator Ilthalaine, those drawn to stealth receive a quieter summons. A runner brings the Encrypted Sigil from Frahun Shadewhisper, Shadowglen's rogue mentor. Its ciphers are meant for initiates of the trade. The bearer is to decipher the message and find Frahun near the roots of Aldrassil to begin instruction. Frahun's message also warns of Kalimdor's uncertain peace. The Third War has ended, but the truce between the Alliance and the emerging Horde remains fragile. Rogue scouts and informers in Shadowglen are urged to sharpen their eyes and ears early. They watch for threats and covert provocations that could renew war across the borders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3118-a0c897d945d7b8ad7117/1-0000.mp3", duration = 52.9763265, start = 0},
  },
}
P.transport["quest:3119"] = {
  hash = "055b49",
  fullHash = "055b49",
  text = "Hallowed Sigil. In Shadowglen, young night elf priests are called to begin their training in Aldrassil. Conservator Ilthalaine passes along Shanda's message as novices learn to wield Elune's grace. Night elf priests serve Elune as handmaidens and servants of the moon goddess. When a young kaldorei in Shadowglen shows devotion and an affinity for the divine light, Conservator Ilthalaine gives them a hallowed sigil. Shanda, the priest trainer, sent the token by messenger as an invitation to come to Aldrassil and begin spiritual training. Shanda tells the young acolyte that unusual change has reached Teldrassil's sheltered sanctuary. Travelers fill the World Tree's boughs, including members of the wider Alliance who have leave to meet with the kaldorei. The wider world calls, but Shanda urges novices to first attend to the troubles facing Shadowglen before turning to conflicts beyond it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3119-06c310a0f5379ec3403f/1-0000.mp3", duration = 48.5616327, start = 0},
  },
}
P.transport["quest:312"] = {
  hash = "51cf63",
  fullHash = "51cf63",
  text = "Tundra MacGrann's Stolen Stash. Tundra MacGrann, an injured dwarven hunter living out in the cold crags of Dun Morogh, has lost his winter supplies to a notorious local beast. A massive yeti known as Old Icebeard hauled off MacGrann's thorium-reinforced meat locker into its den. Unable to outrun the beast on a bum leg, the hunter relies on passing adventurers to slip inside and retrieve his provisions. Surviving the harsh winters of Dun Morogh demands preparation, especially for mountaineers living outside the warmth of Kharanos and Ironforge. Tundra MacGrann had diligently salted away an entire month's worth of dried meats to outlast the coming cold season flurries. Taking precautions against hungry wild bears, he sealed his rations inside a reinforced thorium meat locker. Unfortunately, he did not account for the sheer brute strength of the mountain yetis, who carried the entire chest away rather than trying to open it on the spot. The culprit behind the theft is Old Icebeard, a feared and vicious yeti lurking in the jagged hills. While MacGrann was away hunting deer, Icebeard snatched the chest and dragged it back to his mountain cave. Though MacGrann remains confident that even a yeti cannot shatter solid thorium plating, his own injured leg makes a recovery mission suicidal. Any brave soul venturing into the cave must either contend directly with the beast or time their intrusion carefully while the monster is out prowling the snowdrifts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_312-2aad5f3303351cedef70/1-0000.mp3", duration = 81.5020408, start = 0},
  },
}
P.transport["quest:3120"] = {
  hash = "de83ae",
  fullHash = "de83ae",
  text = "Verdant Sigil. A summons reaches newly awakened night elf druids in Shadowglen. Conservator Ilthalaine passes the Verdant Sigil to fledgling shapeshifters, directing them to Mardant Strongoak within Aldrassil. The token marks the start of their formal training in nature and the Emerald Dream. When a young night elf shows promise in keeping Shadowglen's balance, the order calls for a formal introduction. A runner brings the Verdant Sigil to Conservator Ilthalaine, who entrusts it to the initiate. The token shows that the circle in Aldrassil has taken notice and invites the young druid to begin formal training. Presenting the sigil to Mardant Strongoak inside Aldrassil brings the initiate into the fold. Deeper communion with the Emerald Dream and mastery of animal forms lie ahead. For now, Mardant becomes their first guide, teaching them to read nature's spirits and channel the raw power of the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3120-0beb8a13f3e569c8fff9/1-0000.mp3", duration = 50.5730612, start = 0},
  },
}
P.transport["quest:313"] = {
  hash = "b05b40",
  fullHash = "b05b40",
  text = "The Grizzled Den. Pilot Stonegear of Kharanos is looking for someone with true dwarven grit to spruce up his beloved siege engine, Trollplow. To test an aspiring adventurer's mettle, he sends them west into the perilous cavern known as the Grizzled Den to hunt savage wendigos for their thick pelts. Operating a massive dwarven siege tank requires nerves of iron and the constitution to handle teeth-rattling machinery in freezing mountain air. Pilot Stonegear, stationed at Steelgrill's Depot near Kharanos, claims to have both in spades. Rather than simply giving up work or respect easily, he challenges newcomers to prove they possess the same stalwart temperament by trekking into the frozen hills to face native beasts. Stonegear's siege engine bears the proud and unsubtle name of Trollplow, but its cramped, iron-plated cabin is brutally cold in the bitter Dun Morogh climate. Stonegear hits upon a practical yet wild solution: wendigo pelt. Harvesting thick manes from the ferocious wendigos stalking the Grizzled Den provides the materials needed to fashion a durable, warm rug for Trollplow's deck while keeping local beast numbers in check.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_313-0509516b5a402b6f2473/1-0000.mp3", duration = 66.0636735, start = 0},
  },
}
P.transport["quest:317"] = {
  hash = "238d4f",
  fullHash = "238d4f",
  text = "Stocking Jetsteam. Stocking Jetsteam is an Alliance quest offered by Pilot Bellowfiz at Steelgrill's Depot in Dun Morogh. Preparing his siege engine for an extended deployment with the Ironforge Siege Brigade, the pilot enlists local hunters to gather boar meat and bear pelts to provision his crew. Stationed just outside Kharanos at Steelgrill's Depot, Pilot Bellowfiz oversees preparations for an upcoming long-haul operation on behalf of the Siege Brigade. His siege tank, dubbed Jetsteam, requires both mechanical tuning from master engineer Beldin Steelgrill and a month's worth of field provisions to keep its crew functional in the harsh sub-zero temperatures of Dun Morogh. Because Beldin Steelgrill is occupied under Jetsteam's hood, Bellowfiz cannot abandon his vehicle to gather rations and insulation. He directs travelers to hunt in the snowy plains south of the Grizzled Den, where indigenous boars provide hardy meat for food and native bears yield thick pelts suitable for warm tank bedding.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_317-9e8e88e427616412244b/1-0000.mp3", duration = 58.3836735, start = 0},
  },
}
P.transport["quest:318"] = {
  hash = "506d29",
  fullHash = "506d29",
  text = "Evershine. Evershine is an Alliance delivery quest beginning with Pilot Bellowfiz near Kharanos. The dwarven siege engine pilot sends travelers westward to Brewnall Village to fetch a potent dwarven brew concocted by Rejold Barleybrew. The liquor doubles as a warming drink and an emergency, high-octane fuel for Bellowfiz's siege engine. Dwarven brewing is famed throughout Khaz Modan, but Rejold Barleybrew's recipes in Brewnall Village push the boundaries of standard fermentation. His experimental beverage, Evershine, is infamous for knocking all but the sturdiest dwarves flat on their backs. Despite its fierce potency, it is prized in the bitter cold of Dun Morogh for its sheer heating power. Siege pilots often find unorthodox uses for everyday materials, and Pilot Bellowfiz is no exception. Operating out of Steelgrill's Depot outside Kharanos, Bellowfiz relies on Evershine not just as a nip to stave off the freezing winds, but as supplementary fuel. Dumping the volatile alcohol directly into the furnace of his siege engine, Jetsteam, provides an explosive surge of emergency power that has gotten him out of more than one tight spot.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_318-e1afb29f6a8fa6334c25/1-0000.mp3", duration = 68.6236735, start = 0},
  },
}
P.transport["quest:319"] = {
  hash = "36e03a",
  fullHash = "36e03a",
  text = "A Favor for Evershine. To secure a cask of Evershine for Pilot Bellowfiz at Steelgrill's Depot, an adventurer must first lend a hand to Brewnall Village. Brewer Rejold Barleybrew refuses to part with his liquor until the dangerous predators roaming the nearby snowdrifts are thinned out. Rejold Barleybrew has the cask of Evershine that Pilot Bellowfiz requires, but he is in no hurry to surrender his prized brew for free. Rather than asking for coin, Rejold asks for protection. The wild beasts of western Dun Morogh—ravenous Ice Claw Bears, thick-hided Elder Crag Boars, and prowling Snow Leopards—wander uncomfortably close to Brewnall Village, creating constant distraction and peril for the locals. While Rejold is quick to insist that no self-respecting dwarf cowers before wild animals, dealing with predators around the clock consumes valuable hours. Culling the local wildlife gives the villagers the peace they need to focus on distillation and smithing without keeping one eye perpetually on the tree line.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_319-7bbd335fed454bb3160a/1-0000.mp3", duration = 57.9657143, start = 0},
  },
}
P.transport["quest:3221"] = {
  hash = "c6c295",
  fullHash = "c6c295",
  text = "Speak with Renferrel. Speak with Renferrel is a brief errand within the Sepulcher in Silverpine Forest. High Executor Hadrec directs you back to the Royal Apothecary Society's local researcher to discuss findings regarding tainted wolf hearts. After assisting the Deathstalkers across Silverpine Forest, High Executor Hadrec passes along an urgent message from Apothecary Renferrel. Renferrel has spent time analyzing the discolored wolf hearts gathered from the local wildlife and requires your presence immediately. Apothecary Renferrel serves the Royal Apothecary Society from his laboratory inside the crypt at the Sepulcher. His ongoing work explores how dark magic and disease are altering the beasts of Silverpine, bridging frontline military recon with chemical research.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3221-9211cc673858756ab013/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["quest:3261"] = {
  hash = "6bdb32",
  fullHash = "6bdb32",
  text = "Jorn Skyseer. In the southern Barrens, seasoned Horde hunters seek guidance from Jorn Skyseer. After you hunt local raptors for Sergra Darkthorn, she sends you south to Camp Taurajo, where an elder tracker offers deeper lessons. You have hunted the cunning sunscale and scytheclaw raptors stalking the northern savannah, earning Sergra Darkthorn's respect at the Crossroads. She knows martial skill must be joined with understanding of the land's great beasts. With her mentorship complete, she sends you south. Follow the Gold Road south through increasingly rugged plains to Camp Taurajo, a vital tauren settlement near the southern wilds. Jorn Skyseer waits there, an elder tracker ready to teach hunters how to pursue elusive, legendary quarry across the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3261-35ac4459a317fdcbced9/1-0000.mp3", duration = 42.24, start = 0},
  },
}
P.transport["quest:3281"] = {
  hash = "de038f",
  fullHash = "de038f",
  text = "Stolen Silver. Gazrog at the Crossroads sends you after payroll silver stolen by raptors. Rumors of their cunning lead you south of Ratchet, into the Raptor Grounds. The garrison needs its wages back. Gazrog needs the Crossroads guards paid, and the raptors have taken their wages. You are sent to recover the stolen coin, not simply punish the beasts. When raptors ambushed the payroll shipment, Gazrog first sought vengeance. But killing the pack would not restore the missing money. The Horde must learn how the raptors carried off heavy crates of coin, and where they took them. Scouts found a raptor nest between two craggy peaks, south of Ratchet and northwest of Northwatch Hold. The creatures dragged the intact lockbox into their territory, where they guard it alongside eggs and fresh kills. Tales of raptor cunning and hoarding now seem true to Gazrog. Ordinary beasts rarely stash metallic valuables.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3281-4e9489d6a3d99940b87d/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["quest:33"] = {
  hash = "3b70e8",
  fullHash = "3b70e8",
  text = "Wolves Across the Border. Eagan Peltskinner asks you to hunt wolves prowling Northshire Valley and bring him their meat. He waits outside Northshire Abbey, where the valley’s needs continue despite the guards’ focus on Defias bandits. Eagan Peltskinner waits by Northshire Abbey’s walls with a grudge against the local timber wolves. Marshal McBride and the Stormwind guards have limited strength to defend the abbey from Defias bandits, while tradesfolk still have daily needs. Eagan asks you to thin the wolves’ numbers and bring back their tough meat for his cooking. Wolves roam closer to Northshire Abbey as patrols weaken. The Kingdom of Stormwind has too few troops and is strained by missing leadership. Young wolves and timber wolves now prowl the abbey’s paths and orchards. Hunting them supplies Eagan’s pantry and makes nearby trails safer for novitiates, laborers, and newly arrived defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_33-ecf970145c8988a1f845/1-0000.mp3", duration = 47.8563265, start = 0},
  },
}
P.transport["quest:3301"] = {
  hash = "d11b39",
  fullHash = "d11b39",
  text = "Mura Runetotem. You carry a snapjaw shell from the Barrens across the sea to Mura Runetotem in Silverpine Forest. Its strange vitality may help the tauren healer aid the Forsaken. Tonga Runetotem notices something peculiar about altered snapjaws while investigating the magically changed wildlife around the Barrens oases. Their shells pulse with resilient energy despite their corruption. He asks you to carry one across the Great Sea to his clanmate, Mura Runetotem, who is stationed in the Eastern Kingdoms. Mura Runetotem is at the Sepulcher, a Forsaken outpost in Silverpine Forest. She made the arduous journey there to help the Horde's newest allies cleanse and renew their ailing, blighted woodland. Mura hopes the shell's inner glow and enduring spark of life will reveal ways to restore vitality to the northern continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3301-2574f7012329da4b5fd5/1-0000.mp3", duration = 47.9346939, start = 0},
  },
}
P.transport["quest:332"] = {
  hash = "835225",
  fullHash = "835225",
  text = "Wine Shop Advert. In Stormwind, Renato Gallina draws passersby to his family's wine shop. He offers a voucher for a free bottle of vintage wine from their canal-side storefront, a small sign of trade in the reconstructed capital. Everyday life in Stormwind revolves around brisk commerce. Renato Gallina walks the Trade District's cobbled streets, promoting Gallina Winery, the small shop he runs with his sister, Suzetta. He hands flyers to thirsty travelers and locals, each offering a free tasting. The Gallina family offers a bottle of their famous pinot noir. Follow the ticket to the winery entrance near the canals, where Suzetta Gallina hands over the bottle. The family hopes a taste of their signature wine will bring newcomers back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_332-9310f78db5cf9d881ca5/1-0000.mp3", duration = 43.8595918, start = 0},
  },
}
P.transport["quest:333"] = {
  hash = "af4906",
  fullHash = "af4906",
  text = "Harlan Needs a Resupply. Harlan Bagley, a Stormwind merchant, cannot keep sturdy clothes and armor in stock. As demand surges, he sends an urgent cloth order to Rema Schneider at the Canal Tailor and Fit Shop, unaware of the conflicts brewing beyond the city walls. Across Stormwind City, Harlan Bagley's shelves are emptying fast. Citizens and wandering adventurers are buying reinforced tunics, traveling clothes, and battle-ready armor. Harlan wonders if people are preparing for a harsh season or winter, but the rush has left his shop short of finished cloth. Harlan sends a runner across the city's waterways to Rema Schneider, a seamstress at the Canal Tailor and Fit Shop. She is glad of his trade, yet the sudden demand for protective clothing troubles her. Rumors of tension spread through the kingdom, and Rema wonders whether the House of Nobles is hiding talk of open war from ordinary people.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_333-6d2dfc34c207e0d2da50/1-0000.mp3", duration = 54.0995918, start = 0},
  },
}
P.transport["quest:334"] = {
  hash = "e69294",
  fullHash = "e69294",
  text = "Package for Thurman. In Stormwind City, Rema Schneider needs her son Thurman’s tailoring supplies at Larson Clothiers in the Mage Quarter. He left home without his shears and needles, and Rema asks you to carry them to his workshop. Rema Schneider worries that Thurman will fall behind in his tailoring work without his shears and needles. He left home in a rush, and his mother asks you to carry the tools across Stormwind’s canals to his workshop.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_334-0c8941893b6f94e4c189/1-0000.mp3", duration = 22.3608163, start = 0},
  },
}
P.transport["quest:3361"] = {
  hash = "d39060",
  fullHash = "d39060",
  text = "A Refugee's Quandary. Following the disastrous fall of Gnomeregan to troggs and radiation, displaced gnomes have fled into the snowy wilds of Dun Morogh. Outside Anvilmar, an engineer named Felix Whindlebolt lost his vital belongings and tools to Frostmane troll scavengers during the panicked evacuation. When subterranean troggs overran the high-tech city of Gnomeregan, High Tinker Gelbin Mekkatorque and his advisors authorized the release of radioactive gas in a desperate bid to eradicate the invaders. The gambit backfired catastrophically, slaying thousands of innocents, mutating survivors into mindless leper gnomes, and forcing the remaining populace into a frantic exodus across Dun Morogh. Fleeing engineers and tinkerers carried whatever prized tools and blueprints they could save. However, the icy mountain passes between Gnomeregan and Coldridge Valley are prowled by indigenous Frostmane trolls. As Felix Whindlebolt scrambled toward the sanctuary of Anvilmar, Frostmane raiders snatched his tool chest, lockbox, and bucket of bolts, carting them off to their camps southwest of town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3361-7ef9fb3c2ae0d182edb5/1-0000.mp3", duration = 64.235102, start = 0},
  },
}
P.transport["quest:3364"] = {
  hash = "f947a2",
  fullHash = "f947a2",
  text = "Scalding Mornbrew Delivery. Scalding Mornbrew Delivery is a hurried errand through Coldridge Valley to deliver fresh hot drink before it chills in the mountain frost. Nori Pridedrift entrusts the delivery to an adventurer to ensure Durnan Furcutter receives his mornbrew piping hot. Dun Morogh's biting cold has ruined many a hot meal, and Mornbrew is no exception. After completing a delivery to Grelin Whitebeard, Nori Pridedrift realizes he lacks the time to bring another fresh cup to Anvilmar before it freezes into an unpalatable slush. Rather than let his customer down, he enlists any swift traveler willing to brave the snow. Durnan Furcutter, stationed inside the warmth of Anvilmar's mountain hall, is known to be particular about his refreshments. Chilly Mornbrew simply will not do. Delivering the piping drink intact earns a weary dwarf a much-needed break from his duties, though Nori still expects his favorite mug returned in one piece.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3364-c37c675bc47004572186/1-0000.mp3", duration = 55.4318367, start = 0},
  },
}
P.transport["quest:3365"] = {
  hash = "e2924b",
  fullHash = "e2924b",
  text = "Bring Back the Mug. After delivering a piping hot draught of Mornbrew across the snowdrifts of Dun Morogh, one final errand remains: returning the empty tankard. Durnan Furcutter sends the runner back across Coldridge Valley to return Nori Pridedrift's prized mug. It is a simple courtesy, but one the brew seller deeply appreciates. Serving piping hot Mornbrew out in the biting freeze of Dun Morogh is a delicate business. Once Durnan Furcutter has finished warming his bones with the scalding brew, the empty tankard cannot simply be tossed in the snow. Dwarven hospitality runs on mutual respect, and letting good dishware go missing is a sure way to find oneself cut off from future rounds. Returning to Coldridge Valley completes the delivery run for Nori Pridedrift. As Nori is fond of reminding forgetful couriers, sturdy drinkware does not simply grow on trees—especially not in the subzero crags of the dwarven homeland. Returning the empty vessel in one piece cements an adventurer's reputation as a reliable hand in the local community.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3365-ed3f175745b2af58ee3e/1-0000.mp3", duration = 62.2236735, start = 0},
  },
}
P.transport["quest:3376"] = {
  hash = "727d66",
  fullHash = "727d66",
  text = "Break Sharptusk!. Break Sharptusk! is a decisive rite of passage issued by Brave Windfeather on Red Cloud Mesa. To secure the tauren homeland against ongoing raids, young champions are sent east into Brambleblade Ravine to slay Chief Sharptusk Thornmantle. Eliminating the Bristleback chieftain strikes a severe blow against the quilboar encroaching upon Mulgore. The grassy heights of Red Cloud Mesa have long served as a peaceful sanctuary where young tauren learn the traditions of the hunt and attunement with the Earth Mother. However, this peace is constantly contested. To the east lies Brambleblade Ravine, a thorn-choked gulch claimed by the hostile Bristleback quilboar tribe. The quilboar view the tauren as invaders stealing sacred ground, launching relentless skirmishes against the tribes attempting to establish a stable life in Mulgore. The persistent attacks on the mesa are not aimless frenzy; they are coordinated under the brutal leadership of Chief Sharptusk Thornmantle. Residing in a fortified makeshift village deep within the ravine, Sharptusk directs his warriors and geomancers against the Shu'halo. Recognizing that the Bristleback will never cease their raids while their chief still draws breath, Brave Windfeather commands an aspiring hero to breach the ravine, strike down Thornmantle, and return with his severed head as proof. For young tauren and their allies, hunting Sharptusk is more than a simple execution—it is an initiation into the harsh realities of survival. As Brave Windfeather teaches, the hunt against beasts teaches patience, but hunting an enemy cunning enough to hunt back tests courage, awareness, and martial discipline. Bringing down Sharptusk delivers justice for fallen kin and marks the hunter's readiness to venture out into the wider plains of Mulgore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3376-7bc4fe7968e2f9a0abac/1-0000.mp3", duration = 103.392653, start = 0},
  },
}
P.transport["quest:35"] = {
  hash = "737fde",
  fullHash = "737fde",
  text = "Further Concerns. Marshal Dughan sends an Alliance courier east from Goldshire to check reports of danger. You cross Elwynn Forest to speak with Guard Thomas, who watches the river crossing toward Redridge. Rumors tell of hostile aquatic creatures creeping along Elwynn's riverbanks. Marshal Dughan commands the Goldshire garrison, where banditry and vermin already trouble the center of the forest. He will not dismiss the reports, but he cannot spare guards from town. Instead, he sends you east to consult Guard Thomas, the sentry at the bridge over the river toward Redridge. Guard Thomas has held the bridge outpost for more than a week and has seen what Goldshire's leaders only feared. Hostile, semi-intelligent murlocs have made camps along the waterways of eastern Elwynn. Stormwind's army is absent, while local garrisons protect town walls and supply lines. That leaves rural bridge posts like Thomas's isolated before the growing danger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_35-2132631c7216fac953d3/1-0000.mp3", duration = 54.8832653, start = 0},
  },
}
P.transport["quest:3519"] = {
  hash = "f3f4f3",
  fullHash = "f3f4f3",
  text = "A Friend in Need. Iverron lies bitten and in danger in Shadowglen. The young night elf calls for Dirania Silvershine, whose help may save him from Githyiss the Vile's venom. Iverron lies weakened after a bite from Githyiss the Vile. He ignored warnings and went too near the webwood caverns, where the vicious spider struck. Dizziness and failing strength leave him unable to reach safety alone. Iverron sends passersby toward Aldrassil's central tree to find Dirania Silvershine. She looks out for him and knows the dangers of Shadowglen. His life may depend on her preparing an antidote before the venom proves fatal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3519-4eb7f9364d0c3806465d/1-0000.mp3", duration = 34.4816327, start = 0},
  },
}
P.transport["quest:3521"] = {
  hash = "d99360",
  fullHash = "d99360",
  text = "Iverron's Antidote. Iverron's Antidote is an urgent task in Shadowglen to save a poisoned night elf scout. By gathering wild mushrooms, lilies, and spider ichor, adventurers help Dirania Silvershine brew a remedy before the venom takes full hold. While scouting the boughs of Shadowglen, young Iverron fell victim to the poisonous fangs of the local Webwood spiders. Collapsed and dying, his survival depends entirely on the herbal knowledge of Dirania Silvershine at Aldrassil. With the youth fading fast, she must quickly prepare a specialized concoction to neutralize the aggressive venom coursing through his blood. Dirania's recipe relies on the restorative flora of Teldrassil balanced against the venom itself. Hyacinth mushrooms, favored by the thieving grell to the south, provide an earthy base, while delicate Moonpetal lilies gathered from tranquil forest pools offer purifying qualities. To finish the draft, a sample of Webwood ichor must be extracted directly from the spiders prowling near Shadowthread Cave to tailor the cure to their specific poison.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3521-49458f35dc619844a7ee/1-0000.mp3", duration = 61.0220408, start = 0},
  },
}
P.transport["quest:3522"] = {
  hash = "743285",
  fullHash = "743285",
  text = "Iverron's Antidote. In Shadowglen, Iverron waits for medicine before its strength fades. Poisoned by Webwood spiders, the night elf scout depends on Dirania Silvershine's brew, which must reach him within five minutes. Dirania Silvershine brews the cure from fresh venom sacs, lily roots, and hyacinth fungi. The unstable mixture keeps its strength for only five minutes after it is distilled. Whoever carries the vial must sprint straight from the glade toward the northern heights without hesitation. Webwood spiders around Shadowglen's barrows and caves have poisoned Iverron. He admits he has a habit of stumbling into danger and often depends on Dirania's herbal skill to save him. Even after drinking the antidote, his recovery is fragile. The hostile spiders still guard his way home, and he remains wary of them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3522-71382b7a0ac5e6676b84/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["quest:3524"] = {
  hash = "07fb2e",
  fullHash = "07fb2e",
  text = "Washed Ashore. Along Darkshore, Washed Ashore begins an inquiry into the many sea creatures dying on its shore. Gwennyth Bly'Leggonde starts it in Auberdine for the Temple of the Moon in Darnassus, where priestesses fear the strandings may be an ill omen. Darkshore has seen great sea creatures beach themselves from time to time, a tragic but occasional sight. Now the strandings come in growing numbers along the coast. The Priestesses of Elune in the Temple of the Moon see more than a natural oddity in these deaths. They fear the pattern may bring ill omens to northern Kalimdor. The Temple of the Moon sends scholar Gwennyth Bly'Leggonde to the port town of Auberdine to learn why the great beasts are coming ashore. She gathers biological samples to send by hippogryph to Darnassus for close examination. But Greymist murlocs swarm the carcasses in the surf, scavenging the remains and keeping researchers from the bones without armed protection.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3524-7a186954c25da93797bc/1-0000.mp3", duration = 51.6702041, start = 0},
  },
}
P.transport["quest:353"] = {
  hash = "6eb906",
  fullHash = "6eb906",
  text = "Stormpike's Delivery. Grimand Elmore sends travelers north with an axe for Mountaineer Gringer Stormpike. The road leads from Stormwind's Dwarven District to an Ironforge outpost in Loch Modan. Grimand Elmore has been asked to make a weapon for Mountaineer Gringer Stormpike. The Stormpike clan is respected in Ironforge for its discerning taste and martial pride. Elmore turns to trustworthy travelers to carry the axe north, across the distance between Stormwind and the dwarven borderlands. At Loch Modan's northern guard tower, Mountaineer Stormpike watches over lands troubled by wandering troggs and burrowing kobolds. The southern human kingdoms face rumors of unrest and banditry, while the dwarven frontier has dangers of its own. Stormpike needs a new blade to help keep the mountain passes secure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_353-babe7c317845a8f95f5f/1-0000.mp3", duration = 45.6097959, start = 0},
  },
}
P.transport["quest:354"] = {
  hash = "6e1eea",
  fullHash = "6e1eea",
  text = "Deaths in the Family. Coleman Farthing, a former mill worker now dwelling in Brill, seeks personal vengeance against the aristocratic Agamand family. Convinced to stay and defend their estates against the Scourge during the Third War, Farthing and his fellow workers perished alongside their stubborn employers, only for the Agamands to rise as mindless thralls of the Lich King. Before the Third War devastated Lordaeron, the Agamand family stood as the wealthiest and most influential agrarian dynasty in Tirisfal Glades. Their sprawling mills and fertile pastures produced bountiful grain, commanding the labor of dozens of tenant farmers and millers. When the Plague of Undeath crept across the kingdom, the Agamands refused to flee or abandon their ancestral holdings, convinced that stone walls and loyal workers could hold off the horrors advancing from the east. Believing their lords' assurances, loyal employees like Coleman Farthing stood their ground to defend the estate. The defense proved futile against the Scourge's relentless onslaught. The Agamands and their workers were slaughtered, their bodies rotting where they fell before being raised into undeath. While Farthing eventually broke free through Sylvanas Windrunner's liberation, the Agamand patriarchs and heirs remained trapped under the Lich King's mental grip, wandering the ruined mills as mindless Scourge sentries. Now residing in Brill, Coleman Farthing harbors intense resentment toward the former masters whose arrogance cost him his mortal life. Seeking closure and retribution, he sends Forsaken champions to Agamand Mills to destroy Gregor, Nissa, and Thurman Agamand. Farthing openly hopes that behind their rotting visages, his former masters retained just enough consciousness to feel terror as their unlife was violently brought to an end.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_354-95ee14856adb123d4f73/1-0000.mp3", duration = 103.862857, start = 0},
  },
}
P.transport["quest:355"] = {
  hash = "c558d7",
  fullHash = "c558d7",
  text = "Speak with Sevren. Following the settling of Coleman Farthing's personal score at Agamand Mills, Magistrate Sevren summons the adventurer to Brill. The mills house far more than bitter family ghosts; they represent an active Scourge peril on the settlement's northern border. Coleman Farthing sought personal retribution against his former neighbors, the Agamands, sending travelers north to tear through the undead lurking about the flour mills. Once those remains were delivered, Coleman recognized that his private grudge intersected with a wider tactical problem: the entire Agamand estate remains swarming with mindlessly aggressive Scourge minions right on Brill's doorstep. Magistrate Sevren oversees civic and military security in Brill for the Dark Lady. Impressed by reports of an adventurer capable of surviving deep incursions into the haunted farmlands, Sevren steps in to direct those capable hands toward the root of the infestation—the ancient Agamand family crypt itself.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_355-20603fcf25e92f56a7b2/1-0000.mp3", duration = 54.5436735, start = 0},
  },
}
P.transport["quest:356"] = {
  hash = "1b5fd0",
  fullHash = "1b5fd0",
  text = "Rear Guard Patrol. Rear Guard Patrol is a military scouting mission tasked by Deathguard Linnea to protect the Forsaken defenses along Tirisfal's eastern border. It directs operatives to purge stray Scourge horrors and lingering spirits haunting the Balnir Farmstead before they can compromise the supply lines supporting the Bulwark. The Bulwark stands as the primary bulwark holding back the pestilence and armies of the Western Plaguelands from spilling into Tirisfal Glades. Deathguard Linnea oversees rear-echelon security along this frontier. Because the line cannot afford to divide its forces against ambushes from behind, any undead that bypass the choke point must be destroyed before they can sever the supply lines feeding the front. Once a working farm of eastern Tirisfal, the Balnir Farmstead fell to ruin during the Third War. Now thoroughly blighted, the overgrown fields and crumbling stables provide cover for interloping Bleeding Horrors and restless, Wandering Spirits. Clearing the site denies the Lich King a staging post inside Tirisfal itself and safeguards the road for Horde reinforcements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_356-008c4507434c856548a6/1-0000.mp3", duration = 62.7983673, start = 0},
  },
}
P.transport["quest:357"] = {
  hash = "8cb145",
  fullHash = "8cb145",
  text = "The Lich's Identity. The Lich's Identity is an Undercity quest given by Bethor Iceshard in the Magic Quarter. Seeking to uncover the identity of a reclusive lich living on Brightwater Lake, Bethor sends an emissary to steal the figure's spellbook to gauge his power and allegiance. North of the Undercity, in the misty waters of Brightwater Lake, a lone lich dwells in self-imposed exile on a small island. Unlike the mindless pawns of the Lich King, this necromancer possesses his own free will, yet he lives in deep paranoia. Convinced that any undead who approach him are Scourge thralls sent to drag him back into servitude, he unleashes his summoned minions on anyone setting foot on his shores. Word of the rogue lich eventually reached Bethor Iceshard, the archmage overseeing the mages in the Undercity. Bethor recognized the strategic importance of such an entity: Lady Sylvanas Windrunner seeks every scrap of magical mastery and every capable will to bolster the Forsaken against their many foes. To assess whether the hermit could be recruited, Bethor requires proof of his identity and necromantic expertise.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_357-3fc35399bd8eac4c67d7/1-0000.mp3", duration = 65.4367347, start = 0},
  },
}
P.transport["quest:358"] = {
  hash = "edb21a",
  fullHash = "edb21a",
  text = "Graverobbers. Magistrate Sevren of Brill tasks adventurers with purging Rot Hide gnolls from the Mass Grave southwest of Garren's Haunt. These undead beasts were sent by the Scourge to dig up the corpses of early plague victims to swell their ranks. Slaying them and recovering their embalming ichor protects the fallen and aids the Royal Apothecary Society's research. When the Plague of Undeath first tore through Tirisfal Glades, the dead piled up faster than formal burials could accommodate. Immense mass graves were dug across the north to contain the staggering loss. Until recently, those buried remains escaped resurrection. Now, however, the Scourge has unleashed Rot Hide gnolls upon the trenches southwest of Garren's Haunt, sending them to exhumate the decayed remains to reinforce the Lich King's armies. The Rot Hides are sustained by embalming ichor, an alchemical concoction that preserves and animates their rotting frames. By commanding scouts to slay the graverobbers and extract this fluid, Magistrate Sevren strikes two blows at once: halting the Scourge's harvest of raw bodies and delivering valuable biological specimens directly to the apothecaries in Brill, who seek to turn the Lich King's own craft against him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_358-b6024c33c97c0d534f7d/1-0000.mp3", duration = 70.4783673, start = 0},
  },
}
P.transport["quest:36"] = {
  hash = "f2f772",
  fullHash = "f2f772",
  text = "Westfall Stew. In Westfall, another family is leaving its farm as banditry drives homesteaders from their land. Before departing, Verna Furlbrow entrusts her cherished local recipe to Salma Saldean. Defias thieves and wild mechanical harvest reapers have driven Verna and Farmer Furlbrow from their family acreage. They pack their wagon and prepare to seek refuge behind Stormwind's walls. Before leaving, Verna gives her neighbor Salma Saldean the recipe for Westfall Stew, hoping the farm's home-cooked tradition will live on. Salma Saldean and her husband, Farmer Saldean, still hold their homestead just down the road. Verna's recipe marks the loss of another neighbor to the unrest, yet keeps a local farm tradition alive. Salma sets out to gather the ingredients needed to feed those still struggling on the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_36-50b9efe4f8742039c2db/1-0000.mp3", duration = 47.0465306, start = 0},
  },
}
P.transport["quest:360"] = {
  hash = "cd5880",
  fullHash = "cd5880",
  text = "Return to the Magistrate. Return to the Magistrate concludes an urgent reconnaissance dispatch between the eastern border of Tirisfal Glades and the town of Brill. Having reported to Deathguard Linnea at her waystation east of Brill, adventurers are sent back to deliver troubling news directly to Magistrate Sevren. The message confirms that the mindless minions of the Lich King continue to test the borders of the young Forsaken nation. The eastern road out of Tirisfal Glades leads directly into the blighted ruins of the Western Plaguelands, where the Scourge holds devastating sway. To keep the undead hordes from spilling over into their newly claimed homeland, the Forsaken established the Bulwark—a fortified checkpoint watched from a waystation behind the line by grim sentries like Deathguard Linnea. After gathering reports of what presses against the eastern gate, Linnea sends messengers racing back west along the King's Road toward Brill before enemy infiltrators can capitalize on any gaps. When Magistrate Sevren receives the dispatch in Brill, it confirms his worst fears: Scourge scouts are finding pathways around or through the frontline perimeter. For the Forsaken, every creeping ghoul and mindless skeleton is not merely a military nuisance, but a reminder of the enslavement they broke free from during the fall of Lordaeron. Sevren remains adamant that no matter how ceaseless the Lich King's onslaught becomes, the free undead will never surrender their newfound autonomy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_360-2a218c7ceb5d5b9796bc/1-0000.mp3", duration = 83.2522449, start = 0},
  },
}
P.transport["quest:361"] = {
  hash = "efba4c",
  fullHash = "efba4c",
  text = "A Letter Undelivered. A faded, bloodstained missive found among the skeletal ruins of Agamand Mills, addressed to Yvette Farthing. It reveals a tragic parting between two lovers as the Scourge swept across Lordaeron, offering a glimpse into what the Forsaken left behind when they traded life for undeath. Written by Thurman Agamand, the eldest son of patriarch Gregor Agamand, this unsent parchment never reached its intended recipient before the family estate collapsed into ruin. When the Plague of Undeath consumed Tirisfal Glades, Thurman refused to abandon his ancestral home and kin. Amid the horrors of the onslaught, he took up quill to write one last message to Yvette Farthing, whom he had loved before the kingdom turned to ash.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_361-70e6d35d5fb522142474/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["quest:362"] = {
  hash = "2f21c3",
  fullHash = "2f21c3",
  text = "The Haunted Mills. Coleman Farthing of Brill seeks vengeance against his former landowners, the Agamands, by having their restless undead remains collected and destroyed. This task sends you north to Agamand Mills to put down Devlin Agamand, the sharp-tongued younger son of the estate. It begins a bitter vendetta against the family who failed to protect Tirisfal's common folk from the Plague. Before the Third War, Agamand Mills stood as the breadbasket of northern Tirisfal, owned by a wealthy landed family. When the Scourge swept across Lordaeron, the common folk looked to the noble landowners for safety, only to find neither sanctuary nor salvation. Coleman Farthing survived in undeath, but his heart remains consumed by hatred for the family he served. Rather than letting them roam in eternal torment, Farthing desires the morbid satisfaction of collecting their bones to desecrate them under his own heel. Devlin Agamand was the younger brother of Thurman Agamand. In life, Devlin was widely remembered as a weak, spiteful, and sharp-tongued youth who stood in stark contrast to his gentle elder brother. When the Plague of Undeath crept into the mill estate, Devlin was among the quickest to fall prey to the corruption. Now, stripped of whatever fragile wit he possessed in life, his mindless corpse chatters incessantly along the northern road leading into the family mills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_362-06bd2bf07895c505a6e4/1-0000.mp3", duration = 79.5167347, start = 0},
  },
}
P.transport["quest:363"] = {
  hash = "dc0803",
  fullHash = "dc0803",
  text = "Rude Awakening. Rude Awakening is the first task given to newly awakened Forsaken within the crypts of Deathknell. After rising from death freed from the Lich King's iron grip, you are directed away from the incinerators and sent down the hill to learn the reality of your new existence from Shadow Priest Sarvis. Opening your eyes in the damp subterranean chill of Deathknell's crypt is an unsettling introduction to undeath. Undertaker Mordo stands watch over the freshly interred, sorting the revived into those who have reclaimed their free will and those destined for the burning pits. For many, rising from the grave means waking to rot, cold stone, and total disorientation, having slipped through the grasp of the Scourge by sheer circumstance. Before reaching the chapel, newly awakened dead must grasp a grim truth: they were once mindless tools of the Lich King. It was Lady Sylvanas Windrunner who shattered that psychic enslavement, allowing remnants of former humanity to reclaim independent thought. Stepping up from the tomb and heading down into Deathknell marks the first step into a world where both the living and the Scourge view you as an abomination to be eradicated.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_363-ef50dc8605d79ea1d99b/1-0000.mp3", duration = 66.1420408, start = 0},
  },
}
P.transport["quest:364"] = {
  hash = "0c5a52",
  fullHash = "0c5a52",
  text = "The Mindless Ones. Shadow Priest Sarvis tasks newly awakened Forsaken with culling the Mindless Zombies and Wretched Zombies that wander the northern edges of Deathknell. These shambling corpses are Scourge thralls, devoid of free will and utterly bound to the Lich King's command. Not all who rise from the dirt of Lordaeron regain their minds. While the Forsaken threw off the mental domination of Ner'zhul when his power waned, countless corpses remain hollow husks chained to his will. In northern Deathknell, these Mindless and Wretched Zombies wander without purpose other than raw violence. For a newly risen undead, putting them down is the first bitter trial of existence—proving one's autonomy by severing the chains of those who never broke free. Though Shadow Priest Sarvis laments that these vast legions of dead cannot be recruited to bolster the Forsaken's desperate struggle, there is no curing them. The mindless undead are permanently broken instruments of slaughter. Leaving them to roam invites chaos to Deathknell's doorstep and provides the Lich King with easy fodder. Eliminating them is both a tactical necessity and an act of grim finality for Lordaeron's fallen people.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_364-ff53e75000813ef22f61/1-0000.mp3", duration = 64.0783673, start = 0},
  },
}
P.transport["quest:365"] = {
  hash = "97a374",
  fullHash = "97a374",
  text = "Fields of Grief. Fields of Grief is an early Forsaken mission assigned by Deathguard Simmer along the road north of Deathknell. It tasks fledglings with raiding a living human farmstead to harvest Tirisfal pumpkins for the Royal Apothecary Society in Brill. For new Forsaken adventurers freshly risen from the crypts of Deathknell, stepping onto the misty roads of Tirisfal Glades is an immediate lesson in hostility. Deathguard Simmer represents the pragmatic malice of Sylvanas Windrunner's forces: survival means seizing what the living possess and turning it toward the Undercity's darker endeavors. The targets of the raid are the mortal human farmers attempting to work the blighted soil west of the road, north of Deathknell. Described by the Deathguard as infesting the realm like mold on a corpse, these peasants cling to their homesteads under the uneasy protection of nearby Scarlet Crusade towers. Snatching their crops deals a spiteful blow to their supplies while feeding the Royal Apothecary Society's endless demand for reagents.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_365-022e25bf2f0a4c02fe1b/1-0000.mp3", duration = 60.0032653, start = 0},
  },
}
P.transport["quest:366"] = {
  hash = "c92a8e",
  fullHash = "c92a8e",
  text = "Return the Book. Bethor Iceshard enchants Gunther Arcanus's stolen spellbook to prove his own freedom and recruit his former Kirin Tor colleague to the Forsaken cause. Taking the tome back to Gunther's island retreat reveals that neither former wizard is a thrall to the Lich King. After discovering that the renegade necromancer on Brightwater Lake was his old companion Gunther Arcanus, Bethor Iceshard devised an ingenious method of communication. Having previously ordered the theft of Gunther's spellbook to uncover the necromancer's identity, Bethor weaves an intricate dweomer into its pages. Rather than a demand or an armed parley, the enchantment serves as an arcane signature, proving that Bethor is not only active in Lordaeron, but completely liberated from the Lich King's mental yoke. Before the Third War devastated Lordaeron, Bethor Iceshard, Gunther Arcanus, and Thule Ravenclaw were fellow students and friends within the Kirin Tor in Dalaran. Their paths diverged sharply when the Lich King rose: Thule betrayed his brethren and willingly sided with the Scourge, while Bethor and Gunther both fell to the Plague, and Bethor later broke free alongside Queen Sylvanas. Believing Gunther was either dead or enslaved, Bethor's realization that Gunther also achieved self-willed undeath sparked an urgent effort to draw him into the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_366-a84cb74c9717e72a4c76/1-0000.mp3", duration = 77.2440816, start = 0},
  },
}
P.transport["quest:367"] = {
  hash = "4550c8",
  fullHash = "4550c8",
  text = "A New Plague. A New Plague is an introductory task in Brill that reveals the Forsaken's overarching strategic ambition. Apothecary Johaan tasks recruits with harvesting the blood of wild darkhounds to lay the groundwork for a virulent pathogen commissioned directly by Lady Sylvanas Windrunner. In the damp village of Brill, Apothecary Johaan works on behalf of the Royal Apothecary Society under a mandate directly from the Dark Lady. Sylvanas Windrunner has charged her alchemists with crafting a disease unlike anything Azeroth has ever seen. While the original plague of undeath served the Lich King by slaughtering humanity and binding their souls, this new creation is explicitly designed to annihilate Arthas Menethil and lay waste to his Scourge legions. Developing a biological weapon capable of destroying the undead requires grim experimentation. Johaan believes that the blood of indigenous beasts, starting with the fierce darkhounds roaming the gloom of Tirisfal Glades, holds vital chemical properties. By harvesting vials of this tainted animal blood, Johaan begins isolating elements to test whether the natural resilience and predatory biology of native creatures can catalyze a lethal contagion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_367-96806e84cf8bec8f5a62/1-0000.mp3", duration = 69.5118367, start = 0},
  },
}
P.transport["quest:368"] = {
  hash = "725eba",
  fullHash = "725eba",
  text = "A New Plague. Tasked by Apothecary Johaan in Brill, this errand requires gathering scales from the local Vile Fin murlocs prowling the Tirisfal coast. The Royal Apothecary Society aims to harness unique biological reagents to refine their budding new contagion, ensuring it can spread beyond isolated victims to engulf larger populations. Poisoning a single target is simple alchemy, but formulating a plague capable of sweeping across entire lands demands more complex components. Apothecary Johaan's ongoing research in Brill hinges on creating a disease that can self-propagate and endure in the wild. To engineer this transmissibility, he turns his attention toward the shoreline wildlife of Tirisfal Glades, identifying the resilient biology of the coastal Vile Fin murlocs as a promising source of raw material. The northern and western shores of Tirisfal Glades are plagued by aggressive murloc tribes known as the Vile Fin. Harvesting their scales provides Johaan with organic compounds adapted to damp, harsh conditions. By incorporating the murlocs' slick, resilient scales into his developing cauldron, the apothecary seeks to bolster the virulence and environmental stability of the Royal Apothecary Society's new plague.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_368-c049722cf562a6a6ca87/1-0000.mp3", duration = 72.1763265, start = 0},
  },
}
P.transport["quest:3681"] = {
  hash = "012f1b",
  fullHash = "012f1b",
  text = "Tome of Divinity. Tome of Divinity is a summons directed at developing human paladins visiting Ironforge. Master Brandur Ironhammer bids initiates make the journey south to the Cathedral of Light in Stormwind, where Master Duthorian Rall oversees advanced training in the sacred Tomes of Divinity. While dwarven paladins train vigorously within Ironforge's Hall of Mysteries, the broader traditions of the Silver Hand remain deeply entwined with the Church of the Holy Light in human lands. Word sent north from Stormwind calls on promising holy warriors to present themselves directly before the senior priesthood and paladin mentors of the Cathedral of Light. Master Brandur Ironhammer recognizes when a student has progressed far enough to step into the deeper mysteries of the faith. Journeying south—whether by the subterranean Deeprun Tram or across the mountain passes—brings initiates to Stormwind's Cathedral District, where Duthorian Rall prepares them to study the sacred Tomes and master the rites of redemption.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3681-e033e4dad9a9b61c0a29/1-0000.mp3", duration = 54.2302041, start = 0},
  },
}
P.transport["quest:369"] = {
  hash = "036363",
  fullHash = "036363",
  text = "A New Plague. In Brill, Apothecary Johaan turns his attention toward developing a potent new biological agent for the Forsaken. By studying ancient texts, he discovers that a historic, deadly plague survived through the venom of eastern Tirisfal's night web spiders, prompting an urgent retrieval effort. While pursuing his alchemy for the Royal Apothecary Society in Brill, Apothecary Johaan scours aged tomes in search of deadlier mixtures. He uncovers records of an ancient pestilence that once ravaged thousands of lives. Crucially, the texts indicate that the deadly pathogen survived across generations by harboring within the local arachnids of Tirisfal Glades, making their venom an invaluable biological reagent. To acquire a viable sample of the pathogen, Johaan directs agents toward the eastern reaches of Tirisfal Glades. South of the Scarlet Monastery lies Venomweb Vale, a fog-shrouded hollow infested with vicious night web spiders. Harvesters must venture into their dens to extract fresh venom glands, securing the final ingredient needed to finalize Johaan's experimental brew.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_369-129d51c239fd52d09315/1-0000.mp3", duration = 62.5371429, start = 0},
  },
}
P.transport["quest:37"] = {
  hash = "6bc9b8",
  fullHash = "6bc9b8",
  text = "Find the Lost Guards. Guard Thomas is waiting at Elwynn's eastern bridge for word of two missing guards. Rolf and Malakai were sent north along the river to watch for murlocs, but neither has returned. Guard Thomas watches the eastern crossing of Elwynn Forest, where the King's road approaches Redridge. Murlocs have made the nearby waters more dangerous. Days ago, Thomas sent two Stormwind guards, Rolf and Malakai, north along the riverbanks to scout the threat and clear out nests. Neither has returned, and Thomas fears violence stopped their patrol.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_37-386ee69f6a2cea5267ae/1-0000.mp3", duration = 32.8097959, start = 0},
  },
}
P.transport["quest:370"] = {
  hash = "f52617",
  fullHash = "f52617",
  text = "At War With The Scarlet Crusade. Executor Zygand directs Forsaken champions to strike down Captain Perrine and his garrison stationed at a ruined tower southwest of Brill. Using intelligence recovered in Deathknell, the Forsaken aim to push back the zealous crusaders threatening their borders. Documents recovered from the Scarlet Crusade in Deathknell by Executor Arren revealed active troop movements across Tirisfal Glades. Rather than waiting for the fanatics to mount an offensive against the newly fortified town of Brill, Executor Zygand uses this captured intelligence to orchestrate preemptive strikes against their field commanders. Stationed at a dilapidated watchtower southwest of Brill, Captain Perrine oversees a contingent of Scarlet Zealots and Missionaries. From this vantage, the Crusade attempts to monitor Forsaken movements and project power deeper into Tirisfal, making Perrine's death crucial to the defense of the Dark Lady's young kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_370-666dec780cb58463d52b/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["quest:371"] = {
  hash = "6da9ae",
  fullHash = "6da9ae",
  text = "At War With The Scarlet Crusade. This military operation tasks Forsaken defenders with striking at the Scarlet Crusade encampment near the Balnir Farmstead in southeastern Tirisfal Glades. Under orders from Executor Zygand, players eliminate Captain Vachon and his accompanying friars to stall Crusader raids threatening the Dark Lady's domain. As the Forsaken strive to secure the perimeter around Brill and the Undercity, the Scarlet Crusade maintains fortified pockets across the countryside. Reports funneling into town from Executor Arren alert the military command to active Crusader incursions operating out of a crumbling guard tower in southeastern Tirisfal Glades, uncomfortably close to the abandoned Balnir Farmstead. Recognizing that disorganized zealots are far less perilous than coordinated squads, Executor Zygand focuses the offensive on their field leadership. By eliminating Captain Vachon alongside the Scarlet Friars who bolster his men with holy magic, the Forsaken aim to shatter this cell's operational cohesion and suppress human raids into nearby Forsaken territories.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_371-fc71953d0fad9e2de204/1-0000.mp3", duration = 60.7085714, start = 0},
  },
}
P.transport["quest:372"] = {
  hash = "b3fd8b",
  fullHash = "b3fd8b",
  text = "At War With The Scarlet Crusade. This mission represents the culmination of Executor Zygand's early campaign to secure Tirisfal Glades against Scarlet Crusade incursions. Operating out of Brill, Forsaken agents are directed to strike directly at Captain Melrache and his personal vanguard at a ruined watchtower past Faol's Rest. While the Forsaken consolidate their hold over the ruins of Lordaeron, the Scarlet Crusade relentlessly probes the borders of Tirisfal. From an elevated watchtower situated in northern Tirisfal past Faol's Rest, zealous crusaders have organized raiding parties against Forsaken patrols and territory. Rather than waiting to repel another assault, Executor Zygand chooses decapitation: eliminating the command structure that directs the local raids. Commanding this northern encampment is Captain Melrache, an uncompromising officer flanked constantly by two sworn bodyguards. Melrache's position gives the Crusade observation over the coastal roads and surrounding woods. Slaying him breaks the immediate coordination of the crusaders near Brill, neutralizing a direct threat to Lady Sylvanas's fledgling kingdom and driving the zealots back toward their stronger fortifications further east.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_372-75346ccf1f1ee36602a4/1-0000.mp3", duration = 66.7167347, start = 0},
  },
}
P.transport["quest:374"] = {
  hash = "81de2b",
  fullHash = "81de2b",
  text = "Proof of Demise. Proof of Demise is a military directive issued by Deathguard Burgess in Brill to thin the ranks of the Scarlet Crusade in Tirisfal Glades. Initiated on the orders of Varimathras, Sylvanas Windrunner's dreadlord lieutenant, it tests a soldier's loyalty to the Forsaken cause. Recruits are ordered to strip signet rings from fallen crusaders as tangible evidence of their slaughter. The campaign across northern Tirisfal Glades is not merely defensive; it is a coordinated war of eradication. Varimathras, the dreadlord who surrendered and pledged his blade to Sylvanas Windrunner, oversees many of the Forsaken's aggressive military maneuvers against the living. His directives trickle down to commanders like Executor Zygand and frontline officers such as Deathguard Burgess. Burgess makes the directive clear: the human race is viewed as vermin to be purged from Lordaeron, and the zealous crusaders nearby are the immediate target. Words alone do not satisfy the commanders in Brill. To prove obedience to the Dark Lady and her lieutenant, soldiers must plunder Scarlet Insignia Rings straight from the fingers of slain zealots. These rings bear the iconography of the Scarlet Crusade, marking their bearers as sworn enemies of the Forsaken. Returning with a handful of these trophies serves as unassailable proof of dead crusaders and a demonstration of uncompromising allegiance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_374-be11f140e51e0e1e7acd/1-0000.mp3", duration = 80.9534694, start = 0},
  },
}
P.transport["quest:375"] = {
  hash = "86b313",
  fullHash = "86b313",
  text = "The Chill of Death. In the town of Brill, a Forsaken tailor named Gretchen Dedmar struggles against the creeping cold of mortality and decay. Fearing that the encroaching mindless state will rob her of the ability to serve Lady Sylvanas, she asks for simple materials to sew herself a warm blanket. For the Forsaken, undeath is not a static condition of eternal preservation. As Gretchen Dedmar describes, the lingering Plague of Undeath runs through her body like an icy serpent, draining the warmth from her limbs and threatening to pull her into the mindless state that afflicts so many wandering corpses in Tirisfal Glades. Her shivering hands make ordinary work nearly impossible. Despite her failing strength, Gretchen refuses to abandon her duty to the Forsaken kingdom. When Sylvanas Windrunner first rallied the liberated dead, Gretchen contributed by sewing burial shrouds and body bags for fallen soldiers. By gathering sturdy duskbat pelts and coarse thread, travelers help keep her hands steady enough to craft a blanket and prolong her useful service to the Forsaken cause.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_375-f24b5629cb8ea9a6e59f/1-0000.mp3", duration = 61.9102041, start = 0},
  },
}
P.transport["quest:376"] = {
  hash = "a06ec6",
  fullHash = "a06ec6",
  text = "The Damned. The Damned is an early task given to newly awakened Forsaken by Novice Elreth in the chapel of Deathknell. In exchange for the materials needed to fashion crude clothing and battlefield wraps, Elreth provides salvageable armor to protect fledgling undead from the perils surrounding the cemetery. Awakening into undeath leaves little room for vanity or sentimentality. Novice Elreth attends to the steady stream of fresh Forsaken pulled from the dirt of Deathknell, serving as an assistant to Shadow Priest Sarvis. Between tending to battered soldiers and mending garments, supplies run perilously thin. To ensure new arrivals do not fall apart during their initial trials, Elreth sends them into the surrounding glades to hunt native duskbats and scavenger wolves, trading salvaged armor for the raw pelts, wings, and sinew required to keep the camp functioning. The armor offered by Elreth is far from pristine forge-work; it is hand-me-down gear pulled from those who failed to endure their awakening. Her grim parting words—hoping the garments serve the recipient better than the previous owner—reflect the cold calculus of Forsaken survival. In Tirisfal Glades, nothing is wasted, and every piece of leather and rusted chain has already outlived at least one corpse.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_376-a7c9549370240232ed82/1-0000.mp3", duration = 72.6204082, start = 0},
  },
}
P.transport["quest:38"] = {
  hash = "38eca5",
  fullHash = "38eca5",
  text = "Westfall Stew. Salma Saldean cooks Westfall Stew on her farm, making a meal from what the frontier offers. Its ingredients reflect how Westfall homesteaders endure bandits, famine, and dangerous beasts. Westfall's settlers contend with bandits, famine, and rampaging beasts, far from Stormwind's lavish larders. Families like the Saldeans make do with what the land provides. Salma Saldean turns ingredients many city folk might call pests or scraps into a sustaining meal for working farmhands. Salma's recipe brings together local okra, stringy meat from circling vultures, and snouts from wild goretusks roaming the plains. It also calls for fresh murloc eyes gathered from coastal raiders. The thought of river beasts and carrion birds may turn delicate stomachs in Elwynn, but Westfall cooks swear the blend makes a rich, fortifying meal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_38-9c76c79a8859abe97ac9/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["quest:380"] = {
  hash = "54a436",
  fullHash = "54a436",
  text = "Night Web's Hollow. Night Web's Hollow is an early assignment from Executor Arren to clear out the spiders infesting a nearby gold mine northwest of Deathknell. Facing critical shortages of raw materials, the fledgling Forsaken need the mine's wealth to sustain their settlement and war effort. Newly risen recruits are sent into the tangled cavern to cull the arachnid infestation piece by piece. Survival for the newly risen Forsaken involves more than just defending against the Scourge and Scarlet crusaders. Building a fledgling society requires raw resources, and precious metals like gold were scarce in northern Lordaeron even at the height of the Alliance's strength. Executor Arren, overseeing operations in Deathknell, recognizes that the Forsaken cannot hope to arm, equip, and establish themselves without secured wealth. Directly northwest of the cemetery grounds lies Night Web's Hollow, a natural cavern containing a viable gold vein. Unfortunately, monstrous arachnids have overrun the tunnels, filling the depths with thick webbing and deadly venom. Lacking the seasoned troops to conduct a full-scale purge, Arren relies on fresh recruits to whittle down the young and adult spiders until mining crews can eventually burn away the webs and extract the ore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_380-9afd2641cf4ca101f986/1-0000.mp3", duration = 70.9746939, start = 0},
  },
}
P.transport["quest:381"] = {
  hash = "efb526",
  fullHash = "efb526",
  text = "The Scarlet Crusade. This early mission from Executor Arren tasks newly awakened Forsaken with ambushing a nearby camp of Scarlet Crusade zealots southeast of Deathknell. It serves as a grim introduction to one of the Forsaken's most fanatical and persistent enemies. Once the immediate peril of the Night Web spider infestation is handled, Executor Arren turns Deathknell's attention toward an encroaching threat. A detachment of the Scarlet Crusade has established a foothold just southeast of the settlement. These zealots refuse to acknowledge any distinction between mindless Scourge minions and free-willed Forsaken, meaning their presence on the border poses an existential threat to the newly risen dead. Understanding that dialogue is impossible with holy fanatics who view all dead flesh as an abomination, Arren orders a preemptive strike. Adventurers are sent to cut down Scarlet Initiates and Converts before the encampment can grow into an organized forward assault on Deathknell. The trophies brought back—their crimson armbands—stand as stark proof that survival in Tirisfal must be claimed by force.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_381-67e31937f692f3465c6d/1-0000.mp3", duration = 62.8767347, start = 0},
  },
}
P.transport["quest:382"] = {
  hash = "e7216e",
  fullHash = "e7216e",
  text = "The Red Messenger. Executor Arren tasks newly risen Forsaken with intercepting a courier dispatched from the Scarlet Monastery to the crusade camp outside Deathknell. Intercepting the messenger secures critical intelligence on local Scarlet movements before the zealots can solidify their presence in the valley. This mission marks one of the earliest offensive operations undertaken to secure the Forsaken's fledgling sanctuary. Word travels quickly through Tirisfal Glades, even among the dead. Superiors in Brill alerted Executor Arren that the Scarlet Crusade sent an emissary from their stronghold at the Scarlet Monastery westward into Deathknell. While the Crusaders maintain an aggressive presence across Lordaeron, dispatching a courier directly to the edge of the Forsaken's waking grounds indicates an organized push to eradicate newly risen undead before they can muster an organized defense. The courier, Meven Korgal, blended into the small Scarlet encampment east of Deathknell without bearing distinctive heraldry. Executor Arren directed a targeted strike to assassinate Korgal and confiscate his dispatch. Stripping the courier of his missives denies the local zealots further tactical coordination with their eastern headquarters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_382-9a7ee67d36004f4ecb0d/1-0000.mp3", duration = 69.5902041, start = 0},
  },
}
P.transport["quest:383"] = {
  hash = "4ddd94",
  fullHash = "4ddd94",
  text = "Vital Intelligence. Vital Intelligence marks the end of a freshly risen Forsaken's training in Deathknell. Entrusted with intercepted Scarlet Crusade documents, the courier is sent out into Tirisfal Glades to report to Executor Zygand in Brill. Having neutralized local threats and intercepted a courier of the Scarlet Crusade, newly recruited Forsaken are deemed ready for broader service. Executor Arren entrusts the recovered intelligence to the player, directing them out through the sheltered canyon of Deathknell and east along the road toward Brill, past Cold Hearth Manor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_383-fa7971fc6aa7cdf2c841/1-0000.mp3", duration = 33.5412245, start = 0},
  },
}
P.transport["quest:3861"] = {
  hash = "b45f0c",
  fullHash = "b45f0c",
  text = "CLUCK!. In Westfall, a chicken may answer when you call and feed it. Follow its scratched message to the Saldean family, and a warm egg may be yours to hatch. Ordinary chickens wander the farmsteads of Azeroth, and most travelers pass them by. Mimic a chicken's gestures and clucking, and it may stop pecking to regard you with interest. In that brief moment, the bird scratches letters in the dirt. The message points to the farmer who can provide the food it wants. The bird's request calls for Special Chicken Feed. In Westfall, the Saldean family keeps this grain for their flock. Offer the feed and cheer the chicken on as it eats. In return, it lays a warm egg that can be nurtured into a feathered companion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3861-4ff7da3df42d1c4a6de8/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["quest:39"] = {
  hash = "09e479",
  fullHash = "09e479",
  text = "Deliver Thomas' Report. In eastern Elwynn, Guard Thomas sends word of two dead guards and rising danger. He asks you to carry the report to Marshal Dughan in Goldshire, where the garrison has few hands to spare. Guard Thomas watches the bridges into eastern Elwynn, where river traffic meets the wilderness. Guards Malakai and Rolf have been killed by aggressive murloc tribes. With his remaining guards too few to contain them, Thomas sends you down the road to Goldshire with an urgent report. Marshal Dughan receives Thomas' report in Goldshire, already struggling to keep patrols on the roads. Kobolds infest the area, Defias bandits threaten travelers, and Stormwind City has sent no reinforcements. The deaths of two experienced guards add to his burden. Murlocs may soon threaten Goldshire itself, while the defenses across the region grow ever thinner.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_39-2229bf1dab50103c11ed/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["quest:3901"] = {
  hash = "5e033d",
  fullHash = "5e033d",
  text = "Rattling the Rattlecages. Rattling the Rattlecages is an early trial assigned by Shadow Priest Sarvis to newly awakened Forsaken in Deathknell. Tasked with destroying twelve Rattlecage Skeletons, fresh undead prove their resilience against the Scourge and demonstrate that they possess the willpower to defend their newly won freedom. Having culled the mindless zombies stumbling through Deathknell, newly risen Forsaken are immediately pushed into a harsher trial. Shadow Priest Sarvis directs recruits to confront the Rattlecage Skeletons roaming the outskirts of the settlement. These animated bones lack any trace of sapience or self-control, yet they hit harder and fight with greater ferocity than the decaying corpses nearby. Surviving their clattering ambushes demonstrates that a new recruit will not falter when placed under immediate pressure. To Sarvis and the leadership in Deathknell, culling the skeletons serves a dual purpose. It protects the fragile refuge from being overrun by the lingering grip of the Lich King while weeding out those recruits who cannot cut it. Those who fail or hesitate risk meeting the same fate as the mindless wretches wandering the woods. Overcoming the Rattlecages proves to Sarvis that the recruit possesses the mettle required to navigate a world that despises their very existence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3901-c45e78381830d56e7ca8/1-0000.mp3", duration = 70.4, start = 0},
  },
}
P.transport["quest:3902"] = {
  hash = "26a7c1",
  fullHash = "26a7c1",
  text = "Scavenging Deathknell. Scavenging Deathknell is an early logistical task assigned to newly awakened Forsaken by Deathguard Saltain in Deathknell. As freshly raised undead claw their way from the soil, the Forsaken must scavenge abandoned boxes and crates throughout the blighted settlement to equip incoming recruits. It illustrates the raw scarcity facing Sylvanas's nascent people, who must reclaim discarded goods simply to survive. Newly raised Forsaken awaken into a grim reality of decay and deprivation. Unlike established nations with bustling supply lines and armories, the free undead in Deathknell possess next to nothing. Deathguard Saltain's blunt demand reflects the ruthless practicality required to build an army from the graveyard dirt: every piece of salvageable cloth, leather, and iron must be hauled back to clothe and arm those still crawling out of their plots. The settlement of Deathknell is littered with remnants of its former human inhabitants alongside supplies abandoned during the kingdom's fall to the Scourge. Rather than letting usable materials rot away in crates across town, the Deathguards press newborn undead into service as salvagers. As Saltain makes clear, the Forsaken expect no charity from the living world and must rely entirely on their own industriousness to stand on their feet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3902-8d8fdb7653ca4d873c5f/1-0000.mp3", duration = 74.3183673, start = 0},
  },
}
P.transport["quest:3903"] = {
  hash = "8cd844",
  fullHash = "8cd844",
  text = "Milly Osworth. At Northshire Abbey, Deputy Willem sends you to help Milly Osworth. Her wagon and livelihood are in jeopardy, and she needs help across the abbey grounds. The work takes you from defending the abbey to aiding Elwynn Forest's civilians. After you prove your mettle against the Defias thieves encroaching on Northshire Valley, Deputy Willem recognizes you as capable and willing to help. He sends you to assist his friend Milly Osworth. This favor is personal, outside the abbey's official guard duties, and Milly is a civilian caught in the valley's growing unrest. Milly waits beside her wagon on the far side of Northshire Abbey, near the stables. Deputy Willem must stay at his post to defend the abbey. Milly's troubles lie out in the valley, where the stretched guard garrison has too few hands to help her.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3903-b9c62243462a119e2bd4/1-0000.mp3", duration = 45.844898, start = 0},
  },
}
P.transport["quest:3904"] = {
  hash = "e3fb62",
  fullHash = "e3fb62",
  text = "Milly's Harvest. Defias brigands have driven Milly Osworth from the Northshire vineyards. Her harvest lies scattered in buckets and crates among the occupied rows, where it may be stolen or crushed. Milly Osworth fled the southeastern fields of Northshire Valley when Defias brigands swarmed the vines. She left her gathered grapes behind in buckets and crates among the occupied rows. Northshire's garrison is stretched thin, and Milly fears that boots and fighting will crush any fruit the bandits leave behind. Defias bandits now occupy working vineyards, a sign of how little safety Northshire can offer. Stormwind's attention is elsewhere, and the valley has too few guards. Farmers like Milly must depend on recruits and wanderers to protect their property and secure the food and wine that supply the abbey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3904-370a670f41528e4fce45/1-0000.mp3", duration = 46.0016327, start = 0},
  },
}
P.transport["quest:3905"] = {
  hash = "328e3f",
  fullHash = "328e3f",
  text = "Grape Manifest. Milly Osworth records her rescued grape harvest for Northshire Abbey. She writes a manifest of the yield recovered from Defias thieves, then sends it to Brother Neals so the brotherhood can replenish its wine stores. Northshire Valley's soil and orchards have long supported local food and the abbey's wine. When thieves and bandits seized the eastern fields, they cut off the abbey's supply of grapes and food. With the harvest recovered from the occupied fields, Milly Osworth records the yield in a manifest. Brother Neals oversees food and drink at Northshire Abbey. He is known for sampling Northshire's vintages in the quiet of the bell tower. Brigands still threaten the gates, but fresh grapes give the brotherhood a moment to toast the Light and take heart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3905-ceb6f1b0fcb75d8765e6/1-0000.mp3", duration = 43.7028571, start = 0},
  },
}
P.transport["quest:3921"] = {
  hash = "3195ef",
  fullHash = "3195ef",
  text = "Wenikee Boltbucket. Near the Mor'shan Rampart, Wenikee Boltbucket may be able to mend a broken samophlange. Sputtervalve tinkered with the device after it was retrieved from the Sludge Fen, and now needs an expert hand before his colleagues in Undermine demand results. Sputtervalve's claims to his fellow engineers in Undermine now hang on a broken machine. An adventurer retrieved the mysterious samophlange from the Venture Company's control console at the Sludge Fen, and Sputtervalve could not resist showing it off. His tinkering damaged the delicate contraption. He needs someone with sharper skill to diagnose the damage and repair it. Wenikee Boltbucket camps beside the road just south of the Mor'shan Rampart. The rampart divides the northern Barrens from Ashenvale. Her inquisitive mind is drawn to intricate machinery, and the broken samophlange quickly captures her attention. Its internal gears hold her curiosity, and she sets to work figuring out how to rebuild it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3921-5927468a3a57180d3f1a/1-0000.mp3", duration = 56.32, start = 0},
  },
}
P.transport["quest:3922"] = {
  hash = "223588",
  fullHash = "223588",
  text = "Nugget Slugs. At the Sludge Fen, Wenikee Boltbucket needs parts for a recovered samophlange. The eccentric tinkerer sends you to the nearby Venture Company drilling crews for spare hardware. Wenikee Boltbucket has a recovered samophlange and wants to learn how the intricate machine works. Its goblin mechanisms need exact parts, so she sends you to the Venture Company crews at the Sludge Fen. Their heavy tool buckets hold the seventeen-point-five gauge nugget slugs she needs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3922-93a897ea3217ba5921b4/1-0000.mp3", duration = 28.2644898, start = 0},
  },
}
P.transport["quest:3923"] = {
  hash = "7f39be",
  fullHash = "7f39be",
  text = "Rilli Greasygob. In Orgrimmar, Rilli Greasygob is the specialist Wenikee Boltbucket seeks. She sends you there with a damaged samophlange, hoping his knowledge of its Venture Company origins can explain the device. Wenikee Boltbucket examined the samophlange recovered from the Venture Company drilling site in the Barrens. Her extra gauges showed the apparatus nearing collapse. More levers and dials might destroy it, so she stopped and sent the problem to someone with knowledge of its design. In Orgrimmar's Valley of Honor, Wenikee sends you to Nogg's Machine Shop. Rilli Greasygob works there as an engineer and once learned his trade within the Venture Company. He recognizes the machine at once and marvels that anyone survived exploring the company's contested operations in the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3923-22544e041197f6818134/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["quest:3924"] = {
  hash = "62023f",
  fullHash = "62023f",
  text = "Samophlange Manual. In Orgrimmar, Rilli Greasygob needs help with a broken samophlange. The goblin engineer sends you back into the Barrens for the operating instructions, held by his former Venture Company rival. Rilli Greasygob once worked beside Boss Copperplug in the Venture Company. Copperplug oversaw the samophlange’s inner workings and guarded their secrets closely. He shared no manual with Rilli. Instead, he gave out separate pages only to underlings he trusted, leaving his fellow engineer without the knowledge to understand the device.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_3924-db39f10d852595887c6d/1-0000.mp3", duration = 31.0595918, start = 0},
  },
}
P.transport["quest:398"] = {
  hash = "fc5556",
  fullHash = "fc5556",
  text = "Wanted: Maggot Eye. Wanted: Maggot Eye is an official death bounty posted on the Brill notice board by the town's Forsaken leadership. A notorious gnoll has been looting nearby graveyards and farms to supply dead bodies directly to the Lich King's Scourge. Executor Zygand requires proof of the creature's execution to secure the lands around Garren's Haunt. In Tirisfal Glades, the dead are far from resting peacefully. The gnoll known as Maggot Eye earned a severe death sentence not merely for scavenging, but for active collaboration with the Lich King. While gnolls are generally viewed as savage brutes driven by simple hunger, Maggot Eye has been systematically digging up corpses and collecting remains to fuel the ranks of the Scourge army. For the Forsaken, whose entire existence hinges on breaking free from the Lich King's dominion, feeding dead kin back into the Scourge war machine is among the highest offenses possible. Executor Zygand, overseeing local military enforcement in Brill, commissioned this bounty to put an end to the grave robberies near Garren's Haunt. To collect the prize, the executioner must sever Maggot Eye's paw as unmistakable proof that the beast will trouble Tirisfal no longer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_398-9a07ae8f8baefe35bee1/1-0000.mp3", duration = 67.1869388, start = 0},
  },
}
P.transport["quest:399"] = {
  hash = "6e01d9",
  fullHash = "6e01d9",
  text = "Humble Beginnings. Baros Alexston seeks help from his home in Stormwind's Cathedral Square. His family's Westfall farm has burned, and thieves hold its ruins; he hopes to recover an heirloom from his youth. Baros Alexston grew up working the fields of Westfall. Now he is an accomplished architect in Stormwind City, advising on stonework and city buildings. His path from farm boy to city planner is rare in the kingdom, yet he remains attached to the modest beginnings that shaped him. Lawlessness swept across Westfall, and the Alexston Farmstead fell to it. Bandits and vagrants burned the house, forcing Baros's father from his livelihood. Family heirlooms were left behind amid the fire and occupation. Baros asks you to search the ruined, bandit-held farmstead west of Sentinel Hill for his first compass, hidden before the home fell.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_399-c5cad1faca2caa8cccf2/1-0000.mp3", duration = 47.6212245, start = 0},
  },
}
P.transport["quest:40"] = {
  hash = "330300",
  fullHash = "330300",
  text = "A Fishy Peril. In Goldshire, A Fishy Peril begins with reports of murlocs moving inland through the waterways. Remy \"Two Times\" asks travelers to alert Marshal Dughan, whose guards are already stretched thin. Remy \"Two Times\" grows uneasy over a new threat while seeking business in Goldshire. Murlocs are creeping up the streams and into inland shallows, disrupting fishing and menacing innocent travelers. Remy fears the local guard is overlooking a danger that is still growing, so he asks passersby to carry word to the heart of the township. Marshal Dughan hears the report in Goldshire but remains skeptical. He is charged with protecting the realm while royal forces are stretched thin elsewhere, and Riverpaw gnolls and Defias highwaymen already demand his attention. With no confirmed military intelligence, he will not divert his scarce men to pursue rumors of fish-men in the eastern streams.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_40-30b9a137fbb7878a5271/1-0000.mp3", duration = 50.6514286, start = 0},
  },
}
P.transport["quest:400"] = {
  hash = "5a009a",
  fullHash = "5a009a",
  text = "Tools for Steelgrill. Tools for Steelgrill is an early Alliance delivery errand that introduces travelers leaving Kharanos to the nearby mechanic workshop at Steelgrill's Depot. Tharek Blackstone sends you up the road with a fresh crate of heavy equipment for Beldin Steelgrill, the master siege engine tech who works through spanners and ratchets faster than town suppliers can keep up. Beldin Steelgrill carries an undisputed reputation across Dun Morogh as the sharpest siege engine mechanic in the mountains, but his violent work ethic takes a heavy toll on his workshop. According to Tharek Blackstone in Kharanos, Steelgrill cracks arclight spanners and snaps tools almost as fast as local supply crates can arrive. When a fresh batch of durable gear is assembled in Kharanos, anyone heading northeast is quickly recruited to lug the heavy parcel out to the depot. Arriving at Steelgrill's Depot, travelers find the yard crowded with smoke, grease, and idling iron war machines. Beldin's backlog is thick with demanding military repairs, including critical work on Pilot Stonegear's siege engine. Beldin had snapped his last fang-ratchet mere hours before your arrival, making the delivered crate an immediate lifeline for Ironforge's tracked armor fleet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_400-cb8d9b5ddcb6ce612899/1-0000.mp3", duration = 70.4783673, start = 0},
  },
}
P.transport["quest:403"] = {
  hash = "51e873",
  fullHash = "51e873",
  text = "Guarded Thunderbrew Barrel. The Guarded Thunderbrew Barrel rests in the cellar of the Thunderbrew Distillery in Kharanos. It represents the prized stock of the famed dwarven brewing family, watched over day and night to keep thieves and rivals from meddling with their craft. In the cold snows of Dun Morogh, few things are guarded more fiercely than good ale. Beneath the floorboards of the Thunderbrew Distillery in Kharanos, stout casks of potent brew age in peace. The family takes no chances with their stock, posting watchful sentries like Jarven Thunderbrew right beside the barrels to ensure not a single drop is tampered with or siphoned off. Dwarven brewing is as serious a discipline as smithing or mining. The Thunderbrews take immense pride in their proprietary recipes, particularly potent batches of Thunder Ale. Between greedy troggs creeping around Dun Morogh and bitter brewing rivalries across the Alliance, Jarven's vigilant presence ensures the family's liquid gold remains untouched until properly tapped.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_403-6274c2bfa83feacdd837/1-0000.mp3", duration = 57.3387755, start = 0},
  },
}
P.transport["quest:404"] = {
  hash = "5fc6ef",
  fullHash = "5fc6ef",
  text = "A Putrid Task. A Putrid Task is an early military assignment offered by Deathguard Dillinger in Brill. It directs adventurers to push back the mindlessly aggressive Scourge encroaching upon the old bridge west of the settlement. Collecting proof of the monsters' destruction secures the road and eases pressure on Tirisfal's defenders. Brill sits at a critical crossroads in eastern Tirisfal Glades, making any enemy approach a direct threat to the Forsaken power base. Mindless Scourge constantly seep westward across the waterways, clustering around the broken remnants of the old stone bridge. Without regular patrols beating them back, the shambling corpses would quickly choke transit between Brill and the western farmsteads. For the Forsaken, Scourge roaming their borders is not merely a strategic nuisance; it is an insult. Every mindless ghoul and rotting corpse represents the servitude and torment that Lady Sylvanas Windrunner's followers broke away from. Deathguards like Dillinger take grim satisfaction in crushing their former captors, demanding severed claws as brutal proof that the mindless dead have been put to rest for good.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_404-9e70e1e0319efad57a06/1-0000.mp3", duration = 64.1567347, start = 0},
  },
}
P.transport["quest:405"] = {
  hash = "07f4e1",
  fullHash = "07f4e1",
  text = "The Prodigal Lich. Following your service in Brill against Scourge remnants and rot hide gnolls, Magistrate Sevren directs you south to the Undercity. Bethor Iceshard, a prominent archmage in the Magic Quarter, requires a capable operative for a sensitive mission regarding a wayward lich. Having proven your capability in the ruined town of Brill, Magistrate Sevren deems you worthy of higher-level Forsaken endeavors. Bethor Iceshard, a formidable mage dwelling in the Undercity's Magic Quarter, has demanded an agent tested in combat against the Scourge. Sevren hands over official orders, dispatching you beneath the ruins of Lordaeron into the subterranean corridors of the Forsaken capital. While Sevren admits ignorance of the exact specifics, he reveals that the task revolves around finding and recruiting a rogue lich. Liches are among the most lethal spellcasters raised by the Scourge, making any interaction fraught with peril. When you deliver the orders to Bethor atop his arcane sanctum, the icy mage cuts straight to business, eager to assess whether Brill's magistrate has sent someone strong enough to handle such dangerous quarry.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_405-ab39dbe19714eeff4a58/1-0000.mp3", duration = 66.2204082, start = 0},
  },
}
P.transport["quest:407"] = {
  hash = "6d2b6a",
  fullHash = "6d2b6a",
  text = "Fields of Grief. Fields of Grief concludes Apothecary Johaan's experiment to weaponize ordinary pumpkins gathered from Solliden Farmstead. Having infused the crop with his latest alchemical concotion, Johaan dispatches you to feed the laced vegetable to a captive Scarlet Crusader languishing in Brill. Apothecary Johaan of the Royal Apothecary Society believes the Forsaken must exploit every tactical advantage to fend off the Scourge from the north and human incursions from the south. Rather than relying solely on raw blade-work or dark sorcery, the Society seeks to harness ordinary staples of the land. By tainting the pumpkins recovered from the mortal farmers of Solliden Farmstead, Johaan intends to prove that even common produce can be transformed into an instrument of death on behalf of the Dark Lady.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_407-d35bf89bc614233b60ea/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["quest:408"] = {
  hash = "969660",
  fullHash = "969660",
  text = "The Family Crypt. The Family Crypt is a Horde quest tasking players with confronting the Scourge inside the Agamand Family Crypt. Commanded by Magistrate Sevren in Brill, adventurers must destroy the raised Agamand ancestors and slay the skeletal Scourge commander, Captain Dargol. While the Forsaken have carved out a fragile dominion in Tirisfal Glades, remnants of the Lich King's Scourge remain deeply entrenched in the countryside. The Agamand Mills, once a prosperous flour-producing heartland of Lordaeron, have become a dangerous Scourge stronghold. Magistrate Sevren in Brill watches this military buildup with grave concern, knowing that every inch yielded to mindless undead undermines the Forsaken's independence. The center of the local Scourge occupation is the Agamand Family Crypt, where the skeletal commander Captain Dargol has set up headquarters. Using dark necromancy, Dargol has dragged generations of Agamand family dead from their rest, twisting them into Rotting and Wailing Ancestors to swell his ranks. Sevren dispatches Forsaken agents to purge the crypt, lay the disturbed dead back to rest, and severed Dargol's head to shatter Scourge coordination in northern Tirisfal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_408-9c715fa4e9adc1721cf8/1-0000.mp3", duration = 71.3404082, start = 0},
  },
}
P.transport["quest:409"] = {
  hash = "d92ae9",
  fullHash = "d92ae9",
  text = "Proving Allegiance. Proving Allegiance is the crucial trial presented by Gunther Arcanus to determine whether you truly serve the free-willed Forsaken or the Lich King. To earn the solitary necromancer's trust, you are sent to summon and destroy Lillith Nefara, a dangerous Scourge operative lurking near his island. Gunther Arcanus has isolated himself on an island in Brightwater Lake since rising into undeath, fiercely clinging to his autonomy. Though Bethor Iceshard's magical enchantments on Gunther's spellbook confirmed the emissary does not carry the foul taint of the Scourge, words and charms are not enough for the paranoid hermit. To earn his confidence, an outsider must demonstrate active hostility toward the minions of the Lich King through decisive violence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_409-0a5915b93699365ef35a/1-0000.mp3", duration = 42.1616327, start = 0},
  },
}
P.transport["quest:410"] = {
  hash = "b36d2a",
  fullHash = "b36d2a",
  text = "The Dormant Shade. The Dormant Shade is a dark ritual performed at Gunther's Retreat on Brightwater Lake in Tirisfal Glades. By placing a mystic candle upon an old, blood-soaked table, a traveler summons forth the Scourge agent Lillith Nefara, whose defeat proves to Gunther Arcanus that the visitor is the Lich King's foe. On the island of Gunther's Retreat in Brightwater Lake rests a battered, bloody dinner table. Far from an ordinary piece of neglected domestic furniture, it serves as the physical focus for a sinister conjuration. Stained with dried gore and abandoned to the shadows, the table acts as a makeshift ritual slab where death and dark magic linger.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_410-ad3b1fc9da64773c9884/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["quest:411"] = {
  hash = "b87d29",
  fullHash = "b87d29",
  text = "The Prodigal Lich Returns. The Prodigal Lich Returns marks the conclusion of the effort to recruit Gunther Arcanus into the Forsaken. Having proven your intentions and restored his grimoire, you carry an arcane communion gem back to Bethor Iceshard in the Undercity. Gunther Arcanus spent years isolated on an island in Brightwater Lake, having broken free from the Lich King's grip through sheer force of will, completely unaware that Sylvanas Windrunner had liberated Lordaeron. Bitter and suspicious of outsiders, Gunther distrusted the emissaries of the Undercity until an adventurer returned his spellbook and proved their hostility toward the Scourge. Satisfied that his visitor was not an enemy, Gunther entrusted them with a Nether Gem to establish contact with his former colleague.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_411-ad23aa6d33051bd3248b/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["quest:412"] = {
  hash = "114903",
  fullHash = "114903",
  text = "Operation Recombobulation. Operation Recombobulation is a bold engineering effort orchestrated by Razzle Sprysprocket in Kharanos. In response to the tragedy of Gnomeregan, Razzle and Ozzie Togglevolt seek to reverse the horrific transformation of their afflicted kin into leper gnomes using an experimental contraption known as the Recombobulator. When radiation flooded Gnomeregan to purge the trogg menace, it failed to destroy the invaders and instead warped the majority of the gnomish population into deranged, sickly leper gnomes. Refusing to accept this tragic mutation as permanent, inventor Razzle Sprysprocket has partnered with Ozzie Togglevolt to develop a technological cure: the Recombobulator. Their audacious goal is nothing less than restoring their mutated brethren back to health and sanity. Building a delicate prototype requires precise components, namely Restabilization Cogs and Gyromechanic Gears. In an ironic twist of fate, these essential parts are salvaged directly from the hostile leper gnomes wandering outside the sealed gates of Gnomeregan. By harvesting mechanical debris from their corrupted brothers and sisters, Razzle hopes to assemble the very device that will undo their shared tragedy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_412-7fee28b684bf37e4bba2/1-0000.mp3", duration = 66.7689796, start = 0},
  },
}
P.transport["quest:413"] = {
  hash = "ce1eaf",
  fullHash = "ce1eaf",
  text = "Shimmer Stout. Following the creation of his experimental Shimmer Stout in Brewnall Village, Rejold Barleybrew asks travelers to carry a fresh barrel out to his brother Wellart. Wellart serves as a dwarf Mountaineer stationed at the southern guard tower guarding the pass toward Loch Modan, where a cold post makes a strong drink all the more welcome. Rejold Barleybrew has perfected his new creation, Shimmer Stout, using shimmering fronds gathered from the icy crags of Dun Morogh. While the rest of the Barleybrew family dedicates their craft to the vats and kegs of Brewnall Village, Rejold's brother Wellart chose the life of a Mountaineer. Knowing the lonely conditions of guard duty on the frontier, Rejold sends a fresh barrel along with passing travelers as both a brotherly favor and a true taste test. Wellart Barleybrew is stationed at the southern guard tower flanking the South Gate Pass into Loch Modan. High atop the mountain pass, the Mountaineers endure bitter winds and occasional beast attacks while keeping watch over travelers walking the mountain road. Running low on drink and restless for excitement, Wellart finds that Shimmer Stout delivers quite a punch—so much so that it seems to brighten his vision in the dim mountain night.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_413-ae24144d4f67f01383b5/1-0000.mp3", duration = 70.5044898, start = 0},
  },
}
P.transport["quest:414"] = {
  hash = "7d0976",
  fullHash = "7d0976",
  text = "Stout to Kadrell. Stout to Kadrell is an Alliance delivery quest that leads travelers out of the frozen heights of Dun Morogh and into the temperate valley of Loch Modan. Entrusted with a cask of Rejold Barleybrew's newly perfected Shimmer Stout, you carry the potent brew across the territorial border to share with Mountaineer Kadrell on patrol in Thelsamar. After tasting the newly finished Shimmer Stout created by his brother Rejold, Mountaineer Barleybrew is convinced it is too good to keep entirely within Dun Morogh. Stationed at the eastern border post guarding the mountain passes, Barleybrew looks out toward his kin guarding neighboring lands. Dwarven mountaineering can be a cold, grueling assignment, and a stout heart calls for stout drink. Wanting an honest appraisal from a fellow patrolman on the line, Barleybrew sends a cask eastward with passing travelers bound for Loch Modan. The journey marks a natural rite of passage for young dwarven and gnomish adventurers who have spent their early days among the snowbound crags of Dun Morogh. Passing southeast through the South Gate Outpost and traversing the long tunnels cut through the mountain bedrock, travelers suddenly emerge into the warmer, wooded basin of Loch Modan. Patrolling along the road through the settlement of Thelsamar, Mountaineer Kadrell gladly takes a break from his vigil to tap the cask, discovering that Barleybrew's new recipe has an astonishing kick.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_414-069b4a8a16ec672652d0/1-0000.mp3", duration = 82.0506122, start = 0},
  },
}
P.transport["quest:415"] = {
  hash = "efd742",
  fullHash = "efd742",
  text = "Rejold's New Brew. Rejold's New Brew is an Alliance errand in Dun Morogh summoning an adventurer back to Brewnall Village. Having perfected a new concoction using gathered Shimmerweed, brewmaster Rejold Barleybrew wants a trusted friend to sample his latest recipe. It serves as the bridge between gathering brewing supplies and distributing his prized Shimmer Stout across the mountain realm. Word spreads quickly through Dun Morogh when a dwarven brewer strikes gold in his cellar. After securing Shimmerweed from the bitter slopes, local contacts like Tharek Blackstone or Pilot Bellowfiz urge passing adventurers to report back to Brewnall Village. Rejold Barleybrew has finished fermenting his experimental batches and is eager to share the spoils with the traveler who made it possible. Brewnall Village thrives on distinct ale craft, and Barleybrew's newest batch is no ordinary draught. Infusing local herbs into his mash produced a distinct beverage known as Shimmer Stout. Before shipping barrels off to neighboring outposts and thirsty patrons in Loch Modan, Rejold insists that the adventurer who risked life and limb for the herbs gets the honor of the inaugural sip.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_415-e757cf9db6e2811e6026/1-0000.mp3", duration = 66.9518367, start = 0},
  },
}
P.transport["quest:4161"] = {
  hash = "76ef10",
  fullHash = "76ef10",
  text = "Recipe of the Kaldorei. Zarrin teaches a lesson in balance through the Recipe of the Kaldorei. In Dolanaar, young cooks learn to gather only what they need from Teldrassil's woods. Behind the inn in Dolanaar, Zarrin tends a bubbling cauldron and teaches young adventurers the traditions of his people. The night elves once called themselves the kaldorei, or children of the stars. Zarrin begins their understanding of that heritage with the bond between a hunter, their food, and Teldrassil's boughs, rather than the battlefield. Zarrin teaches restraint through a simple demand: gather small spider legs from the woodland arachnids outside Shadowglen, but take exactly seven. The kaldorei seek harmony with nature by taking only what they need and showing kindness to the wild. Even in troubled times, that balance matters. A spider kabob becomes a lesson in living with care.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4161-6ad9bad6f9f40b36159d/1-0000.mp3", duration = 50.3379592, start = 0},
  },
}
P.transport["quest:417"] = {
  hash = "22b1b6",
  fullHash = "22b1b6",
  text = "A Pilot's Revenge. Following the trail of a missing dwarven siege engine pilot leads to a frozen corpse in the wilds of Dun Morogh. Found among the remains, Hildelve's personal journal details his fatal struggle against a notorious predator known as Mangeclaw, leaving behind a dying wish for vengeance. Pilot Hildelve did not survive his time stranded in the rugged snowy crags. When travelers locate his remains, they discover his journal resting beside him. In his last penned words, Hildelve recorded a savage encounter with a massive Ice Claw bear he named Mangeclaw. Though he managed to fend off the monstrosity initially, the injuries proved severe, and the beast eventually returned to finish off the weakened pilot. Knowing his end was near, Hildelve wrote down one final plea in his journal: retribution against the monster that took his life. Returning to Pilot Hammerfoot with the journal and a claw torn from the fallen beast brings grim closure to the Ironforge Siege Brigade, honoring their lost comrade and removing a deadly menace from the mountain paths.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_417-1be7ce4489177761a2ae/1-0000.mp3", duration = 61.9102041, start = 0},
  },
}
P.transport["quest:418"] = {
  hash = "da9969",
  fullHash = "da9969",
  text = "Thelsamar Blood Sausages. In the bustling town of Thelsamar, cook Vidra Hearthstove keeps the local laborers and miners fed with a famous highland staple: blood sausages. Preparing this hearty dwarven fare requires freshly gathered ingredients from the surrounding valley of Loch Modan. Thelsamar is never short on hungry appetites. Between energetic children and weary miners returning from the Ironband Excavation, Vidra Hearthstove works tirelessly over the tavern stove. To keep the populace fed and satisfied, she relies on a local culinary tradition known across Loch Modan: savory blood sausages made from the wildlife wandering the rugged mountain pass. While traditional blood sausage relies on fresh blood, seasoned meat, and natural casings, Vidra's recipe reflects the rugged pragmatism of the dwarves. Boar intestines provide the casings, bear meat forms the dense filling, and spider ichor is added to lend a sharp, pungent bite. Though collecting venomous fluid and entrails is not for the faint of heart, the result is a regional favorite that travelers quickly learn to appreciate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_418-a12a1d5e47638cc8806f/1-0000.mp3", duration = 63.2685714, start = 0},
  },
}
P.transport["quest:419"] = {
  hash = "4110d7",
  fullHash = "4110d7",
  text = "The Lost Pilot. Pilot Hammerfoot fears the worst for his comrade, Mori Hildelve, who ventured into the craggy hills of Dun Morogh on foot after wrecking his siege engine. Hildelve was searching for a rare ore vital for potent blastpowder, but days have passed amidst unsettling roars echoing through the peaks. Dwarven siege engines are formidable war machines, but even iron treads struggle against the treacherous, jagged ridges of Dun Morogh. While scouring the slopes for a rare mineral deposit required to produce high-grade blastpowder, Pilot Mori Hildelve pushed his engine too far up a steep hill and busted the machine. Undeterred by the breakdown, Hildelve ordered his companion, Pilot Hammerfoot, to stay behind and guard the broken machinery while he pressed higher into the frozen wilderness on foot. Days went by with no sign of Hildelve returning to camp. In the dead of night, strange and vicious beastly growls began echoing down from the rocky crags, turning Hammerfoot's mild impatience into creeping dread. Though Hildelve had a reputation for being as tough as nails, surviving the frigid heights of Dun Morogh without mechanized armor or heavy support against prowling predators is a dangerous gamble.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_419-26ee1ff562df43b6455e/1-0000.mp3", duration = 68.4669388, start = 0},
  },
}
P.transport["quest:420"] = {
  hash = "78d58b",
  fullHash = "78d58b",
  text = "Senir's Observations. This errand completes a scouting line out of Coldridge Valley, carrying Grelin Whitebeard's completed report through the trogg-infested pass to his brother Senir in Kharanos. It bridges the secluded training grounds of Anvilmar with the broader troubles facing Dun Morogh. Through Senir's candid reception, travelers catch their first glimpse of political friction simmering between field scouts and the Ironforge Senate. After Grelin Whitebeard recovers his stolen journal from the Frostmane trolls, he prepares a detailed report of the valley's threats for his brother Senir. Mountaineer Thalos, stationed guarding the gate out of Coldridge Valley, entrusts passing adventurers with carrying this dispatch. Leaving the relative seclusion of the introductory vale means braving the tunnel cut through the mountain, which has recently been overrun by violent troggs ambushing all traffic. Travelers who punch through emerge onto the snowblown highways of central Dun Morogh, following the main road straight into the cozy hub of Kharanos. Senir Whitebeard, found seeking warmth over drinks at the Thunderbrew Distillery in Kharanos, greets newcomers with rough mountaineer hospitality. Reading through Grelin's findings, Senir chuckles over his brother's aggressive rhetoric. Grelin liberally invokes the name of King Magni Bronzebeard to press for urgent action, an assertive tactic Senir notes is bound to agitate the stubborn Ironforge Senate. Senir admits he has fallen behind on filing his own observations due to the bitter cold, but receiving Grelin's dispatch nudges him back into service, opening further work monitoring hostile forces across the snowfields.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_420-e9081b112cc071739463/1-0000.mp3", duration = 92.4473469, start = 0},
  },
}
P.transport["quest:421"] = {
  hash = "ee990d",
  fullHash = "ee990d",
  text = "Prove Your Worth. Prove Your Worth is an introductory Horde quest offered by Dalar Dawnweaver at the Sepulcher in Silverpine Forest. To assist the Forsaken campaign against southern human and dwarven territories, adventurers are tasked with thinning the feral worgen prowling near the roadside. It marks the opening step in unraveling the arcane fallout wrought by Archmage Arugal. Lady Sylvanas Windrunner and her dreadlord lieutenant, Varimathras, have set their sights on securing the regions south of Tirisfal Glades, including human and dwarven enclaves. However, the path through Silverpine Forest remains fraught with danger. Instead of an open staging ground, the Forsaken find their supply lines and forward bases threatened by feral Moonrage worgen that roam the pine-choked hills. The presence of these beasts is no natural occurrence. Dalar Dawnweaver points the finger directly at Arugal, a disgraced former mage of Dalaran who unleashed otherworldly worgen upon the region during the Scourge invasion. Arugal has since claimed Shadowfang Keep, letting his feral creations overrun the forest. Before Dalar will entrust soldiers with deeper investigations into Arugal's sorcery, recruits must demonstrate their martial prowess by culling the nearest Moonrage Whitescalps.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_421-9989e6f8eec88b985407/1-0000.mp3", duration = 70.2432653, start = 0},
  },
}
P.transport["quest:422"] = {
  hash = "7e662d",
  fullHash = "7e662d",
  text = "Arugal's Folly. Assigned by Dalar Dawnweaver at the Sepulcher, this quest tasks Forsaken agents with securing Arugal's earliest spellbooks from a nearby farmstead. Uncovering the magic behind the worgen curse is vital for the Forsaken to turn it against the mad mage and secure Silverpine Forest. Recovering the Remedy of Arugal marks the first step in unraveling the threat looming from Shadowfang Keep. Dalar Dawnweaver, an ambitious Forsaken mage residing in the crypts of the Sepulcher, holds no respect for Archmage Arugal. To Dawnweaver, Arugal was an unremarkable practitioner whose inclusion in the Kirin Tor was baffling and whose magical understanding seemed amateurish. However, the monstrous beasts now roaming Silverpine cannot be ignored. To break Arugal's hold on the region, Dawnweaver intends to deconstruct the spells that unleashed the worgen upon Lordaeron.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_422-24c2b8be1b33418860a3/1-0000.mp3", duration = 51.2, start = 0},
  },
}
P.transport["quest:423"] = {
  hash = "9f17a1",
  fullHash = "9f17a1",
  text = "Arugal's Folly. This task sends Forsaken agents to collect enchanted shackles from Moonrage worgen roaming Silverpine Forest. Dalar Dawnweaver, analyzing Arugal's notes, aims to unravel how the renegade mage artificially reinforced his unstable magic. Studying these bindings brings the Forsaken closer to dismantling the worgen threat plaguing the region. Upon inspecting Arugal's recovered research, Dalar Dawnweaver expresses utter contempt for his former peer. According to Dalar, Arugal was never fit to serve Dalaran, let alone handle high sorcery during the kingdom's direst hour. To compensate for his mediocre talent, Arugal relied on enchanted relics and hardware to bolster and bind his summoned worgen beasts. Dalar requires physical samples of these items to dissect the magical tether holding the monsters together. The cursed inhabitants of Silverpine, transformed into Moonrage worgen, wander the woods carrying physical manifestations of Arugal's binding enchantments. Moonrage Gluttons and Moonrage Darksouls stalk the regions to the north and east of the Sepulcher. Prized for the residual arcane energy woven into their metal, their heavy shackles serve as crucial specimens for Dawnweaver's counter-research against Shadowfang Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_423-1524b88dc56697d923c3/1-0000.mp3", duration = 74.5273469, start = 0},
  },
}
P.transport["quest:425"] = {
  hash = "e1176e",
  fullHash = "e1176e",
  text = "Ivar the Foul. Ivar the Foul is a quest in Silverpine Forest that marks the culmination of the reconnaissance mission undertaken by Deathstalkers Rane and Quinn Yorick. Trapped at the farmstead known as the Ivar Patch, Rane asks Horde travelers to eliminate the savage ghoul Ivar the Foul so Quinn can recover from his mauling and complete their report to High Executor Hadrec. Siblings Rane and Quinn Yorick were deployed by the Deathstalkers to conduct reconnaissance across Silverpine Forest on behalf of High Executor Hadrec at the Sepulcher. Their reconnaissance grinded to a sudden, violent halt when moving through a farmstead in the northern forest, where they were ambushed by the vicious ghoul known as Ivar the Foul. Though the scouts managed to escape with their unlives, Quinn was severely mauled in the confrontation. Even after receiving an alchemical remedy concocted from forest beasts, Quinn remains too frail to march. Knowing Ivar prowls the nearby barn waiting for Rane's guard to falter, Rane calls upon Horde adventurers to storm the barn, sever Ivar's head, and permanently secure the homestead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_425-0a279acc47dba3d1d3f8/1-0000.mp3", duration = 61.9885714, start = 0},
  },
}
P.transport["quest:426"] = {
  hash = "78ef5a",
  fullHash = "78ef5a",
  text = "The Mills Overrun. Tasked by Deathguard Dillinger in Brill, this mission sends Forsaken soldiers to break the Scourge's foothold at the nearby Agamand Mills. Mindless undead gather among the ruined windmills, threatening to establish a forward base dangerously close to Tirisfal Glades' settlements. To halt this staging ground, recruits must shatter the ranks of skeletal soldiers and bonecasters. The Agamand Mills once anchored the agricultural heart of Tirisfal Glades, but in the wake of the Third War, their windmills overlook a far grimmer harvest. Scourge forces under the Lich King's thrall have begun massing on the grounds. If these mindless thralls successfully secure the mills, they will have an entrenched base of operations from which to push deeper into Tirisfal and strike directly at the fledgling Forsaken holdings. Deathguard Dillinger wastes little time on sentiment. Tasked with fortifying Brill and policing the territory, Dillinger orders recruits to hunt down Rattlecage and Cracked Skull Soldiers alongside Darkeye Bonecasters. By demanding notched ribs and blackened skulls as proof of their destruction, Dillinger ensures the skeletal ranks are being physically battered apart, throwing the mindless remnants back toward the Plaguelands before their offensive can truly begin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_426-4c2118b78a3bf0cc1299/1-0000.mp3", duration = 71.68, start = 0},
  },
}
P.transport["quest:427"] = {
  hash = "0606bf",
  fullHash = "0606bf",
  text = "At War With The Scarlet Crusade. Executor Zygand in Brill coordinates the Forsaken campaign against the Scarlet Crusade in Tirisfal Glades. Using intelligence recovered by Executor Arren, you are dispatched to eliminate Scarlet Warriors stationed at a guard tower west of the Solliden Farmstead. This assault marks the Forsaken military's opening offensive to purge the zealous crusaders from their borders. The fledgling Forsaken state under Lady Sylvanas Windrunner faces simultaneous threats on multiple fronts. While the Deathguard keeps a wary vigil against the swelling armies of the Lich King, the fanatical mortals of the Scarlet Crusade contest Forsaken dominance over their former homeland. The Crusade considers all undead abominations to be purged with fire and blade, blind to the fact that the Forsaken have broken free of the Scourge's control. Thanks to intelligence documents secured by Executor Arren at Deathknell, Executor Zygand now knows the exact encampments and outposts held by the zealots across Tirisfal Glades. With regular Deathguard garrisons occupied by Scourge containment, independent Forsaken champions are commissioned to strike out directly. The first strike falls upon the guard tower west of Solliden Farmstead, where Scarlet Warriors muster and threaten the western approaches to Brill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_427-1f27d679a2278daaef55/1-0000.mp3", duration = 71.6016327, start = 0},
  },
}
P.transport["quest:428"] = {
  hash = "c5fedd",
  fullHash = "c5fedd",
  text = "Lost Deathstalkers. Lost Deathstalkers is a reconnaissance mission assigned by High Executor Hadrec at the Sepulcher. Two Forsaken scouts, Rane and Quinn Yorick, went missing weeks ago while surveying the haunted farmsteads of northern Silverpine Forest. Tracking them down reveals not only their fate, but the encroaching perils that threaten the Forsaken hold on the region. The Deathstalkers serve as the eyes, ears, and hidden daggers of Lady Sylvanas and the Forsaken. When operatives go silent, command takes notice. High Executor Hadrec deployed the scouts Rane and Quinn Yorick into northern Silverpine Forest weeks ago to monitor the abandoned farms and watch for enemy movements. Having received no courier or report since their departure, Hadrec fears the duo met a grim end at the hands of the Scourge or worse. Northern Silverpine is rife with danger, situated between the ruined estates of Lordaeron and the shadowed borders of Tirisfal Glades. Wandering undead, prowling beasts, and feral worgen make unescorted travel perilous even for seasoned rogues. Tracking the Yoricks requires searching the dilapidated northern farmsteads where their reconnaissance first began, hoping to recover whatever intelligence they gathered before danger overwhelmed them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_428-b32cee0503a5a2edb0da/1-0000.mp3", duration = 70.3216327, start = 0},
  },
}
P.transport["quest:429"] = {
  hash = "e729f0",
  fullHash = "e729f0",
  text = "Wild Hearts. Wild Hearts is a Horde quest in Silverpine Forest tasked by Rane Yorick. To save her brother Quinn from wounds inflicted by the ghoul Ivar the Foul, you must harvest discolored worg hearts and deliver them to Apothecary Renferrel at the Sepulcher for an alchemical remedy. Following the disastrous mission that left the Deathstalkers pinned down at a farm in northern Silverpine, Rane Yorick finds herself attending to her severely wounded brother, Quinn. The feral ghoul Ivar the Foul left Quinn mangled and failing to recover. Knowing conventional rest will not restore an undead body torn by such savagery, Rane looks to the macabre arts of the Royal Apothecary Society to stitch her brother back together. Silverpine's wolves have not escaped the dark corruption plaguing northern Lordaeron. The local worgs carry corrupted, discolored hearts that contain uniquely potent essences. While vile to ordinary eyes, the Royal Apothecaries have learned to distill these blighted organs into concoctions capable of revitalizing withered Forsaken flesh.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_429-ff970de2aa9354be081d/1-0000.mp3", duration = 61.8318367, start = 0},
  },
}
P.transport["quest:430"] = {
  hash = "bb7189",
  fullHash = "bb7189",
  text = "Return to Quinn. Return to Quinn is a Horde quest in Silverpine Forest where an adventurer delivers a restorative draught concocted by Apothecary Renferrel to the wounded Deathstalker Quinn Yorick. Trapped and weakened at the Ivar Patch north of the Sepulcher, Quinn requires the draught before he can contemplate returning to duty. Following the harvesting of wild beast hearts for the Royal Apothecary Society, Apothecary Renferrel at the Sepulcher brews a restorative potion formulated to aid Quinn Yorick. Renferrel has little time for sentimentality or bedside manners, quickly handing off the mixture to return to his own clandestine alchemical research, leaving the adventurer to run the courier run back into the wilderness. Quinn Yorick hides beside his sister, Deathstalker Rane Yorick, amid the ruined farmstead known as the Ivar Patch. Severely hurt by the ghoul Ivar the Foul and unable to march through hostile territory, Quinn drinks the draught immediately upon arrival. While the concoction restores his strength enough to eventually travel, the surrounding territory remains fraught with danger, particularly under the watchful malice of the ghoul lurking nearby.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_430-f912ca7755997cbed2cb/1-0000.mp3", duration = 65.7502041, start = 0},
  },
}
P.transport["quest:431"] = {
  hash = "c23231",
  fullHash = "c23231",
  text = "Candles of Beckoning. Candles of Beckoning is a brief task centered around salvaging specialized ritual tapers discovered in Tirisfal Glades. These eerie tallow candles are steeped in dark practices and recovered from a crate on Gunther's Retreat, Gunther Arcanus's island in Brightwater Lake. The crate on Gunther's Retreat supplies the Candle of Beckoning used in his test of allegiance. Gunther asks an adventurer to take a candle to the old, bloody altar just off the island's southern coast, light it, and confront the Scourge agent Lillith Nefara. The crate holding these candles sits on Gunther's Retreat, the island in Brightwater Lake where the lich Gunther Arcanus dwells. A single candle is all that is needed for the test Gunther sets in Proving Allegiance: lit upon the old, bloody altar off the island's southern coast, it awakens the Scourge agent Lillith Nefara.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_431-69bb93d4e2cd54423ecc/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["quest:432"] = {
  hash = "b680b8",
  fullHash = "b680b8",
  text = "Those Blasted Troggs!. Foreman Stonebrow is at his wit's end after troggs completely overran his operations at Gol'Bolar Quarry. Destructive and aggressive, the beasts have trashed his mining equipment and powder barrels, leaving him furious and demanding retaliation. Unable to fight them himself due to failing aim, he pays brave adventurers to head down into the pit and cull the brute Skullthumpers. Gol'Bolar Quarry was once a proud, productive dwarf excavation site nestled in the snowy hills of eastern Dun Morogh. That prosperity ended abruptly when subterranean troggs broke through the bedrock and swarmed the lower terraces. Instead of merely occupying the tunnels, the savages have wreaked wanton havoc, smashing scaffolding and blowing through precious barrels of blasting powder. Watching the ruin of his life's work from the safety of the ridge has pushed Foreman Stonebrow to the brink of apoplexy. Frustrated by his own aging hands and poor aim, he relies on passing wanderers and Alliance recruits to execute raw vengeance. Thinning the ranks of the burly Rockjaw Skullthumpers provides him a brief moment of relief, though nothing short of total extermination will truly satisfy his wrath.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_432-abb2861dfdbccffedd36/1-0000.mp3", duration = 69.5118367, start = 0},
  },
}
P.transport["quest:433"] = {
  hash = "86bbed",
  fullHash = "86bbed",
  text = "The Public Servant. Senator Mehr Stonehallow of Ironforge has traveled directly to Gol'Bolar Quarry to address the sudden trogg invasion threatening Dun Morogh's mining operations. Seeking to reclaim the site, he enlists adventurers to cut down the aggressive Rockjaw Bonesnappers so miners can return to work. It is rare to find a member of Ironforge's Senate standing in the slush and dirt of a contested mine, but Senator Mehr Stonehallow is no typical politician. Holding dual allegiance to the dwarven ruling body and the scholarly Explorers' League, Stonehallow has taken personal responsibility for organizing a response to the trogg infestation at Gol'Bolar Quarry. Rather than waiting for slow legislative measures, he directly contracts capable mercenaries and travelers to cull the invaders. Gol'Bolar Quarry was once a vital source of stone and mineral wealth for Dun Morogh, but deep excavations broke into previously sealed subterranean hollows. Primitive, savage troggs of the Rockjaw tribe flooded into the pits, wrecking delicate mining equipment and driving out civilian laborers. Stonehallow's objective is to clear out the vicious Rockjaw Bonesnappers, paving the way for Mountaineer garrisons to secure the quarry and restore iron-shoveling infrastructure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_433-82c9f7fe0c2b10609960/1-0000.mp3", duration = 69.8253061, start = 0},
  },
}
P.transport["quest:435"] = {
  hash = "2d3153",
  fullHash = "2d3153",
  text = "Escorting Erland. Trapped indoors by aggressive prowling predators, Deathstalker Erland requires an escort through Silverpine Forest to regroup with his partner. Assisting him safely across the wilderness delivers him directly to Deathstalker Rane Yorick. Even seasoned scouts of the Forsaken occasionally find themselves outmatched by the unforgiving ecology of Silverpine Forest. Deathstalker Erland finds himself cornered inside a dilapidated shelter, surrounded by starved wolves eager to pick at what little flesh remains on his withered frame. Alone, breaking through their pack is suicide. Erland's objective lies near the Ivar Patch, where his partner Deathstalker Rane Yorick maintains watch. The route cuts directly through predatory wolf territory. Once guided through the prowlers, Erland sprints the final stretch to reach the safety of Rane Yorick's outpost, where the scouts can consolidate their intelligence for the Undercity.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_435-3fa0be6c481910be51e2/1-0000.mp3", duration = 53.2636735, start = 0},
  },
}
P.transport["quest:437"] = {
  hash = "6dbd5a",
  fullHash = "6dbd5a",
  text = "The Dead Fields. The Dead Fields is an assault mission issued by High Executor Hadrec from the Sepulcher. Forsaken scouts discovered that the Rot Hide gnolls infesting an abandoned northern farmstead are led and shielded by the Scourge banshee Nightlash, whose destruction is critical to securing Silverpine Forest. North of the Sepulcher lies an abandoned farmstead known as the Dead Fields. Once ordinary farmland, the grounds are now choked by Rot Hide gnolls—pestilent, plagued scavengers that infest the Silverpine countryside. High Executor Hadrec previously sent small raiding parties to dislodge them, but every offensive stalled under unnatural magical resistance. The Rot Hides are not acting merely on feral instinct; they are reinforced by the Scourge. A banshee named Nightlash oversees the area, using dark sorcery to scatter Forsaken skirmishers whenever the gnolls face ruin. Hadrec dispatches Horde champions to cut down the gnolls until Nightlash is lured out, demanding her spectral essence as proof of her demise.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_437-7e214e514835d1b94d70/1-0000.mp3", duration = 59.0367347, start = 0},
  },
}
P.transport["quest:445"] = {
  hash = "d81be8",
  fullHash = "d81be8",
  text = "Delivery to Silverpine Forest. This errand serves as a vital courier mission linking the Royal Apothecary Society's research in Brill with their ongoing efforts in Silverpine Forest. Tasked by Apothecary Johaan, you carry valuable findings to Apothecary Renferrel at the Sepulcher to aid the development of the Dark Lady's New Plague. The Royal Apothecary Society operates under the direct command of Lady Sylvanas Windrunner, tasked with concocting a New Plague capable of wiping out both the living and the Scourge. Isolated laboratories across Forsaken territory cannot work in a vacuum; survival and progress demand constant communication. In Brill, Apothecary Johaan has gathered experimental results that must be circulated to other researchers in the field without delay. Silverpine Forest represents the next frontier of Forsaken expansion and research. Based out of the Sepulcher, Apothecary Renferrel oversees biochemical testing amidst regional threats like the Moonrage worgen, rogue humans, and lingering Scourge. By receiving Johaan's notes from Tirisfal Glades, Renferrel integrates new alchemical findings into his own local experiments, further advancing the Society's grand design.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_445-836b4026dcd3697f08a7/1-0000.mp3", duration = 70.0865306, start = 0},
  },
}
P.transport["quest:447"] = {
  hash = "aebd12",
  fullHash = "aebd12",
  text = "A Recipe For Death. A Recipe For Death is an alchemical errand commissioned by Apothecary Renferrel at the Sepulcher in Silverpine Forest. Tasked with gathering grizzly bear hearts and arachnid blood, adventurers transport the volatile biological reagents to Master Apothecary Faranell in the Undercity to aid in formulating the Forsaken's lethal New Plague. Positioned on the front lines in Silverpine Forest, Apothecary Renferrel recognizes the grim arithmetic facing Sylvanas's people. Surrounded by the relentless legions of Arthas and enduring remnants of humanity, conventional warfare offers little hope. The Forsaken's grand ambition lies in developing a New Plague—an engineered contagion potent enough to rot both living humans and undead Scourge alike. Renferrel's field research determined that combining arachnid venom from the Skittering Dark with toxins concentrated in the hearts of native bears yields a virulent foundation. Once the harvested organs and blood are collected from the wilderness of Silverpine, they must be delivered beneath the ruins of Lordaeron into the heart of the Apothecarium. There, Master Apothecary Faranell oversees the grand design of the Royal Apothecary Society. Faranell immediately takes custody of Renferrel's samples, testing their contaminable properties to refine formulas that might one day secure Forsaken supremacy across the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_447-548bcd1ba725d0b35ed9/1-0000.mp3", duration = 76.8522449, start = 0},
  },
}
P.transport["quest:449"] = {
  hash = "34ec17",
  fullHash = "34ec17",
  text = "The Deathstalkers' Report. The Deathstalkers' Report is a crucial military courier assignment delivered to High Executor Hadrec at the Sepulcher. After securing injured Deathstalkers in the northern wilds, you carry their gathered intelligence concerning unexpected Scourge activity back to Forsaken high command. This dispatch alters the Forsaken's assessment of their hold on Silverpine Forest. The Deathstalkers act as the eyes, ears, and daggers of the Dark Lady, pushing into the untamed wilderness ahead of standard military units. Near the border of Tirisfal and Silverpine, an advance patrol ran into catastrophic resistance while charting enemy movements. Though Deathstalker Quinn barely survived his injuries and Erland fought his way to safety, their scouting mission yielded intelligence essential to the Forsaken occupation of Silverpine Forest. When High Executor Hadrec reviews the sealed field report, it confirms dark news: the mindless forces of the Scourge have maintained a far heavier and more aggressive presence in Silverpine than Undercity strategists anticipated. Instead of merely securing abandoned human hamlets and pacifying rogue beasts, the Sepulcher command must brace for coordinated Scourge opposition while fighting to claim the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_449-247e588b3a8d0f3cee37/1-0000.mp3", duration = 70.8702041, start = 0},
  },
}
P.transport["quest:4495"] = {
  hash = "c71953",
  fullHash = "c71953",
  text = "A Good Friend. At Aldrassil, Dirania Silvershine grows worried when Iverron misses his daily visit. She asks travelers to search the hills near Shadowthread Cave, north of Shadowglen. Dirania Silvershine waits beneath Aldrassil for Iverron, who visits her every day. Hours pass without him, and she asks travelers heading into Shadowglen to look for her friend. Iverron often wanders the hills in northern Shadowglen, near the webwood spiders of Shadowthread Cave. The spiders make the surrounding slopes dangerous for travelers. Search west of the cave entrance, where Iverron is hiding and needs help.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4495-060da52c8d89749f7c7b/1-0000.mp3", duration = 34.4816327, start = 0},
  },
}
P.transport["quest:45"] = {
  hash = "0537ba",
  fullHash = "0537ba",
  text = "Discover Rolf's Fate. In eastern Elwynn, two Stormwind guards are missing near Stone Cairn Lake. Malakai's half-eaten remains and webbed tracks lead toward a murloc village, where the search for Rolf continues. Guard Thomas sent patrols around eastern Elwynn Forest as threats grew, but Malakai and Rolf vanished near Stone Cairn Lake. Malakai's half-eaten remains lie by the shore. Webbed footprints pressed into the mud lead east along the water's edge, straight to a ramshackle murloc camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_45-39bd7234e5f06a95f944/1-0000.mp3", duration = 28.917551, start = 0},
  },
}
P.transport["quest:456"] = {
  hash = "f88d75",
  fullHash = "f88d75",
  text = "The Balance of Nature. Conservator Ilthalaine calls newly awakened night elves to tend Shadowglen’s wildlife. Young nightsabers and thistle boars have grown too numerous, and keeping Teldrassil’s natural harmony calls for stewardship and difficult choices. In Shadowglen, beneath the Great Tree’s sprawling boughs, heavy spring rains have disrupted Teldrassil’s young, fragile forest cycle. Some wildlife populations have grown beyond what the land can sustain. They threaten to strip the glen of resources and bring famine to the ecosystem. Preserving the forest calls for active care. Conservator Ilthalaine watches over Shadowglen’s woods, keeping any one part from overtaking the others. To prevent mass starvation among the animals, he sends young night elves into the grove to thin thistle boars and predatory nightsabers. The work is unglamorous, but vital: kaldorei stewardship means seeking harmony with nature through active balance and difficult decisions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_456-0f64df28171360239005/1-0000.mp3", duration = 54.804898, start = 0},
  },
}
P.transport["quest:457"] = {
  hash = "193e68",
  fullHash = "193e68",
  text = "The Balance of Nature. Conservator Ilthalaine sends defenders into Shadowglen to thin its growing wildlife. Mature thistle boars and mangy nightsabers threaten the glade's balance. Shadowglen's adult animals now threaten the World Tree's ecosystem. Conservator Ilthalaine sends young defenders deeper into the forest to hunt mature thistle boars and older, mangy nightsabers. Their appetites can exhaust the land's limited plants and game. North of Aldrassil, younger cubs give way to mottled nightsabers and aggressive boars that root through the soil. For kaldorei, controlled hunting is a grim duty, but it protects the whole forest from collapse.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_457-1cc0823c1a183ee90eee/1-0000.mp3", duration = 37.5379592, start = 0},
  },
}
P.transport["quest:458"] = {
  hash = "a3a978",
  fullHash = "a3a978",
  text = "The Woodland Protector. In Shadowglen, Melithar Staghelm hears troubling whispers from the forest spirits. He asks you to find Tarindrella, an elusive dryad whose unexpected return hints at trouble beneath Teldrassil’s canopy. Melithar Staghelm receives troubling omens from the woodland spirits while training novices beneath Aldrassil’s boughs. Tarindrella, a dryad regarded as a protector of the wild, has returned to Shadowglen after many years away from Kalimdor’s woodlands. Dryads rarely appear without cause, and Melithar fears the natural order is out of balance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_458-e1eab359417312b23c63/1-0000.mp3", duration = 34.2465306, start = 0},
  },
}
P.transport["quest:459"] = {
  hash = "540856",
  fullHash = "540856",
  text = "The Woodland Protector. In Shadowglen, Tarindrella seeks the cause of the forest’s sudden unrest and the furbolgs’ disappearance. Grells have turned aggressive, and Fel Moss points to dark magic in Teldrassil’s boughs. Shadowglen’s quiet woods have grown hostile. The furbolgs have left their ancestral dens and gathered as the Gnarlpine tribe. Feral grells and grellkin now overrun the woodland paths, and Tarindrella has noticed the dark change spreading through Teldrassil. Tarindrella suspects corruption is stirring the forest’s creatures. You slay the grells and bring her samples of Fel Moss, evidence of dark enchantments clinging to Teldrassil’s boughs. With the corruption confirmed, she sends young defenders to Dolanaar to speak with Druid Athridas Bearmantle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_459-27b9227922b48a381e5a/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["quest:46"] = {
  hash = "fdc98c",
  fullHash = "fdc98c",
  text = "Bounty on Murlocs. Murlocs are spreading through eastern Elwynn, and the Stormwind Army has put a bounty on them. With the garrison stretched thin, Guard Thomas turns to travelers to clear the shoreline camps around Stone Cairn Lake and the southern waterways before the murlocs overrun nearby farms and roads. Murlocs have made shoreline camps around Stone Cairn Lake and along the fork of the southern streams. Lurkers and foragers now attack travelers and press toward human settlements. What began as a minor nuisance has grown into a threat across eastern Elwynn, while the western roads remain comparatively secure. Guard Thomas is stationed at the eastern bridge beside the Redridge Mountains, where dangers beyond the bridge and disorder at home compete for his attention. King Varian Wrynn is missing, and Stormwind's military command is mired in bureaucracy. Town garrisons rarely get the reinforcements they request. Marshal Dughan and local officers have turned to public bounties, offering coin for murloc fins to slow the attacks along the waterways.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_46-1a7d5e947817eb0783ee/1-0000.mp3", duration = 59.9771429, start = 0},
  },
}
P.transport["quest:4681"] = {
  hash = "2eeb53",
  fullHash = "2eeb53",
  text = "Washed Ashore. Along Darkshore's misty coast, dead sea creatures have drawn Gwennyth Bly'Leggonde into a troubling inquiry. She serves the Temple of the Moon in Darnassus and seeks to learn why marine life is stranding or dying along the shore. Dead sea creatures line Darkshore's beaches and shallows, puzzling the night elves of Auberdine. Gwennyth Bly'Leggonde has already examined one stranded creature along the beach. Now she asks you to dive west of the docks, near a sunken vessel, and inspect the bones of a massive sea turtle. The evidence will help her report to the Temple of the Moon.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4681-088946f4efec0a80eefb/1-0000.mp3", duration = 34.9779592, start = 0},
  },
}
P.transport["quest:47"] = {
  hash = "18b576",
  fullHash = "18b576",
  text = "Gold Dust Exchange. At Goldshire's crossroads, Gold Dust Exchange brings Remy \"Two Times\" coin for gold dust from kobolds in Elwynn's mines. Travelers gather the dust and trade it to the nervous broker for pay. Goldshire sits where Elwynn Forest's roads meet, and travelers, merchants, and guards pass through town. Remy \"Two Times\" is a shady broker with a habit of repeating his words and a sharp eye for profit. Instead of paying mining crews to dig for raw minerals, he turns to travelers passing through the Lion's Pride Inn. He offers coin for gold dust taken from the kobolds in the region. Kobolds have overrun Fargodeep Mine south of Goldshire and Jasperlode Mine to the northeast. These rat-like tunnelers chip through the dark for candles and shiny baubles, gathering flecks of unrefined ore in their pouches. Pushing them back serves the kingdom, and gathering their dust turns the work into a trade for coin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_47-024337a7899d4b0a12ad/1-0000.mp3", duration = 52.7934694, start = 0},
  },
}
P.transport["quest:4722"] = {
  hash = "a353c0",
  fullHash = "a353c0",
  text = "Beached Sea Turtle. Along Darkshore’s surf-battered shore, a massive sea turtle lies beached as murlocs pick over its carcass. Viable biological samples remain among the scavenged remains, and Auberdine naturalists send them to the Temple of the Moon in Darnassus for study. Darkshore’s long coast often catches the dead and confused from the Great Sea. Ancient sea turtles drift ashore after death or beach themselves in confusion. Their carcasses quickly draw scavengers, and hostile Greymist murlocs have made crude camps around this turtle’s skeletal frame. They carve away flesh and shell, yet viable bone, shell, or tissue samples may remain intact in the wreckage. Gwennyth Bly'Leggonde is stationed in Auberdine as a field researcher, documenting unusual marine life and ecological disturbances along the coast. Night elves regard stranded beasts with reverence and scientific curiosity. Suitable remains are cataloged and prepared for shipment to scholars in Darnassus, who seek to understand why so many giants of the open sea are washing ashore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4722-960a266ff57adb339727/1-0000.mp3", duration = 62.6416327, start = 0},
  },
}
P.transport["quest:4723"] = {
  hash = "282b87",
  fullHash = "282b87",
  text = "Beached Sea Creature. At Mist's Edge, a giant sea thresher lies stranded while murlocs feed on its carcass. In Auberdine, Gwennyth Bly'Leggonde gathers samples for night elf researchers in Darnassus, who seek to learn why deep-sea giants are washing ashore. Enormous thresher remains have appeared along Mist's Edge, where shipwrecks and tide-washed debris are familiar sights. This beast dwarfs the wildlife of Darkshore's shallows, suggesting it came from far beyond the calm waters of the Veiled Sea. Murlocs swarm over the corpse to feed, but they lack the strength and coordination to bring down a creature of this size. Something else killed the predator before the sea carried it ashore. Gwennyth Bly'Leggonde coordinates efforts in Auberdine to salvage bones and biological samples from Darkshore's stranded sea giants. Night elf researchers in Darnassus hope the remains will show whether illness, disturbances in the deep sea, or arcane corruption drives the giants onto the killing sands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4723-8b245bc736e4b64104b8/1-0000.mp3", duration = 57.7828571, start = 0},
  },
}
P.transport["quest:4725"] = {
  hash = "1bfae5",
  fullHash = "1bfae5",
  text = "Beached Sea Turtle. Along Darkshore's shore, Beached Sea Turtle lies with a broken carriage on its shell. Greymist murlocs have gathered around the great carcass. You find a broken carriage strapped across a giant sea turtle's shell on Darkshore's misty shore. Many sea creatures have washed up along this coast, but this turtle was made to carry a load. Its handlers drove it onto the beach, and the carriage now lies abandoned in the tide. Greymist murlocs soon swarm the turtle's remains. They have made a den among the rotting meat and scavenged timber. A marked container lies among their refuse and the broken carriage frame, left by the turtle's former masters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4725-cf6443330e0c8baa38dc/1-0000.mp3", duration = 38.5044898, start = 0},
  },
}
P.transport["quest:4727"] = {
  hash = "e0afc0",
  fullHash = "e0afc0",
  text = "Beached Sea Turtle. Along Darkshore’s northern shore, Beached Sea Turtle remains untouched by nearby Greymist murlocs. A sample is carried to Gwennyth Bly'Leggonde in Auberdine for the Temple of the Moon. Naturalists and priestesses seek to learn why great sea creatures wash ashore and scavengers leave them alone. Greymist murlocs crowd Darkshore’s northern coast and scavenge whatever food washes up from the Veiled Sea. Yet the great turtle’s skeleton lies mostly untouched. Those studying the shore wonder whether the murlocs missed it or avoided it for some unknown reason. In Auberdine, Gwennyth Bly'Leggonde gathers samples from beached sea turtles for the Temple of the Moon. The night elf priestesses study the disturbances in Darkshore’s waters. Skeletal fragments may help them learn whether sickness, magic, or dangerous sea predators are killing the ancient creatures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4727-a33a518c47c2939b978d/1-0000.mp3", duration = 52.3232653, start = 0},
  },
}
P.transport["quest:4728"] = {
  hash = "846b63",
  fullHash = "846b63",
  text = "Beached Sea Creature. Along Darkshore, a giant sea mammal lies washed ashore beside an abandoned dig site. Its carcass and scattered tools draw murlocs and passing travelers. A giant sea mammal lies on Darkshore's sand, partly gutted and worn by the sea. A rusted wheelbarrow and discarded tools mark the place where an organized study began. The researchers left before they could finish. Dwarven field researchers from the Explorer's League were studying the carcass in Darkshore. Their work stopped when local murlocs swarmed the site to scavenge. Gwennyth Bly'Leggonde in Auberdine acts for the Temple of the Moon and accepts salvaged bone samples to help study the unnatural wash-ups along the coast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4728-3d28437d7161ac059e3f/1-0000.mp3", duration = 41.195102, start = 0},
  },
}
P.transport["quest:4730"] = {
  hash = "fd9c57",
  fullHash = "fd9c57",
  text = "Beached Sea Creature. Along Darkshore, a great sea mammal lies half-devoured on the sand. Murlocs gather around it, and Priestess Gwennyth Bly'Leggonde in Auberdine seeks bone samples to learn why gentle sea beasts are dying on the shore. Far north along Darkshore's lonely beaches, a great sea mammal lies rotting and half-eaten. Murlocs pick over its bones, more vicious than usual. These beasts were gentle in life, and their deaths trouble the coast as much as the blighted forests inland. Priestess Gwennyth Bly'Leggonde says these gentle mammals live in the waters around Teldrassil's base. Unlike aggressive threshers, they have never been known to drive themselves onto the rocks. The Temple of the Moon is gathering bone samples to learn what corruption or threat drives them from the deep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4730-72a67ccd58045b9d51dd/1-0000.mp3", duration = 45.2963265, start = 0},
  },
}
P.transport["quest:4731"] = {
  hash = "cacb45",
  fullHash = "cacb45",
  text = "Beached Sea Turtle. Along Darkshore's coast, a Beached Sea Turtle lies dead beneath the carriage it once hauled. A box marked with strange runes rests in the wreckage. A dead sea turtle lies among the ancient bones scattered along Darkshore's coast. Splintered carriage boards still cling to its broad shell. The turtle was driven onto the rocks while hauling cargo, rather than stranded by sickness or disorientation. A container carved with unfamiliar, serpent-like marks lies in the wreckage, amid scavengers feeding on the remains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4731-f5fb99e20b5cdcd5e74c/1-0000.mp3", duration = 30.1714286, start = 0},
  },
}
P.transport["quest:4733"] = {
  hash = "994625",
  fullHash = "994625",
  text = "Beached Sea Creature. Along Darkshore's rocky Twilight Shore, a colossal thresher lies stranded, far larger than any known local specimen. Its death and stranding add to the deep-sea troubles worrying the night elves. You find driftwood and sea debris along the Twilight Shore in southern Darkshore, but one inlet holds the remains of an enormous thresher. Tides and scavengers have begun picking it apart, yet its skeleton dwarfs ordinary predators in these coastal shallows. The giant is an outsider to these waters. Sickness or disorientation may have driven it onto the rocks, or some deeper disturbance may lie out in the Veiled Sea.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4733-38949d80a3eb5583c007/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
P.transport["quest:4740"] = {
  hash = "654672",
  fullHash = "654672",
  text = "WANTED: Murkdeep!. Auberdine posts an Alliance bounty for Murkdeep, blamed for a Sentinel's death and ships lost off Darkshore. The village council wants the dangerous murloc chieftain dead. Find him south along the misty coast. The Greymist murlocs along Darkshore are usually a nuisance, but Murkdeep has turned against Auberdine. The wanted poster outside the inn names him as the killer of at least one night elf Sentinel. It also suspects him of sabotaging or wrecking two cargo vessels offshore. With ships lost and raids along the coast, the Auberdine Village Council has set a public bounty on the murloc leader. Murkdeep lurks off the southern coast, near murloc huts clustered around a bonfire. Trespassers draw an organized defense: Greymist coastrunners and shore-crawlers surge from the surf to protect their settlement. Murkdeep then emerges alongside his vanguard to strike the intruders. Proof of Murkdeep's death meets a grim need for the Sentinels. Sentinel Glynda Nal'Shea handles the bounty payout for the council. With Greymist leadership broken, travelers and ships on the foggy Darkshore coast gain a reprieve from sabotage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4740-46fa023ae35454c6843d/1-0000.mp3", duration = 69.0416327, start = 0},
  },
}
P.transport["quest:475"] = {
  hash = "d539c0",
  fullHash = "d539c0",
  text = "A Troubling Breeze. Athridas Bearmantle waits for word from Starbreeze Village, but the reports have stopped. Great Warden Gaerolas Talvethren watches over the sleeping Druids of the Talon in the Ban'ethil Barrow Den, and his silence points to danger in Teldrassil. Athridas Bearmantle depends on regular word from Gaerolas Talvethren, the Great Warden watching over the Druids of the Talon in the Ban'ethil Barrow Den. The druids sleep there to keep their sacred pact with Ysera in the Emerald Dream. Their sanctuary matters to the spiritual balance of the young World Tree. Now reports from the east have ceased, and unease spreads through the forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_475-16213a013d7938760092/1-0000.mp3", duration = 35.2914286, start = 0},
  },
}
P.transport["quest:476"] = {
  hash = "5e2c2f",
  fullHash = "5e2c2f",
  text = "Gnarlpine Corruption. Near Starbreeze Village, Gnarlpine Corruption threatens Teldrassil. Wounded Great Warden Gaerolas Talvethren sends word to the night elf leadership in Dolanaar: Gnarlpine furbolgs have overrun the village and fallen to demonic corruption. Their violence may reach the sleeping druids of Ban'ethil Barrow Den. Near the ruins of Starbreeze Village, Gaerolas Talvethren lies grievously wounded after an ambush by his former allies. The Gnarlpine furbolgs were long regarded as peaceful neighbors and stewards of the wild, but now they have turned feral. Too injured to carry the warning himself, Gaerolas entrusts you with bringing word to Athridas Bearmantle in Dolanaar before the madness spreads farther through Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_476-369d1df9e4ed5103c4f2/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["quest:4761"] = {
  hash = "f24687",
  fullHash = "f24687",
  text = "Thundris Windweaver. In Auberdine, reports of Blackwood aggression reach the village elder. Terenthis sends you to Thundris Windweaver with news of the furbolgs’ growing hostility. Thundris seeks the cause of the corruption spreading through Darkshore. After scouting corrupted furbolg camps in Darkshore, you carry Terenthis’s report to Thundris Windweaver in Auberdine. Terenthis remains in the wilds to investigate the spreading corruption. As village elder, Thundris oversees the settlement’s daily welfare and considers the spiritual and environmental dangers facing the kaldorei. Your report gives Auberdine’s leadership evidence that the furbolgs are growing more than territorial: an unnatural malice is taking hold of them. Thundris has heard of rising hostility from the forest dwellers near Auberdine. The furbolgs’ aggression is not the only concern. Corruption is spreading through Darkshore’s soil, plants, and waters. Thundris believes the land cannot be healed until the source of the blight is found. He turns to the waterways and enlists capable allies to trace the taint upstream.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4761-9ad0404194f6cfab17a6/1-0000.mp3", duration = 63.8432653, start = 0},
  },
}
P.transport["quest:4762"] = {
  hash = "ec86ee",
  fullHash = "ec86ee",
  text = "The Cliffspring River. In Darkshore, foul water now runs down the Cliffspring River toward Auberdine. Thundris Windweaver asks Alliance investigators to take a sample from the pool beneath a road bridge waterfall. He suspects the corruption began beyond the riverbanks. The Cliffspring River runs from the eastern highlands to the coastal shoals of Mist's Edge, just north of Auberdine. Its waters have begun to carry an unnatural rot toward the night elf settlement. Thundris Windweaver fears the foul water will poison the shores and the town's supplies, so he sends scouts upriver to take samples from the waterfall pool beneath the road bridge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4762-240327d3dd2952283d90/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["quest:477"] = {
  hash = "7f08d4",
  fullHash = "7f08d4",
  text = "Border Crossings. Border Crossings is an espionage task assigned by Shadow Priest Allister in the Sepulcher to investigate Dalaran's covert operations in Silverpine Forest. By intercepting supply crates bound for the Dalaran encampment near Pyrewood Village, the Forsaken hope to uncover why the Kirin Tor are actively supporting the human bastion of Ambermill. While Ambermill stands as the main stronghold of surviving human resistance in eastern Silverpine Forest, the magi of Dalaran have not left them to stand alone. Wagon shipments filled with supplies and arcana have been smuggled out of the Hillsbrad Foothills, crossing through Silverpine to supply forward outposts and staging grounds. One such logistical camp sits just north of Pyrewood Village, manned by Dalaran personnel watching the road. Shadow Priest Allister and the Forsaken leadership at the Sepulcher find Dalaran's intense investment in Ambermill troubling. To them, a provincial town would hardly justify the Kirin Tor risking resources and lives deep within Forsaken-claimed territory unless some greater strategic or magical objective was at stake. Investigating the crates gives the Forsaken direct intelligence on what Dalaran is shipping west.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_477-d34193b7473480aa4125/1-0000.mp3", duration = 66.4816327, start = 0},
  },
}
P.transport["quest:478"] = {
  hash = "eeee59",
  fullHash = "eeee59",
  text = "Maps and Runes. Maps and Runes is a Forsaken reconnaissance mission in Silverpine Forest. After discovering a suspicious shipment shipped toward Ambermill, adventurers recover a rune-inscribed pendant to deliver to Shadow Priest Allister at the Sepulcher for further investigation. While intercepting logistics around Ambermill, Horde agents uncover a Dalaran crate concealed along the border routes. Rather than mundane supplies, the container holds detailed regional charts and an enigmatic, rune-inscribed pendant. Recognizing the potential danger of Dalaran's arcane reach so close to their borders, scouts carefully retrieve the artifact to avoid alarming the surrounding human sentries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_478-55d65511eaf56743c301/1-0000.mp3", duration = 39.7844898, start = 0},
  },
}
P.transport["quest:481"] = {
  hash = "1389b3",
  fullHash = "1389b3",
  text = "Dalar's Analysis. Dalar's Analysis is a Horde quest in Silverpine Forest linking Shadow Priest Allister's espionage against Ambermill with the arcane research of Dalar Dawnweaver. After uncovering a rune-inscribed pendant from a Dalaran supply crate, adventurers bring the relic to Dalar at the Sepulcher for scrutiny. The artifact reveals that the surviving mages of Dalaran are marshaling significant magical power for a hidden initiative. Following a raid on a Dalaran supply crate at a camp north of Pyrewood Village, Shadow Priest Allister receives a rune-inscribed pendant found beneath a bundle of old maps. Recognizing that its enchantment lies beyond his spiritual purview, Allister directs the relic to Dalar Dawnweaver, an arcane scholar stationed at the Sepulcher who is better suited to decipher Dalaran's magical warding.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_481-d8bf7eeb2870d0c01ae6/1-0000.mp3", duration = 47.5428571, start = 0},
  },
}
P.transport["quest:4811"] = {
  hash = "cbc4da",
  fullHash = "cbc4da",
  text = "The Red Crystal. Sentinel Glynda Nal'Shea asks travelers in Auberdine to investigate a red crystal in Darkshore's eastern mountains. Hostile moonkin are multiplying nearby and seem drawn to it, and the Sentinels need to know if the formation is real. Moonkin were long seen as gentle, mystical creatures bound to the wilds of Kalimdor. Now aggressive packs are multiplying along the slopes east of Auberdine. Some night elves still revere them, but Sentinel Glynda Nal'Shea puts the town's safety first as the danger grows. Reports place the beasts at a single spot among the eastern peaks. Scouts and wanderers speak of an unnatural red crystal jutting from a rocky hillside high above Darkshore. Rumors travel easily along the fogbound coast, so Glynda wants someone to see the place firsthand. The crystal is real, and the Sentinels still need to learn why the moonkin gather there and whether it threatens the land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4811-65d4c890fe1516867647/1-0000.mp3", duration = 50.6253061, start = 0},
  },
}
P.transport["quest:4812"] = {
  hash = "0b16fd",
  fullHash = "0b16fd",
  text = "As Water Cascades. Sacred water is brought to bear on the red crystal in Darkshore. Sentinel Glynda Nal'Shea hopes moonwell water from Auberdine will reveal what lies beneath its opaque surface. Sentinel Glynda Nal'Shea seeks a safe way to study the red crystal high on Darkshore's eastern cliffs. Moonwell water holds divine, restorative magic, blessed by the night elves' devotion to Elune. Glynda believes water from Auberdine's moonwell may react with the strange stone and pierce its opaque shell without destroying it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_4812-d165c44b564598417a6f/1-0000.mp3", duration = 31.0595918, start = 0},
  },
}
P.transport["quest:482"] = {
  hash = "3e0742",
  fullHash = "3e0742",
  text = "Dalaran's Intentions. Dalaran's Intentions is a Silverpine Forest quest delivered by Dalar Dawnweaver to Shadow Priest Allister. Having studied a rune-inscribed pendant bound for the Kirin Tor in Ambermill, Dalar realizes the wizards intend to tap a dormant ley energy node beneath the town, prompting the Forsaken leadership at the Sepulcher to plan a counter-offensive. While examining a rune-inscribed pendant recovered from a Dalaran supply crate, Dalar Dawnweaver remembers an old Kirin Tor survey. Ambermill was not chosen by the mages by coincidence; the quiet village rests directly atop a dormant ley energy node. Awaking such a subterranean nexus requires immense magical reserves, and the enchanted pendants worn by the wizards serve as key components in channeling and catalyzing that power. The Forsaken cannot tolerate a fortified, power-fueled Kirin Tor outpost threatening the southern approaches to the Sepulcher and Tirisfal Glades. Whatever grand ritual the magi are preparing, harnessing raw ley lines would grant Dalaran an enormous strategic advantage in Lordaeron. Dalar sends word urgently to Shadow Priest Allister to formulate a strategy that will stall the wizards' progress before their ritual reaches completion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_482-04f53949c6a3497a750e/1-0000.mp3", duration = 73.3518367, start = 0},
  },
}
P.transport["quest:483"] = {
  hash = "2e3492",
  fullHash = "2e3492",
  text = "The Relics of Wakening. At Ban'ethil Barrow Den, an urgent effort is underway to save the sleeping Druids of the Talon. Corrupted Gnarlpine furbolgs have overrun the sacred mounds, threatening the druids whose spirits wander the Emerald Dream. Four ritual relics are needed to bring the sleepers safely back to the waking world. West of Dolanaar, a swarm of corrupted Gnarlpine furbolgs has overrun the winding corridors of Ban'ethil Barrow Den. Barrow dens are secluded sanctuaries where night elf druids hibernate while their spirits walk the Emerald Dream. A foul taint spreading across Teldrassil has driven these former allies mad. They have desecrated the sanctum, leaving the sleepers unaware that danger threatens their physical bodies. Athridas Bearmantle needs four sacred relics for the delicate ceremony that can safely awaken the Druids of the Talon. A druid's spirit needs an anchor when returning from the Dream; without one, a sudden awakening can shatter the mind or strand the spirit. The relics lie in chests across the den: the Raven Claw Talisman, the Black Feather Quill, the Sapphire of Sky, and the Rune of Nesting. They are the sleepers' only hope before the Gnarlpine butcher or abduct them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_483-0407a232a0283872e96e/1-0000.mp3", duration = 69.5118367, start = 0},
  },
}
P.transport["quest:486"] = {
  hash = "f9db26",
  fullHash = "f9db26",
  text = "Ursal the Mauler. In Teldrassil, Athridas Bearmantle seeks to wake the Druids of the Talon from their unnatural sleep. Their kin remain trapped in the Barrow Den, and the corrupted Gnarlpine chief behind the disturbance must be slain. The Druids of the Talon withdrew to the Barrow Den of Ban'ethil to sleep and commune with the Emerald Dream. Their peaceful trance became a prison with no way back to waking. Athridas Bearmantle traced the trouble to the gnarlpine furbolgs, and to their vicious leader, Ursal the Mauler, who meddled with the druids' sacred ritual. The sleepers remain caught between waking and the Dream. Athridas needs more than the Relics of Wakening to reach the druids through the spiritual fog. The source of the interference must be ended. Ursal the Mauler makes his lair in Gnarlpine Hold, the tribe's home in far southwestern Teldrassil. Striking down the furbolg warlord breaks his hold on the sleepers' minds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_486-be00a099b9d9fe53c3c8/1-0000.mp3", duration = 52.9502041, start = 0},
  },
}
P.transport["quest:487"] = {
  hash = "69dd13",
  fullHash = "69dd13",
  text = "The Road to Darnassus. Along Teldrassil’s western road, corrupted Gnarlpine furbolgs threaten the route from Dolanaar to Darnassus. Moon Priestess Amara coordinates scouts and travelers to keep this trade and messenger road clear of ambushes. You travel west from Dolanaar toward Darnassus on Teldrassil’s main overland road. Trade goods, political messages, and travelers use it each day to stay connected with the capital and the boughs of the great tree. Teldrassil is young and wild, so safe roads matter to its kaldorei communities. The Gnarlpine furbolgs of Teldrassil have fallen to a foul corruption. Driven mad by a sickness plaguing the boughs of the World Tree, they attack from hidden dens beneath the ridges. Gnarlpine ambushers stalk the tree line beside the road, preying on couriers and travelers and making the forest passage deadly. Moon Priestess Amara watches over the road outside Dolanaar. She joins the spiritual authority of Elune’s priesthood with the Sentinels’ vigilance, directing capable travelers to strike at ambushers near their dens below the road. The safety of the route to Darnassus’s gates depends on keeping them at bay.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_487-731b5540bf0da0ea3f23/1-0000.mp3", duration = 64.6269388, start = 0},
  },
}
P.transport["quest:488"] = {
  hash = "50f633",
  fullHash = "50f633",
  text = "Zenn's Bidding. Zenn Foulhoof draws newcomers into his schemes north of the road from Shadowglen to Dolanaar. The solitary satyr asks them to gather animal parts, preying on their trust and naivety. Travelers on the path from Shadowglen to Dolanaar may find Zenn Foulhoof beneath the Great Tree. The satyr offers material rewards and secrets for simple work, asking for nightsaber fangs, strigid owl feathers, and webwood spider silk from the surrounding woods. He whispers conspiratorially, urging travelers to keep their bargain between themselves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_488-09a42f304f1cbb5360ca/1-0000.mp3", duration = 31.0595918, start = 0},
  },
}
P.transport["quest:489"] = {
  hash = "b08cf1",
  fullHash = "b08cf1",
  text = "Seek Redemption!. In Dolanaar, you face the Council of the Forest's demand for atonement. Adventurers were duped into doing Zenn Foulhoof's dirty work, and now the council sends you to trick the satyr into eating corrupted fel cones. Just outside Dolanaar, solitary satyr Zenn Foulhoof uses deceit to make passersby do his bidding. Adventurers who unwittingly slaughtered nightsabers, strigid owls, and webwood spiders to satisfy his twisted appetites draw the Council of the Forest's sharp disapproval. The council will not accept harm to nature, especially from its own allies. Syral Bladeleaf, Sentinel Kyra Starsong, or Sentinel Shayla Nightbreeze warns you that you must make amends to remain welcome in Teldrassil. Dolanaar's guardians tell you to turn Foulhoof's wicked gluttony against him instead of facing him with steel. Gather the billowing, corrupted fel cones from the forest floor, then offer the unsuspecting satyr a taste of his own foul medicine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_489-71175070cf4e1aee9bfa/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["quest:492"] = {
  hash = "0e0232",
  fullHash = "0e0232",
  text = "A New Plague. This quest marks the grim culmination of Apothecary Johaan's initial research in Brill on behalf of the Royal Apothecary Society. Having harvested venom, blood, and vile concoctions across Tirisfal Glades, Johaan sends you to the cellar of Gallows' End Tavern to test his lethal brew on a captive dwarven mountaineer. Throughout your time aiding Apothecary Johaan, your efforts have steadily built toward refining a lethal toxin. The Royal Apothecary Society pursues an ambitious and shadowy agenda on behalf of Lady Sylvanas Windrunner: crafting a new plague that bypasses undead biology while annihilating the living. In this final step, Johaan brews what he euphemistically calls a 'special drink' and tasks you with administering it directly to an imprisoned enemy of the Forsaken. Beneath Gallows' End Tavern in Brill, the Deathguard maintains a damp cellar used as a makeshift holding cell for captives awaiting interrogation or disposal. Among them sits a captured Dwarven Mountaineer, an operative of the Ironforge reconnaissance units trespassing in Tirisfal Glades. Defiant and thirsty, he eagerly accepts a drink, completely unaware of its true alchemical payload.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_492-64940d67878c9da86f97/1-0000.mp3", duration = 70.635102, start = 0},
  },
}
P.transport["quest:5041"] = {
  hash = "277019",
  fullHash = "277019",
  text = "Supplies for the Crossroads. Thork needs supplies back at the Crossroads after Razormane quilboar raids. The stolen crates hold provisions the outpost needs amid conflict across the Barrens. Thork needs provisions restored to the Crossroads after a supply caravan is ambushed. The outpost links Horde travel, trade, and defense across the Barrens, and cargo arrives from Durotar and Mulgore. Without it, shortages of provisions, tools, and arms threaten daily life in the harsh wilderness. Razormane quilboar have taken the crates. These swine-beasts contest Horde control across central Kalimdor. They hauled the cargo to their thorn-bush camps and keep it there. Thork sends trusted warriors into Razormane territory to recover the supplies for the Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5041-25eb2eddbce6cf877847/1-0000.mp3", duration = 42.6579592, start = 0},
  },
}
P.transport["quest:5061"] = {
  hash = "5e2dc3",
  fullHash = "5e2dc3",
  text = "Aquatic Form. You return to Darnassus with the restored Pendant of the Sea Lion. The rite teaches Alliance druids to attune their spirits to deep waters. For Cenarion Circle initiates, shapeshifting joins the druid’s spirit to the wild aspects of Azeroth. After enduring trials in the dark coastal depths and in Moonglade, young night elf druids receive the assembled Pendant of the Sea Lion from Dendrite Starblaze. They carry the sacred token back to Teldrassil as proof of their respect for the laws of air, water, and breath. Mathrengyl Bearwalker awaits your return in the Cenarion Enclave. The trials along the coasts of Darkshore and Westfall demand endurance and attunement. Presenting the completed pendant shows Bearwalker that your mind and body are ready to shed their mortal skin and take the swift, breathing form of the sea lion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5061-d6c1085822cdb6fc0823/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:52"] = {
  hash = "420b76",
  fullHash = "420b76",
  text = "Protect the Frontier. Guard Thomas watches Elwynn's eastern bridge as predators threaten the frontier. Stormwind's forces are thin here, and wolves and bears have grown bold near the Eastvale Logging Camp. He asks capable adventurers to cull the beasts threatening travelers and workers. Guard Thomas watches the bridge over the river at Elwynn Forest's eastern edge. Goldshire and the Northshire Valley have a visible Stormwind garrison, but this frontier receives far less protection. With Stormwind's forces stretched across the realm, Thomas is one of few sentries between the settled heartlands and the wilderness. Travelers help keep vital supply roads open. Eastvale Logging Camp supplies timber to Stormwind City, but woodsmen felling trees at the forest's edge meet dangerous wildlife. Prowlers, gray forest wolves, and young forest bears now roam near roads and lumber yards. Culling them eases the danger to local workers for a time. Thomas suspects a disturbance deeper in the woods is driving the beasts toward settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_52-9cb5fcf01a49426cdd85/1-0000.mp3", duration = 58.9583673, start = 0},
  },
}
P.transport["quest:5261"] = {
  hash = "40c595",
  fullHash = "40c595",
  text = "Eagan Peltskinner. Outside Northshire Abbey, Eagan Peltskinner has work for recruits as timber wolves threaten the valley. The local furrier needs hunters to thin the packs and bring back pelts. Deputy Willem often sends recruits from the abbey to find Eagan Peltskinner, who works nearby on its grounds. Northshire Valley's orchards and fields lie beside wild woods where timber wolves prowl. Eagan wants newcomers to hunt the aggressive packs and gather pelts for his craft. Timber wolves threaten workers, acolytes, and supplies moving in and out of Northshire. Sending young champions to Eagan helps keep nearby paths safe while sparing Stormwind's few remaining guards. They are already occupied by rising tensions across Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5261-4c1afb01b49c38043f27/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["quest:543"] = {
  hash = "afeb76",
  fullHash = "afeb76",
  text = "The Perenolde Tiara. Count Remington Ridgewell seeks a lost heirloom in the Ruins of Alterac. The Stormwind aristocrat sends mercenaries north to recover the Perenolde Tiara, once owned by Alterac's royal family and now said to be held by an ogre mage. Alterac's royal family wore an emerald-set tiara crafted by master dwarven jewelers in Ironforge. During the Second War, King Aiden Perenolde betrayed the Grand Alliance and joined the Orcish Horde. His betrayal led to Alterac's conquest and collapse. In the fall of Alterac City, many treasures of the royal family vanished among the snowy rubble of the Alterac Mountains. Grel'borg the Miser, an ogre mage of the Crushridge ogres, came to hold the tiara among the ruins of Alterac. He searches the broken stones for baubles and abandoned wealth. Count Remington Ridgewell, a collector of historical oddities in Stormwind City, learns the tiara survived. He hires mercenaries to enter ogre-held territory, defeat Grel'borg, and bring the jewel back to his gallery.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_543-ca773d79d583f90458f0/1-0000.mp3", duration = 59.7420408, start = 0},
  },
}
P.transport["quest:5481"] = {
  hash = "f3eaf3",
  fullHash = "f3eaf3",
  text = "Gordo's Task. Gordo's Task is an errand in Tirisfal Glades given by Gordo, a wandering abomination trying to gather flora along the road to Brill. Unsuited for delicate fieldwork, he recruits travelers to pick Gloom Weed and deliver it to his handler, Junior Apothecary Holland. Gordo is an abomination who trudges back and forth along the countryside between Deathknell and Brill. While abominations excel at brute combat and heavy hauling, their massive, sutured hands make fine manipulation almost impossible. Sent into the meadows to gather ingredients for the Royal Apothecary Society, Gordo quickly realizes his blunt fingers crush more stems than they pluck, prompting him to bully or bribe passersby into doing the tedious work for him.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5481-83c9fae233cb83207ecf/1-0000.mp3", duration = 42.24, start = 0},
  },
}
P.transport["quest:5482"] = {
  hash = "4bb481",
  fullHash = "4bb481",
  text = "Doom Weed. Doom Weed is a task given by Junior Apothecary Holland in Brill to gather noxious flora sprouting near Tirisfal's northern mass graves. Holland recruits passing adventurers after becoming frustrated with the clumsy harvesting efforts of the abomination Gordo. Junior Apothecary Holland conducts research on behalf of the Royal Apothecary Society from the settlement of Brill. Seeking to advance his experiments, he requires quantities of doom weed, a vile plant that infests the blighted soil of Tirisfal Glades. Finding Gordo incapable of discerning the proper reagents, Holland turns to sharper hands to salvage his harvest. Doom weed thrives in places heavily corrupted by death and plague, proliferating densely around the mass gravesite situated just north of the Brill graveyard. Gathering the flora is made perilous by aggressive Rot Hide gnolls that prowl the desecrated burial mounds, scavenging among the remains and defending the overgrown trenches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5482-81e074dbd63b51971b03/1-0000.mp3", duration = 55.1967347, start = 0},
  },
}
P.transport["quest:5502"] = {
  hash = "0ab467",
  fullHash = "0ab467",
  text = "A Warden of the Horde. In Orgrimmar, Children's Week ends with Grunth's return to Orphan Matron Battlewail. After seeing the world with his guardian, the young orphan hopes to become a hero himself. After the adventures of Children's Week, Grunth thanks you for showing him more than he ever dreamed he would see. He remembers his parents' advice to rise above hardship and hopes to become a hero like you. His final request is to return home and tell the matron about your time together. You return Grunth to Orphan Matron Battlewail at the orphanage in the Valley of Honor. In the new Horde, caring for the young is a profound duty, since war has left countless children without parents. Battlewail praises your compassion as the true measure of a Horde hero. Grunth parts with a beloved pet so you will remember the bond formed during your travels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5502-ad2b9150acd6b3e58b13/1-0000.mp3", duration = 45.4530612, start = 0},
  },
}
P.transport["quest:5541"] = {
  hash = "df894d",
  fullHash = "df894d",
  text = "Ammo for Rumbleshot. Gunsmith Hegnar Rumbleshot is running low on shot and powder for the riflemen practicing outside Anvilmar. A missing crate of ammunition was abandoned in the snowy wilds near the Grizzled Den when a courier was routed by hungry wendigo. Loslor Rudge at Steelgrill's Depot keeps steady supply lines flowing to tradesmen across Dun Morogh, but the valley's wildlife often interferes. His latest shipment of heavy ammunition never reached Hegnar Rumbleshot's roadside workshop. While camping near the cave system known as the Grizzled Den, the terrified courier crossed paths with local wendigo and fled for his life, abandoning the heavy wooden crate in the snow. Hegnar Rumbleshot operates a gun shop situated right along the main road leading away from Anvilmar. The clearing outside his forge sees constant traffic from Ironforge riflemen, mountaineers, and dwarven mortar squads looking to zero their sights and drill with live fire. Without steady crates of powder and lead from suppliers like Loslor, the riflemen's marksmanship training quickly grinds to a dead stop.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5541-bd37e204b8238819313e/1-0000.mp3", duration = 61.5967347, start = 0},
  },
}
P.transport["quest:5545"] = {
  hash = "216b50",
  fullHash = "216b50",
  text = "A Bundle of Trouble. At Eastvale Logging Camp, A Bundle of Trouble begins with timber left in the woods and a deadline near. Supervisor Raelen needs the cut wood brought back before the shipment falls behind. Supervisor Raelen has a shipment of timber due soon. Eastvale Logging Camp cuts wood for Stormwind, and her crew has fallen behind schedule. With the deadline close, Raelen needs the timber sent on its way. Wolves and bears north of the camp have driven the woodcutters away from bundles of cut timber. The workers left the wood where it lay. Raelen cannot wait for guards to clear the area, so she asks you to bring the bundles back to camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5545-8042a0ef3602ea222aa9/1-0000.mp3", duration = 37.3812245, start = 0},
  },
}
P.transport["quest:5621"] = {
  hash = "c9ebde",
  fullHash = "c9ebde",
  text = "Garments of the Moon. Laurna Morninglight sends a young priest to aid a wounded Sentinel south of Dolanaar. The duty tests an initiate's devotion and brings formal recognition in the Sisterhood of Elune. The Sisterhood of Elune guides kaldorei in worship and helps defend Teldrassil's borders. Sentinel Shaya is wounded while patrolling the wilderness south of Dolanaar, and priest trainer Laurna Morninglight cannot leave her post to help. She asks a newly trained initiate to tend Shaya's wounds and strengthen her with protective magic. After restoring Sentinel Shaya's vigor, a priest returns to Dolanaar to receive formal robes of office from Laurna Morninglight. The robes mark an acolyte's passage from classroom instruction to practical service that can save lives. For the kaldorei, aiding the Sentinels is both service to Elune and a duty to Teldrassil's safety.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5621-0ccb1447dbd51d83ece0/1-0000.mp3", duration = 48.7183673, start = 0},
  },
}
P.transport["quest:5622"] = {
  hash = "33def8",
  fullHash = "33def8",
  text = "In Favor of Elune. Young night elf priests leave Shadowglen for guidance and training in Dolanaar. Priestess Shanda sends them along the forest path to Laurna Morninglight. Priestess Shanda trains initiates serving Elune within Aldrassil's secluded shelter. Their learning begins with simple prayers and defensive invocations under her watchful eye. Shadowglen's cloistered life cannot prepare a priestess or priest for the turmoil gripping the wider world. Once an initiate shows steady faith and discipline, Shanda sends them down the shadowed forest path toward Dolanaar to continue their education. Reaching Dolanaar marks an essential milestone in a night elf's divine vocation. There, respected priestess Laurna Morninglight prepares disciples for the trials facing Teldrassil. The acolyte can receive advanced instruction in moonlit spellcraft and claim their first formal vestments, marking their official standing within the Sisterhood of Elune.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5622-5d3470a5b5bf73a3cc75/1-0000.mp3", duration = 55.4579592, start = 0},
  },
}
P.transport["quest:5623"] = {
  hash = "fbcbae",
  fullHash = "fbcbae",
  text = "In Favor of the Light. Priestess Anetta sends you south from Northshire Abbey to continue your training in Goldshire. Priestess Josetta is waiting at the Lion's Pride Inn to guide your next steps in the Holy Light. Northshire Abbey gives you shelter and your first lessons in the Holy Light. After you learn prayer and divine healing, Priestess Anetta sends you south along the road to Goldshire. There, you leave the abbey's sheltered study for service among the people of Elwynn. Priestess Josetta tends to Goldshire's spiritual needs from the Lion's Pride Inn and guides rising acolytes. She builds on the lessons you learned at the abbey, teaching you to offer comfort, protect the faithful, and heal the injured. Under her guidance, you begin learning the duties of the Church's servants across the kingdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5623-0c51beb5e15ab5f887b5/1-0000.mp3", duration = 43.5461224, start = 0},
  },
}
P.transport["quest:5624"] = {
  hash = "d9e92b",
  fullHash = "d9e92b",
  text = "Garments of the Light. At Goldshire, Garments of the Light mark a novice priest’s first trial under Priestess Josetta. She sends you east to Crystal Lake to tend the wounded Guard Roberts. The work tests your healing and earns you vestments recognized by the Church of the Holy Light. Priestess Josetta teaches acolytes who come to Goldshire from Northshire Abbey. Before the Church of the Holy Light formally recognizes a novice, she tests their skill with divine power. When Guard Roberts is reported wounded by the lake east of Goldshire, Josetta sends you to care for him. His need gives you a chance to prove your healing in practice. You need to do more than close Guard Roberts’s wounds. Mend him with restorative prayers, then strengthen him with a blessing of fortitude. Stormwind’s forces are stretched thin, and local garrisons face kobolds and bandits. Josetta teaches that priests help defenders endure danger. Healing Roberts will aid the township and show that you can support its guards. After treating Guard Roberts, return to the Lion’s Pride Inn. There you receive your first formal robes, a sign of approval and fellowship from the priesthood in Stormwind. The robes are not required for further training, but they show that the Church recognizes you as a servant of the Holy Light.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5624-1a9cb094f64c3c5fa60c/1-0000.mp3", duration = 72.8816327, start = 0},
  },
}
P.transport["quest:5625"] = {
  hash = "481b4f",
  fullHash = "481b4f",
  text = "Garments of the Light. Garments of the Light is an early rite of passage for fledgling dwarven priests in Dun Morogh. Directed by Priest Trainer Maxan Anvol in Kharanos, the initiate is tasked with aiding a wounded mountaineer just outside town to earn their vestments. Traditionally, acolytes of the Holy Light undergo formal trials to prove they are worthy of wearing church vestments. In Kharanos, however, priest trainer Maxan Anvol favors practical results over ceremony. With local patrols hard-pressed against troggs and wild beasts, theoretical exams take a back seat when actual defenders lie bleeding in the snow. To earn their robes, young priests are sent just south of town to locate Mountaineer Dolf, who was wounded in the line of duty. By mending Dolf's injuries with restorative prayers and bolstering his constitution with Power Word: Fortitude, the initiate proves that their devotion translates directly into survival for the defenders of Ironforge. Upon aiding the mountaineer, Maxan Anvol presents the acolyte with their formal garments. Beyond providing warm insulation against Dun Morogh's chill, these robes serve as a visual badge of office, signaling to wounded wanderers and local guards alike that a servant of the Light is present to offer aid.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5625-d7daf76706cb7cc96585/1-0000.mp3", duration = 72.8816327, start = 0},
  },
}
P.transport["quest:5626"] = {
  hash = "3c38de",
  fullHash = "3c38de",
  text = "In Favor of the Light. \"In Favor of the Light\" marks a young priest's rite of passage from the isolated training grounds of Coldridge Valley into the wider reaches of Dun Morogh. Instructed by Branstock Khalder, novitiates are sent through the mountain tunnel to Kharanos to further their studies under Priest Trainer Maxan Anvol. It signals that an acolyte is ready to shoulder real responsibilities and earn the traditional vestments of their calling. In the secluded cradle of Coldridge Valley, dwarven priests begin their studies under the watchful eye of instructors like Branstock Khalder. Once a novice demonstrates sufficient dedication and grasp of Holy magic, their preliminary instruction comes to an end. Rather than keeping them sheltered in Anvilmar, Khalder directs promising students beyond the mountains to Kharanos, where the demands of ministry and defense intersect with the daily struggles of Dun Morogh's folk. Reaching Kharanos requires trekking through the Coldridge Pass tunnel into the windswept snows of central Dun Morogh. Waiting at the settlement is Maxan Anvol, a senior priest tasked with guiding students beyond rudimentary prayers. Anvol believes firmly that devotion to the Holy Light requires equal measures of moral character, physical hardiness, and an unyielding will. For acolytes who prove their resolve under his tutelage, Anvol prepares to bestow their first formal garments of office.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5626-ffd83675d2bfecbdc04f/1-0000.mp3", duration = 78.3934694, start = 0},
  },
}
P.transport["quest:5627"] = {
  hash = "60014b",
  fullHash = "60014b",
  text = "Stars of Elune. In Darnassus, night elf acolytes are called to the Temple of the Moon after proving their devotion to their people. There, the Sisterhood of Elune teaches them sacred arts of their faith. Night elf priests draw their holy power from Elune, their goddess, while humans and dwarves turn to the Light. When an acolyte serves the realm with steadfast devotion, the Sisterhood in Darnassus takes notice. The acolyte is summoned to the Temple of the Moon and judged ready for deeper communion. There, the priest learns sacred spells passed down through thousands of years of worship. Priestess Alathea calls the initiate to receive instruction in holy mysteries of the night elf faith, including Starshards. These spells channel the radiant wrath and grace of the White Lady. The teaching marks an acolyte's passage beyond basic training, ready to venture beyond Teldrassil's protective canopy in Elune's name.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5627-3be99cddfd26dd2ca465/1-0000.mp3", duration = 52.4016327, start = 0},
  },
}
P.transport["quest:5628"] = {
  hash = "53c458",
  fullHash = "53c458",
  text = "Returning Home. In Goldshire, a novice night elf priest receives a call to return home. The novice has wandered as far as Elwynn Forest, where Priestess Josetta relays an urgent message from Darnassus: return to the Temple of the Moon and continue spiritual training under Priestess Alathea. Night elves are an unusual sight in Elwynn Forest, and a young acolyte among its human settlements draws attention. When you arrive in Goldshire, Priestess Josetta greets you warmly with news. A Sister of Elune has traveled across continents seeking you, bearing an urgent command from the Temple of the Moon. It is time to return to Kalimdor and advance your calling. At the heart of Darnassus stands the Temple of the Moon, center of night elf faith and leadership. Priestess Alathea and High Priestess Tyrande Whisperwind oversee the Sisterhood’s instruction, watching their disciples even when curiosity carries them overseas. When you return, the priestesses welcome you with motherly concern and immediately set you to deeper studies of the Moon Goddess’s celestial mysteries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5628-97be7cb7894a92033a12/1-0000.mp3", duration = 61.44, start = 0},
  },
}
P.transport["quest:5629"] = {
  hash = "0ad840",
  fullHash = "0ad840",
  text = "Returning Home. In Darnassus, Returning Home brings young night elf priests before the leaders of their faith. After proving themselves in Teldrassil’s wilds, they are summoned to the Temple of the Moon to meet Priestess Alathea and High Priestess Tyrande Whisperwind. Priests tending the wounded and cleansing corruption around Dolanaar draw the Sisterhood of Elune’s notice. Trainer Laurna Morninglight intercepts promising initiates with word that Priestess Alathea has asked to meet them. Aid to local settlements matters, but each devotee must also deepen their communion with the Moon Mother and answer the faith’s higher calling. The road leads from Teldrassil’s boughs to the Temple of the Moon in Darnassus. The sanctuary rises above the city in Elune’s gentle glow. It is the kaldorei’s chief house of worship and spiritual capital. An invitation into its halls means an initiate is recognized by the priesthood’s leaders, no longer treated only as a young student. Priestess Alathea greets returning initiates warmly. She says she and High Priestess Tyrande Whisperwind take pride when initiates venture into the uncertain world and return unharmed. This homecoming begins deeper sacred trials under Alathea’s direct guidance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5629-67fea7318276dd14e850/1-0000.mp3", duration = 68.9632653, start = 0},
  },
}
P.transport["quest:5630"] = {
  hash = "462d4d",
  fullHash = "462d4d",
  text = "Returning Home. A summons reaches wandering night elf priests in Dun Morogh, calling them back to Darnassus. Maxan Anvol, the dwarven priest trainer, directs them to report to Priestess Alathea at the Temple of the Moon. In Kharanos, Maxan Anvol takes note of the night elf's fortitude amid Dun Morogh's bitter cold, far from Teldrassil's serene forests. The dwarven priest trainer brings urgent word: a priestess of Elune passed through looking for the elf, carrying orders from Darnassus that demand an immediate return. The road leads across the sea to the Temple of the Moon in Darnassus, among Teldrassil's sacred boughs. Priestess Alathea welcomes the traveler back to the Sisterhood of Elune, relieved to see another devotee return unscathed from foreign lands. She swiftly prepares the priest for the next rites of devotion, beginning with the Stars of Elune.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5630-c1a8e88a2e477dceb8d3/1-0000.mp3", duration = 48.9534694, start = 0},
  },
}
P.transport["quest:5631"] = {
  hash = "b20304",
  fullHash = "b20304",
  text = "Returning Home. In human lands, a night elf priest receives a summons to return to Teldrassil. Brother Joshua delivers the message from Priestess Alathea, who calls the young priest to the Temple of the Moon in Darnassus for advanced guidance in Elune’s mysteries. Night elf priests sometimes travel to human lands such as Stormwind to share spiritual fellowship with the Church of the Holy Light. Their deepest ties remain with the Sisterhood of Elune. Brother Joshua tells an acolyte that a night elf emissary has come searching for them. Their early travels are over, and their home temple calls them back for deeper training with High Priestess Tyrande Whisperwind’s inner circle. Across the sea, Darnassus welcomes the returning priest at the Temple of the Moon. Priestess Alathea greets the acolyte warmly and celebrates their safe passage through a troubled world. Their return brings joy to Alathea and Tyrande, while more demanding spiritual trials await.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5631-01ead8c5a3e15aea7aaa/1-0000.mp3", duration = 54.8832653, start = 0},
  },
}
P.transport["quest:5632"] = {
  hash = "2d3a31",
  fullHash = "2d3a31",
  text = "Returning Home. Priestess Alathea calls promising night elf priests back to Darnassus. The summons brings them to the Temple of the Moon to be recognized by the Sisterhood of Elune and receive advanced guidance. A messenger from the Sisterhood reaches you while you visit Nara Meideros in Stormwind's Park. You have served your people abroad, and the order's leaders now require you in Darnassus. They have watched your spiritual growth and call you back for an evaluation and a rite of recognition. The journey marks your passage from a new initiate to an active servant of the Mother Moon. The summons sends you to Priestess Alathea at the Temple of the Moon, Darnassus's highest sanctuary. High Priestess Tyrande Whisperwind oversees the Sisterhood, which watches over its members wherever they serve. Your safe return to the temple honors your community and Elune. It also shows that the goddess's grace has guided and preserved you through your early trials in the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5632-6b1caa9e660cd6cc3993/1-0000.mp3", duration = 54.1518367, start = 0},
  },
}
P.transport["quest:5633"] = {
  hash = "1a4013",
  fullHash = "1a4013",
  text = "Returning Home. Night elf priests in Ironforge are called back to the Temple of the Moon in Darnassus. A Sisterhood emissary seeks out acolytes abroad and sends them to Priestess Alathea for urgent training and sacred duties. In Ironforge, night elf priests remain tied to the Sisterhood of Elune, though they are far from Teldrassil. Braenna Flintcrag, a dwarven priest trainer in the Mystic Ward, carries a message from a visiting night elf priestess. The messenger sought young disciples traveling abroad and said their mentors needed them back in the capital at once. At the Temple of the Moon in Darnassus, returning acolytes report to Priestess Alathea. Beneath the watchful gaze of High Priestess Tyrande Whisperwind, Alathea welcomes her student and is relieved they crossed the seas safely. Their return begins further devotion and sacred duties, including the Stars of Elune.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5633-c55f4e3e6cd3fa9df909/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["quest:5634"] = {
  hash = "4839bb",
  fullHash = "4839bb",
  text = "Desperate Prayer. In Stormwind, human priests seek a prayer for their own hour of need. At the Cathedral of Light, High Priestess Laurena teaches acolytes to call on the Holy Light when their lives are at risk. Priests in the Cathedral of Light learn to use their faith to shield companions, heal wounds, and strike at evil. Yet even the devout can be isolated, cornered, or brought close to death. In such moments, an acolyte may cry out to the Holy Light for help, with their own survival at stake. High Priestess Laurena guides clergy in Stormwind's Cathedral Square and judges when an acolyte is ready for deeper teachings. Human initiates who show devotion to the Light across the kingdom receive this lesson as both protection and a charge to continue serving the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5634-ac11a2d353839434da0a/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:5635"] = {
  hash = "ec6d4e",
  fullHash = "ec6d4e",
  text = "Desperate Prayer. Promising priests from Elwynn Forest are summoned to Stormwind for further training in the Church of the Holy Light. After proving their devotion and discipline, they come before High Priestess Laurena at the Cathedral of Light. Priestess Josetta guides novice priests in Goldshire, while other local mentors serve the outlying settlements of Elwynn Forest. When a disciple proves capable in spirit and deeds, word reaches the senior priesthood in Stormwind. A summons to the Cathedral of Light marks the move to deeper responsibilities in the faith and formal training at the spiritual heart of the Kingdom of Stormwind. At the Cathedral, acolytes present themselves to High Priestess Laurena, one of the Church's senior leaders in Stormwind. She oversees their spiritual grounding and practical training as newly elevated priests. Her instruction prepares them for the harsh trials facing the Alliance and teaches the Light's miracles, including Desperate Prayer, the plea for salvation known among human practitioners.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5635-196b8931a8681620764e/1-0000.mp3", duration = 55.7453061, start = 0},
  },
}
P.transport["quest:5636"] = {
  hash = "42e9fa",
  fullHash = "42e9fa",
  text = "Desperate Prayer. In Dolanaar, Laurna Morninglight sends human priests home to Stormwind for further training. A fellow priest has crossed continents to summon them to the Cathedral of Light. In Dolanaar, Priestess Laurna Morninglight brings you word from home. A fellow priest has crossed continents to find you, and Laurna urges you to return without delay. She offers Elune’s blessing and good wishes for your faith as you leave Teldrassil. Your path leads across the Great Sea to Stormwind City’s Cathedral of Light. High Priestess Laurena guides the Alliance faithful in their spiritual growth. She summons promising acolytes to deepen their devotion and learn Desperate Prayer, an emergency prayer that can save a life in a darkest hour.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5636-3309af8f9f5c7538d739/1-0000.mp3", duration = 42.0832653, start = 0},
  },
}
P.transport["quest:5637"] = {
  hash = "049b14",
  fullHash = "049b14",
  text = "Desperate Prayer. In Stormwind, dwarven priests are called to deepen their service to the Light. High Priestess Laurena summons promising acolytes from Dun Morogh to the Cathedral of Light. There they take on wider duties among the Alliance. Dwarven priests trained in Dun Morogh can outgrow the lessons of local mentors like Maxan Anvol in Kharanos. When an acolyte shows promise, High Priestess Laurena sends a formal summons from the Cathedral of Light. Her attention means the young priest is ready for deeper study and greater duties in the faith. Ironforge keeps its own holy traditions in the Mystic Ward, while Stormwind's Church of the Holy Light welcomes humans and dwarves alike. The journey south by Deeprun Tram brings dwarven acolytes into the wider church community and strengthens the spiritual bond between the allied kingdoms.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5637-4b39b260d71fed699c1a/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:5638"] = {
  hash = "17b80f",
  fullHash = "17b80f",
  text = "Desperate Prayer. In Stormwind, a summons carries a young priest from the Park to the Cathedral of Light. Nara Meideros sends you to High Priestess Laurena for further instruction. In Stormwind’s Park, Nara Meideros keeps faith with Elune. The city’s spiritual guides share ties across their different traditions. When the Cathedral seeks a promising student, Nara sends you across the canals with quiet encouragement. The message brings good tidings, not cause for alarm. At the Cathedral of Light in Cathedral Square, you report to High Priestess Laurena. One of Stormwind’s senior clerical leaders, she guides young acolytes beyond their first prayers. Laurena teaches the sacred invocation called Desperate Prayer, a personal plea for divine aid. It can mend grievous wounds in an instant when a servant of the Light stands near death.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5638-69e11fc7735901330b1e/1-0000.mp3", duration = 48.9795918, start = 0},
  },
}
P.transport["quest:5639"] = {
  hash = "b3b573",
  fullHash = "b3b573",
  text = "Desperate Prayer. Desperate Prayer is a rite of passage for dwarven priests coming of age in Ironforge. Dispatched by High Priest Rohan, acolytes journey through the Deeprun Tram to Stormwind to continue their training under High Priestess Laurena. Reaching the grand Cathedral of Light marks an initiate's transition into deeper mysteries of healing and survival. Within the stone vaults of Ironforge's Mystic Ward, High Priest Rohan oversees dwarven initiates dedicated to the Holy Light. When an acolyte demonstrates sufficient discipline and faith, Rohan directs them southwest to the human kingdom of Stormwind. Human and dwarven clerics maintain close spiritual bonds, and advanced theological instruction is centralized in the grand halls of Stormwind City. Upon arriving via the subterranean Deeprun Tram, acolytes ascend to the Cathedral Square. There, within the majestic Cathedral of Light, High Priestess Laurena tests candidates on behalf of the Church. Her instruction focuses on the desperate appeals a priest must make in the crucible of battle—pleas for divine intervention when physical endurance fails and death looms near.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5639-3c9d3c221aa621ce75b0/1-0000.mp3", duration = 67.3436735, start = 0},
  },
}
P.transport["quest:5640"] = {
  hash = "4440fc",
  fullHash = "4440fc",
  text = "Desperate Prayer. In Darnassus, young human and dwarven priests find guidance in another faith. Priestess Alathea teaches the ways of Elune, while followers of the Holy Light are directed to Stormwind. There, High Priestess Laurena welcomes the returning acolyte to the Cathedral of Light. Alliance priests follow different sacred paths. In Darnassus, the priesthood tends to Elune, channeling the moon goddess's radiance and wrath. Priestess Alathea honors Elune and respects the Holy Light, but cannot teach another race the deeper prayers bound to a different devotion. Human and dwarven acolytes who seek those prayers must look elsewhere. Initiates of the Holy Light return home to learn its rites, including the prayer for divine aid in a moment of peril. High Priestess Laurena guides returning priests in Stormwind's Cathedral of Light, beneath its marble arches.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5640-e89ebf4ae039502ca56c/1-0000.mp3", duration = 50.8081633, start = 0},
  },
}
P.transport["quest:5648"] = {
  hash = "8d7631",
  fullHash = "8d7631",
  text = "Garments of Spirituality. In Razor Hill, Tai'jin sends new priests to prove their healing in the field. They seek Grunt Kor'ja, wounded while standing against Kul Tiras survivors, and tend her injuries. Those who succeed earn ceremonial vestments and recognition among the Horde's spiritual practitioners. South of Razor Hill, the Horde still fights remnants of Grand Admiral Daelin Proudmoore's forces. Tai'jin, the troll priest trainer, tests new priests in the work of real combat triage. She sends them to find Grunt Kor'ja, a warrior badly wounded while repelling human infiltrators. You tend her injuries and strengthen her before she succumbs. Healing Kor'ja proves a young priest is ready to serve the Horde's spiritual tradition. Tai'jin awards the Garments of Spirituality for saving a frontline defender. To orcs and Darkspear trolls alike, the robes mark their wearer as more than an apprentice of incantations: they can be trusted to keep Horde warriors alive in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5648-8dfcea5e6219d37aade4/1-0000.mp3", duration = 54.0212245, start = 0},
  },
}
P.transport["quest:5649"] = {
  hash = "9c672f",
  fullHash = "9c672f",
  text = "In Favor of Spirituality. Young Darkspear priests leave the Valley of Trials under Ken'jai's direction. They report to Tai'jin in Razor Hill and take their first steps into Durotar's wider challenges. Their path balances ancestral troll heritage with life in the Horde. Darkspear acolytes leave the Valley of Trials after learning their basic rites under Ken'jai. The paths out of the secluded training grounds lead to Razor Hill, a crossroads settlement in Durotar. For a young priest, the journey marks a step beyond basic survival drills and toward the spiritual and cultural responsibilities of the tribe. Ken'jai speaks plainly about the Darkspear's place in Thrall's Horde. The trolls value the orcs' loyalty and lessons of honor, yet some ancestral traditions sit uneasily among their allies. Darkspear spiritual leaders teach their pupils to preserve their heritage quietly while serving the Horde. At Razor Hill, Tai'jin welcomes the acolytes and guides them toward self-sufficiency and strength within the community.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5649-48c7b8694dcaad0ac8f0/1-0000.mp3", duration = 57.6, start = 0},
  },
}
P.transport["quest:5650"] = {
  hash = "e4b6b4",
  fullHash = "e4b6b4",
  text = "Garments of Darkness. Garments of Darkness is a foundational rite of passage for fledgling Forsaken priests in Brill. Dark Cleric Beryl tasks initiates with healing and fortifying an injured Deathguard, testing their grasp of supportive magics before they delve deeper into the shadows. While the Forsaken priesthood draws renown and distinct identity from shadow and darkness, its elders recognize the enduring pragmatic necessity of restoration. Dark Cleric Beryl teaches that understanding the dark demands an understanding of the light and restorative arts. A priest who seeks only ruin is cautioned to study arcane magic instead; the priesthood's true calling involves strengthening and preserving comrades just as much as afflicting enemies. To demonstrate mastery, the initiate is sent north of Brill's cemetery to aid Deathguard Kel. Stationed against prowling gnoll packs, Kel has sustained injuries holding the line. By binding his wounds with healing spells and bolstering his stamina with protective enchantments, the acolyte proves capable of maintaining the defenders of Tirisfal Glades, earning Beryl's vestment and acceptance into the priesthood's higher mysteries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5650-2080ea0f20060d0963ca/1-0000.mp3", duration = 64.9404082, start = 0},
  },
}
P.transport["quest:5651"] = {
  hash = "1bb443",
  fullHash = "1bb443",
  text = "In Favor of Darkness. In Favor of Darkness marks a Forsaken priest's transition beyond the starting crypts of Deathknell toward advanced instruction in Brill. Entrusted by Dark Cleric Duesten, the fledgling disciple travels to study under Dark Cleric Beryl to master the delicate balance between the Holy Light and the Shadow. While priests of other races revere the Holy Light as an unblemished source of moral virtue, the Forsaken approach faith through the harsh lens of their own undeath. As Dark Cleric Duesten teaches, the Forsaken were forged in corruption and discarded like carrion. Their survival demands understanding both Light and Shadow without sentimentality. In Favor of Darkness directs new disciples out of Deathknell's cloistered graveyard to confront the wider reality awaiting them in Tirisfal Glades. The road leading northeast out of Deathknell brings the fledgling priest over a wooden covered bridge and into the ruined hamlet of Brill. There, in the upper quarters of the local inn, Dark Cleric Beryl waits to test the initiate's resolve. Beryl values ambition and cold practicality over blind devotion, demanding that a Forsaken priest wield divine power as a weapon and a tool rather than a moral crutch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5651-220be69799f2399e7ad8/1-0000.mp3", duration = 68.4408163, start = 0},
  },
}
P.transport["quest:5654"] = {
  hash = "59eba0",
  fullHash = "59eba0",
  text = "Hex of Weakness. In Durotar, Hex of Weakness carries a young Darkspear priest from Razor Hill to Orgrimmar. Tai'jin sends an initiate north to Ur'kyo, who welcomes new students into the tribe's spiritual circle and teaches the loa's darker arts. Young Darkspear priests continue their lessons in Razor Hill's barracks under Tai'jin's watch. Once an acolyte shows command of spiritual communion and shadow magic, the first lessons end. Tai'jin sends the promising priest north, across Durotar's red dirt canyons, toward the Horde capital. There, elder practitioners guide the tribe's wider magical traditions. The Darkspear keep a distinct cultural sanctuary in Orgrimmar's Valley of Spirits, apart from the orcs' clanging forges and warrior grounds. Ur'kyo, an elder priest, waits there for new initiates. Joining his circle means embracing the ancestral traditions of the jungle trolls: honoring the loa while learning potent curses and hexes that sap an enemy's strength in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5654-33c8fd95e6ee09d89d36/1-0000.mp3", duration = 57.9918367, start = 0},
  },
}
P.transport["quest:5713"] = {
  hash = "eaab01",
  fullHash = "eaab01",
  text = "One Shot. One Kill.. On the road to Auberdine, Sentinel Aynasha needs help to survive an ambush and deliver her message. Marosh the Devious and his furbolg trackers have poisoned her, leaving her unable to travel while she mixes an antidote. Sentinel Aynasha was carrying important communications toward Auberdine when hostile furbolgs intercepted her on a northern Kalimdor trail. Marosh the Devious led the pack. Their venom left the scout unsteady and unable to continue on foot. Aynasha knows how to make natural remedies, but mixing and taking an antidote takes time. Marosh's trackers are closing in, so she needs travelers to guard her while she works. Though her strength is failing, she keeps her bow steady and fires into the brush to hold the attackers back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5713-c7fb5520d16ee58db466/1-0000.mp3", duration = 42.8930612, start = 0},
  },
}
P.transport["quest:5722"] = {
  hash = "b4b429",
  fullHash = "b4b429",
  text = "Searching for the Lost Satchel. Rahauro sends you from Thunder Bluff’s Elder Rise into Ragefire Chasm. Magatha Grimtotem seeks her lost emissary Maur and the unusual discovery he made among the troggs. Magatha Grimtotem hears on Thunder Bluff’s Elder Rise that her emissary, Maur Grimtotem, entered the cavern beneath Orgrimmar to study the troggs and try to parley with them. He never returned, and rumors say he found something unusual shortly before his death. While Warchief Thrall and his advisers focus on the Shadow Council presence in Ragefire Chasm, the Grimtotem clan follows its own interests.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5722-e39b6523ca1c8cc97189/1-0000.mp3", duration = 34.0114286, start = 0},
  },
}
P.transport["quest:5723"] = {
  hash = "8f9455",
  fullHash = "8f9455",
  text = "Testing an Enemy's Strength. Magatha Grimtotem seeks retribution after troggs slaughter her emissaries beneath Orgrimmar. Rahauro on Thunder Bluff’s Elder Rise sends warriors into Ragefire Chasm to cull the troggs infesting it. Magatha Grimtotem sent tauren emissaries into the fiery depths beneath Orgrimmar to make peace with the troggs. The creatures slaughtered the delegates as soon as they arrived. Magatha saw the massacre as an insult to the tauren and a growing danger to the Horde. She resolved to answer it with force. Rahauro carries out Magatha’s orders from Thunder Bluff. He directs warriors into Ragefire Chasm to find and kill trogg warriors and shamans. The Horde strikes deep into their underground home to thin their numbers before they can pour through their tunnels into Orgrimmar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5723-565ecf5967d82479be2b/1-0000.mp3", duration = 45.2179592, start = 0},
  },
}
P.transport["quest:5724"] = {
  hash = "e9ede3",
  fullHash = "e9ede3",
  text = "Returning the Lost Satchel. In Ragefire Chasm beneath Orgrimmar, the search for Maur Grimtotem ends with his satchel. You must carry it back to Rahauro on Elder Rise in Thunder Bluff. Maur Grimtotem was slain by troggs in the fiery depths of Ragefire Chasm beneath Orgrimmar. Even in death, his arms clung to his personal satchel. Freeing it from his grip is the only clue to why a member of the Grimtotem clan entered the volcanic caverns beneath Thrall's capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5724-d40e67027b6750aa5048/1-0000.mp3", duration = 25.3910204, start = 0},
  },
}
P.transport["quest:5725"] = {
  hash = "990ac3",
  fullHash = "990ac3",
  text = "The Power to Destroy.... In the Undercity, Varimathras sends Horde adventurers into Ragefire Chasm beneath Orgrimmar. Lady Sylvanas Windrunner wants two dark tomes held by the Searing Blade cult, hoping their power will aid her war against the Scourge and the Lich King. Thrall's orcs are hunting the Searing Blade cult beneath their capital, while the Forsaken covet the cult's occult stores. On Sylvanas Windrunner's orders, Varimathras sends operatives into Ragefire Chasm to seize two demonic grimoires: Spells of Shadow and Incantations from the Nether. The Dark Lady believes disciplined Forsaken will can put these demonic gifts to better use than the lesser cultists. Varimathras explains the tomes' purpose once they are secured. Their dark magic is meant to strengthen Sylvanas's campaign against the Scourge. By claiming every scrap of forbidden power, the Forsaken hope to break the Lich King's hold across Lordaeron and free the remaining undead from his mental enslavement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5725-7d56b403dfcda955b6c1/1-0000.mp3", duration = 56.555102, start = 0},
  },
}
P.transport["quest:5726"] = {
  hash = "ace512",
  fullHash = "ace512",
  text = "Hidden Enemies. Hidden Enemies is the opening chapter of Warchief Thrall's investigation into cultist infiltration within Durotar. Aware that demonic sympathizers are operating right under the Horde's nose, Thrall tasks a promising young adventurer with recovering a Lieutenant's Insignia from Skull Rock to initiate a covert operation. While the nascent Horde struggles to carve out a secure home in Durotar, Warchief Thrall faces an insidious threat far deadlier than centaur raids or quilboar incursions: internal betrayal. The demonic cult known as the Burning Blade has rooted itself right outside the gates of Orgrimmar, preying on lingering demonic corruption and thirst for dark power. Thrall recognizes that sending his official Kor'kron guards or known commanders would merely scatter the cultists into deeper hiding. He needs someone untainted by high-profile associations to serve as his discreet eyes and ears. East of Orgrimmar lies Skull Rock, a rugged cavern infested with warlocks, voidwalkers, and fanatical cultists. Thrall sends the adventurer straight into this nest with a specific mission: claim a Lieutenant's Insignia from one of the Burning Blade leaders. This emblem is far more than a battlefield trophy; it is a vital credential meant to grant the bearer access to the cult's shadowy hierarchy, enabling a deeper sting operation designed to reveal who directs the cult's movements from behind the scenes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5726-6058cc3e3b95e185b94e/1-0000.mp3", duration = 81.2669388, start = 0},
  },
}
P.transport["quest:5727"] = {
  hash = "22d645",
  fullHash = "22d645",
  text = "Hidden Enemies. Thrall sends you into Orgrimmar to learn what the Burning Blade knows. After cult activity is found at Skull Rock, you carry a lieutenant's insignia to Neeru Fireblade and test his loyalties. Thrall turns to cunning instead of striking at the Cleft of Shadow. He knows Neeru Fireblade pretends to serve the Horde while aiding the cultists in secret. If Thrall strikes now, Neeru's masters will be warned and the trail into the conspiracy may end. So Thrall gives you an insignia taken from the cult in Durotar and asks you to pose as an initiate, to learn what Neeru knows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5727-0af149add34b4d8004e4/1-0000.mp3", duration = 33.3061224, start = 0},
  },
}
P.transport["quest:5728"] = {
  hash = "b97ca4",
  fullHash = "b97ca4",
  text = "Hidden Enemies. Thrall sends you against the Searing Blade beneath Orgrimmar. After tricking Neeru Fireblade into believing you are an ally, he sends you into Ragefire Chasm to assassinate the cult's top commanders. Orgrimmar was built as a haven for a free Orcish race, but its foundations conceal an old demonic threat. Beneath the markets, the Cleft of Shadow opens onto the tunnels of Ragefire Chasm. In those volcanic depths, remnants of the Shadow Council called the Searing Blade gather strength. They practice dark arts and scheme to seize the young Horde from within its own capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5728-2c96feb3f26ba5034990/1-0000.mp3", duration = 32.9665306, start = 0},
  },
}
P.transport["quest:5729"] = {
  hash = "c69dc0",
  fullHash = "c69dc0",
  text = "Hidden Enemies. Thrall's watch on Hidden Enemies reaches into the Cleft of Shadow. After Bazzalan and Jergosh the Invoker are killed beneath the city, Thrall sends you to win Neeru Fireblade's trust. Thrall sees a chance after Bazzalan and Jergosh the Invoker are killed in Ragefire Chasm. He chooses not to expose Neeru Fireblade. Neeru has lost his underground lieutenants, leaving the local cult without its leaders. Thrall sends you back to the Cleft of Shadow to offer yourself as an ally who can fill that gap.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5729-d9882943471f1e3f99d4/1-0000.mp3", duration = 27.9510204, start = 0},
  },
}
P.transport["quest:5730"] = {
  hash = "dd29c5",
  fullHash = "dd29c5",
  text = "Hidden Enemies. Neeru Fireblade has earned your trust, and Thrall awaits your report in Orgrimmar. The Warchief needs to know how far the Burning Blade's reach extends across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5730-1ac2facffa2009f75dad/1-0000.mp3", duration = 10.1877551, start = 0},
  },
}
P.transport["quest:5761"] = {
  hash = "7d6485",
  fullHash = "7d6485",
  text = "Slaying the Beast. In Orgrimmar’s Cleft of Shadow, Neeru Fireblade sends Horde adventurers into Ragefire Chasm to hunt Taragaman the Hungerer. He claims Warchief Thrall ordered the hunt and demands the towering felguard’s heart as proof the demonic cult has fallen. Ragefire Chasm lies beneath Orgrimmar’s red earthen streets, a fiery fissure filled with troggs, beasts, and covert Searing Blade agents. In the Cleft of Shadow above, Neeru Fireblade presents himself as a loyal servant carrying out Thrall’s order to cleanse this demonic rot. He points to Taragaman the Hungerer, a massive felguard in the cavern’s heart, and names him as the mastermind behind the cult below the city.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5761-07092a5768dfde96360f/1-0000.mp3", duration = 39.0530612, start = 0},
  },
}
P.transport["quest:579"] = {
  hash = "ae6d93",
  fullHash = "ae6d93",
  text = "Stormwind Library. In Stormwind Keep, Donyal Tovald copies the kingdom’s histories for those with library scrips. Young King Anduin Wrynn has set aside royal funds for the work, opening these accounts of Azeroth to citizens and scholars. While Highlord Bolvar Fordragon and Lady Katrana Prestor guide Stormwind’s defenses and court in King Varian’s absence, young King Anduin turns royal support toward learning. He funds copies of ancient manuscripts and historical journals, so the kingdom’s past can be preserved and studied. Within Stormwind Keep, the Royal Library keeps these written accounts and copies them for those in royal service. Hand copying delicate parchment takes time, ink, and royal sanction. Librarian Donyal Tovald accepts official library scrips issued to adventurers and scholars across Alliance territories. In return, he provides copies of historical works, from the ancient histories of the Eastern Kingdoms to accounts of distant lands, offering knowledge of conflicts beyond the capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_579-16d5cc56ac71d25b37e6/1-0000.mp3", duration = 57.4955102, start = 0},
  },
}
P.transport["quest:59"] = {
  hash = "94369d",
  fullHash = "94369d",
  text = "Cloth and Leather Armor. In Goldshire, Cloth and Leather Armor sends a trusted traveler east for gear. Marshal Dughan issues an armor marker redeemable with Sara Timberlain at Eastvale Logging Camp. The trip carries recruits beyond Guard Thomas's bridge to obtain armor for the realm's defense. Guard Thomas watches Elwynn's eastern river crossing, where murlocs and gnolls threaten the border. After you carry his report to Goldshire, Marshal Dughan recognizes your service with an official Stormwind Armor Marker. Goldshire's garrison has meager stores, so Dughan gives you a marker instead of drawing equipment from them. The marker is a military voucher that records your service to the crown. East of Guard Thomas's bridge lies Eastvale Logging Camp, Elwynn's main timber operation. Sara Timberlain works there under an official commission from the Stormwind Army to make cloth and leather gear. The kingdom's central armories are strained, leaving local artisans like Sara to outfit troops and auxiliary scouts on the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_59-3e9eb08bcb3ab3bc5b3f/1-0000.mp3", duration = 58.4359184, start = 0},
  },
}
P.transport["quest:5921"] = {
  hash = "94a13d",
  fullHash = "94a13d",
  text = "Moonglade. In Darnassus, young night elf druids learn to reach Moonglade. Mathrengyl Bearwalker teaches novices a spell to carry themselves across the world into Moonglade, where they meet Dendrite Starblaze in Nighthaven. There begins their path toward mastering bear form. Moonglade is an ancient sanctuary apart from the rest of Azeroth, devoted to the teachings of Cenarius. Keeper Remulos watches over its groves, where druids find peace and communion with nature. Young druids learn a spell that lets them carry themselves across the world into Moonglade, reaching a heart of druidic wisdom beyond mortal distances. Moonglade welcomes all who follow the wild, though the Cenarion Circle knows its share of tension. In Darnassus, Arch Druid Fandral Staghelm and Keeper Remulos disagree over nature’s care and the creation of Teldrassil. Their differences do not close Nighthaven to young acolytes, who are welcomed to pursue their studies. In Nighthaven, Dendrite Starblaze guides young druids in the ways of the Claw. Before an initiate can take up the bear’s mantle, the trials teach the bear’s endurance, fury, and defense of the wild. Starblaze welcomes each student in reverence to Father Cenarius as the trials of the Great Bear Spirit begin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5921-c455e23b676d3baeabff/1-0000.mp3", duration = 75.4416327, start = 0},
  },
}
P.transport["quest:5922"] = {
  hash = "79e3d7",
  fullHash = "79e3d7",
  text = "Moonglade. This quest marks a young tauren druid's introduction to Moonglade, the sacred sanctuary of Cenarion druidism. Guided by Turak Runetotem in Thunder Bluff, the initiate learns to traverse the waking world to commune directly with nature's ancient keepers. Moonglade stands apart from the turbulent politics of Kalimdor. Sheltered beneath primeval boughs and watched over by Keeper Remulos, the son of Cenarius, this ancient valley is a neutral refuge for all who walk the path of nature. Whether night elf or tauren, any druid who enters Nighthaven does so as an equal peer under the timeless mantle of the Cenarion Circle. To aid your spiritual and martial development, Turak Runetotem teaches you a unique transport spell tied to the valley itself. By invoking the mystic bond between druids and the natural world, you step across hundreds of leagues in a heartbeat. This sanctuary will serve as both a study hall and an enduring refuge throughout your journey.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5922-939516d8188f6585a920/1-0000.mp3", duration = 56.4244898, start = 0},
  },
}
P.transport["quest:5923"] = {
  hash = "2d07e6",
  fullHash = "2d07e6",
  text = "Heeding the Call. Heeding the Call marks the moment an apprentice night elf druid catches the attention of the Cenarion Circle's senior leadership. Summoned to Darnassus to meet Mathrengyl Bearwalker, the young initiate begins the sacred path toward mastering their first animal aspect, the bear. Novice druids honing their craft across Teldrassil—or studying abroad in far-off realms like Stormwind—eventually receive a personal summons. Instructors such as Kal in Dolanaar, Denatharion in Darnassus, or Theridran across the Great Sea carry word that Mathrengyl Bearwalker wishes to oversee their training personally. As the direct assistant to Arch Druid Fandral Staghelm, Mathrengyl is one of the most respected and knowledgeable mentors among the night elves, and his attention is an unmistakable sign that an apprentice is ready for genuine trials. Reaching Mathrengyl on the upper level of Fandral Staghelm's towering residence in the Cenarion Enclave opens the door to deeper mysteries. To serve nature properly, a druid must learn to embody its living creatures rather than merely observing them. Mathrengyl welcomes candidates with the news that their first great undertaking will be embracing the strength, endurance, and spirit of the bear—a journey that will take them far beyond Teldrassil to sacred ancestral grounds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5923-69745ee20535c32e95ca/1-0000.mp3", duration = 73.4040816, start = 0},
  },
}
P.transport["quest:5926"] = {
  hash = "33d361",
  fullHash = "33d361",
  text = "Heeding the Call. Heeding the Call marks a novice druid's summoning to Elder Rise in Thunder Bluff for advanced personal instruction. Relayed by innkeepers and kin across Horde settlements, the summons directs aspiring shapeshifters to Turak Runetotem. This meeting sets off the sacred trials required to master the form and spirit of the bear. Word travels quickly across the plains of Mulgore and through the dusty thoroughfares of Orgrimmar. Whether heard from Innkeeper Gryshka among the orcs, Innkeeper Pala in Thunder Bluff, or Gennia Runetotem in Bloodhoof Village, the message is the same: Turak Runetotem has noticed your early progress. The Cenarion Circle does not summon practitioners lightly, and this invitation signals that your days of elementary herb-gathering and basic spellweaving have earned you deeper communion with nature's wild spirits. Turak Runetotem serves as an assistant to Archdruid Hamuul Runetotem, guiding young tauren toward their ancestral duty inside the large Cenarion tent on Elder Rise. Welcoming initiates into a broader understanding of Cenarius's legacy, Turak instructs them that animals and plants are both allies and solemn charges. Meeting him is the opening threshold of the rite: stepping beyond basic mentorship to confront the trials of body and heart required to commune directly with the Great Bear Spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5926-9ba81cdd18b3b0df2508/1-0000.mp3", duration = 77.7404082, start = 0},
  },
}
P.transport["quest:5931"] = {
  hash = "af7eff",
  fullHash = "af7eff",
  text = "Back to Darnassus. After meeting the Great Bear Spirit, a young night elf druid returns to Darnassus. The initiate has left Moonglade and now reports to Mathrengyl Bearwalker in the Cenarion Enclave for practical shapeshifting trials. Dendrite Starblaze sends the initiate from Nighthaven back to Darnassus after the meeting with the Great Bear Spirit in Moonglade. The journey joins two sanctuaries: Moonglade, where the young druid has communed with the spirit, and the unsettled world beyond. In Darnassus, local mentors watch over Teldrassil and guide the next stage of training. Mathrengyl Bearwalker waits in the Cenarion Enclave, where he guards nature even as its balance falters. The Great Bear Spirit's blessing is only the first step. Mathrengyl prepares the initiate for trials of body and heart, to give physical form to the spirit's fierce ancestral wisdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5931-910276f33221acc7976c/1-0000.mp3", duration = 49.2930612, start = 0},
  },
}
P.transport["quest:5932"] = {
  hash = "b3c5b3",
  fullHash = "b3c5b3",
  text = "Back to Thunder Bluff. \"Back to Thunder Bluff\" is an essential rite of passage for young tauren druids returning from the sacred glades of Moonglade. Having communed with the Great Bear Spirit, the initiate is sent by Dendrite Starblaze back to Elder Rise to continue training under Turak Runetotem. Moonglade stands apart from the factional divides of the mortal world, serving as a sanctuary where night elf and tauren practitioners of nature magic gather as the Cenarion Circle. After communion with the Great Bear Spirit, night elf mentor Dendrite Starblaze sends the young tauren back to their people. While night elves often view tauren as fledglings in the formalized teachings of Cenarius, Starblaze readily acknowledges the profound wisdom and balance maintained by Turak Runetotem. Upon climbing back to the sweeping heights of Elder Rise in Thunder Bluff, the novice stands before Turak Runetotem transformed. Communing with ancient totemic spirits like the Great Bear Spirit is deeply ingrained in tauren culture, yet undertaking the Path of the Claw marks a serious commitment. With the spiritual connection forged, Turak prepares the druid to put that newfound strength and endurance into active practice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_5932-c18612e824debf85de5e/1-0000.mp3", duration = 68.6236735, start = 0},
  },
}
P.transport["quest:6"] = {
  hash = "f81075",
  fullHash = "f81075",
  text = "Bounty on Garrick Padfoot. In Northshire, an Alliance bounty names Garrick Padfoot, a notorious local thief. Deputy Willem at Northshire Abbey calls for recruits to hunt him near the vineyards. Northshire Valley once offered a safe place to train recruits and tend its sacred vineyards. As order falters across Elwynn, thieves have reached the valley. Garrick Padfoot, a cutthroat, quickly rose to lead them. For weeks, he and his gang have plundered shipments, robbed merchants on the roads, and threatened local farmers. Stormwind's guards are stretched thin, protecting the capital and its outer borders. Local marshals and deputies rely on volunteers to keep Northshire peaceful. Deputy Willem places a public bounty on Garrick's head, hoping to rid the valley of his gang. Bringing Padfoot down at his rundown shack east of the river strikes at the lawlessness spreading through the human heartland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6-07cb2ee5de4582866b43/1-0000.mp3", duration = 51.6179592, start = 0},
  },
}
P.transport["quest:60"] = {
  hash = "62c383",
  fullHash = "62c383",
  text = "Kobold Candles. At the Lion's Pride Inn in Goldshire, William Pestle seeks candles from kobolds that have overstocked Elwynn Forest's mines. Visiting from his shop in Stormwind, the alchemist needs their thick wax, and the errand introduces adventurers to the subterranean pests encroaching on the kingdom's valuable gold veins. William Pestle runs Pestle's Apothecary with his brother in Stormwind City's Trade District. Wax is always in short supply as he brews remedies, ointments, and concoctions. Instead of buying polished candles from city merchants, Pestle turns to the vermin in Elwynn. The kobolds carry hefty lumps of tallow and wax on their brows, ready for an adventurer willing to pry them loose. Kobolds have overrun Fargodeep Mine south of Goldshire and Jasperlode Mine to the northeast. These snuffling creatures prize their candles above almost all else. The flickering flames guide them through dark shafts as they dig for gold and shiny trinkets. Taking the candles replenishes Pestle's alchemy stocks and chips away at the vermin choking off the kingdom's precious mining claims.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_60-8186ff093c92f7452adf/1-0000.mp3", duration = 62.5893878, start = 0},
  },
}
P.transport["quest:6001"] = {
  hash = "16d96a",
  fullHash = "16d96a",
  text = "Body and Heart. In Darnassus, a young night elf druid nears the end of initiation into the path of the claw. Mathrengyl Bearwalker sends the initiate into Darkshore to summon Lunaclaw and prove strength of body and heart before taking the form of the bear. Mathrengyl Bearwalker sends night elf druid initiates east of Auberdine, the coastal settlement in Darkshore. A natural cavern there shelters wild moonkin and an ancient Moonkin Stone. Anointing the sacred stone with Cenarion Moondust awakens Lunaclaw, its ancient defender. The guardian challenges any initiate who seeks the sacred strength of the claw.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6001-7f5e56bc6fa5a3b46873/1-0000.mp3", duration = 36.2579592, start = 0},
  },
}
P.transport["quest:6002"] = {
  hash = "665c53",
  fullHash = "665c53",
  text = "Body and Heart. Body and Heart is the culminating trial for young tauren druids seeking to master Bear Form. Dispatched by Turak Runetotem in Thunder Bluff, the initiate must travel to the border of Mulgore and the Barrens to summon and best Lunaclaw at the Moonkin Stone. To truly follow the path of the Druid of the Claw, tauren initiates must unite spiritual conviction with physical resilience. After communion with the Great Bear Spirit in Moonglade, a druid's training is put to an active test. Turak Runetotem, the elder druid trainer atop the Elder Rise in Thunder Bluff, bestows Cenarion Lunardust upon worthy aspirants, charging them to seek out a sacred stone resting near the arid frontier where Mulgore meets the Barrens. Resting west of Camp Taurajo, the Moonkin Stone marks a rare Cenarion site in southern Kalimdor. Moonkin are not native to the sun-scorched plains of central Kalimdor, making the presence of the guardian beast Lunaclaw deeply significant. By scattering the lunardust across the ancient monument, the druid calls forth Lunaclaw in battle. Defeating the creature proves the aspirant commands both strength of body and clarity of heart, earning the beast's blessing and unlocking the inner essence of the bear.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6002-6d69cdc974f190dec875/1-0000.mp3", duration = 72.96, start = 0},
  },
}
P.transport["quest:6061"] = {
  hash = "838a28",
  fullHash = "838a28",
  text = "Taming the Beast. Taming the Beast is the foundational rite of passage for young tauren hunters in Bloodhoof Village. Guided by trainer Yaw Sharpmane, the hunter ventures into Mulgore to tame an adult plainstrider, taking the first step toward forging a spiritual bond with the creatures of the Earthmother. For the tauren, hunting has never been purely about slaying beasts for meat and hides. Ancestral traditions hold that overcoming and communion with the wildlife of Mulgore allows a hunter to intake their spirits and draw closer to the Earthmother. Taming a companion beast elevates this connection, turning what could be an adversary into a lifelong partner aligned with the natural balance of the plains. Yaw Sharpmane begins an initiate's instruction not with ferocious apex predators, but with the swift and watchful plainstriders roaming Mulgore's grasslands. Armed with an enchanted taming rod, the hunter must face an adult plainstrider, calm its wild instincts, and earn its trust. This initial trial proves the hunter's resolve and prepares them for the more demanding beasts that follow.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6061-ba5d76dfadf3e94deef6/1-0000.mp3", duration = 62.6416327, start = 0},
  },
}
P.transport["quest:6062"] = {
  hash = "b57bfe",
  fullHash = "b57bfe",
  text = "Taming the Beast. In Razor Hill, Taming the Beast begins a young Horde hunter’s training with a taming rod. Thotar guides aspiring hunters as they face a vicious dire mottled boar. Orc and Darkspear troll hunters in Durotar must learn to command the wild as well as survive it. Thotar, the veteran hunter trainer, gives young hunters an enchanted taming rod and sends them to face a fierce wild boar. They must subdue the beast without killing it, then make it a loyal ally. Dire mottled boars roam the dry brush around Razor Hill. Their strength and temper make them a fitting first test for young hunters. The rod can subdue a charging boar, but using it takes patience and resolve, qualities every Horde tracker needs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6062-f8e5b144d901a7121e72/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["quest:6063"] = {
  hash = "b4e87f",
  fullHash = "b4e87f",
  text = "Taming the Beast. In Dolanaar, Taming the Beast begins a night elf hunter’s trials with a wild Webwood Lurker. Dazalar lends an enchanted taming rod, and the hunter must win the spider’s trust through a bond with nature. For the kaldorei, hunting means more than tracking prey or surviving in the wild. It binds a hunter to nature, which is greater than any mortal. Animals are independent creatures, not tools to bend to a hunter’s will. Dazalar teaches novice hunters to meet them with respect. Before gaining a lifelong beast companion, a hunter must master local wildlife through ancient techniques, never brute force. Giant arachnids infest Teldrassil’s boughs, and Dazalar gives the hunter a taming rod. The hunter seeks a Webwood Lurker in the shadowed thickets, facing the venomous spider and its attacks while trying to reach it through empathy. A brief mental bond proves the hunter can commune with the World Tree’s eerie, skittering predators.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6063-776db62d6e6f3acbbb61/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["quest:6064"] = {
  hash = "fe3d40",
  fullHash = "fe3d40",
  text = "Taming the Beast. Taming the Beast is the first trial in a dwarven hunter's journey to mastering companion beasts in Dun Morogh. Guided by Grif Wildheart in Kharanos, young trackers learn to quell and bond with a ferocious Large Crag Boar using an enchanted taming rod. Up to this point, dwarven mountaineers and trackers rely solely on their gunplay, traps, and wilderness instincts. Yet the true soul of a hunter lies in forging a lifelong partnership with a wild beast. Grif Wildheart, stationed outside the Thunderbrew Distillery in Kharanos, oversees this rite of passage. Rather than expecting a novice to permanently bind the first beast they come across, Grif instructs them to test their patience and resolve against several native species of Dun Morogh. The first trial pits the tracker against a Large Crag Boar, one of the rugged, thick-hided swine that roam the snowy foothills of Dun Morogh. Armored in bristling fur and tough flesh, these beasts are stubborn and aggressive, making them an ideal starting test of will. By wielding the enchanted Taming Rod provided by Grif, the hunter must withstand the boar's charge and soothe its ferocity until it submits to their command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6064-1e2e8e6e58951cc90a11/1-0000.mp3", duration = 70.3738776, start = 0},
  },
}
P.transport["quest:6065"] = {
  hash = "5f4cfa",
  fullHash = "5f4cfa",
  text = "The Hunter's Path. The Hunter's Path is a vital milestone for young tauren hunters in Mulgore, directing them toward advanced training in beast companionship. Dispatched by their local mentors once their basic marksmanship and tracking are proven, novices are sent to Bloodhoof Village to seek the counsel of hunter trainer Yaw Sharpmane. This journey initiates the spiritual and practical trials required to tame and bond with wild beasts. To the nomadic Shu'halo, hunting is sacred rather than mere sport. A hunter must understand the balance of nature, honor the spirits of the plains, and show respect for the animals that sustain the tribes. When a young hunter demonstrates sufficient prowess in surviving the wild and wielding a bow or gun, their elders recognize that they are ready to step beyond solitary tracking. The directive to seek out seasoned mentors marks the threshold of true adulthood in tauren culture. The path leads novitiates across the sweeping grasslands of Mulgore to Bloodhoof Village, a central gathering settlement nestled beside Stonebull Lake. There awaits Yaw Sharpmane, an experienced huntsman well-versed in the temperament of the local fauna. Speaking with Sharpmane is not a mere formality; it signals a hunter's readiness to undertake the demanding trials of beast taming, learning how to commune with predators rather than merely hunt them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6065-e72d5064aec13a6d6890/1-0000.mp3", duration = 73.9004082, start = 0},
  },
}
P.transport["quest:6068"] = {
  hash = "61769c",
  fullHash = "61769c",
  text = "The Hunter's Path. In Durotar, The Hunter's Path sends young orc and troll hunters to Razor Hill. There, Thotar teaches them to bind wild predators. In Durotar, young hunters learn to track prey with bow and cunning. Following trails through red clay canyons and harsh scrubland teaches patience. To master the hunter's way in the Horde, they must also learn to bond with the land's wild beasts. When class trainers judge a student ready, they direct them to Razor Hill. Thotar waits at Razor Hill, where he teaches young hunters how to subdue Durotar's fierce beasts without breaking their spirit. Learning from him begins the path to traveling the wilderness with a loyal companion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6068-124ef94913d042d4bae4/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["quest:6074"] = {
  hash = "5f71d7",
  fullHash = "5f71d7",
  text = "The Hunter's Path. The Hunter's Path is a rite of passage offered to novice dwarven hunters across Dun Morogh once they reach basic competence in tracking and marksmanship. Local trainers direct their apprentices to Grif Wildheart in Kharanos to begin learning the art of taming wild beasts as permanent companions. Until a hunter masters the art of beast bonding, they walk the snowy crags of Dun Morogh alone, relying solely on axe, rifle, or bow. Trainers like Olmin Burningbeard and Tristane Shadowstone watch their pupils closely until they demonstrate the poise required to face a savage creature without killing it. Once a novice shows sufficient discipline, they are sent down the mountain roads toward Kharanos. In Kharanos, Grif Wildheart oversees the final trials of dwarven huntsmanship. Taming a beast is considered far more demanding than bringing one down for meat or pelt; it requires patience, physical endurance, and an intuitive bond with the wild predators of the mountains. Wildheart acts as the gateway to these trials, preparing the hunter for the grueling task of testing their willpower against Dun Morogh's fiercest wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6074-08bba5e4440e33a98259/1-0000.mp3", duration = 67.4220408, start = 0},
  },
}
P.transport["quest:6081"] = {
  hash = "025a00",
  fullHash = "025a00",
  text = "Training the Beast. In Durotar, young orc and troll hunters are sent to learn from veteran master hunter Ormak Grimshot. After proving themselves with the plains beasts, they travel from Razor Hill to Orgrimmar. There they learn to care for, feed, and train a lifelong animal companion. In Durotar's arid canyon lands, skill with a bow and survival in the harsh wilds are only part of a hunter's duty. Young hunters first tame the plains beasts: fierce boars, crab scavengers, and armored scorpid stalkers. Once they prove their resilience, Thotar sends them from Razor Hill north through the red clay gulches to Orgrimmar's fortified gates, ready to take responsibility for a companion. Orgrimmar's Valley of Honor is an enclave where veteran stalkers and warriors hone their craft. There, aspiring hunters seek Ormak Grimshot, one of the Horde's revered master hunters. He looks beyond their youth to judge whether they have the patience to command a beast and sustain and nurture it through famine, battle, and loss. A beast won through force remains wild until hunter and companion come to understand one another. Ormak teaches the sacred traditions that keep their bond: which foods nourish each creature's spirit, how discipline teaches a beast lethal techniques, and the spiritual focus needed to revive one that falls in the line of duty.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6081-c2233dead98d3bb8fe29/1-0000.mp3", duration = 76.7216327, start = 0},
  },
}
P.transport["quest:6082"] = {
  hash = "28f56e",
  fullHash = "28f56e",
  text = "Taming the Beast. In Durotar, Taming the Beast tests a young Horde hunter's skill with wild creatures. Thotar in Razor Hill guides the hunter through one last trial: taming a dangerous armored scorpid. Success brings the ability to tame, call, and dismiss a lasting companion. Before a hunter can travel Kalimdor with an animal companion, they must prove they can command Durotar's harsh wildlife. Thotar, the hunter trainer in Razor Hill, sends trainees to subdue three kinds of creature with an enchanted taming rod. After facing dire boars and swift surf crawlers, they must now tame an armored scorpid, a venomous predator protected by heavy plates and known for resilience and speed. Taming an armored scorpid tests a hunter's focus and control under attack, not their skill at killing. Thotar urges hunters to match the beast's quick, confident strikes. Once the hunter has charmed the scorpid, they return to Razor Hill and give the taming rod back to Thotar. That return completes the trial, and Thotar then teaches the wild's innate techniques, letting the hunter seek out and bind a permanent companion of their choosing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6082-df6c09434c57b879131c/1-0000.mp3", duration = 63.8693878, start = 0},
  },
}
P.transport["quest:6083"] = {
  hash = "fbe84f",
  fullHash = "fbe84f",
  text = "Taming the Beast. In Durotar, Taming the Beast sends young hunters to the coast for their second trial. Thotar, the hunter trainer in Razor Hill, directs aspiring orc and troll hunters to pacify a surf crawler near the Echo Isles and extend their bond to coastal wildlife. After mastering a dire mottled boar, you turn your attention to the sea at Thotar's direction. Durotar's harsh shores are jagged, and shallow reefs teem with armored crustaceans. A surf crawler resists intrusion into its coastal domain, so taming one calls for patience and fortitude. Thotar teaches that a bound beast must become an extension of a hunter's strength. Subduing a surf crawler with the taming rod teaches you to command creatures of different temperaments in different surroundings. It proves you are ready for permanent companions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6083-81ab34d32e49f97444e4/1-0000.mp3", duration = 46.1844898, start = 0},
  },
}
P.transport["quest:6084"] = {
  hash = "f1b859",
  fullHash = "f1b859",
  text = "Taming the Beast. This quest is the second trial in the dwarf hunter initiation given by Grif Wildheart in Kharanos. After learning to handle the brute resilience of a crag boar, the young hunter is tasked with mastering the swiftness and lethal grace of a native snow leopard. While crag boars teach a mountaineer how to withstand raw ferocity and absorb blows, Grif Wildheart emphasizes that a master hunter must understand different styles of combat. He points his students southeast toward the prowling snow leopards of Dun Morogh. Grif compares these graceful predators to an elegantly crafted rifle: outwardly striking, yet concealing devastating power beneath their pristine white coats. Using an enchanted taming rod, the hunter must confront a wild leopard and bend its hunting instincts into partnership. Snow leopards test agility, speed, and sharp reflexes rather than pure endurance. Mastering such a creature demonstrates that the novice can harmonize with predators that strike swiftly from the snowy crags, taking another step toward true command over the beasts of the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6084-c638f29bea3afea89a94/1-0000.mp3", duration = 63.8693878, start = 0},
  },
}
P.transport["quest:6085"] = {
  hash = "5da628",
  fullHash = "5da628",
  text = "Taming the Beast. This quest marks the final trial in a dwarven hunter's basic training under Grif Wildheart in Kharanos. By using an enchanted rod to subdue and understand an aggressive Ice Claw Bear, the hunter demonstrates mastery over sheer brute strength. Completing this exercise unlocks the foundational abilities needed to tame, call, and dismiss a permanent wild companion. Throughout Dun Morogh, mountaineers and scouts have long relied on hardy beasts to endure the freezing crags. After directing his students to practice on swift and cunning predators, master huntsman Grif Wildheart tasks budding hunters with capturing an Ice Claw Bear. Found prowling the snowdrifts east of Kharanos, these massive beasts embody raw physical power and relentless endurance—qualities every dwarven huntsman must learn to control. The trials with the Taming Rod are strictly educational exercises meant to teach hunters how wild instincts respond to will and calm intent. Once the rod holds the bear docile, the temporary bond fulfills its purpose. Returning the tool to Grif concludes the formal trials, prompting the master to share the permanent secrets of beast mastery: how to pacify any compatible wild creature and call upon it throughout a lifetime of adventure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6085-e4504d4e47fdb580d6b3/1-0000.mp3", duration = 74.0571429, start = 0},
  },
}
P.transport["quest:6086"] = {
  hash = "bb4556",
  fullHash = "bb4556",
  text = "Training the Beast. Training the Beast is the culminating rite of passage for young dwarven hunters in Dun Morogh. Having mastered the art of soothing and taming wild predators in the snowy crags, novice rangers are directed into the heart of Ironforge to learn how to sustain, discipline, and care for a lifelong animal companion. After proving their mettle against the savage beasts of Dun Morogh—soothing large crag boars, snow leopards, and sturdy ice claw bears with a taming rod—apprentice hunters complete their trial under the watchful eye of Grif Wildheart near Kharanos. Yet capturing the wild heart of an animal is only half the bond. Grif sends his newly seasoned pupils up the mountain pass into Ironforge to find the military district known as the Hall of Arms. Within the stone vaults of Ironforge's Hall of Arms stands Belia Thundergranite, one of the dwarven kingdom's most revered master animal trainers. Belia imparts the essential knowledge that turns a wild, terrified beast into a fiercely loyal partner. Her teachings go far beyond simple commands: she shows young hunters how to nourish their pets, teach them new battlefield skills, and even call their spirits back from death should they fall defending their master. Dwarven tradition emphasizes that beast mastery is fundamentally built on respect rather than subjugation. Belia reminds every young hunter that an animal companion reflects the care it receives. If kept well-fed, respected, and properly trained, a beast will offer unwavering loyalty against troggs, frost trolls, and any threat that dares imperil Khaz Modan.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6086-b94e6c1156284c8dc988/1-0000.mp3", duration = 90.0440816, start = 0},
  },
}
P.transport["quest:6087"] = {
  hash = "e9266b",
  fullHash = "e9266b",
  text = "Taming the Beast. This trial marks the second stage of a tauren hunter's initiation into the art of beast taming. Guided by hunter trainer Yaw Sharpmane in Bloodhoof Village, the novice is charged with mastering the swift and fearless prairie stalker. Having successfully mastered the defensive endurance of the adult plainstrider, Yaw Sharpmane challenges the young hunter to look beyond mere survival. The prairie stalker represents an entirely different hunting philosophy: relentless speed, pack coordination, and fearless aggression. To tame one requires approaching a cunning predator without breaking stride, mirroring the wolf's own decisive nature. For the tauren, hunting with a beast is never about servitude or raw subjugation. Yaw Sharpmane stresses that the hunter and predator must fight as one cohesive unit, bound by mutual respect and shared rhythm. By bonding with the prairie stalker under the open skies of Mulgore, the hunter learns to complement a partner's assault and move in tandem during the heat of battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6087-601aa90a5313a1f41067/1-0000.mp3", duration = 57.3126531, start = 0},
  },
}
P.transport["quest:6088"] = {
  hash = "867514",
  fullHash = "867514",
  text = "Taming the Beast. This trial marks the final lesson in a young tauren hunter's training under Yaw Sharpmane in Bloodhoof Village. By using a taming rod to bond with a wild swoop, the hunter proves mastery over creatures of the air and earns the sacred trust of the Earthmother. Completing this task grants the permanent knowledge required to tame and command a lifelong companion. Having already subdued ground-dwelling predators in the rolling plains of Mulgore, Yaw Sharpmane turns your focus toward the open heavens. The swoop is a fierce, sharp-beaked bird of prey known for its sweeping dives and intimidating demeanor. Bringing such a wild, airborne hunter under control tests your reflexes and your calm, demanding that you endure its talons while using the enchanted rod to align your spirit with its instincts. For the tauren, hunting and animal companionship are fundamentally spiritual pursuits rather than mere subjugation. By mastering creatures of both earth and sky, you demonstrate the balance and respect necessary to walk the plains without disrupting nature. Yaw Sharpmane recognizes this maturity, taking back his temporary taming rod and passing on the lasting techniques of calling, dismissing, and permanently taming a companion of your own choosing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6088-625752c52a0b63a654f1/1-0000.mp3", duration = 69.6685714, start = 0},
  },
}
P.transport["quest:6089"] = {
  hash = "cf51bf",
  fullHash = "cf51bf",
  text = "Training the Beast. Training the Beast is the culminating rite of passage for young tauren hunters in Mulgore. After demonstrating the spiritual patience and resolve required to soothe the wild beasts of the plains, hunters are sent to Thunder Bluff to learn the lifelong discipline of bonding with, nourishing, and commanding a permanent animal companion. Having successfully tested their spirit against the dangerous predators of Mulgore—plainstriders, prairie stalkers, and swoops—tauren hunters are judged ready for the true mantle of the hunter. Yaw Sharpmane, the mentor in Bloodhoof Village, entrusts the novice with a journey to Hunter Rise in Thunder Bluff. There stands Holt Thunderhorn, a legendary figure among the shu'halo whose reputation for communing with the wilds is surpassed only by his reverence for the Earthmother. To the tauren, a beast is not a simple weapon or thrall; it is a partner granted through harmony with the natural world. Holt Thunderhorn imparts the vital knowledge required to sustain this partnership. A hunter must learn not only how to guide the creature's combat instincts, but how to nourish its body through regular feeding, mend its injuries, and call its spirit back should it fall defending its companion on the plains.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6089-71a212029baffa7f9621/1-0000.mp3", duration = 70.922449, start = 0},
  },
}
P.transport["quest:61"] = {
  hash = "cbf71e",
  fullHash = "cbf71e",
  text = "Shipment to Stormwind. William Pestle sends a parcel from Goldshire to his brother Morgan in Stormwind. Its candles carry wax supplies from Elwynn Forest to Pestle's Apothecary in the Trade District. William gathers herbs, reagents, and raw goods in Goldshire, while his brother Morgan runs Pestle's Apothecary in Stormwind's Trade District. William cannot easily leave his post at the Lion's Pride Inn, so he depends on travelers heading into the city to carry goods for him. William's parcel holds large candles gathered from kobolds in Elwynn's mines. He says he collects them for their wax. Delivering the shipment brings those supplies to Morgan at Pestle's Apothecary in the Trade District.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_61-34424ac722a8bf459095/1-0000.mp3", duration = 38.6612245, start = 0},
  },
}
P.transport["quest:6101"] = {
  hash = "f0efb3",
  fullHash = "f0efb3",
  text = "Taming the Beast. Dazalar guides a night elf hunter through a second trial in Dolanaar. With an enchanted taming rod, you subdue a nightsaber stalker and learn how wild beasts differ. Dazalar teaches you that the forest's creatures do not all behave alike. Each species has its own temperament, and a hunter must learn to meet it on its own terms. Beneath Teldrassil's canopy, the next test brings you against beasts more cunning and predatory than webspinners. Kaldorei revere nightsabers as sacred predators, fierce guardians, and companions of the Sentinels. With the taming rod, you face a nightsaber stalker and must keep a steady nerve and calm authority. Winning its trust shows you can handle a predator, not only the more docile creatures of the woods.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6101-56ac4967099555dc200c/1-0000.mp3", duration = 43.7812245, start = 0},
  },
}
P.transport["quest:6102"] = {
  hash = "75205c",
  fullHash = "75205c",
  text = "Taming the Beast. In Dolanaar, Taming the Beast brings a young night elf hunter to the final trial of basic training. Under Dazalar’s direction, hunters tame a predatory owl of the skies before gaining the power to choose a lifelong companion. Night elf hunters must make peace with creatures across Teldrassil before their basic beastcraft is complete. After proving their will against beasts of the underbrush, they face the spirit of the skies, the Strigid Screecher. These watchful birds of prey roost high in the boughs west of Dolanaar. Patience and a steady nerve are needed to pacify one with the enchanted Taming Rod. Taming the Strigid Screecher fulfills the ancient lessons of communion between kaldorei hunters and nature. When the apprentice returns the spent rod to Dazalar, the training exercises end. The apprentice earns the full art of calling, dismissing, and permanently taming beasts of their own choosing across Azeroth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6102-459b7ce60806a708dd0a/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["quest:6103"] = {
  hash = "bdf4a5",
  fullHash = "bdf4a5",
  text = "Training the Beast. In Teldrassil, Training the Beast sends night elf hunters from the wilds to Darnassus. After taming beasts among the boughs, they learn pet care and discipline from Jocaste. Dazalar sends you from the wilds near Dolanaar to Darnassus once you prove you can tame a beast. Before you travel Kalimdor with a loyal companion, you need to learn more than how to use a taming rod. Subduing a wild creature tests your strength and will, but an untrained beast can still be unpredictable. Jocaste teaches you the arts of caring for a companion in Darnassus's Cenarion Enclave. She shows you how to feed your pet, bring it back if tragedy strikes, and train it to fight. For night elves, this bond reflects reverence for nature, not simple control.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6103-6da077b099eba8bfd06b/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["quest:6121"] = {
  hash = "f85deb",
  fullHash = "f85deb",
  text = "Lessons Anew. Mathrengyl Bearwalker sends Alliance druids from Darnassus to Moonglade for training. There, Dendrite Starblaze begins their instruction in cleansing venom and toxins. Druids learn from Cenarius, the demigod whose teachings and blessings bind them to the living world. His gifts include the power to cleanse venom with a simple incantation. Such power is not given lightly. Before young druids can wield it, they must learn the hard, ordinary work of fighting toxins without nature's magic. Mathrengyl Bearwalker trains druids in Darnassus's Cenarion Enclave. He sends his student past local practice and on to Moonglade. In Nighthaven, Dendrite Starblaze coordinates the Cenarion Circle's wider efforts and has practical work for the novice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6121-5cd9aea2788e8687835a/1-0000.mp3", duration = 44.1730612, start = 0},
  },
}
P.transport["quest:6122"] = {
  hash = "0fc88d",
  fullHash = "0fc88d",
  text = "The Principal Source. At Cliffspring Falls, a sickness among Darkshore's deer draws the Cenarion Circle's attention to the water. Dendrite Starblaze sends young druids from Moonglade to collect a sample for Auberdine naturalist Alanndarian Nightsong. Cliffspring Falls feeds northern Darkshore with fresh water. When deer began to sicken with a lingering malady, the Cenarion Circle looked to the river for its cause. Dendrite Starblaze in Moonglade suspects the water source is tainted and sends novice druids to gather a sample at the cavern mouth beneath the falls. Vicious naga dwell inside Cliffspring River Cave, near the falls' headwaters. Their presence threatens anyone trying to investigate the blight. The Cenarion Circle needs a sample from the cave mouth to study what is making the wilderness sick.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6122-66f633889f9e48d8d3be/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["quest:6123"] = {
  hash = "a1271b",
  fullHash = "a1271b",
  text = "Gathering the Cure. Gathering the Cure is an essential trial for young night elf druids learning to master nature's healing powers in Darkshore. Guided by Alanndarian Nightsong in Auberdine, the druid collects vital natural reagents to brew a restorative salve for the region's ailing wildlife. This task lays the practical foundation for understanding how herbal remedies combat venom and disease. Following the discovery of a contaminated water source plaguing the local wildlife, Alanndarian Nightsong in Auberdine sets out to concoct an effective curative salve. While the sampled Cliffspring water forms the base of the mixture, genuine healing requires potent natural catalysts. The afflicted forest deer cannot recover on their own, making the gathering of wholesome remedies a matter of urgency for the Cenarion Circle. The restorative salve demands two crucial flora: Earthroot and Lunar Fungus. Earthroot provides pure curative properties, requiring the practiced eye of an herbalist to harvest from the rocky soil. To lend the mixture potency, Alanndarian sends the druid into the nearby eastern caves to gather fungal blooms that flourish in the dark, nestled among increasingly territorial and agitated moonkin.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6123-15ea18937e773524d756/1-0000.mp3", duration = 68.5453061, start = 0},
  },
}
P.transport["quest:6124"] = {
  hash = "4d2257",
  fullHash = "4d2257",
  text = "Curing the Sick. Darkshore’s deer are sick, and Curing the Sick asks you to bring them relief. Alanndarian Nightsong gives you salve to treat the poisoned animals before you report to the Cenarion Circle in Moonglade. In Darkshore, deer fall sick from the Cliffspring River south to the border of Ashenvale. They wander the misty woods, weakened by toxins in the soil and streams. After you gather the needed reagents, Alanndarian Nightsong gives you freshly brewed animal salve to treat the afflicted deer.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6124-f4e1a4d73cc989639dc8/1-0000.mp3", duration = 27.4808163, start = 0},
  },
}
P.transport["quest:6125"] = {
  hash = "a9494f",
  fullHash = "a9494f",
  text = "Power over Poison. In Darnassus, a young druid returns to complete Power over Poison. The Cenarion Circle's trial began in Darkshore, where the initiate learned to brew a remedy by hand. In Darkshore, Alanndarian Nightsong asks young druids to gather Earthroot and Lunar Fungus by hand. They brew a salve to heal stricken wildlife. Before granting the magic to purge toxins, the Cenarion Circle wants initiates to know the hardship of treating poison without spiritual aid. The work teaches them what common folk face when venom strikes, and why a druid must meet their suffering with care. After the remedy proves effective in Auberdine, Starblaze sends the druid across the sea to Darnassus. Mathrengyl Bearwalker awaits in the Cenarion Enclave. Pleased with the initiate's grace under pressure, he teaches the art of cleansing toxins through nature's power. But virulent poisons in the wilds around Auberdine trouble him, for they point to an unnatural blight disturbing the land's balance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6125-62d6cfea2366263e4d23/1-0000.mp3", duration = 58.3836735, start = 0},
  },
}
P.transport["quest:6126"] = {
  hash = "681aca",
  fullHash = "681aca",
  text = "Lessons Anew. Lessons Anew is a rite of passage for young tauren druids, initiated by Turak Runetotem on the Elder Rise of Thunder Bluff. It directs apprentices to travel to the sacred haven of Moonglade to begin mastering the art of cleansing natural and unnatural poisons. Guided by the night elf Dendrite Starblaze, this lesson sets aside mock trials in favor of confronting an urgent, real-world poisoning crisis. Druids hold a sacred mandate to protect the wilds, which includes the miraculous ability bestowed by Cenarius to purge virulent toxins with a simple incantation. However, such potent magic is not handed over without grounding. Turak Runetotem insists that before channeling divine energies to effortlessly dispel blights, a druid must understand the physical toll of venom and learn to treat it through grounded, mundane means. Rather than conducting training solely on the bluffs of Mulgore, promising acolytes are sent north through sacred pathways to Moonglade. There, within the peaceful village of Nighthaven, ancient night elf mentors such as Dendrite Starblaze oversee the education of both elf and tauren practitioners. This shared instruction highlights the delicate truce that exists within the Cenarion Circle, rising above the political strife separating Horde and Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6126-169913b2799b8b37dccf/1-0000.mp3", duration = 77.9232653, start = 0},
  },
}
P.transport["quest:6127"] = {
  hash = "894f3a",
  fullHash = "894f3a",
  text = "The Principal Source. Dendrite Starblaze sends Horde druids to Dreadmist Peak for a water sample. From Moonglade, she asks them to bring it to Tonga Runetotem at the Crossroads, where it can help explain the poison harming wildlife. Dreadmist Peak rises northwest of the Crossroads, with springs and pools high above the dry northern Barrens. Their waters shape local weather and moisture. The Burning Blade, a cult devoted to demons, has taken hold on the crags. Dendrite Starblaze fears their foul sorcery may taint the basin around this important mountain. Sick gazelles stumble across the northern savanna, north of the main east-west trail through the Crossroads. Tonga Runetotem seeks help for the local tauren and turns to the Cenarion Circle to learn what is poisoning the herd. Druids who reach the peak and bring back a sample of its tainted water give Tonga what he needs to study the sickness and brew an antidote.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6127-b4cea184a869358bdb98/1-0000.mp3", duration = 50.8865306, start = 0},
  },
}
P.transport["quest:6128"] = {
  hash = "ee120e",
  fullHash = "ee120e",
  text = "Gathering the Cure. At the Crossroads, young tauren druids face a sacred passage under Tonga Runetotem's guidance. You gather earthroot and sturdy kodo horns to make a salve for the poisoned gazelles of the Barrens. Tonga Runetotem needs raw ingredients to brew an antidote from the water sample you secured at Dreadmist Peak. Natural water forms the salve's base, earthroot supplies its medicinal qualities, and ground kodo horn gives it the strength to drive venom from a creature's system. For a young druid, gathering them means relying on the gifts of the earth and hunting local beasts. Tonga Runetotem uses the salve's preparation to teach the limits of physical medicine. Herbal lore and alchemy can counter specific toxins, but each poison usually needs its own cure. Rather than carry endless herbs and horns, druids learn to attune to nature's healing energies. That lesson leads to the druidic art of Cure Poison.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6128-7431d2e7359bfcfa86c3/1-0000.mp3", duration = 50.8081633, start = 0},
  },
}
P.transport["quest:6129"] = {
  hash = "f06cf9",
  fullHash = "f06cf9",
  text = "Curing the Sick. Curing the Sick is an essential trial for young Horde druids, tasking them with healing afflicted wildlife in the northern Barrens. By applying a freshly concocted herbal salve to ailing gazelles, initiates demonstrate both their practical field medicine and their commitment to preserving natural balance. Completing this duty proves their dedication directly to the Cenarion Circle in Moonglade. Across the northern savanna of the Barrens, grazing gazelles have begun succumbing to an unnatural affliction. After gathering earthroot and kodo horns to assemble a curative remedy, Tonga Runetotem at the Crossroads entrusts a young druid with administering the field treatment. The initiate must search north of the main crossroads to find and minister to ten suffering animals, providing immediate relief before the rot takes further root in the ecosystem. Once the salve is dispensed, the druid's path leads back into the tranquil boughs of Moonglade. There, Dendrite Starblaze recognizes the initiate's compassion and vigilance. He notes that the suffering of the gazelles is merely a symptom of a deeper, insidious corruption stalking Kalimdor's wilderness. By tending to the lowliest beasts, tauren druids demonstrate that reverence for Cenarius transcends tribal boundaries, earning deeper secrets of poison cleansing and nature magic.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6129-3970cfb8e2e5a068b50b/1-0000.mp3", duration = 78.1583673, start = 0},
  },
}
P.transport["quest:6130"] = {
  hash = "154dc5",
  fullHash = "154dc5",
  text = "Power over Poison. Power over Poison is the concluding rite in a young Horde druid's trial to master restorative nature magic. Having cured afflicted gazelles around the Crossroads using only herbal mixtures, the initiate returns to Turak Runetotem on Thunder Bluff's Elder Rise to receive the true gift of Cure Poison. Before granting a fledgling druid the innate magical power to cleanse venoms, the Cenarion Circle demands they understand the physical reality of affliction. Dendrite Starblaze sent the novice to the Crossroads, where Tonga Runetotem had them gather earthly reagents for a curative salve made by hand. Only by treating the poisoned plains gazelles of the Barrens without spiritual aid does the student witness the agonizing struggle ordinary creatures face against natural and unnatural toxins. With the trial complete, Dendrite sends the initiate back to Turak Runetotem, the grand druid trainer residing on the Elder Rise in Thunder Bluff. Turak observes that the strange, virulent poisons surfacing near the Crossroads threaten the natural balance of the plains and warrant grave concern. Commending the initiate's grace under pressure, Turak permanently imparts the spiritual art of curing poisons, entrusting them to safeguard Kalimdor's living creatures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6130-66de2441be6af10d70a0/1-0000.mp3", duration = 70.4, start = 0},
  },
}
P.transport["quest:6181"] = {
  hash = "b0c927",
  fullHash = "b0c927",
  text = "A Swift Message. Quartermaster Lewis at Sentinel Hill needs urgent armor shipments from Stormwind to equip the People's Militia. Because Westfall receives almost no official military aid, he sends you to Thor the gryphon master to carry an urgent requisition note to the capital by air. Sentinel Hill stands isolated against a rising tide of Defias outlaws and gnolls, starved of direct military aid from Stormwind. Quartermaster Lewis relies on private contacts in the capital to keep the People's Militia supplied with weapons and armor. With gear running thin, his only lifeline is Osric Strang, an armorer located in Old Town. Getting an urgent requisition to him requires swift travel, leading Lewis to enlist travelers to contact Westfall's gryphon master, Thor. Gryphons provide the Kingdom of Stormwind with an invaluable rapid transit and courier network. Perched at Sentinel Hill, Thor manages the outpost's aerial link back to the capital. Handing Lewis's note to Thor opens the skies between Westfall and the royal city, demonstrating how crucial the gryphon riders are to sustaining frontier garrisons cut off from formal aid.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6181-651df1cdd8ef8adcd0d3/1-0000.mp3", duration = 65.515102, start = 0},
  },
}
P.transport["quest:62"] = {
  hash = "27a033",
  fullHash = "27a033",
  text = "The Fargodeep Mine. Kobolds have overrun The Fargodeep Mine south of Goldshire, between the Stonefield and Maclure farms. The mine's fall points to a growing pest problem across Elwynn Forest. While Northshire Valley faces its own vermin, reports reach Goldshire that kobolds have claimed another vital site. Between the feuding Stonefield and Maclure homesteads south of town, the Fargodeep Mine once supplied stone and ore for the realm. Now shrill chattering and tallow candles fill its damp tunnels. Marshal Dughan sends you to scout the depths and learn how bad the trouble is. The report of kobolds in the mine adds to the Stormwind Guard's strain. Its troops are already stretched thin defending against Defias bandits and gnoll incursions, leaving too few to clear the tunnels. When Dughan hears the report, he worries about other mineral sites, including the Jasperlode Mine to the northeast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_62-d35b4f454b88ab9dac27/1-0000.mp3", duration = 49.92, start = 0},
  },
}
P.transport["quest:6261"] = {
  hash = "ada49b",
  fullHash = "ada49b",
  text = "Dungar Longdrink. At Stormwind's Trade District roost, Dungar Longdrink arranges swift gryphon transport for supplies bound to Westfall's embattled defenders. Defias outlaws and feral harvest golems have pushed Westfall close to breaking point. Quartermaster Lewis and the People's Militia are desperate for provisions. Lewis sent word to the capital, and armorer Osric Strang packed the requested equipment. Carrying military cargo on foot through bandit-ridden Elwynn and Westfall takes precious time. Stormwind's new aerial routes offer a vital link to the frontier. The gryphon roost sits in Stormwind's Trade District, where Dungar Longdrink coordinates courier and passenger flights. Wildhammer dwarves traditionally raise and handle these majestic beasts. They carry people and cargo across human lands when roosts at both ends know the route. Bringing Osric's heavy crate straight to Dungar teaches couriers how aerial logistics work. It connects the capital's stockpiles directly to frontier outposts such as Sentinel Hill.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6261-3ebb6b790db31eb7da25/1-0000.mp3", duration = 58.7232653, start = 0},
  },
}
P.transport["quest:6281"] = {
  hash = "d64236",
  fullHash = "d64236",
  text = "Continue to Stormwind. You carry a requisition from Sentinel Hill to Stormwind by gryphon, where Osric Strang awaits in Old Town. Quartermaster Lewis prepares a requisition note in Sentinel Hill. The local gryphon master Thor offers you the fastest way out of the contested plains. For a modest fee, you ride one of the kingdom's trained gryphons above dusty farmlands and the river border of Elwynn Forest, then over Stormwind City's high white ramparts. After you land at the capital's trade roosts, you head into Old Town to find Osric Strang at his shop, Limited Immunity. Osric supplies the frontier, but his grim reception shows the growing rift between Westfall's beleaguered People's Militia and the distracted rulers in Stormwind Keep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6281-7c8b41de7673b5646910/1-0000.mp3", duration = 42.3967347, start = 0},
  },
}
P.transport["quest:6285"] = {
  hash = "d7d4f1",
  fullHash = "d7d4f1",
  text = "Return to Lewis. Dungar Longdrink sends armor from Stormwind to the People's Militia at Sentinel Hill. Osric's Crate crosses Elwynn and Westfall by gryphon, carrying supplies to defenders under pressure. Westfall is slipping from the kingdom's grasp. Defias bandits, ravenous gnolls, and mechanical harvest reapers threaten the land. Overland supply routes face harassment, and roads are dangerous for solitary wagons. The flight master network offers a crucial lifeline. Osric, an armorer in Stormwind's Old Town, prepared a heavy crate of armor for the battered volunteers of the People's Militia at Sentinel Hill. Gryphons are loyal, well-trained beasts, but travel across the lands depends on established familiarity. Dungar Longdrink explains that gryphons instinctively know how to return to their capital roost in Stormwind. To carry a rider to a remote outpost, though, they need the traveler to have met its flight master in person. You have already checked in with Thor at Sentinel Hill, opening the skies over the frontier to rapid travel. At Sentinel Hill, Quartermaster Lewis receives the crate. He is the officer tasked with outfitting Gryan Stoutmantle's volunteer force, and he sets to work distributing the armor among the frontier defenders. For Sentinel Hill, reliable aerial contact with the capital can mean the difference between holding the line and being overrun by the Defias Brotherhood.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6285-8f5513eb2dd0c240f164/1-0000.mp3", duration = 80.5616327, start = 0},
  },
}
P.transport["quest:6321"] = {
  hash = "abbec4",
  fullHash = "abbec4",
  text = "Supplying the Sepulcher. Supplying the Sepulcher is a logistical task issued by Deathguard Podrig at the Sepulcher in Silverpine Forest. To keep the local Deathguard detachment equipped against feral horrors and Scourge prowling the woods, an urgent weapon requisition must be routed via bat handler Karos Razok toward weapon suppliers in the Undercity. While Deathguard Podrig reports that the Sepulcher is relatively well-stocked, continuous attrition in Silverpine Forest consumes equipment at an alarming rate. Between feral beasts, prowling Scourge remnants, and aggressive local threats, frontline gear wears down or gets abandoned in skirmishes. Under orders from Executor Hadrec, Podrig drafts a direct requisition order addressed to Gordon Wendham, a weapon dealer operating out of the capital. Securing a steady flow of replacement blades and armor is essential if the Forsaken hope to retain their fragile footholds outside Tirisfal Glades. Moving critical correspondence and military supplies through Silverpine's mist-choked roads on foot is slow and prone to ambush. To bypass these perils, the Forsaken rely on captive, trained vampire bats. Handing Podrig's requisition to bat handler Karos Razok integrates foot soldiers into the broader aerial logistics network of the Undercity, establishing the aerial transit lines that tie outlying garrisons directly to Sylvanas's capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6321-86f3e986150cd2fd3d98/1-0000.mp3", duration = 78.08, start = 0},
  },
}
P.transport["quest:6322"] = {
  hash = "3416de",
  fullHash = "3416de",
  text = "Michael Garrett. Michael Garrett is a simple courier task linking trade in the Undercity with the Forsaken's flight network. After collecting supplies packed by Gordon Wendham in the Trade Quarter, you are directed to deliver the crate to the bat handler Michael Garrett to arrange aerial transport out toward the Sepulcher. It highlights how the Forsaken utilize trained vampire bats to connect their capital with outposts across Lordaeron. Running a fledgeling kingdom carved out of the ruins of Lordaeron requires constant logistics. Outposts like the Sepulcher in Silverpine Forest rely heavily on goods, munitions, and provisions moving out from the Undercity. Gordon Wendham packs the necessary field supplies into a single crate in the city's Trade Quarter, but carting freight by ground through blighted forests is both slow and vulnerable to ambush by Scourge remnants or wild beasts. To bypass the dangers on the roads, the Forsaken rely on captive vampire bats bred and maintained by skilled handlers. Michael Garrett oversees these winged beasts from his roost in the Undercity's Trade Quarter. Delivering the cargo to him ensures the supplies can be strapped to a bat and flown directly over the hills to Silverpine, teaching new couriers how the capital coordinates with remote settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6322-ad164aa6a3fb3bd57be2/1-0000.mp3", duration = 73.0383673, start = 0},
  },
}
P.transport["quest:6323"] = {
  hash = "0f248c",
  fullHash = "0f248c",
  text = "Ride to the Undercity. Ride to the Undercity introduces fledgling Forsaken adventurers to the Horde's aerial flight network across Lordaeron. Carrying weapon requisitions from the embattled outpost of the Sepulcher, couriers take a dread bat directly into the Undercity's Trade Quarter to resupply regional defenders. Maintaining lines of communication between the Forsaken capital and its frontline outposts requires swift, reliable transit. Karos Razok, the bat handler stationed at the Sepulcher in Silverpine Forest, manages the trained dread bats that ferry messengers and supplies across the plagued landscape. With roads crawling with hostile beasts, Moonrage worgen, and remnants of the Scourge, taking to the skies is the safest and fastest way to ensure urgent military requests reach the capital. Upon touching down in the Undercity's bustling Trade Quarter, the courier delivers Podrig's equipment requisition directly to Gordon Wendham. As an Undercity weaponsmith dedicated to the Dark Lady's cause, Wendham ensures that regional outposts like the Sepulcher remain outfitted with clean, battle-ready armaments. Sustaining these defensive hubs is vital for the fledgling Forsaken nation as it secures its borders against surrounding enemies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6323-09012fae0a86ea70cd08/1-0000.mp3", duration = 68.6236735, start = 0},
  },
}
P.transport["quest:6324"] = {
  hash = "faf141",
  fullHash = "faf141",
  text = "Return to Podrig. Return to Podrig is a logistics quest concluding a courier run between Silverpine Forest and the Undercity. After delivering a dispatch to the capital, the courier is entrusted with a crate of weapons to ferry back to Deathguard Podrig at the Sepulcher using the Forsaken bat handler network. Outposts throughout Lordaeron depend heavily on regular shipments from the Undercity to remain operational. At the Sepulcher in Silverpine Forest, Deathguard sentries face pressure from local worgen, Dalaran remnants, and Scourge stragglers. Supplying remote garrisons with freshly forged armaments is vital to holding the region under Forsaken control. Bat Master Michael Garrett operates the central roost in the Undercity's Trade Quarter, serving as the hub for Forsaken aerial travel. While bats naturally return to the capital, riders must first coordinate with local handlers like Karos Razok before flights to distant outposts can be charted. Flying Gordon's Crate across Lordaeron's skies teaches couriers how the Forsaken bind their scattered strongholds together.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6324-9c855eb5a89272678bef/1-0000.mp3", duration = 60.6302041, start = 0},
  },
}
P.transport["quest:6341"] = {
  hash = "b104d6",
  fullHash = "b104d6",
  text = "The Bounty of Teldrassil. Nessa Shadowsong is sending fish samples from Rut'theran Village to Auberdine for comparison. She wants to learn whether Teldrassil's fish are larger and more plentiful than those along the mainland coast. Nessa Shadowsong asks you to carry fish bones and scales to Laird in Auberdine. Fishers in Rut'theran Village bring in large, plentiful catches, and she wants to know whether the mainland waters yield the same kind of fish. The samples will let Laird compare the island catch with fish from the coast of Darkshore. Nessa Shadowsong sends you to Vesprystus, the hippogryph master in Rut'theran Village, with the collection for Auberdine. Carrying the samples to him arranges your passage across the water to Darkshore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6341-61d681ed1ebb8a8b528b/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["quest:6342"] = {
  hash = "3d36d4",
  fullHash = "3d36d4",
  text = "Flight to Auberdine. You leave Teldrassil for Auberdine with a bundle of unusual fish specimens. Vesprystus sends you from Rut'theran Village by hippogryph to deliver them to Laird. Rut'theran Village is a sanctuary at the edge of the wider world for young adventurers leaving Teldrassil. A mundane ferry crosses the strait between the island and mainland Kalimdor, while night elves also travel by bonded hippogryph. Nessa Shadowsong entrusts you with a parcel of rare fish parts, and you take wing to reach the shores of Darkshore. Laird waits for Nessa's findings at the docks of Auberdine. He finds enormous scales as large as fists and a jawbone nearly twice the size of mainland specimens. The waters around the base of the World Tree seem to produce altered or abnormally large life, a curiosity tied to Teldrassil's potent, restless nature.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6342-057894e1479e0a1bce8c/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["quest:6343"] = {
  hash = "6ac913",
  fullHash = "6ac913",
  text = "Return to Nessa. You carry Laird's findings from Auberdine back to Nessa Shadowsong in Rut'theran Village. The journey is an introductory errand that teaches young travelers how to cross between Kalimdor and Teldrassil. Laird sends you back across the water with his written observations. He has found stark differences between the fish caught off Darkshore and those near Teldrassil, and suspects the great World Tree changes the local marine life. You can return to Rut'theran Village by hiring a flight from Caylais Moonfeather, the hippogryph master, or by boarding the regular ferry at Auberdine's pier. Nessa Shadowsong receives Laird's reply at Rut'theran Village and is fascinated by the difference in marine life. Fish near the World Tree grow so large that they bring an immediate boon to local fishermen, though the Kaldorei still do not know why. Nessa plans to share the findings with her fellow villagers. For now, she is content to harvest the abundant sea life and watch for whatever forces may be responsible.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6343-e82d7c69e067596943a1/1-0000.mp3", duration = 57.0253061, start = 0},
  },
}
P.transport["quest:6344"] = {
  hash = "0e5f76",
  fullHash = "0e5f76",
  text = "Nessa Shadowsong. In Darnassus, Mydrannul sends a courier to meet Nessa Shadowsong below the World Tree. The delivery runs from Rut'theran Village to Darkshore, linking the canopy city with the shore. Mydrannul watches over travelers seeking work and purpose in Darnassus. Fishing merchant Nessa Shadowsong needs a package carried across the sea to Darkshore, so Mydrannul directs able couriers toward the coast. Many young night elves begin their journeys among Teldrassil's boughs; this delivery takes them beyond the tree. From the Temple Gardens, the western portal in Darnassus leads down through the World Tree to Rut'theran Village. At the ocean-level roots, fishing docks and hippogryph perches connect Teldrassil with the rest of Kalimdor. Nessa Shadowsong tends her trade there and prepares shipments for Auberdine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6344-e2d6b22484c4cd89065b/1-0000.mp3", duration = 47.5428571, start = 0},
  },
}
P.transport["quest:6361"] = {
  hash = "082457",
  fullHash = "082457",
  text = "A Bundle of Hides. Jahan Hawkwing sends cured hides from the Crossroads to Thunder Bluff for leatherworking. The delivery takes you across central Kalimdor and introduces the Crossroads wind rider roost. Hunters bring game hides and meat to the Crossroads, where Jahan Hawkwing gathers pelts from across the Barrens. The outposts cannot process every raw hide, so he asks travelers to carry them west to Thunder Bluff. Master leatherworkers there can turn the pelts into gear for the Horde. The trail across the Barrens and into Mulgore is rough, and quilboar and predators threaten anyone carrying cargo on foot. Jahan sends you to Devrak, the Crossroads wind rider master. He can take the goods by air aboard a trained wyvern, linking the Horde’s scattered settlements.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6361-1b43aedec9b9ff0afe27/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["quest:6362"] = {
  hash = "f5020c",
  fullHash = "f5020c",
  text = "Ride to Thunder Bluff. This quest sends young Horde adventurers taking their first flight path across Kalimdor aboard a wind rider. Entrusted with a shipment of cured hides, travelers depart the dry crossroads of the Barrens to deliver valuable leatherwork supplies directly to the heights of Thunder Bluff. For many travelers making their way through the Barrens, booking a flight with Devrak marks their first journey through the skies on the back of a wind rider. These winged wyverns provide vital aerial links between the dispersed settlements of the fledgling Horde, avoiding the perilous ground routes prowled by quilboar and centaur packs. The shipment consists of a bundle of cured hides prepared in the Barrens and destined for Ahanu, a craftsman working out of Hewa's Armory in Thunder Bluff. Nestled right beneath the great wind rider roost on the central mesa, Ahanu relies on raw supplies brought in from hunting outposts across the plains to outfit local warriors and hunters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6362-b6cbef6b1eed49d0a6a7/1-0000.mp3", duration = 52.3755102, start = 0},
  },
}
P.transport["quest:6363"] = {
  hash = "ca6c1a",
  fullHash = "ca6c1a",
  text = "Tal the Wind Rider Master. Tal the Wind Rider Master is a simple courier task connecting Mulgore leatherworkers with merchants in the Barrens. The leatherworker Ahanu entrusts a parcel of finished hides to be flown out of Thunder Bluff. Delivered directly to Tal, the mesa's flight master, it introduces fledgling Horde travelers to the wind rider transport network. Trade between Mulgore and the arid scrub of the Barrens is essential for the young Horde. Ahanu, a leatherworker selling his wares on Thunder Bluff's lower rise, produces durable leather goods intended for Jahan Hawkwing's trade stall at the Crossroads. Because the overland walk down the bluffs and through the golden plains takes hours on foot, merchants rely on winged couriers to ferry fragile or urgent parcels over the craggy divide. Perched upon the highest central tier of Thunder Bluff, Tal tends to the city's flock of wind riders—also known as wyverns. These intelligent, leathery-winged beasts are ideally suited for navigating Kalimdor's unpredictable thermal drafts and rugged peaks. Tal coordinates flights departing to outposts like the Crossroads, ensuring messengers and cargo pass quickly between the tauren capital and their orcish allies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6363-1ea35cd88bb649fed47e/1-0000.mp3", duration = 67.9967347, start = 0},
  },
}
P.transport["quest:6364"] = {
  hash = "3d2f5b",
  fullHash = "3d2f5b",
  text = "Return to Jahan. Return to Jahan marks the concluding leg of an introduction to the Horde's wind rider flight network between Mulgore and the Barrens. After visiting Thunder Bluff to deliver hides to the skinner Ahanu, travelers take a wyvern back to the Crossroads carrying finished leather wares for the merchant Jahan Hawkwing. For many travelers, this errand is their first experience soaring aboard a trained wind rider. Tal, the wind rider master perched high atop Thunder Bluff's central mesa, arranges flights across the plains of central Kalimdor. As long as a traveler has already established contact with the roost at another settlement—such as Devrak's outpost at the Crossroads—these winged beasts can effortlessly cover leagues that would otherwise demand a perilous overland trek through the Red Rocks and northern Barrens. The courier run serves an economic purpose alongside flight training. Jahan Hawkwing operates out of the bustling settlement of the Crossroads, where hunters, scouts, and mercenaries gather daily. Raw hides sent to Ahanu on the high rises of Thunder Bluff are refined into durable armor and equipment, then flown back to the dusty intersection of the Barrens to supply the Horde's expanding frontier efforts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6364-e006cde2a363e9ded3a3/1-0000.mp3", duration = 67.5004082, start = 0},
  },
}
P.transport["quest:6365"] = {
  hash = "9557b1",
  fullHash = "9557b1",
  text = "Meats to Orgrimmar. At the Crossroads, Zargh sends a parcel of Barrens meat toward Orgrimmar. He asks young orc and troll adventurers to carry it to Devrak, the wind rider master, and learn the flight route to the Horde capital. Wildlife fills the Barrens, from zhevras and plainstriders to kodos and thunder lizards. Zargh has prepared choice cuts for a personal delivery to Gryshka, the innkeeper in Orgrimmar's Valley of Strength. Rather than risk the long, dusty trek across the Southfury River into Durotar, he sends runners from the Crossroads to the wind rider perch. Meeting Devrak gives a young Horde warrior a first look at the wind rider flight network. Wind rider masters connect remote outposts like the Crossroads to the Horde's fortified seat of power in Orgrimmar. Devrak prepares you and the cargo for a swift flight over the savannah.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6365-f7dfbdeaf13bfbba55cf/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["quest:6384"] = {
  hash = "01c2df",
  fullHash = "01c2df",
  text = "Ride to Orgrimmar. A wind rider carries Horde travelers from the Crossroads to Orgrimmar. With Zargh’s fresh cuts of meat in hand, you fly to the capital’s Skytower and deliver them to Innkeeper Gryshka. Devrak sends trained wind riders between the Crossroads and Orgrimmar. The flight crosses the dry Barrens and reaches Durotar’s red cliffs, sparing travelers the hard journey on foot. From high above the dusty canyon trails, the wyverns carry messengers and travelers, along with dispatches and trade goods, straight to the capital. Zargh has prepared fresh cuts of meat for Innkeeper Gryshka in Orgrimmar’s Valley of Strength. From the central Skytower, her inn is a short walk away. Gryshka accepts the parcel and remarks with fondness that Zargh knows how to win a lady’s heart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6384-d62c442a4a64dedeb7c3/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["quest:6385"] = {
  hash = "ec1ede",
  fullHash = "ec1ede",
  text = "Doras the Wind Rider Master. Innkeeper Gryshka needs a courier to carry her thanks to Zargh at the Crossroads. She sends travelers to Doras the Wind Rider Master at Orgrimmar's skytower to arrange the flight back to the Barrens. Innkeeper Gryshka sends thanks to Zargh after a shipment of meat arrives safely from the Barrens hunting grounds. With no time to travel through Durotar herself, she trusts the established aerial courier network linking major Horde settlements to carry her letter back across the frontier. At the flight tower in the Valley of Strength, Doras oversees Orgrimmar's wind rider roost. The trained wyverns carry military messages and supplies between the capital and outposts such as the Crossroads, far faster than anyone traveling by foot or kodo cart.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6385-2bbdd9262c2229afdb14/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["quest:6386"] = {
  hash = "2e84c6",
  fullHash = "2e84c6",
  text = "Return to the Crossroads.. Gryshka's reply is on its way from Orgrimmar to Zargh at the Crossroads. A wind rider carries it across the distance between Durotar and the Barrens. You carry Gryshka's written reply to Zargh after bringing her a parcel of prime meat in Orgrimmar. Doras, the wind rider master atop Orgrimmar's high bluffs, provides a mount for the return to the Barrens. You have already met Devrak at the Crossroads, so the wyverns know the flight path. The ride crosses the desert sky and saves you the long march overland across the Southfury River. Zargh's courtship has won Gryshka's warm reply. Quality provisions have pleased her, and Zargh celebrates, even musing about an impending wedding. The delivery also brings you back to the Barrens' central hub for travel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6386-7acc056876dd106bf476/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["quest:6387"] = {
  hash = "2f8ac5",
  fullHash = "2f8ac5",
  text = "Honor Students. Mining instructor Brock Stoneseeker rewards promising young apprentices in Thelsamar with honorary mining picks. To arrange delivery of the tools from Ironforge, he directs adventurers to enlist the aid of the local gryphon master, Thorgrum Borrelson. In the dwarf town of Thelsamar, mining is more than an occupation—it is a cornerstone of daily survival and dwarven pride. Brock Stoneseeker watches dozens of fresh recruits pass through his training, drilling them on rock composition and tunnel safety. For the students who distinguish themselves above the rest, tradition demands recognition in the form of a finely crafted honorary pick. Because local supply is limited, obtaining these picks requires reaching across Khaz Modan into the heart of Ironforge. Rather than trusting the slow, mountainous trek back through Dun Morogh on foot, Brock relies on the kingdom's aerial courier network. Thorgrum Borrelson tends the gryphon roost perched beside Thelsamar, offering rapid transit to the capital. Handing Brock's order to Thorgrum initiates a courier run that connects rural frontier training directly to the grand foundries of the dwarven capital.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6387-25f6ddd829cacd998959/1-0000.mp3", duration = 65.8285714, start = 0},
  },
}
P.transport["quest:6388"] = {
  hash = "d22422",
  fullHash = "d22422",
  text = "Gryth Thurden. This errand introduces adventurers to Ironforge's gryphon network by tasking them with carrying a bundle of ceremonial tools to the city's gryphon master. Entrusted with the Honorary Picks by Golnir Bouldertoe, the courier must deliver them to Gryth Thurden so they can be dispatched back to Loch Modan. After traveling from Loch Modan to the Great Forge, couriers receive a bundle of Honorary Picks from Golnir Bouldertoe meant for Brock Stoneseeker's mining apprentices. Rather than making the trek back down the mountain passes on foot, Golnir advises taking advantage of the dwarven gryphon network, sending the messenger across the city to coordinate with Ironforge's master handler. Gryth Thurden manages the flight roosts within the great mountain hall, connecting Ironforge to dwarven settlements across Khaz Modan. Thurden agrees to arrange transport back to Thorgrum Borrelson in Thelsamar provided the adventurer has already scouted the route and spoken with the local handler there. The delivery teaches fledgling heroes the vital role aerial couriers play in tying the dwarven kingdom together.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6388-a67e9aaf6c3538e5da7e/1-0000.mp3", duration = 61.9102041, start = 0},
  },
}
P.transport["quest:6391"] = {
  hash = "78c44f",
  fullHash = "78c44f",
  text = "Ride to Ironforge. Ride to Ironforge is an introductory courier quest that sends newly trained adventurers on their first gryphon flight from Thelsamar in Loch Modan into the dwarven capital. Entrusted with a list of top mining students from Brock Stoneseeker, the traveler carries the dispatch straight to Golnir Bouldertoe at the Great Forge. For many young mountaineers and travelers, the flight from Thelsamar to Ironforge marks their very first journey astride a gryphon. Handled by Gryphon Master Thorgrum Borrelson, this short passage carries travelers over Dun Morogh's snowy ridges and directly into the cavernous entry of the mountain fortress. The errand itself serves the Deep Mountain Mining Guild. Brock Stoneseeker regularly sends word of his most promising mining pupils from Thelsamar. Waiting at the Great Forge is Golnir Bouldertoe, who inscribes the apprentices' names onto ceremonial honorary picks to reward their hard work in Loch Modan's quarries and mines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6391-ef1a454ea642d508254a/1-0000.mp3", duration = 54.8310204, start = 0},
  },
}
P.transport["quest:6392"] = {
  hash = "6753c5",
  fullHash = "6753c5",
  text = "Return to Brock. Having delivered Brock Stoneseeker's missive to Ironforge, you are entrusted with a batch of Honorary Picks to carry back to Thelsamar. Taking advantage of the dwarven aerial transit network, you board a gryphon with Gryth Thurden to return quickly across the mountains. The great mountain stronghold of Ironforge relies on a coordinated network of gryphon roosts to maintain communication and trade with outlying settlements like Loch Modan. Gryth Thurden, Ironforge's gryphon master, oversees this transit from the city's central flight master platform. Because travelers must first establish a rapport with an aerie's handler before flying there, Gryth ensures you have already spoken with Thorgrum Borrelson in Thelsamar before saddling a mount for the return trip. Your journey serves a practical purpose beyond introducing you to gryphon travel: Brock Stoneseeker, a respected mining instructor in Thelsamar, needs new equipment for his apprentices. With the Honorary Picks safely delivered to his hands, young miners across the valley can begin working the rich copper and tin veins that line the hills surrounding the Loch.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6392-8a16d1b6e38c8db4b92b/1-0000.mp3", duration = 61.3616327, start = 0},
  },
}
P.transport["quest:6395"] = {
  hash = "b4d95c",
  fullHash = "b4d95c",
  text = "Marla's Last Wish. Marla's Last Wish is an early Forsaken task given by Novice Elreth in Deathknell. It asks you to hunt down the Scourge-enslaved remnants of Samuel Fipps so he can be buried beside his murdered wife, Marla. The task reflects the fledgling Forsaken society's yearning to honor human ties and distinguish themselves from the mindless Scourge. Before the Third War devastated Lordaeron, Marla and Samuel Fipps lived together as husband and wife. When the plague swept through their lands, Samuel succumbed to the contagion and was reanimated as a mindless thrall of the Scourge. Though Marla was spared undeath, she could not escape Samuel himself, who brutally slew her in his mindless frenzy. Despite dying at her husband's hands, Marla harbored no hatred in her final moments. Her dying wish, remembered by Novice Elreth, was to rest eternally beside her husband in the Deathknell graveyard. Novice Elreth dispatches Forsaken adventurers northeast of Deathknell to locate Samuel Fipps, who still wanders among a ruined campsite. Putting an end to Samuel's torment serves a dual purpose: it cleanses an encroaching Scourge minion from the valley and allows his physical remains to be carried back to Marla's resting place. As Elreth emphasizes, honoring the deceased and respecting their final wishes is a vital moral distinction separating the newly liberated Forsaken from the mindless malice of the Scourge.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6395-2d730d786dc35aea15aa/1-0000.mp3", duration = 85.2636735, start = 0},
  },
}
P.transport["quest:64"] = {
  hash = "d17818",
  fullHash = "d17818",
  text = "The Forgotten Heirloom. In Westfall, the Furlbrows have fled their farm, leaving a cherished heirloom behind. Recovering the pocket watch offers them a chance to salvage something personal from the chaos spreading through the region. Farmer Furlbrow and his wife Verna were driven from their Westfall farm by violence. Shouts rose from the pumpkin patches in the night, waking them with little time to gather what they could carry. In the rush to flee, Furlbrow left behind the pocket watch Verna's father gave him on their wedding day. It remains in the wardrobe of their occupied farmhouse. Defias thugs and thieves, including Benny Blaanco, now pick through the abandoned Furlbrow farm. For ordinary folk, returning for a keepsake could mean death. By securing the pocket watch from the wardrobe, you restore a measure of dignity to a family that has lost nearly everything to Westfall's lawlessness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_64-f6d3ab76f5ed3304b9be/1-0000.mp3", duration = 50.2595918, start = 0},
  },
}
P.transport["quest:65"] = {
  hash = "7ed634",
  fullHash = "7ed634",
  text = "The Defias Brotherhood. In Westfall, the Defias Brotherhood's thieves threaten the farms and roads. Gryan Stoutmantle sends you from Sentinel Hill east into Redridge to seek a contact who may know where they hide. Westfall's harvests are gone, and bandits in red bandanas roam the land. Gryan Stoutmantle and the People's Militia hold Sentinel Hill under near-constant attack, but they do not know who directs their enemies. Stoutmantle knows that fighting stray looters will not save the region. He needs to find the cartel's inner circle and learn who commands it. Gryan Stoutmantle sets aside military channels and Stormwind's absent nobles, and calls on someone he knows. He sends trusted adventurers east, past Elwynn and into the Redridge Mountains. In Lakeshire, a quiet village by the lake, Wiley the Black waits on the upper floor of the local inn. The rogue knows the underworld better than any militia captain, and may offer the first lead to the Brotherhood's hideouts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_65-993e71be17a1891a70cf/1-0000.mp3", duration = 58.0963265, start = 0},
  },
}
P.transport["quest:6541"] = {
  hash = "21670b",
  fullHash = "21670b",
  text = "Report to Kadrak. At the Crossroads, Thork sends proven Horde fighters north to report to Kadrak. The orc holds a watch tower near the Ashenvale border and prepares recruits for the fighting ahead. The Crossroads faces quilboar, centaur, and local brigands, while the Horde looks north to Ashenvale's thick forests. Thork directs fighters who have proved themselves in the central Barrens to the northern border tower, where Kadrak is stationed. Kadrak oversees the southern approach to Ashenvale and organizes reinforcements for the Horde's foothold across the border. Splintertree Post and an outpost along the Zoram Strand help the Horde strengthen its presence in the timber-rich woodlands, where native night elves resist them fiercely.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6541-6a4f8dcc41877b9e3487/1-0000.mp3", duration = 41.1428571, start = 0},
  },
}
P.transport["quest:6543"] = {
  hash = "0fea06",
  fullHash = "0fea06",
  text = "The Warsong Reports. Kadrak sends couriers from the northern Barrens to gather reports across Ashenvale. The Warsong Reports carry orders and field observations from outriders near Azshara, Splintertree Post, and the Zoram Strand. Kadrak watches the mountain pass between the northern Barrens and Ashenvale from a fortified tower. The Horde needs the pass because the Barrens cannot supply the timber Orgrimmar requires. The Warsong clan has pushed into the ancient elven forest to reach those supplies. Couriers carry orders between scattered patrols and help keep them in step, while night elf ambushes threaten the wilderness trails. Warsong scouts watch three parts of Ashenvale. On the western coast, a runner at Zoram'gar Outpost watches naga activity and other coastal threats along the Zoram Strand. At Splintertree Post, a scout coordinates defense against Sentinel raids. Farther east, an outrider watches the road toward the shattered ruins of Azshara. Their reports give Kadrak a view of night elf movements and weaknesses along the frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6543-8c9e271d3115930b9b1c/1-0000.mp3", duration = 60.0032653, start = 0},
  },
}
P.transport["quest:6608"] = {
  hash = "53c140",
  fullHash = "53c140",
  text = "You Too Good.. Lumak sends you from Orgrimmar to find his friend Nat Pagle. Your skill has outgrown ordinary lessons, and Nat camps on a distant islet south of Theramore Isle. Lumak trains fishers in Orgrimmar's Valley of Honor. He sees that you have learned all he can teach about rod and reel, and admits you are too good for ordinary lessons. To learn the art of artisan fishing, you must seek knowledge beyond the city and the Horde. Lumak sends you to find his human friend, Nat Pagle. He warns you not to harm or eat Nat, despite the friction between the Horde and Alliance across Kalimdor. Nat camps on an islet south of Theramore Isle in Dustwallow Marsh. He keeps clear of politics and cares only whether the fish are biting.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6608-73b7b6ccd6ea4352310b/1-0000.mp3", duration = 40.1763265, start = 0},
  },
}
P.transport["quest:6611"] = {
  hash = "15673d",
  fullHash = "15673d",
  text = "To Gadgetzan You Go!. In Orgrimmar, Zamja sends Horde cooks south to learn from an eccentric goblin butcher. Zamja trains cooks in the Drag, where she feeds warriors and travelers passing through Durotar. When a cook has learned every recipe and technique she can teach, Zamja admits she has imparted all her culinary mojo. She sends her seasoned pupil to Tanaris, saying only a master of strange and exotic meats can help a talented cook advance further. In Tanaris, Gadgetzan is a steam-powered trading hub run by the Steamwheedle Cartel. Dirge Quikcleave works inside the town tavern. The eccentric goblin butcher has an unconventional palate and no squeamishness about food. Across Kalimdor, he is known for turning monstrous desert creatures, and sometimes scraps of leather, into hearty meals for hardened adventurers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6611-8b78014018c44db29f1a/1-0000.mp3", duration = 48.7444898, start = 0},
  },
}
P.transport["quest:6623"] = {
  hash = "662102",
  fullHash = "662102",
  text = "Horde Trauma. At Hammerfall in the Arathi Highlands, Horde Trauma calls skilled medics into front-line surgery. Doctor Gregory Victor, chief physician of the Horde's trauma division, seeks hands able to save lives under extreme pressure. In Orgrimmar's Valley of Spirits, the orc first aid trainer Arnok tells proficient healers that they have caught Doctor Gregory Victor's attention. Victor oversees Horde Trauma from Hammerfall, tucked away in the contested hills of the Arathi Highlands. Arnok regards the summons as the pinnacle of professional advancement for a battlefield surgeon. At Hammerfall, constant skirmishes with Stromgarde's forces and local hostile factions leave Victor inundated with wounded grunts, raiders, and scouts. The chief physician wastes no time welcoming recruits with pleasantries. Instead, he orders newcomers into their scrubs to prove their worth in brutal, fast-paced emergency triage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6623-fcdf909515abc134026c/1-0000.mp3", duration = 51.9314286, start = 0},
  },
}
P.transport["quest:6962"] = {
  hash = "fdaa6a",
  fullHash = "fdaa6a",
  text = "Treats for Great-father Winter. At the Smokywood Pastures display in Orgrimmar, the Greatfather Winter performer is worn out from hearing holiday wishes. He asks you for gingerbread cookies and milk. The Greatfather Winter who greets visitors in the Valley of Strength works for Smokywood Pastures. Long hours listening to citizens speak of festive treats leave him hungry. He turns to passing travelers for warm baking and a cold drink. You can bake the cookies with Holiday Spices sold by Smokywood Pastures peddlers and Small Eggs gathered from wild birds. Bring them together with Ice Cold Milk from a local tavern, and the feast's organizers offer you festive cheer and a small token of gratitude.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6962-62a1111aae416acbefdc/1-0000.mp3", duration = 36.7281633, start = 0},
  },
}
P.transport["quest:6984"] = {
  hash = "4fb5bc",
  fullHash = "4fb5bc",
  text = "A Smokywood Pastures' Thank You!. Great-father Winter waits in Orgrimmar to thank those who recovered Smokywood Pastures' stolen holiday treats. Kaymard Copperpinch sends you to receive a token of appreciation for bringing the supplies back. In Orgrimmar, Smokywood Pastures sells treats, recipes, and seasonal cheer for the Feast of Winter Veil. Their shipment was stolen in the snowy hills of the Alterac Mountains, and business stalled. With the treats recovered and the Abominable Greench dealt with, Kaymard Copperpinch sends you to receive the company's thanks. Great-father Winter waits beside the holiday tree in the Valley of Strength. The goblins have arranged for him to honor those who rescued the holiday supplies with a seasonal blessing and a Smokywood Pastures Special Gift.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_6984-c4a01b10ac1b5f2ee1d8/1-0000.mp3", duration = 42.3967347, start = 0},
  },
}
P.transport["quest:7"] = {
  hash = "91f2dc",
  fullHash = "91f2dc",
  text = "Kobold Camp Cleanup. At Northshire, Kobold Camp Cleanup puts new recruits to their first test defending Stormwind's borders. Marshal McBride sends volunteers after kobolds in the northern woods, where their growing numbers threaten the abbey grounds. Northshire Valley once offered quiet for prayer, farming, and novice training. In recent years, Stormwind's forces have grown thin. With the King missing and royal garrisons scattered, wild creatures and opportunists press at civilization's edge. Marshal McBride directs the valley's defense from Northshire Abbey. He depends on fresh volunteers to keep threats from disrupting the abbey or endangering the surrounding vineyards. Kobolds are timid cave-dwellers with a strong attachment to candles. They usually pick at underground seams, far from direct sunlight. Now an entire clan has reached Northshire's northern timberline. If left unchecked, their numbers can turn scavenging into open raids. McBride sends recruits to thin their vanguard and test their resolve to defend the realm.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7-8ba64bf833848b6f6a96/1-0000.mp3", duration = 58.8016327, start = 0},
  },
}
P.transport["quest:730"] = {
  hash = "ca3db1",
  fullHash = "ca3db1",
  text = "Trouble in Darkshore?. In Darnassus, Chief Archaeologist Greywhisker seeks help for his missing crew. His introductory appeal sends travelers across the sea to Auberdine, where the dwarven expedition met Darkshore's wild, shadowy coast. Darnassus, the grand night elven capital, is home to dwarven researchers from Ironforge studying Kalimdor's ancient mysteries. Chief Archaeologist Greywhisker sent an excavation party across the water to Darkshore to unearth artifacts of antiquity. Weeks have passed without a message or progress report, and Greywhisker fears his field crew has met dangers they could not survive alone. Greywhisker laments that many in the Alliance dismiss dwarven archaeology as an eccentric hobby. Findings in Khaz Modan have convinced his colleagues that an ancient, terrifying force threatens Azeroth from Lordaeron to Kalimdor. The work in Darkshore's ruins is more than scholarship: it seeks to understand historic cataclysms and the deep-seated menaces buried beneath ancient soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_730-5109597023a2f6cb6c0f/1-0000.mp3", duration = 58.5665306, start = 0},
  },
}
P.transport["quest:745"] = {
  hash = "2f8fc0",
  fullHash = "2f8fc0",
  text = "Sharing the Land. Assigned by Baine Bloodhoof in Bloodhoof Village, this task sends young Horde adventurers to curb the destructive poaching of the local Palemane gnolls. By culling their tanners, skinners, and poachers, you protect Mulgore's wildlife and learn the tauren philosophy of living in balance with the Earth Mother. The tauren hold deep reverence for the natural world, taking from it only what is necessary to survive and honoring the Earth Mother in all things. The Palemane gnolls, having settled south of Bloodhoof Village and in a cavern to the west, harbor no such respect. Rather than hunting in moderation, they aggressively butcher wildlife across the plains, leaving stripped carcasses and upset ecosystems in their wake. For a people striving to build a peaceful homeland in Mulgore, this reckless slaughter cannot be tolerated. Baine Bloodhoof initially hoped to resolve the matter peacefully, attempting to open dialogue with the encroaching gnolls. The Palemanes rejected every overture, answering diplomacy with hostility and continued devastation. Seeing that negotiation is futile, Baine turns to force. Young braves are sent directly to their hunting camps to put down the poachers, tanners, and skinners before the grasslands suffer permanent damage. This mission serves as a rite of passage and a moral lesson for growing champions. Upon returning from the culling, Baine reminds the adventurer that taking life must never be done out of malice, but out of necessity to maintain harmony. Life and death exist as an interconnected circle where one cannot thrive without the other, a foundational truth every guardian of Mulgore must carry forward.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_745-f3f8f1ac7dfa1cb7afc5/1-0000.mp3", duration = 96.3657143, start = 0},
  },
}
P.transport["quest:746"] = {
  hash = "ce47ea",
  fullHash = "ce47ea",
  text = "Dwarven Digging. Dwarven Digging is a quest in Mulgore given by Baine Bloodhoof in Bloodhoof Village. Concerned that dwarven excavations will enrage the native beasts and defile the sacred earth, Baine tasks young Horde defenders with sabotaging their efforts by confiscating and shattering their pickaxes. Northwest of Bloodhoof Village, dwarven prospectors have begun staking out a dig site in the rolling hills of Mulgore. The Explorer's League and its excavation crews seek titan relics and earthen secrets across Kalimdor, but their operations rarely respect indigenous lands or customs. To the tauren, the earth is a living mother to be revered, not stripped and hollowed for stones and metal. Baine Bloodhoof recognizes that the dwarven machinery and relentless blasting threaten the fragile harmony of the plains. Beyond the physical destruction, the commotion agitates the local wildlife, stirring the plains kodos into frenzy. By smashing the prospectors' tools at their own forges, the tauren hope to send a blunt message and stall the encroachment before lasting harm is done.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_746-97bd816a56cc8901aeb4/1-0000.mp3", duration = 60.2383673, start = 0},
  },
}
P.transport["quest:747"] = {
  hash = "68d457",
  fullHash = "68d457",
  text = "The Hunt Begins. The Hunt Begins is a foundational rite of passage for young adventurers in Camp Narache on Red Cloud Mesa. Tasked by Grull Hawkwind, initiates are sent to hunt local plainstriders to provide meat and feathers for the village. Fulfilling this task marks the first step toward earning the respect of Chief Hawkwind and eventually gaining entry into Thunder Bluff. On the heights of Red Cloud Mesa, survival and tradition intertwine. The tauren hunt out of necessity to feed and clothe their people, while also viewing the stalk and chase as a vital test of discipline and sport. When the stores of Camp Narache run lean, the community looks to its rising youth to gather fresh plainstrider meat for cooking and sturdy feathers for tribal garments. No aspiring hero simply walks off Red Cloud Mesa into the wider reaches of Mulgore without proving their worth. Grull Hawkwind serves as a primary judge of character for the newcomers, insisting that one must prove their capability before stepping before his father, Chief Hawkwind. Bringing in a clean hunt demonstrates not only self-reliance, but devotion to supporting the tribe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_747-8b7d6c89133ab299601b/1-0000.mp3", duration = 63.764898, start = 0},
  },
}
P.transport["quest:748"] = {
  hash = "82b20c",
  fullHash = "82b20c",
  text = "Poison Water. Poison Water begins the tauren effort to purge pollution from Mulgore's sacred wells. Entrusted by Mull Thunderhorn in Bloodhoof Village, young Horde defenders gather natural components from the plains to craft a restorative ritual totem. The grassy plains of Mulgore are sacred ground to the tauren, but insidious forces have begun threatening their vital lifeblood. Mull Thunderhorn, an elder stationed in Bloodhoof Village, discovers that goblin interlopers and their lackeys have tainted the precious water wells that sustain the tribes and the local wildlife. The pollution strikes directly at the spiritual heart of the nomadic people who recently settled here. To counteract industrial contaminants, Mull relies on traditional tauren shamanism rather than crude remedies. Cleansing the Winterhoof Water Well requires crafting a potent ritual totem imbued with the vitality of Mulgore's indigenous predators. He sends hunters to track prairie wolves for their paws and mature plainstriders for their talons across the southwestern plains, enlisting the strength of the land to heal its own wounds.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_748-6572a46dd1651a433b1c/1-0000.mp3", duration = 60.5518367, start = 0},
  },
}
P.transport["quest:7493"] = {
  hash = "f7e266",
  fullHash = "f7e266",
  text = "The Journey Has Just Begun. After Onyxia's fall, skilled leatherworkers in Orgrimmar learn how her scales can guard against the black dragonflight. Overlord Runthak recognizes their craft and teaches a rare technique for making protective cloaks, needed against the flames of Blackrock Spire. Onyxia's fall is a triumph for the Horde, yet the black dragonflight remains a threat. The broodmother's scaled hide resists draconic flame. Horde leaders seek craftsmen who can turn the dragon's remains into defensive armor rather than let them go to waste.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7493-67f69e0ffdd84fc85295/1-0000.mp3", duration = 30.1714286, start = 0},
  },
}
P.transport["quest:7497"] = {
  hash = "284d81",
  fullHash = "284d81",
  text = "The Journey Has Just Begun. In Stormwind, Major Mattingly recognizes the artisan who brought down Onyxia. He teaches the craft needed to make a cloak from her scales. Few who helped bring down Onyxia can also work her hide. When an artisan with master leatherworking reports to Major Mattingly in Stormwind, the officer recognizes how much those skills matter in the battles ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7497-9a97da6f9fa478703381/1-0000.mp3", duration = 20.5061224, start = 0},
  },
}
P.transport["quest:752"] = {
  hash = "65557e",
  fullHash = "65557e",
  text = "A Humble Task. A Humble Task is an early rite of duty given by Chief Hawkwind in Camp Narache. As the Chieftain attends to pressing tribal concerns on the Red Cloud Mesa, he asks a young adventurer to venture southeast and check on his elderly mother at the local water well. The request emphasizes communal responsibility, elder reverence, and the daily harmony essential to the tauren way of life. In the shadow of Camp Narache, every member of the tribe is expected to pull their weight and share in the harmony of life. For young tauren coming of age, tribal duty is not measured solely in battle prowess against quilboars or predators; it begins with basic social responsibility. Chief Hawkwind demonstrates this ethos directly: bound to his post by administrative and defensive leadership, he places his trust in novice adventurers to watch over the community's vulnerable elders. Mulgore's Red Cloud Mesa relies on vital natural water wells scattered beyond the perimeter of the encampment. Early in the morning, Greatmother Hawkwind left the village unattended to retrieve fresh water from the southeastern spring. In a land stalked by territorial wildlife and encroaching Bristleback quilboars, an elder remaining absent for hours raises quiet concern, prompting Hawkwind to send aid to ensure she is unharmed.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_752-ab57da4d9e90d4209cb9/1-0000.mp3", duration = 73.9787755, start = 0},
  },
}
P.transport["quest:753"] = {
  hash = "038dfa",
  fullHash = "038dfa",
  text = "A Humble Task. A Humble Task is an introductory rite of service in Red Cloud Mesa, where an elder tests a fledgling adventurer's humility and diligence. By carrying fresh well water across the plains to Camp Narache's leader, young tauren learn that serving their people starts with the simplest duties. Greatmother Hawkwind has walked many trails in her long life, and while her spirit remains steady, her legs no longer carry her across the plains with the speed of her youth. Stationed near the water well on the southern edges of Red Cloud Mesa, she tends to her responsibilities with patient resolve. When aspiring tribal defenders cross her path, she redirects their youthful energy toward practical community needs, offering them a chance to prove their worth through service rather than violence. The task asks the initiate to haul a filled water pitcher back northwest to Camp Narache and present it directly to the settlement's leader, Chief Hawkwind, who happens to be the Greatmother's son. In tauren society, survival across the arid plains of Mulgore demands shared labor and reliable supplies of fresh water. Demonstrating respect for the community's elders by shouldering their burdens is considered the cornerstone of becoming a true protector of the tribe. Chief Hawkwind sees more than a mere chore completed when a young wanderer arrives bearing water from his mother. In tauren custom, an individual's readiness to champion their people across wider lands begins with humility and an unprompted willingness to help. By demonstrating this quiet discipline, the initiate catches the chief's eye and earns recommendation for the ancient Rites of the Earthmother, the true spiritual tests that open the gates to Thunder Bluff.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_753-ef38d31d01b6cd36a7f4/1-0000.mp3", duration = 95.6342857, start = 0},
  },
}
P.transport["quest:754"] = {
  hash = "b0ab77",
  fullHash = "b0ab77",
  text = "Winterhoof Cleansing. Winterhoof Cleansing is a rite entrusted to Horde adventurers by Mull Thunderhorn in Bloodhoof Village. After goblin operations fouled the local springs, a consecrated totem must be carried into the Venture Company's territory to purify the Winterhoof Water Well. Restoring this spring is a vital first step in healing the poisoned waters of central Mulgore. The grassy plains of Mulgore rely on a delicate network of ancestral water wells to sustain both wild game and the scattered tauren tribes. Recently, ruthless industrial mercenaries of the Venture Company moved into the rolling hills southeast of Bloodhoof Village. Their operations have contaminated the local aquifers, leaving the Winterhoof Water Well rank and toxic. Wild beasts shun the tainted water, and the nearby camps face an impending crisis if the corruption spreads further through the earth. To counter the industrial filth, Mull Thunderhorn carves and enchants a ritual cleansing totem infused with the blessings of the Earth Mother. However, delivering this remedy requires braving armed Venture Company goons who have staked their claim over the spring. By placing the totem directly at the wellhead, an adventurer dispels the foul runoff, allowing clean, life-giving water to rise once more from the depths of the earth.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_754-fe071bce4933de051e33/1-0000.mp3", duration = 72.0718367, start = 0},
  },
}
P.transport["quest:756"] = {
  hash = "f9e3ba",
  fullHash = "f9e3ba",
  text = "Thunderhorn Totem. Thunderhorn Totem is a task given by Mull Thunderhorn in Bloodhoof Village to craft a sacred cleansing totem. To combat goblin-borne pollution spreading through Mulgore's water wells, young Horde champions must gather natural talons from plains predators to bind the land's primal strength into ritual wood. As the Venture Company's industrial exploitation poisons Mulgore's precious water sources, Mull Thunderhorn works urgently to craft remedies. Creating the Thunderhorn Cleansing Totem requires the natural essences of the plains' most focused hunters: prairie stalkers and flatland cougars. By taking the claws of these predators roaming east and west of Bloodhoof Village, the ritual channels the raw, uncorrupted predatory vigor of the wildlife directly into the totem. Tauren tradition sees a profound distinction between hunting for sustenance or spiritual balance and the wholesale plunder practiced by the goblins. Mull emphasizes that the purity with which native predators hunt is vital for purifying corrupted earth. Where goblin machinery defiles the springs with oil and industrial waste, the natural strength of the beasts contending with the land provides the spiritual catalyst needed to restore the Thunderhorn Water Well.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_756-7e61cdabfefb5da87e39/1-0000.mp3", duration = 69.4334694, start = 0},
  },
}
P.transport["quest:757"] = {
  hash = "1e6fd1",
  fullHash = "1e6fd1",
  text = "Rite of Strength. The Rite of Strength is the initial trial in the traditional Rites of the Earthmother undertaken by young tauren at Camp Narache. To demonstrate their bravery and defense of the tribe, initiates must cull encroaching Bristleback quilboar in Brambleblade Ravine and present their belts to Chief Hawkwind. For a young tauren seeking recognition from tribal elders and eventual acceptance in Thunder Bluff, completing the Rites of the Earthmother is an essential duty. Bestowed by Seer Graytongue, the Rite of Strength serves as the starting trial. It demands physical courage and decisive action in defense of Red Cloud Mesa, testing whether an initiate can face the tribe's mortal foes without flinching. The chosen crucible for this trial is Brambleblade Ravine, a thorn-choked gash east of Camp Narache occupied by Bristleback quilboar. These aggressive interlopers continuously trespass on ancestral lands, ambushing hunting parties and raiding camp supplies under cover of darkness. Slaying them and claiming their belts serves as both proof of valor and a necessary measure to keep the settlement secure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_757-5c4606219ee2786f07a3/1-0000.mp3", duration = 61.5967347, start = 0},
  },
}
P.transport["quest:758"] = {
  hash = "9f51ab",
  fullHash = "9f51ab",
  text = "Thunderhorn Cleansing. Thunderhorn Cleansing is an essential spiritual rite in Mulgore, charging travelers with purifying the corrupted Thunderhorn Water Well. Armed with a ritual totem prepared by Mull Thunderhorn, adventurers restore the contaminated spring vital to the local tribe. Successful purification earns the heartfelt approval of the Thunderhorn ancestors. Water wells across the sweeping plains of Mulgore are vital lifelines for the tauren nomadic tribes who recently settled the grasslands. When foul poisons taint these underground springs, both wildlife and nearby settlements face devastating consequences. The Thunderhorn Water Well, situated north of Bloodhoof Village, fallen victim to contamination, requires deliberate spiritual intervention to heal the troubled land. To counteract the corruption, Mull Thunderhorn crafts a consecrated Cleansing Totem imbued with spiritual potency. Carrying this relic directly to the poisoned waters allows adventurers to channel ancestral power into the spring, dispersing the toxins and restoring pristine natural balance. Mull receives direct confirmation of the deed's success when the spirits of Thunderhorn ancestors visit him in a dream to express their enduring gratitude.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_758-bafadfc238c451d8b089/1-0000.mp3", duration = 68.3102041, start = 0},
  },
}
P.transport["quest:759"] = {
  hash = "befac9",
  fullHash = "befac9",
  text = "Wildmane Totem. Wildmane Totem represents the third and final stage in Mull Thunderhorn's efforts to craft cleansing totems for Mulgore's poisoned wells. To restore the Wildmane Well, the ritual demands offerings taken from the territory's fiercest natural predators: prairie wolf alphas. After securing the materials required to consecrate totems for the Winterhoof and Thunderhorn wells, only one afflicted source remains in central Mulgore: the Wildmane Well. The poisoned water across the plains threatens both migrating wildlife and settlements, demanding powerful primal ingredients to restore the earth's natural balance. To counter the potent corruption lingering in the northern waters, Mull Thunderhorn requires a sacrifice of ferocity. Prairie wolf alphas prowl the grasslands, particularly around the towering bluffs beneath Thunder Bluff. Harvesting their teeth channels the relentless drive and resilience of Mulgore's apex hunters directly into the crafting of the cleansing totem. In tauren spiritual tradition, drawing upon the land's creatures carries emotional and elemental weight. Mull views the gathering of alpha teeth not as conquest, but as a somber necessity where the sacrifice of Mulgore's predators helps heal the Earth Mother's stricken waters.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_759-4670828580355810a96c/1-0000.mp3", duration = 69.0416327, start = 0},
  },
}
P.transport["quest:76"] = {
  hash = "39fe90",
  fullHash = "39fe90",
  text = "The Jasperlode Mine. Kobolds have overrun the Jasperlode Mine in eastern Elwynn. Marshal Dughan sends scouts to learn how far the infestation has spread. After kobolds swarmed the Fargodeep tunnels south of Goldshire, Marshal Dughan feared they had reached other mines. Jasperlode lies in the rocky foothills northeast of the Tower of Azora and supplies raw stone and metal to the kingdom. Dughan cannot spare Stormwind guards from their town patrols, so he sends independent adventurers east to see whether kobolds have taken this mine too. Scouts who reach Jasperlode's chambers find kobolds have driven out the human miners and fortified the dark passages. Marshal Dughan faces another blow as the crisis grows. King Varian Wrynn is missing, and royal troops are withheld from outlying territories. The local garrison has too few soldiers to clear the mines, leaving the kingdom's heart short of minerals and hemmed in by threats.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_76-788b822c0d60288c3638/1-0000.mp3", duration = 54.2302041, start = 0},
  },
}
P.transport["quest:760"] = {
  hash = "fae83a",
  fullHash = "fae83a",
  text = "Wildmane Cleansing. Wildmane Cleansing marks the culmination of the tauren ritual efforts to purify the vital watering holes of Mulgore. Entrusted by Mull Thunderhorn in Bloodhoof Village, heroes take the completed Wildmane Totem north to cleanse the final poisoned well. Driving back goblin pollutants restores balance to the plains and secures the pastoral livelihood of the tauren tribes. Water is sacred lifeblood across the sun-drenched plains of Mulgore, sustaining the herds, the soil, and the nomadic tribes who have recently gathered around Thunder Bluff. When the Venture Company and encroaching goblins began contaminating these aquifers with toxic industrial runoff, the tauren elders recognized an existential threat. Following the purification of the Winterhoof and Thunderhorn wells, the Wildmane Water Well stands as the third and final corrupted site requiring spiritual intervention. Crafted from specific elements gathered across the region, the Wildmane Cleansing Totem channels the restorative power of ancestral spirits and elemental earth. Planting the totem beside the foul waters north of Thunder Bluff disperses the foul chemicals, drawing out the toxins and reviving the natural flow. By completing the ritual, the tauren safeguard their people from disease and send an unmistakable message that the despoiling of their sacred ground will not be tolerated.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_760-189f4ad00291fa28e1db/1-0000.mp3", duration = 80.8489796, start = 0},
  },
}
P.transport["quest:763"] = {
  hash = "6a0535",
  fullHash = "6a0535",
  text = "Rites of the Earthmother. Rites of the Earthmother marks the transition of a young tauren out of the secluded Red Cloud Mesa and into the wider plains of Mulgore. Having proven your mettle in Camp Narache, Chief Hawkwind sends you north to Bloodhoof Village with a carved totem to continue the ancient trials under Baine Bloodhoof. For generations, young tauren have tested their strength within the safe cradle of Camp Narache on Red Cloud Mesa. Completing the initial trials proves one has the discipline and resolve to survive, but the sacred Rites of the Earthmother require far more than surviving local wildlife. Chief Hawkwind recognizes when an initiate has outgrown the mesa's sheltered hunting grounds and must step into the broader community. To bridge the journey between Narache and the central settlements, Chief Hawkwind provides a hand-carved totem as a mark of introduction. Bearing this emblem down the winding path to Bloodhoof Village, you present yourself to Baine Bloodhoof, the young chieftain of the village and son of High Chieftain Cairne Bloodhoof. The totem serves as testament to your readiness for the rites of spirit and wisdom that lie ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_763-2c0e0a819601df2000fc/1-0000.mp3", duration = 64.6269388, start = 0},
  },
}
P.transport["quest:764"] = {
  hash = "344720",
  fullHash = "344720",
  text = "The Venture Co.. Investigating a ravaged Venture Company caravan in Mulgore uncovers an aggressive buildup of Venture Company goblins digging into the eastern hills. Having had their formal requests for mining permits flatly rejected, the company chose to quarry the Earth Mother's soil anyway, prompting Morin Cloudstalker to commission a lethal response. The tauren of Mulgore revere the land as an extension of the Earth Mother, cherishing its pristine plains and balanced wildlife. When the Venture Company approached the tribes seeking rights to blast and excavate the rolling hills for raw ore, their petitions were categorically denied. Undeterred by tribal decrees or territorial sovereignty, the relentless cartel sneaked heavy machinery, laborers, and overseers directly into Mulgore's eastern ridges to mine illicitly. Tauren scouts like Morin Cloudstalker recognize that corporate greed cannot be reasoned with through diplomatic appeals once picks hit the stone. With documents recovered from a ravaged Venture Co. caravan confirming the company's mining operation, Morin dispatches Horde champions to cut down both the taskmasters cracking the whips and the laborers driving the drills. The bloody reprisal is intended to ensure the Venture Company calculates the cost of trespassing as far too steep.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_764-0c185fb4a049cf72f050/1-0000.mp3", duration = 70.2171429, start = 0},
  },
}
P.transport["quest:765"] = {
  hash = "5006da",
  fullHash = "5006da",
  text = "Supervisor Fizsprocket. Supervisor Fizsprocket is a high-ranking Venture Company overseer stationed within the mining tunnels of Mulgore. Charged by Morin Cloudstalker with putting an end to the goblin enterprise's calculated pillaging, Horde adventurers enter the mine to eliminate him and recover his detailed clipboard. Documents recovered from a destroyed Venture Company caravan revealed that the Venture Company was not merely digging for ore—they were deliberately formulating schemes to drive the tauren from Mulgore entirely. By uprooting the locals, the rapacious corporation sought unchecked freedom to strip the rolling hills and deep subterranean veins of every natural resource.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_765-a5ceda272e9b80ebf446/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["quest:766"] = {
  hash = "e6464c",
  fullHash = "e6464c",
  text = "Mazzranache. Maur Raincaller in Bloodhoof Village has fallen victim to a venomous bite from Mazzranache, a legendary plainstrider that terrorized his grandfather a generation ago. Struck by fever and delirious nightmares, the tauren requires a potent remedy brewed from Mulgore's wildlife before the infection claims his life. For years, Maur Raincaller regarded Mazzranache as little more than a harrowing family tale passed down by his grandfather. The elder tauren spoke of an unusually savage plainstrider armed with glowing red eyes, razor-sharp talons, and a toxic bite that defied the peaceful nature of most Mulgore wildlife. When Maur crossed paths with the beast out on the open grass, the legend proved all too real, leaving him severely wounded and struggling to make it back to safety. The creature's venom works swiftly, inducing high fevers and nightmarish delirium. To purge the venom before it turns fatal, traditional tauren medicine relies on the vitality of the local beasts. Maur requires a prairie wolf heart, a flatland cougar femur, a plainstrider scale, and a swoop gizzard. By combining the essences of these varied hunters and scavengers, he can brew a concoction capable of halting the necrotic spread and nursing him back to health.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_766-57deae6b686e95cad846/1-0000.mp3", duration = 71.4187755, start = 0},
  },
}
P.transport["quest:767"] = {
  hash = "f81981",
  fullHash = "f81981",
  text = "Rite of Vision. The Rite of Vision is a pivotal coming-of-age trial within the Rites of the Earthmother, testing a young adventurer's spiritual maturity. Initiated by Baine Bloodhoof, the quest directs aspirants to seek counsel from the village seer, Zarlman Two-Moons. Undertaking this journey is essential for anyone seeking the blessings and respect of the elders on the rises of Thunder Bluff. For generations, the nomadic tauren have turned to the Earthmother to guide their people across the plains of Kalimdor. Now gathered within the safe borders of Mulgore, their spiritual traditions remain the cornerstone of their society. The Rite of Vision is one of the ancient trials known as the Rites of the Earthmother. While earlier trials test an initiate's physical strength and connection to the hunt, the Rite of Vision demands an inward journey, directing young tauren and honored allies to commune directly with the spirits. Before any spiritual vision can be sought, an initiate must be prepared by someone steeped in ancient wisdom. In Bloodhoof Village, that responsibility falls to the revered shaman Zarlman Two-Moons. Entrusted by Baine Bloodhoof to prepare travelers, Zarlman possesses the keen sight to recognize those walking the path of the ancestors, offering the preliminary rites and sacred preparations necessary to pierce the veil of the physical world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_767-af8cfb9a248aa88cbbda/1-0000.mp3", duration = 76.1991837, start = 0},
  },
}
P.transport["quest:771"] = {
  hash = "34d871",
  fullHash = "34d871",
  text = "Rite of Vision. The Rite of Vision is a foundational spiritual trial undergone by young tauren stepping beyond the Red Cloud Mesa into greater Mulgore. To pierce the veil and receive guidance from ancestral spirits, initiates must gather natural reagents to brew the Water of the Seers under the watchful eye of Zarlman Two-Moons in Bloodhoof Village. Before any vision can be granted, the initiate must demonstrate an intimate understanding of the natural gifts found across Mulgore. Zarlman Two-Moons instructs the seeker to collect well stones found near the sacred communal water wells and ambercorn fallen beneath the roots of Mulgore's ancient trees. These natural elements are not merely physical objects; to the tauren, they hold the latent magic and lifeblood of the Earth Mother, ready to be channeled into ritual use. Once gathered, Zarlman combines the stones and ambercorn into the potent Water of the Seers. When consumed beside the village's tribal flame, this ceremonial draft clears the mind and summons an ethereal guide. Following this manifestation across the plains forms the true heart of the rite, testing the initiate's ability to walk between the physical world and the spiritual whispers of the land.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_771-1bbe163cd7b2e4307738/1-0000.mp3", duration = 69.355102, start = 0},
  },
}
P.transport["quest:772"] = {
  hash = "a87bd7",
  fullHash = "a87bd7",
  text = "Rite of Vision. The Rite of Vision is the spiritual climax of an ancient trial undertaken by young tauren in Bloodhoof Village. By drinking the sacred Water of the Seers beside the tribal bonfire, initiates summon a spectral guide to lead them toward their destiny. After gathering the necessary ritual herbs and passing the initial trials of faith, an initiate is granted the Water of the Seers by the village shaman, Zarlman Two-Moons. This potent draught must be ingested before the roaring tribal fire at the heart of Bloodhoof Village. When consumed with a focused and respectful mind, the sacred waters expand the drinker's perception beyond physical sight, bridging the veil between the material plane and the spiritual realm. Upon drinking the brew, the flames yield an ethereal apparition: an ancestral ghost wolf. The spirit does not speak or fight, but silently lopes northwest across the rolling plains of Mulgore. A true initiate must heed its quiet path, tracking its journey away from the village and deep into the rocky hills where the hermit Seer Wiserunner awaits in secluded meditation. Reaching Seer Wiserunner at the mouth of his mountain cavern signifies the successful completion of the vision. This journey across the grassy hills tests an initiate's patience, trust in ancestral guidance, and attunement to the Earth Mother. Passing this rite grants the young adventurer the right to undergo the ultimate test of adulthood: the Rite of Wisdom.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_772-4abe46a68bb707b5dfab/1-0000.mp3", duration = 84.2187755, start = 0},
  },
}
P.transport["quest:773"] = {
  hash = "76d7aa",
  fullHash = "76d7aa",
  text = "Rite of Wisdom. The Rite of Wisdom is the concluding trial in the traditional Rites of the Earthmother undertaken by young adventurers in Mulgore. After purifying their sight through the Rite of Vision, petitioners travel to the sacred burial grounds of Red Rocks to commune with an Ancestral Spirit and receive the blessing of the dead. Having cleared their perception through the Rite of Vision, young protectors are directed east of Thunder Bluff toward Red Rocks. This ancient burial ground holds the physical remains and lingering spirits of those who fought and died to carve out a peaceful existence in Mulgore. Passing the trial requires approaching the resting grounds with proper reverence and communion, facing whatever territorial threats roam the hills to seek the counsel of the honored dead. At the summit of Red Rocks, the communion with the Ancestral Spirit is not a test of martial strength, but of spiritual readiness and continuity. The spirits resting there represent the generation that fought alongside Cairne Bloodhoof to establish Thunder Bluff and safeguard the tribes. By receiving their blessing, the supplicant officially inherits the solemn duty of protecting the city, earning their place as a recognized adult and defender worthy of entering Thunder Bluff with pride.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_773-eebbc571531d77bb4b11/1-0000.mp3", duration = 70.5567347, start = 0},
  },
}
P.transport["quest:775"] = {
  hash = "3a9ab8",
  fullHash = "3a9ab8",
  text = "Journey into Thunder Bluff. Journey into Thunder Bluff is the culminating pilgrimage marking the end of a young hero's trials across Mulgore. Having completed the sacred Rites of the Earthmother under the guidance of the spirits, the adventurer is granted an audience with the High Chieftain of the tauren, Cairne Bloodhoof. Before any traveler or fledgling warrior can truly claim to have proven themselves in Mulgore, they must undergo the ancient Rites of the Earthmother. These trials test strength, vision, and wisdom across the rolling plains and ancestral sites of the land. Once the Ancestral Spirit acknowledges the final rite, the initiate is deemed worthy of entering the city of Thunder Bluff not as a mere visitor, but as an honored defender of the tauren people. The quest directs the traveler from the sacred ground where the spirits wander straight to the towering heights of Thunder Bluff. Perched atop the mesas, the city is a beacon of peace carved from red stone and supported by sweeping rope bridges and massive wooden elevators. There, on the High Rise, High Chieftain Cairne Bloodhoof awaits to personally greet those who have walked the path of the ancestors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_775-7e9904615bad9b9c4542/1-0000.mp3", duration = 62.484898, start = 0},
  },
}
P.transport["quest:776"] = {
  hash = "53b3bf",
  fullHash = "53b3bf",
  text = "Rites of the Earthmother. This trial, set directly by High Chieftain Cairne Bloodhoof, tasks rising heroes with hunting down the great kodo beast Arra'chea across the plains of Mulgore. Though an initiate may have completed the traditional rites of passage, Cairne expects his people to continually reaffirm their strength, tracking, and devotion to the tribe. Returning with Arra'chea's horn proves an adventurer is ready to serve the wider Horde beyond the mesas. Reaching Thunder Bluff marks the end of simple youth for a tauren, but High Chieftain Cairne Bloodhoof does not let young hunters rest on their laurels. To Cairne, earning a place among the high bluffs is merely the beginning of one's responsibility to the United Tauren Tribes. Rather than sending initiates against petty pests, he demands proof of real fieldcraft: the tracking and clean harvest of one of Mulgore's most renowned wandering beasts. The quarry is Arra'chea, a massive, legendary kodo whose looping trek winds across the golden grasses northeast of Thunder Bluff. To fell such a creature takes more than brute force; it demands patient stalking across the open savannah and respect for a titan of the plains. Bringing Arra'chea's horn back to the high rise earns not just personal glory, but provisions for the city, as Cairne immediately dispatches skinners and gatherers to ensure nothing of the sacred beast goes to waste.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_776-95eaafa87041d43f4014/1-0000.mp3", duration = 78.6285714, start = 0},
  },
}
P.transport["quest:7781"] = {
  hash = "01731d",
  fullHash = "01731d",
  text = "The Lord of Blackrock. Nefarian's severed head is bound for Stormwind Keep after his defeat in Blackwing Lair. Highlord Bolvar Fordragon receives the trophy, a sign that the master of Blackrock Mountain has fallen. The victory is among the Alliance's greatest military triumphs in recent history. Nefarian, brood-master of the Black Dragonflight and ruler of Upper Blackrock Spire, has long threatened the surrounding human kingdoms. His defeat ends his twisted experiments and schemes. Carrying his battle-scarred head back to Stormwind gives proof that the Lord of Blackrock has fallen to the Alliance's greatest heroes. Highlord Bolvar Fordragon governs the kingdom from the throne room of Stormwind Keep. The dragon's severed head shocks the royal court and commands reverence. With the kingdom strained by internal political strife and threats from beyond, the victory lifts morale and earns a place in Alliance history.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7781-51e86f32676255cb4ff0/1-0000.mp3", duration = 51.2261224, start = 0},
  },
}
P.transport["quest:7783"] = {
  hash = "f974d6",
  fullHash = "f974d6",
  text = "The Lord of Blackrock. Nefarian's severed head is carried from Blackrock Mountain to Orgrimmar as proof of victory. Presented to Warchief Thrall, it marks the fall of a great enemy of the Horde. Nefarian has fallen at last. He masterminded Blackwing Lair and led the black dragon brood in the Eastern Kingdoms. His colossal, battle-scarred head proves his death. For Horde warriors, carrying the prize from the burning heights of Blackrock Mountain across the Great Sea to Durotar brings great honor. The trophy is brought before Warchief Thrall. He knows the corruption of Blackrock Mountain well. He freed his people from the internment camps and led them away from the old Horde's demonic bloodlust. The son of Deathwing has fallen, and the Blackrock orcs are free of the dark dragon's cruel dominion.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7783-e25124405317a2bc29b0/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:7784"] = {
  hash = "dfae9b",
  fullHash = "dfae9b",
  text = "The Lord of Blackrock. In Orgrimmar, Nefarian's severed head is brought before the Horde. After Thrall confirms the black dragon's death, he sends the victor to High Overlord Saurfang in the Valley of Strength to show the trophy to all. Nefarian's head reaches Orgrimmar after the black dragon is slain atop Blackwing Lair. Warchief Thrall confirms that Deathwing's son has fallen, then sends the victor to High Overlord Saurfang in the Valley of Strength. There, the remains are prepared for public display, a warning to enemies and a rallying cry for the true Horde.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_7784-9d8f0d4bbc0b66b9d6e7/1-0000.mp3", duration = 32.4179592, start = 0},
  },
}
P.transport["quest:780"] = {
  hash = "31a0b6",
  fullHash = "31a0b6",
  text = "The Battleboars. The Battleboars is a rite-of-passage hunting quest given by Grull Hawkwind in Camp Narache. Young tauren are tasked with culling the vicious war-trained boars of Brambleblade Ravine to defend tribal lands and feed the settlement's youth. To the east of Red Cloud Mesa lies Brambleblade Ravine, a thorn-choked scar held by the Bristleback quilboar. As tensions between the Shu'halo and the quilboar escalate into open war, the Bristlebacks have trained vicious battleboars to probe tauren boundaries and terrorize their traditional hunting grounds. Left unchecked, these aggressive beasts threaten not only game trails but the safety of Camp Narache itself. For the tauren, hunting serves both defensive necessity and communal sustenance. Grull Hawkwind instructs initiates to bring back the snouts and flanks of the slain battleboars. Even beasts trained by quilboar hands are not wasted; their meat and gristle are harvested to prepare hearty stew for the tribe's youth, turning a quilboar weapon into nourishment for the next generation of tauren defenders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_780-9338f4581da95ece4609/1-0000.mp3", duration = 59.3502041, start = 0},
  },
}
P.transport["quest:781"] = {
  hash = "c4aafb",
  fullHash = "c4aafb",
  text = "Attack on Camp Narache. Attack on Camp Narache is a vital discovery made within the quilboar den of Brambleblade Ravine. A dirt-stained map reveals that the aggressive Bristleback tribe is actively plotting an organized siege against Camp Narache. Delivering these plans to Chief Hawkwind alerts Camp Narache in time to summon aid from Bloodhoof Village. While scouting deep inside the caverns of Brambleblade Ravine, young tauren adventurers uncover a crude, dirt-stained map laying on the rock floor. Upon closer inspection, the parchment reveals deliberate tactical markings made by the Bristleback quilboar. Rather than engaging in mere opportunistic skirmishes, the quilboar are coordinating a full-scale, prolonged siege against Camp Narache. Carrying the attack plans back to Camp Narache provides Chief Hawkwind with crucial intelligence. Recognizing the dire threat posed to the relatively undefended camp and its young initiates, Hawkwind prepares to send word to Bloodhoof Village for reinforcements. The intercepted map transforms what could have been a catastrophic ambush into a prepared defense.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_781-afdcd62e32867b09f4a3/1-0000.mp3", duration = 64.5485714, start = 0},
  },
}
P.transport["quest:783"] = {
  hash = "76e899",
  fullHash = "76e899",
  text = "A Threat Within. Volunteers are answering Stormwind's call in Northshire Valley, where local defenses need help. At Northshire Abbey, Marshal McBride explains that the kingdom's forces are spread thin abroad, leaving garrisons short-handed against trouble at home. Northshire Valley once offered quiet for prayer, farming, and monastic study. Now it is Elwynn Forest's first line of defense against unrest at home. Stormwind's regular forces serve on distant fronts, leaving the heartlands short of soldiers. With few guards nearby, the Stormwind Guard must call on every willing volunteer who reaches the abbey. Marshal McBride directs Northshire Valley's defenses from Northshire Abbey as pressures grow. Distant dangers threaten the Alliance, while bandits, vermin, and pests from below ground take advantage of the shortage of soldiers close to home. You answer the call to serve in the valley, starting with the ground around the abbey as threats spread across Elwynn.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_783-978264b1d22157a71936/1-0000.mp3", duration = 54.5697959, start = 0},
  },
}
P.transport["quest:784"] = {
  hash = "c2e056",
  fullHash = "c2e056",
  text = "Vanquish the Betrayers. At Tiragarde Keep, Kul Tiran forces hold a coastal foothold in Durotar. Gar'Thok has ordered a Horde strike against Lieutenant Benedict's garrison, whose presence breaks the fragile peace with Theramore. Thrall led the Horde across the Great Sea to Kalimdor, where he joined Lady Jaina Proudmoore against the Burning Legion at Mount Hyjal. Peace broke when Jaina's estranged father, Grand Admiral Daelin Proudmoore, brought Kul Tiras's navy to Durotar. He blamed all orcs for the Old Horde's atrocities and seized coastal footholds, including Tiragarde Keep. Daelin died at Theramore, but remnants of his fleet still refuse any pact or surrender their hatred. Tiragarde Keep fell briefly after the Grand Admiral's defeat, then Kul Tiras reserves under Lieutenant Benedict retook it. The fortress lies between Razor Hill and Sen'jin Village. From there, sailors and marines harass travelers and threaten Durotar's eastern sea approaches. Gar'Thok sees their position as an immediate danger to Durotar's security and calls on Horde warriors to strike at Benedict's command.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_784-3759adc51c0322bda4d7/1-0000.mp3", duration = 63.1902041, start = 0},
  },
}
P.transport["quest:786"] = {
  hash = "45a5da",
  fullHash = "45a5da",
  text = "Thwarting Kolkar Aggression. Lar Prowltusk has found invasion plans in Kolkar Crag, west of Sen'jin Village. The Kolkar centaurs plan to strike Durotar's settlements and Orgrimmar. Lar Prowltusk, a troll tracker scouting western Durotar, slipped into Kolkar Crag under cover of night. There he found the Kolkar centaurs planning more than scattered coastal raids. Three centaur leaders had divided the invasion plans among them, with attacks aimed at the Valley of Trials, Sen'jin Village, and the gates of Orgrimmar. You are sent into Kolkar Crag to destroy the three attack scrolls before the centaurs can strike. The dry canyons hold their camps, and each scroll belongs to a different leader. Lar Prowltusk believes the Horde would defeat a full invasion, but burning the plans can spare Durotar's defenders costly fighting while their young nation finds its footing.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_786-1ab9806f4c4ef87d3dd4/1-0000.mp3", duration = 50.1812245, start = 0},
  },
}
P.transport["quest:787"] = {
  hash = "ff07e5",
  fullHash = "ff07e5",
  text = "The New Horde. In the Valley of Trials, veteran warrior Eitrigg calls new recruits to the Den. He sends you to Gornek to begin training and shares why he returned to the Horde and what Thrall hopes it can become. Eitrigg stands in the Valley of Trials under Warchief Thrall's orders, ready to evaluate and mentor the Horde's newest hopefuls. After the Second War, he abandoned the Old Horde, disillusioned by its corruption by the Burning Legion. He lived in quiet exile until humans captured him. Thrall rescued Eitrigg, and the veteran chose to return after learning of the young Warchief's dream: an honorable Horde rooted in ancestral shamanism and entirely free of demonic masters. Before you venture beyond the harsh canyons of the Valley of Trials, Eitrigg sends you into the shaded cavern called the Den to speak with Gornek. Gornek rarely minces words about the crude state of new aspirants. His oversight ensures that only those who master discipline and survival enter the wider reaches of Durotar.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_787-f4dc172e16dd366d734e/1-0000.mp3", duration = 57.2865306, start = 0},
  },
}
P.transport["quest:791"] = {
  hash = "d1afde",
  fullHash = "d1afde",
  text = "Carry Your Weight. Atop the watchtower overlooking Razor Hill, Furl Scornbrow asks young Horde adventurers to gather canvas from human and centaur hostiles. Too old for the front lines, the scarred veteran will make supplies to aid their journey. Furl Scornbrow fought beside Warchief Thrall in Durotar and at Mount Hyjal. Age and old injuries have slowed the veteran, and he no longer wields his axe in battle. From the Razor Hill watchtower, Furl keeps a steady vigil and sounds the alarm against incursions. He supports the next generation of defenders from his post. As the Horde's grip on the region tightens, signal horn alerts grow less frequent, leaving Furl more hours to craft practical gear. Sturdy canvas is scarce in Durotar's arid canyons, but the Kul Tiran interlopers along the eastern shore and the nomadic Kolkar centaur roaming the plains carry it in abundance. Canvas scavenged from these hostile forces gives Furl cloth to stitch utility bags for active scouts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_791-cfb40c41b6f3397c7fc8/1-0000.mp3", duration = 56.084898, start = 0},
  },
}
P.transport["quest:792"] = {
  hash = "acdc3a",
  fullHash = "acdc3a",
  text = "Vile Familiars. In the Valley of Trials, Vile Familiars are creeping out of a nearby cavern. Zureetha Fargaze found a hidden Burning Blade coven while watching over the valley's trials. Recruits are sent to hunt the familiars spreading across Durotar's red earth. The Valley of Trials tests young orcs and Darkspear trolls in strength, discipline, and loyalty to Thrall's Horde. Its trials were meant to pit recruits against scorpids and boars, not demonic corruption. Yet a cave to the northeast shelters agents of the Burning Blade, who have formed a secret coven beneath the valley overseers' watch. Zureetha Fargaze, an instructor guiding newcomers near the Den, spotted the taint before it could overrun the canyon. Vile Familiars now pour from the cave mouth, hurling fire at anyone who wanders too close. Before the Horde can root out the masters in hiding, young recruits are sent to cut down these lesser servants and keep the valley secure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_792-0989e5dd3897c3b785bc/1-0000.mp3", duration = 53.2114286, start = 0},
  },
}
P.transport["quest:794"] = {
  hash = "cfca73",
  fullHash = "cfca73",
  text = "Burning Blade Medallion. Zureetha Fargaze sends young Horde initiates into the Burning Blade Coven cave in the Valley of Trials. They face a hidden cultist and seek a dark relic, the Burning Blade Medallion. Its presence points to demonic corruption taking root near the Horde. Young orcs and trolls face trials of combat and survival in the Valley of Trials, while a menace gathers nearby. The warlock Zureetha Fargaze senses through divination that the vile familiars on the northern bluffs are only the vanguard of a darker presence. Deep in a nearby cavern, the Burning Blade cult has made a hidden coven, where its followers practice dark arts and keep dangerous relics of demonic power.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_794-dd7057de74ad664143dd/1-0000.mp3", duration = 38.8179592, start = 0},
  },
}
P.transport["quest:8"] = {
  hash = "57b2dd",
  fullHash = "57b2dd",
  text = "A Rogue's Deal. A seemingly casual favor for Calvin Montague in Deathknell sends a traveler on the road to the Gallows' End Tavern in Brill. The errand involves ferrying a mysterious, unaddressed message to Innkeeper Renee under the guise of an ordinary courier run. Lounging amidst the solemn graves and ruined chapels of Deathknell, Calvin Montague presents himself as an exhausted fighter burdened by too many Scourge zombies and creeping spiders. Claiming he simply needs a hand delivering a message to Brill, he entrusts passing adventurers with an unmarked letter. His breezy demeanor and promise of generous coin make the task appear as nothing more than a harmless favor meant to point freshly awakened Forsaken toward the region's main town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8-0ffb519c96591c6b5a74/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["quest:804"] = {
  hash = "739bc7",
  fullHash = "739bc7",
  text = "Sarkoth. In the Valley of Trials, Hana'zua waits for help after Sarkoth's venom leaves him stranded. You have slain the scorpid that wounded him; now Gornek needs word at the Den so aid can reach the scout. Hana'zua, a Darkspear scout, lies stranded on the high bluffs of the Valley of Trials. Sarkoth's venom has left him too weak to descend the treacherous paths alone. You have avenged him by slaying the scorpid, but he still cannot cross the arid stones without help. A passing initiate must carry word down to the training encampment. Gornek waits at the Den for your report. Once he hears of Hana'zua's plight, he recognizes the danger from Sarkoth and organizes aid for the scout. Horde commanders honor those who set aside their own training to defend and rescue a fallen stranger. Such conduct proves an initiate's worth before they march into Durotar proper.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_804-8fc5da98b6763ac5f570/1-0000.mp3", duration = 52.5061224, start = 0},
  },
}
P.transport["quest:805"] = {
  hash = "789fbf",
  fullHash = "789fbf",
  text = "Report to Sen'jin Village. Zureetha Fargaze sends word from the Valley of Trials to Sen'jin Village. Burning Blade cultists have been active in the valley, and she asks young initiates to warn the Darkspear trolls. Master Gadrin tells them dark magic threatens the nearby Echo Isles. Young initiates leave the Valley of Trials after proving their combat mettle and recovering dark medallions from the Burning Blade Coven. Zureetha Fargaze sees that the demons in the sacred proving grounds are no isolated nuisance; they point to a blight spreading across Durotar. She sends the proven fighters east past the ravine's mouth, then south toward the coast, to warn the Darkspear tribe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_805-542c465bf4c45c756147/1-0000.mp3", duration = 37.6946939, start = 0},
  },
}
P.transport["quest:806"] = {
  hash = "ba460f",
  fullHash = "ba460f",
  text = "Dark Storms. In Durotar, Burning Blade cultists corrupt the land from Thunder Ridge. Orgnil Soulscar in Razor Hill has learned that the goblin warlock Fizzle Darkstorm leads them, and asks you to end his threat. Orgnil Soulscar has learned that dark magic has taken hold in Thunder Ridge, northwest of Razor Hill. Burning Blade cultists prowl the ravine while young Horde defenders patrol Durotar’s borders. Their presence brings ruin to the wildlife and land. Fizzle Darkstorm, a goblin warlock allied with the Burning Blade, directs the cultists in Thunder Ridge. He wields fel power for the cult rather than serving commerce or cartel interests. Slaying him and bringing back his twisted claw will show Orgnil that the cult’s leaders in the ravine have been struck down.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_806-00de9ba8719f05eeb64b/1-0000.mp3", duration = 43.9379592, start = 0},
  },
}
P.transport["quest:808"] = {
  hash = "d1d5a3",
  fullHash = "d1d5a3",
  text = "Minshina's Skull. In Sen'jin Village, Master Gadrin hears the desperate cries of his dead brother, Minshina. Zalazane slew Minshina on the Echo Isles and bound his soul with dark magic to his own severed skull. To free him from torment, you must reclaim the skull from Zalazane's ritual grounds. Master Gadrin is one of the Darkspear tribe's spiritual anchors in Sen'jin Village, yet dark visions torment him. His brother Minshina fell when Zalazane betrayed the tribe and seized control of the Echo Isles. Minshina died in the conflict, but death has brought him no peace. In troll tradition and voodoo mysticism, the body can die while the spirit remains bound. Now Minshina's tormented voice reaches Gadrin in his dreams, pleading to be saved from a fate worse than death. Zalazane does more than kill his former brethren; he traps their souls to fuel his dark sorcery. He bound Minshina's spirit to his own skull, now set within a blasphemous circle of power on the largest of the Echo Isles. Hexed trolls guard the circle, where candles burn through the rites and the skull focuses Zalazane's twisted mojo. While it remains there, Minshina is captive to the witch doctor's will.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_808-5e1adaf8768614fdaae9/1-0000.mp3", duration = 72.3069388, start = 0},
  },
}
P.transport["quest:809"] = {
  hash = "d21309",
  fullHash = "d21309",
  text = "Ak'Zeloth. Neeru Fireblade sends you from Orgrimmar into the Barrens after signs of demonic corruption emerge. His contact waits near the border. Neeru Fireblade says the Burning Blade still threatens the Horde with demonic corruption. After you bring him a Burning Blade insignia collar from Durotar, he sends you into the Barrens. A cult gathers around the Demon Seed, an artifact of vile power, and Neeru wants you to find his contact near the border.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_809-2b5045ebe7d703422d34/1-0000.mp3", duration = 26.5926531, start = 0},
  },
}
P.transport["quest:812"] = {
  hash = "84fb0f",
  fullHash = "84fb0f",
  text = "Need for a Cure. Rhinag lies poisoned on Durotar’s northwestern cliffs, far from the cure he needs. The Darkspear troll has little time before the venom kills him, so he sends a passing courier to Orgrimmar for Kor'ghan’s remedy. Rhinag was fighting venomtail scorpids near Durotar’s border when one stung him. Their venom can kill in less than an hour. The poison keeps him from walking to Orgrimmar, so his survival depends on a traveler reaching his remote camp in time. Rhinag sends travelers beneath Orgrimmar to the Cleft of Shadow, where Kor'ghan knows how to counter the poisons of Durotar’s wastes. Kor'ghan can brew a cure, though he rarely helps those who have not proved themselves.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_812-f781550dc24fcd57f2fc/1-0000.mp3", duration = 39.68, start = 0},
  },
}
P.transport["quest:813"] = {
  hash = "daac39",
  fullHash = "daac39",
  text = "Finding the Antidote. Kor'ghan in Orgrimmar races to brew a cure for the poisoned hunter Rhinag. You gather venomtail poison sacs from scorpids outside the city walls before their venom proves fatal. Durotar's wildlife is unforgiving, and survival depends on wilderness preparation. Rhinag, a Darkspear troll, was hunting in Durotar when he faced venomtail scorpids without an antidote. Their potent venom struck quickly, leaving him in need of immediate aid. Kor'ghan, an experienced hunter in Orgrimmar, must mix a draught before the poison kills him. Mature venomtail scorpids outside Orgrimmar's gates carry the sacs Kor'ghan needs to make an antidote. He says there will be time to chastise Rhinag for going unprepared, but every moment matters now. Bring the sacs back into the city, and Kor'ghan can brew the draught for the dying hunter.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_813-f84851998a7026c3f2e7/1-0000.mp3", duration = 49.2930612, start = 0},
  },
}
P.transport["quest:816"] = {
  hash = "c65925",
  fullHash = "c65925",
  text = "Lost But Not Forgotten. Misha Tor'kren waits at her homestead for news of her son, Kron. He went west to hunt crocolisks along the Southfury River, and she fears the worst. Misha Tor'kren lives at a farmstead northwest of Razor Hill in Durotar. Days ago, her son Kron set out west toward the Southfury River, along the Barrens border, to hunt its fierce crocolisks. Misha warned him how deadly the beasts were, but pride drove him to leave and prove his strength. No one has seen him since.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_816-37fc8c71aa2621e745de/1-0000.mp3", duration = 29.4661224, start = 0},
  },
}
P.transport["quest:817"] = {
  hash = "f0ee52",
  fullHash = "f0ee52",
  text = "Practical Prey. Vel'rin Fang needs hunters to bring tiger hides from the Echo Isles to Sen'jin Village. The Darkspear need the supplies as their numbers grow and their stores run low. The Darkspear in Sen'jin Village have to make every resource last along Durotar's harsh coast. Tiger pelts can be made into tents, blankets and armor. As refugees arrive and scouts return, the village's stores have thinned, and leatherworker Vel'rin Fang has sent hunters out for more hides. The Darkspear leave the tigers of Durotar largely undisturbed, hunting them only when the tribe needs more supplies. Hunters cross the water to the Echo Isles to track the predators. For the trolls, the hunt also tests patience, discipline and skill in the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_817-8c7d862ccd35355c357b/1-0000.mp3", duration = 42.004898, start = 0},
  },
}
P.transport["quest:818"] = {
  hash = "de2886",
  fullHash = "de2886",
  text = "A Solvent Spirit. Master Vornal tests would-be pupils in Sen'jin Village as his eyesight fades. He asks them to gather makrura eyes and crawler mucus along Durotar's coast. Though he scoffs at taking an apprentice, the work tests patience and resolve. Master Vornal lives in Sen'jin Village, where age has dimmed his sight. Primal magic once came readily to his fingertips, but now he relies on alchemy to sharpen his perceptions and weave his arts. Though his body weakens, the stubborn troll refuses an apprentice. He says neither the Darkspear nor Durotar's orcs have produced anyone worthy of his teaching. Vornal asks for raw materials from the harsh coast: intact makrura eyes and vials of crawler mucus. Taking undamaged eyes from armored, snapping makrura calls for careful strikes. Gathering enough mucus tests whether a would-be pupil can endure tedious work. For Vornal, hunting these coastal beasts is less about the reagents than finding out who can keep their focus. For Master Vornal, time and patience measure strength. He expects brash youths to grow frustrated or abandon the work. Bringing pristine ingredients back to Sen'jin Village shows survival skills along the dangerous reefs of the Echo Isles channel, and the discipline needed to master alchemy's subtle arts.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_818-fda79ecf31ed6a6babc9/1-0000.mp3", duration = 74.7102041, start = 0},
  },
}
P.transport["quest:819"] = {
  hash = "8d9072",
  fullHash = "8d9072",
  text = "Chen's Empty Keg. A keg bearing Chen Stormstout’s mark lies abandoned in the Barrens. Its discovery points toward the wandering brewmaster’s old ties to Durotar. Travelers sometimes find an abandoned wooden barrel across the dry Barrens. Razormane quilboar and Kolkar centaur leave ordinary casks behind, but this barrel is carefully made and bears a plaque: “Chen Stormstout - May your spirit be raised and always raise your spirits.” It is an odd relic beneath Kalimdor’s sun. To learn how it came to the Barrens, you seek someone who knows brewing. Brewmaster Drohn in Ratchet recognizes the keg’s craftsmanship and names Chen Stormstout as its owner. Chen, a wandering Pandaren, traveled with Rexxar during the battles that secured Durotar for Thrall’s Horde. Years have passed since Chen walked Kalimdor’s red earth, yet seasoned brewers still remember his recipes and wandering spirit.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_819-48fc3ec8de895e2f1619/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["quest:821"] = {
  hash = "4476c3",
  fullHash = "4476c3",
  text = "Chen's Empty Keg. In Ratchet, Brewmaster Drohn hopes to revive Chen Stormstout's potent brew with wild ingredients from the Barrens. A marked keg brings Chen Stormstout to mind for Brewmaster Drohn in Ratchet. Chen passed the secrets of his namesake brew to Drohn's mentor, who entrusted them to Drohn. The recipe calls for raw, potent elements taken straight from the Barrens' fierce wildlife, an unusual choice to those outside the brewing trade.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_821-1c9f2e5089be991e43f4/1-0000.mp3", duration = 26.2008163, start = 0},
  },
}
P.transport["quest:823"] = {
  hash = "cbe721",
  fullHash = "cbe721",
  text = "Report to Orgnil. Master Gadrin sends word from Sen'jin Village to Razor Hill about the Burning Blade. This early Horde dispatch carries a warning of demonic corruption spreading through Durotar. Sen'jin Village faces its own troubles, especially Zalazane's treachery on the Echo Isles. Yet reports of the Burning Blade point to a danger far wider than the village's local woes. Demonic corruption was uncovered in the Valley of Trials, and Master Gadrin knows the threat cannot be met in isolation. He sends you north along the road to Razor Hill, where orc authorities watch over Durotar. Orgnil Soulscar is stationed at Razor Hill's military encampment, charged with rooting out evils within Durotar and guarding its central lands. When you bring Gadrin's warning, Orgnil combines reports from Sen'jin Village and the Valley of Trials. The Burning Blade's reach is dangerously close, so he quickly mobilizes forces to break up the cultists before their rituals can unseat the young nation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_823-85fb3dc3ee3a3acc70eb/1-0000.mp3", duration = 57.8612245, start = 0},
  },
}
P.transport["quest:825"] = {
  hash = "4c1111",
  fullHash = "4c1111",
  text = "From The Wreckage..... Gar'Thok sends Horde scouts to the wrecks off the Scuttle Coast for Gnomish Tools. The Horde hopes to study Alliance engineering and turn its advantage to their own use. Grand Admiral Daelin Proudmoore brought Kul Tiras's fleet to Kalimdor, where its ships crowded the shore near Tiragarde Keep. After his defeat, broken hulls sank along the Scuttle Coast. Kul Tiran soldiers who survived fortify the keep, while the fleet's wreckage lies scattered on the shoals beneath the tide. The Horde knows Alliance ingenuity can give its enemies an edge over orcish strength, iron, and blood. Gnomish technicians sailed with the expeditionary fleet and equipped its ships with complex machinery and precise tools. Gar'Thok wants those tools recovered from the wrecks so the Horde can learn how they work. Gar'Thok sends the salvaged tools by caravan from Razor Hill to Orgrimmar. Horde craftspeople and tacticians hope to study the gnomish instruments and better counter Alliance devices in future conflicts, while strengthening their own industries.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_825-d8843b8f97e69ebbd4db/1-0000.mp3", duration = 56.0065306, start = 0},
  },
}
P.transport["quest:826"] = {
  hash = "ef10dd",
  fullHash = "ef10dd",
  text = "Zalazane. On the Echo Isles, Zalazane's treachery has driven the Darkspear from their home. Master Gadrin of Sen'jin Village sends Horde champions to end the witch doctor's rule. Dark magic drove Zalazane mad, and he enslaved his fellow tribesmen, seizing the Darkspear trolls' rightful home and forcing them into exile on Durotar's coast. The Darkspear made a home on the Echo Isles after fleeing their sunken island and following Thrall across the Great Sea. The isles lie just off Durotar's southeast coast. Zalazane, once a respected and powerful witch doctor of the tribe, hungered for power. He used hexes to enslave the minds of his kin and began a violent uprising. Vol'jin led the Darkspear who remained free, but they were driven from their ancestral camps across the water. They had to build a temporary refuge at Sen'jin Village. Zalazane still sends raiding parties from his hilltop stronghold on the largest Echo Isle. They cross the channel to seize more Darkspear and drag them under his control. The captured trolls become mindless voodoo and hexed thralls, lost to their tribe. Master Gadrin sees more than an occupation of Darkspear land: Zalazane threatens the tribe's survival. Until his severed head is brought before the elders, no Darkspear can be safe.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_826-8931f1c7f8f3bfecba34/1-0000.mp3", duration = 75.2065306, start = 0},
  },
}
P.transport["quest:827"] = {
  hash = "6ebbeb",
  fullHash = "6ebbeb",
  text = "Skull Rock. Margoz sends you into Skull Rock, east of Orgrimmar. Burning Blade cultists have overrun the cave and use painful demonic devices to bind themselves to dark magic. Margoz needs the cursed artifacts to study the cult's presence near the capital. In northeastern Durotar, cultists gather close to Orgrimmar's gates. The cave lies among the hills, far from the open roads, yet near the Warchief's seat. The Burning Blade, a demonic cult that has long plagued orcish society, has made its home in the tunnels. Its followers perform rituals there while the Warchief's scouts watch nearby. Burning Blade cultists wear Searing Collars around their necks, metal bands that scorch and brand their flesh. Margoz believes the pain and fel sorcery in the collars attune their wearers to demonic power. He asks you to recover the collars so he can study the spells and bindings that empower the cultists.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_827-261a5b97abc8a8f593d6/1-0000.mp3", duration = 52.6628571, start = 0},
  },
}
P.transport["quest:828"] = {
  hash = "865ee3",
  fullHash = "865ee3",
  text = "Margoz. In northern Durotar, Margoz watches for the Burning Blade's growing threat. After the clash with fel corruption at Thunder Ridge, Orgnil Soulscar sends champions to seek the isolated orc shaman before they strike a nearby cultist stronghold. Margoz's counsel reveals Skull Rock, the Burning Blade's concealed cavern base. After Thunder Ridge revealed the depth of fel taint, Orgnil Soulscar sees that strength alone cannot cleanse Durotar. He sends champions to Margoz, an experienced orc shaman keeping a lonely camp in the crags northeast of Razor Hill. Between Drygulch Ravine and the eastern sea, Margoz watches the northern reaches for dark omens that Orgrimmar's busy warriors often miss. Margoz knows the Burning Blade's power base in northern Durotar: Skull Rock, a concealed cavern system carved into the mountain cliffs outside Orgrimmar's southern gates. The cultists are closer to Thrall's capital than the Warchief's guards realize, and Skull Rock's hidden passages can conceal a demonic ambush. Margoz gives those sent against the coven counsel so they do not enter blindly.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_828-d856950bdcf6a0f9e9f8/1-0000.mp3", duration = 64.3918367, start = 0},
  },
}
P.transport["quest:829"] = {
  hash = "4bd3a9",
  fullHash = "4bd3a9",
  text = "Neeru Fireblade. In Orgrimmar, Neeru Fireblade studies dark arts he says can protect the Horde. Margoz sends you from Durotar with a Searing Collar taken from the Burning Blade cult, hoping the warlock can explain its demonic power. Margoz has found the limit of shamanic arts. The collars taken from Burning Blade cultists at Skull Rock carry demonic sorcery, beyond what he can unravel. Shamans draw on the elements and ancestral spirits, so Margoz sends you to a warlock in the capital to learn what the collars do. Orgrimmar's Cleft of Shadow lies beneath its red cliffs. Warlocks and other practitioners of forbidden magic work there under Thrall's wary eye. Neeru Fireblade lives in the cavern and says he studies fel power to thwart demonic threats. When you bring him the collar, his curiosity turns Durotar's investigation toward the warlock enclave.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_829-2577b1638b017d1412c9/1-0000.mp3", duration = 50.4163265, start = 0},
  },
}
P.transport["quest:83"] = {
  hash = "67f861",
  fullHash = "67f861",
  text = "Red Linen Goods. At Eastvale Logging Camp, Sara Timberlain needs cloth for her tailoring. She asks passing adventurers to hunt Defias bandits and take their linen bandanas, then uses the cloth to make goods for travelers. Defias bandits across Elwynn wear red linen bandanas. Their less organized kin in Northshire Valley make do with cheap burlap masks. For local craftsmen short on materials, the bandanas offer cloth they can use. Sara Timberlain works as a seamstress at Eastvale Logging Camp, near Elwynn's eastern border. She needs workable textiles for her trade, so she asks adventurers to thin the Defias camps scattered through the woods. The cloth keeps her tailoring supplied while the bandits' encroachment on the area is checked.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_83-5ad0955309b9229a8bea/1-0000.mp3", duration = 42.7363265, start = 0},
  },
}
P.transport["quest:830"] = {
  hash = "e3f930",
  fullHash = "e3f930",
  text = "The Admiral's Orders. Recovered from a locked strongbox atop Tiragarde Keep, these weathered papers bear the personal seal of the late Grand Admiral Daelin Proudmoore. The recovered orders reveal that the Kul Tiran human garrison along Durotar's coast is far more entrenched and organized than simple shipwreck survivors. Delivering them to Gar'Thok in Razor Hill exposes lingering military plans threatening the fledgling Orc nation. Hidden inside a heavy chest on the upper floors of Tiragarde Keep, an aged envelope survives under the watch of Lieutenant Benedict. Sealed with the crest of Grand Admiral Daelin Proudmoore, the parchment outlines direct naval commands issued during Kul Tiras's bloody invasion of Durotar. Even after the Grand Admiral fell at Theramore, his officers maintained their fortifications, clinging tightly to their mission to eradicate the Horde settlement.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_830-527227b1db2e042a1c0a/1-0000.mp3", duration = 48.5616327, start = 0},
  },
}
P.transport["quest:8311"] = {
  hash = "b563a1",
  fullHash = "b563a1",
  text = "Hallow's End Treats for Jesper!. Jesper lies sick in Stormwind during Hallow's End, longing for the treats and fun beyond the orphanage. Too ill to go out, he asks Alliance adventurers to gather sweets for him. Jesper stays in the orphanage in Stormwind's Cathedral Square, sick during Hallow's End. He cannot enjoy the childhood pleasure of gathering sweets across Azeroth, so he hopes passing adventurers will share the holiday spirit and collect treats for him. To bring Jesper the sweets he hopes for, you travel beyond Elwynn Forest. You visit the innkeepers of Stormwind, Ironforge, and Darnassus, along with the gnome exile Talvash del Kissel. Each asks you to perform before giving you a treat. You cluck like a chicken, dance, flex, or chug like a train, earning regional sweets such as Stormwind Nougat and Gnomeregan Gumdrops.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8311-3d30334b5889db990457/1-0000.mp3", duration = 46.9681633, start = 0},
  },
}
P.transport["quest:832"] = {
  hash = "64ebcb",
  fullHash = "64ebcb",
  text = "Burning Shadows. Recovered from the Burning Blade cultist Gazz'uz in the depths of Skull Rock, this mysterious glowing pendant whispers urgent warnings into the bearer's mind. The voice specifically threatens Gazz'uz with the wrath of Neeru Fireblade, an orc warlock residing in Orgrimmar. Upon slaying Gazz'uz deep within Skull Rock, an ominous pendant known as the Eye of Burning Shadow is retrieved from his remains. Rather than being an inert magical trinket, the stone vibrates with psychic communication. A demanding voice speaks directly into the mind of anyone holding it, demanding reports from Gazz'uz and warning him that his clandestine operations east of Orgrimmar have been compromised.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_832-bf79bf35f384019309ed/1-0000.mp3", duration = 38.8963265, start = 0},
  },
}
P.transport["quest:834"] = {
  hash = "629b1f",
  fullHash = "629b1f",
  text = "Winds in the Desert. A stolen supply caravan leaves Rezlak waiting in Durotar. Dustwind harpies ambushed it in Razorwind Canyon, scattering the construction materials among the cliffs. Rezlak came directly from Ratchet, sent by Chief Engineer Gazlowe to help the Horde build across Durotar. The harsh, barren land already makes fortification work hard. Now shipments keep vanishing before they reach the building sites, and without the cargo, work stops. The irritable goblin supervisor has nothing to build with. Dustwind harpies ambushed the latest supply run in Razorwind Canyon. They roost along the high ravines beside the road from Razor Hill to Orgrimmar, then swoop on passing wagons. These scavengers do not eat or destroy the freight. They hoard the crates and sacks near their nests, where the supplies remain for anyone willing to fight through their territory.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_834-3b57fbddd63d4c262bbd/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["quest:835"] = {
  hash = "150610",
  fullHash = "150610",
  text = "Securing the Lines. Near Razorwind Canyon, Rezlak needs the goblin supply routes through Durotar protected. Harpies in Drygulch Ravine keep intercepting and plundering caravans, so he hires help to drive them out. Dustwind harpies make travel through Durotar’s dry valleys dangerous. Rezlak watches over regional supply operations for his boss, Gazlowe. The harpies roosting in Drygulch Ravine raid caravans in Razorwind Canyon and seize shipments before they reach their destinations. Rezlak believes the right price can get anything done. Rather than enter the canyon himself, he hires adventurers to break the roost by eliminating Dustwind Savages and Dustwind Storm Witches. Clearing the harpies keeps trade corridors open, secures shipments of engineering gadgets, and points helpful travelers toward greater opportunities in Ratchet.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_835-675f548b5c3d9340d973/1-0000.mp3", duration = 48.7967347, start = 0},
  },
}
P.transport["quest:8356"] = {
  hash = "ab30c8",
  fullHash = "ab30c8",
  text = "Flexing for Nougat. During autumn's Hallow's End, you gather festive sweets for an orphan in Stormwind. Innkeeper Allison at the Gilded Rose asks you to flex before she gives you Stormwind Nougat. Hallow's End brings a lighter mood to Stormwind's streets. The holiday marks the turning of the seasons and wards off dark spirits. Common folk celebrate with disguises, revelry, and trick-or-treating. Alliance innkeepers join in, offering traditional sweets to those who perform a harmless trick. At the Gilded Rose in the Trade District, Innkeeper Allison asks for a show before handing out holiday candy, even when you're gathering sweets for Jesper, an orphaned boy. She comments playfully on your physique and asks you to flex your muscles. When you do, she gives you a piece of chewy Stormwind Nougat.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8356-90c1d22a6d1d61a333c3/1-0000.mp3", duration = 44.8, start = 0},
  },
}
P.transport["quest:8357"] = {
  hash = "9c01c9",
  fullHash = "9c01c9",
  text = "Dancing for Marzipan. During Hallow's End, travelers in Darnassus gather sweets for Jesper, a sick orphan in Stormwind. Innkeeper Saelienne keeps the trick-or-treat custom: a dance comes before her Darnassus Marzipan. Hallow's End brings a lighter spirit to Darnassus, the sacred forest city of the long-lived night elves. You come seeking sweets for Jesper, a sick child recovering in Stormwind. Innkeeper Saelienne keeps the season's custom, even when the treat is meant for a child in need. First, she asks for a trick. Saelienne asks you to dance on the inn floor before she gives you Darnassus Marzipan. The performance earns the sweet needed for the holiday care package bound for Jesper.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8357-beddc9d3338d1ec83e26/1-0000.mp3", duration = 40.4114286, start = 0},
  },
}
P.transport["quest:8359"] = {
  hash = "8ad2d7",
  fullHash = "8ad2d7",
  text = "Flexing for Nougat. In Orgrimmar, Innkeeper Gryshka offers nougat to those who play along. During Hallow's End, she asks you to flex for a piece meant to cheer Spoops, a bedridden child. Hallow's End brings pranks and sweet-gathering to Azeroth's capitals. In Orgrimmar's inn, Innkeeper Gryshka keeps holiday sweets for those who take part in the season's custom. You face dragons and dark sorcery in your travels, but here the bargain is simple: perform a trick or leave without a treat. Innkeeper Gryshka wants a display of Orcish strength before she gives you Orgrimmar Nougat for young Spoops. Whatever disguise or armor you wear, she asks you to strike a muscular pose. Even the Horde's feared combatants can be made to entertain the common folk for candy.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8359-d226ffe93fae8af05fad/1-0000.mp3", duration = 44.2514286, start = 0},
  },
}
P.transport["quest:84"] = {
  hash = "ecc078",
  fullHash = "ecc078",
  text = "Back to Billy. You carry Bernice Stonefield's freshly baked pie across the road to Billy Maclure, who has information about her missing necklace. The delivery continues the feud between the Stonefield and Maclure families in central Elwynn Forest. The old feud between the Stonefields and Maclures leaves little room for kindness. Auntie Bernice Stonefield baked a pork belly pie because Billy Maclure would not share what he knew about her family heirloom without it. She hands you the pie with plain irritation and hopes Billy chokes on every bite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_84-671da9fc0574a1120d23/1-0000.mp3", duration = 30.1714286, start = 0},
  },
}
P.transport["quest:840"] = {
  hash = "e52e6f",
  fullHash = "e52e6f",
  text = "Conscript of the Horde. Along Durotar’s western road, Conscript of the Horde sends recruits toward the Barrens. Takrin Pathseeker watches beyond Razor Hill and gives them a letter for Kargal Battlescar, whose outpost guards the crossing. After proving your strength around Razor Hill, you are called west to serve the wider Horde. Takrin Pathseeker watches the road out of Durotar for his friend, veteran Kargal Battlescar. He gives capable travelers a recruitment letter to carry across the Southfury River. For a recruit, the letter marks a first formal assignment beyond the orcs’ new homeland. Kargal Battlescar holds the outpost beyond the bridge, between Durotar’s red canyons and the dry Barrens. He gathers recruits to guard the frontier, where centaur, quilboar, and Alliance expeditions test the border. The Horde needs more than guards there: raw manpower is being sent to the settlement of the Crossroads.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_840-1078a00f5b85666bb791/1-0000.mp3", duration = 54.0995918, start = 0},
  },
}
P.transport["quest:842"] = {
  hash = "fb99c8",
  fullHash = "fb99c8",
  text = "Crossroads Conscription. Recruits leave the Far Watch Post for duty at Crossroads Conscription. Carrying Kargal Battlescar’s signed letter, you report to Sergra Darkthorn at the Barrens’ central hub. Kargal Battlescar sends you west from the Far Watch Post after you prove your worth. He gives you a signed recruitment letter to carry along the packed dirt road through the Barrens’ arid brush. The road reaches a central junction, where the Crossroads links northern Kalimdor with the southern wilderness. Sergra Darkthorn receives new arrivals at the Crossroads. Warchief Thrall chose the sharp-tongued orc shaman to oversee its operations. Kargal Battlescar grumbles that she is difficult and talks too much, but Thrall holds her in high esteem. Sergra is fierce and unyielding. She reminds recruits, especially arrogant men, that female warriors and leaders stand as equals in Thrall’s Horde, and she will tolerate no insolence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_842-3cdf12f42bbb77c44497/1-0000.mp3", duration = 53.8644898, start = 0},
  },
}
P.transport["quest:844"] = {
  hash = "93a371",
  fullHash = "93a371",
  text = "Plainstrider Menace. At the Crossroads, Sergra Darkthorn sends new Horde adventurers after plainstriders east of the outpost. The birds threaten its food supplies, and the hunt gives newcomers a first measure of the Barrens. The Crossroads coordinates supplies across Kalimdor, but plainstriders east of the outpost have begun picking at its food crates. Sergra Darkthorn, an orc shaman, sends newly arrived Horde adventurers to hunt the birds before they damage the stores. Their attacks threaten provisions the settlement depends on. Sergra Darkthorn uses the hunt to measure newcomers as well as protect supplies. She sees the plainstriders as simple prey, fit to teach young hunters to endure the elements and track quarry across the sun-baked plains. Bringing back their sharp beaks shows a hunter has patience and the basic martial skill needed to face fiercer beasts of the Barrens.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_844-e8be90fbcaf1a6bb1397/1-0000.mp3", duration = 48.6661224, start = 0},
  },
}
P.transport["quest:845"] = {
  hash = "7290db",
  fullHash = "7290db",
  text = "The Zhevra. At the Crossroads, Sergra Darkthorn sends young Horde warriors after the zhevra. Their hunt tests the skills needed to face the Barrens' more dangerous beasts. After the plainstriders, Sergra Darkthorn sends you after tougher prey. Zhevras run in herds across the northern and southern Barrens. They are not the savanna's fiercest beasts, but they are swift and stubborn, and their kicks can break bone. Sergra uses the hunt to test your growing skill. She asks for four intact hooves as proof of the kill and warns that a zhevra's rear kick can knock a grown tauren onto their haunches. Passing this trial brings you closer to facing the plains' predatory prowlers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_845-b39e1395ddd6a482e43b/1-0000.mp3", duration = 38.5828571, start = 0},
  },
}
P.transport["quest:848"] = {
  hash = "91cfe2",
  fullHash = "91cfe2",
  text = "Fungal Spores. At the Barrens oases, Horde adventurers gather Fungal Spores for Apothecary Helbrim of the Royal Apothecary Society. Strange, mutative energies flow through the springs and alter the local plants into potent reagents. Helbrim seeks the specimens to brew concoctions for his colleague in Thunder Bluff. The Barrens is a dry savanna, but the Forgotten Pools, Lushwater Oasis, and Stagnant Oasis brim with unnatural vitality. A curious surge of life energy flows from their waters, warping and invigorating plants and beasts that drink there. Laden mushrooms grow along the muddy banks, absorbing those currents. Their spores hold rare properties that draw the curiosity of passing alchemists. Apothecary Helbrim works at the Crossroads, far from the Undercity, yet remains devoted to the Royal Apothecary Society's research. He gathers the altered spores because Kalimdor's native reagents have strange potency, and he uses them to craft powerful mixtures. The specimens are destined for Apothecary Zamah in Thunder Bluff, part of the Forsaken's scientific work across allied lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_848-334c9b29d722cb1a9d21/1-0000.mp3", duration = 64.6269388, start = 0},
  },
}
P.transport["quest:85"] = {
  hash = "36704e",
  fullHash = "36704e",
  text = "Lost Necklace. In southern Elwynn, Bernice Stonefield searches for her missing necklace. She suspects Billy Maclure, the young son of the neighboring family, and asks you to find him across the road. The Stonefield and Maclure families live on adjoining land in southern Elwynn Forest, but they share little goodwill. When \"Auntie\" Bernice Stonefield discovers her cherished necklace is gone, she blames the youngest Maclure. Certain that Billy Maclure slipped onto her farm and took it, the bitter widow asks you to cross the road to the vineyards, find the boy, and demand its return.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_85-d4eed2af843396917719/1-0000.mp3", duration = 33.1493878, start = 0},
  },
}
P.transport["quest:851"] = {
  hash = "d47ab2",
  fullHash = "d47ab2",
  text = "Verog the Dervish. Across the southern Barrens, Verog the Dervish keeps moving, and Regthar Deathgate seeks to draw him out. The orc directs Horde champions to attack the Kolkar command tent at the Stagnant Oasis, hoping to force the nomadic leader into the open. After Barak Kodobane fell, Regthar Deathgate turned to the remaining Kolkar warlords. Barak had stayed near the northern waters of the Forgotten Pools, but Verog the Dervish roams the sun-baked plains and rarely lingers in one camp. Horde scouts cannot easily track him across that wide territory. Their chance is to make the commander come to them. Verog operates from the Kolkar command post at the Stagnant Oasis, southeast of the Crossroads. Regthar sends you against the camp, where you strike the Kolkar warriors near their command tent. Their alarm calls Verog back to defend the outpost, bringing him within reach of the Horde blades.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_851-7f44e92b2a8c0950a969/1-0000.mp3", duration = 52.0881633, start = 0},
  },
}
P.transport["quest:852"] = {
  hash = "be1e96",
  fullHash = "be1e96",
  text = "Hezrul Bloodmark. At Lushwater Oasis, Hezrul Bloodmark directs the Kolkar incursions across the Barrens. Regthar Deathgate sends you to end his command and break the centaur's hold on the region. After Barak Kodobane and Verog the Dervish fall, Hezrul Bloodmark remains the Barrens Kolkar's paramount chieftain. Regthar Deathgate calls him brutal and cunning, the spearhead behind the centaur incursions across the savanna. The Horde hopes his death will sow chaos and fracture the Kolkar ranks beyond recovery, before they can overwhelm Horde settlements. Hezrul commands his warbands from Lushwater Oasis, south of the Crossroads. The few watering holes in the Barrens are vital to survival, making this oasis a strategic hub and a staging ground for Kolkar raiders. On Hezrul's own ground, you deny the centaur their most vital stronghold and sever their hold on the southern trails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_852-d3186e156a4ff213de95/1-0000.mp3", duration = 51.1216327, start = 0},
  },
}
P.transport["quest:853"] = {
  hash = "f674b6",
  fullHash = "f674b6",
  text = "Apothecary Zamah. This errand sends an adventurer racing from the arid Barrens to Thunder Bluff carrying a volatile, rendered fungal emulsion. Apothecary Helbrim needs the potent mixture delivered swiftly to his colleague, Apothecary Zamah, tucked away in the shadowy depths beneath Spirit Rise. After studying the peculiar fungal blooms thriving across the oases of the Barrens, Apothecary Helbrim cooks down a batch into a delicate emulsion. The unstable brew degrades rapidly once prepared. Lacking the time to travel to Mulgore himself, Helbrim entrusts the flask to a reliable runner to make the climb up the bluffs before the solution loses its chemical potency. Apothecary Zamah maintains her laboratory far from the open plains of Mulgore, sequestered inside the Pools of Vision. This subterranean cavern rests deep beneath the sacred heights of Spirit Rise, shared with Forsaken mages and priests. Here, beneath the floor of the tauren sanctuary, the Royal Apothecary Society quietly conducts its research using raw materials gathered throughout the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_853-7598446e19da19cdb2b4/1-0000.mp3", duration = 61.2571429, start = 0},
  },
}
P.transport["quest:854"] = {
  hash = "f321dc",
  fullHash = "f321dc",
  text = "Journey to the Crossroads. At Camp Taurajo, Kirge Sternhorn sends travelers north to aid Thork at the Crossroads. The journey carries them from Mulgore into the Barrens and the wider struggles of the Horde. Camp Taurajo is where many tauren first face the Barrens beyond Mulgore. Just past the mountain pass, mystic Kirge Sternhorn watches travelers descend into the dry grasslands. When Sternhorn sees that a traveler is ready to go farther, Kirge points north along the dusty trade route toward the Crossroads. The tauren of Thunder Bluff and Thrall's new Horde now share their fortunes. Kirge says the two peoples' fates are bound together, and orcs at the Crossroads need reinforcements as they struggle to establish an outpost. At the settlement, Thork welcomes travelers from even the high bluffs, ready to test their strength against the dangers of the savanna.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_854-fd5ac91b0ee20d121d4e/1-0000.mp3", duration = 48.2481633, start = 0},
  },
}
P.transport["quest:855"] = {
  hash = "1cc359",
  fullHash = "1cc359",
  text = "Centaur Bracers. West of the Crossroads, Regthar Deathgate calls for Centaur Bracers. Kolkar centaurs contest the central Barrens, threatening Horde control of the plains. The young Horde is fighting to secure territory across Kalimdor. The Barrens lie between Durotar and Mulgore, but Kolkar centaurs contest its watering holes and open plains. They attack supply trains and scouting parties. Regthar Deathgate, an orc warrior, directs the defense from his bunker west of the Crossroads. Regthar asks for proof that Kolkar warriors have fallen. Soldiers who enter Kolkar territory bring back bracers taken from slain centaurs. The trophies verify claims for Horde bounties and are meant to frighten surviving Kolkar raiders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_855-2fa146a277d43d09a126/1-0000.mp3", duration = 43.6244898, start = 0},
  },
}
P.transport["quest:8569"] = {
  hash = "6fb9a7",
  fullHash = "6fb9a7",
  text = "Past Efforts in Warsong Gulch. In Warsong Gulch, soldiers fight for Ashenvale while commanders honor their sacrifices. Capital officers accept the Ribbon of Sacrifice as a sign of steadfast service, even when battles bring no clear victory. The Silverwing Sentinels and Warsong Outriders fight brutal skirmishes along Ashenvale’s southern border. Many battles end without a clear victory. Stormwind, Orgrimmar, and other capitals honor those who hold their ground despite the odds. The Ribbon of Sacrifice marks fighters who gave themselves to the struggle. Far from the front, Alliance Brigadier Generals and Horde Warbringers oversee their forces. Recruiters send new fighters to Warsong Gulch, while quartermasters and tacticians account for veterans returning from hard campaigns. By honoring courage in stalemate or defeat, their leaders help keep soldiers committed to holding Ashenvale.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8569-60086010f189695d3248/1-0000.mp3", duration = 51.1216327, start = 0},
  },
}
P.transport["quest:858"] = {
  hash = "74f7c0",
  fullHash = "74f7c0",
  text = "Ignition. At a Venture Company camp in the northern Barrens, a trapped pilot needs an ignition key before their cover fails. The operative hijacked a shredder without its key and needs someone to fetch it from the site supervisor. A spy sent by Sputtervalve has slipped into a Venture Company shredder at the northern Barrens drilling grounds. The operative means to seize the machine and study how it works. But the steering and movement column stays locked without its ignition key. A goblin worker has noticed the shredder sitting idle, so the hijacker bluffs that its engine has failed. Trapped beneath the glass canopy with workers nearby, the operative points you toward the central derrick. The supervisor keeps spare ignition keys in the upper control office, the only way out before the bluff fails.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_858-285b60c2a1e9632212f4/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["quest:86"] = {
  hash = "3de6f7",
  fullHash = "3de6f7",
  text = "Pie for Billy. Auntie Bernice Stonefield's missing necklace has left Billy Maclure bargaining for a pork belly pie. The Stonefield and Maclure families have feuded for generations, and Billy will say who has the necklace only after he gets his pie. Billy Maclure gives no apology when asked about Auntie Bernice Stonefield's missing necklace. He will not return it or say who has it until he gets a freshly baked pork belly pie. He knows Bernice is the finest cook in the valley, and he means to enjoy the bargain. The Maclures and Stonefields have traded insults, brawls, and accusations across their pumpkin patches for generations. Bernice is furious at the thought of feeding the boy she believes stole her family's jewelry, yet she agrees to bake. You gather tender meat from the wild boars roaming the nearby pastures, and she sets aside her pride to get her prized necklace back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_86-7216b4ee9b214166e157/1-0000.mp3", duration = 50.0244898, start = 0},
  },
}
P.transport["quest:860"] = {
  hash = "53c262",
  fullHash = "53c262",
  text = "Sergra Darkthorn. Having proven their basic tracking and stalking skills in the rolling hills of Mulgore, young tauren are directed outward into the arid wilderness of the Barrens. Melor Stonehoof sends aspiring hunters north of the border to report to Sergra Darkthorn at the Crossroads. This journey marks the hunter's formal transition from local trials to the demanding predatory hierarchy of Kalimdor's broader plains. For a novice tauren hunter, completing initial rites in Mulgore is only the beginning. The lush valleys of their ancestral homeland are protected and familiar, nurturing beasts that test patience rather than sheer survival. Melor Stonehoof recognizes when a hunter's spirit has grown enough to require harsher trials. He instructs his pupils to pack their gear, leave the safety of Bloodhoof Village, and venture east across the mountain pass into the baked scrublands of the Barrens. The path through the red rock canyons leads straight into the wide, sun-scorched savanna where the young Horde stakes its claim. At the intersection of Kalimdor's central trade routes lies the Crossroads, a fortified settlement bustling with orcs, trolls, and tauren. There waits Sergra Darkthorn, an experienced orc shaman renowned for her unforgiving standards. She acts as a mentor to any bold enough to stalk the Barrens' fierce fauna, promising to temper raw eagerness into hardened wilderness discipline.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_860-30955fc7810015e83eab/1-0000.mp3", duration = 81.2408163, start = 0},
  },
}
P.transport["quest:861"] = {
  hash = "882b12",
  fullHash = "882b12",
  text = "The Hunter's Way. The Hunter's Way is a rite of passage offered to aspiring trackers in Mulgore by the elder Skorn Whitecloud. To prove their emerging skill and respect for the wild, wanderers must fell the cunning flatland prowlers and present their claws to Melor Stonehoof atop Thunder Bluff's Hunter Rise. For the tauren, hunting is neither mere sport nor simple subsistence; it is considered one of their people's highest honors. It demands patience, awareness of the Earth Mother's balance, and reverence for the beasts that roam the rolling plains. Elder Skorn Whitecloud, resting in Mulgore after decades of tracking across Kalimdor, recognizes this restlessness in young adventurers. Rather than allowing them to wander aimlessly, he channels their ambition into a traditional trial of maturity and discipline. To demonstrate that their tracking instincts are genuine, candidates are tasked with taking down Mulgore's flatland prowlers. These great cats are swift, stealthy, and cunning ambush predators that blend easily into the high grass of the plains. Gathering four sets of claws proves that a fledgling wanderer can spot a predator before becoming prey, turning the hunter's own ferocity back upon them. Upon securing the trophies, the initiate ascends the soaring wooden towers and bridges leading up to Thunder Bluff. There, upon the Hunter Rise, Melor Stonehoof receives the claws. As a master tracker who values Skorn Whitecloud's ancient wisdom, Stonehoof accepts the offering as proof that the initiate possesses the right spirit to be guided further along the predatory paths of Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_861-ab44e05d88b5e666aafe/1-0000.mp3", duration = 90.0440816, start = 0},
  },
}
P.transport["quest:863"] = {
  hash = "ea188a",
  fullHash = "ea188a",
  text = "The Escape. You help Wizzlecrank flee the Venture Company drill site at the Sludge Fen in the northern Barrens. Trapped in a stolen prototype shredder, the goblin pilot needs protection from company mercenaries as he climbs from the industrial pit. Afterward, you report to his contact, Sputtervalve, in Ratchet. Wizzlecrank struggles to control the stolen shredder at the Sludge Fen. He has lit the prototype deep inside the Venture Company drill site, but knows little of its levers and switches. The heavy machine lurches across the muddy quarry floor, and its erratic driving and roaring joints alert nearby laborers and armed guards. A stealthy escape becomes a running battle up the excavation pit’s western ramp. The Venture Company sends mercenaries to stop the stolen prototype. As the machine claws up the slope toward open ground, squads move to intercept and disable it. The shredder lashes out, but cannot withstand their sabotage without your protection. It clears the rim and staggers from the main drilling depression, though the machine soon suffers a critical failure.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_863-df006da9b5c13b60a381/1-0000.mp3", duration = 59.6636735, start = 0},
  },
}
P.transport["quest:8646"] = {
  hash = "2ea6c5",
  fullHash = "2ea6c5",
  text = "Hammershout the Elder. During the Lunar Festival, Hammershout the Elder appears in Stormwind's Park. Travelers honor the old races and receive a ceremonial token from him. During the Lunar Festival, revered ancestor spirits appear across Azeroth with wisdom and blessings for travelers who pay their respects. Hammershout the Elder appears in Stormwind's Park district. His presence near the heart of human civilization recalls the ancient races who walked the land before today's kingdoms rose. Hammershout the Elder asks for no trial or oath, only acknowledgment of the past. He is relieved and grateful when people still honor the old races. In return, he gives travelers a ceremonial token, a sign of the bond between the living and the spirits who came before.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8646-f6ea57071c0eeb8de11c/1-0000.mp3", duration = 44.564898, start = 0},
  },
}
P.transport["quest:8649"] = {
  hash = "94df3e",
  fullHash = "94df3e",
  text = "Stormbrow the Elder. Near Goldshire, Stormbrow the Elder waits beside the water during the Lunar Festival. Travelers honor ancient traditions and the olden races of Azeroth, and receive a token of remembrance in return. A quiet pond lies just behind the smithy in Goldshire, where Stormbrow the Elder appears. Guards, tradesfolk, and weary travelers pass through town on their way into the forest. Beneath Elwynn Forest's canopy, the honored spirit welcomes anyone who comes to honor the realm's long history. During the Lunar Festival, spirits of great ancestors return to walk among the living. Stormbrow the Elder commends travelers who remember those who came before. For honoring the wisdom and legacy of the elder peoples, he grants a blessing and a commemorative coin for the season.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8649-68f60b4fa9983ce17e84/1-0000.mp3", duration = 47.2293878, start = 0},
  },
}
P.transport["quest:865"] = {
  hash = "da4bab",
  fullHash = "da4bab",
  text = "Raptor Horns. In Ratchet, Mebok Mizzyrix wants intact raptor horns for a scheme of his own. The goblin believes the cunning of Barrens raptors lies in their horns and hires travelers to hunt Sunscale Scytheclaws. Mebok Mizzyrix looks for fortune in Ratchet, where goblins chase one scheme after another. He has watched the Barrens raptors act with unusual craft and coordination compared with beasts elsewhere. Mebok decided their intelligence must be held in their horns. He has no formal inquiry in mind; he wants to put this idea to profit. Mebok wants undamaged horns from Sunscale Scytheclaws, among the Barrens' deadliest predators. They prowl the southern stretches of the Barrens and the northern borders near Ashenvale. The raptors hunt in packs and defend their territory fiercely, so bringing down one and taking its horns intact calls for considerable skill in battle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_865-432f62ebed391eb81ba3/1-0000.mp3", duration = 50.1028571, start = 0},
  },
}
P.transport["quest:867"] = {
  hash = "76048a",
  fullHash = "76048a",
  text = "Harpy Raiders. Witchwing harpies strike supply caravans on the northwestern trails of the Barrens. Darsok Swiftdagger at the Crossroads sends you to hunt their raiders and roguefeathers, taking their talons as proof. Witchwing harpies strike caravans crossing the Barrens. From rocky crags in the northwest, they swoop on merchant trains and supply wagons. They kill pack animals and seize goods bound for orcish outposts, making each journey through the region dangerous. Darsok Swiftdagger, an orc rogue, has spent days watching the flock's habits and ranks. He believes an unfocused assault on their mountain roosts would scatter them. His plan is to break the Witchwing from the lowest rank upward, starting with the raiders before turning to their commanders.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_867-17ec1e39713758094e99/1-0000.mp3", duration = 42.6579592, start = 0},
  },
}
P.transport["quest:8670"] = {
  hash = "6248eb",
  fullHash = "6248eb",
  text = "Runetotem the Elder. During the Lunar Festival, travelers in Durotar can honor Runetotem the Elder, an ancestral spirit. She waits in Razor Hill beneath a beam of heavenly light, offering blessings and festival tokens to those who remember the past. During the Lunar Festival, spirits of ancient elders appear across Azeroth to commune with the living. Elder Runetotem waits inside Razor Hill, just past the southern entrance. A beam of starlight falls on her as she watches over the orcish settlement. Travelers can pause there to honor the wisdom of those who came before. When you pay Elder Runetotem homage, she gives you a festival token of fortune and tells you where other spirits can be found. Her directions point toward Elder Darkhorn and Elder High Mountain elsewhere across the continent.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8670-fd57850ae25a5924aec5/1-0000.mp3", duration = 42.5795918, start = 0},
  },
}
P.transport["quest:8675"] = {
  hash = "c1c7b9",
  fullHash = "c1c7b9",
  text = "Skychaser the Elder. During the Lunar Festival, Skychaser the Elder appears atop Sentinel Tower in Westfall. Travelers climb to honor her and receive her blessing in return. Sentinel Hill holds against Defias raiders and roving scavengers in Westfall's troubled scrublands. During the Lunar Festival, an ancestral spirit named Elder Skychaser appears on the open platform atop Sentinel Tower. From above the dust and wind, she watches over the weary soldiers and beleaguered settlers below. Anyone may climb the tower and pay her respect. Across Azeroth, the Lunar Festival honors wisdom, heritage, and the deeds of ancient spirits who walked the earth before today's struggles. When you approach, Elder Skychaser recognizes the living spark within you. She accepts your homage and gives you a token of her favor, a bond between the living and the honored dead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8675-3383d0e61c3f06624bfa/1-0000.mp3", duration = 50.1812245, start = 0},
  },
}
P.transport["quest:8677"] = {
  hash = "f4dc5c",
  fullHash = "f4dc5c",
  text = "Darkhorn the Elder. At the Lunar Festival, Darkhorn the Elder receives travelers in Orgrimmar. Honored among the ancestors, she embodies age, survival, and ancestral pride. During the Lunar Festival, revered ancestors appear across Azeroth to share wisdom with the living. Elder Darkhorn rests within Orgrimmar’s fortified ramparts, watching the young warrior city. You can approach her to honor those who walked the earth generations ago, whether you fight for the Horde or brave the gates as an Alliance traveler. Travelers greet Elder Darkhorn and pay her reverence, and she recognizes the spark of life in them. For honoring the old ways, you receive a Coin of Ancestry and her blessing. The tokens celebrate victory over ancient perils and remind the living to cherish the strength handed down through unbroken bloodlines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8677-fca71e6ea9ef2f728a09/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:86784"] = {
  hash = "2fdf43",
  fullHash = "2fdf43",
  text = "Sticks and Bones. Sticks and Bones is a local task offered by Deathguard Bartholomew in Tirisfal Glades. He sends travelers to gather dry branches across the blighted woodland to deliver to Eleanor Shackleton, an experienced survivalist camped in the western hills. While Deathguards in Tirisfal Glades are usually consumed by military patrol duty and guarding against the Scourge or Scarlet crusaders, Deathguard Bartholomew takes a moment to look out for an acquaintance. Knowing that Eleanor Shackleton spends her unlife out in the harsh elements, he encourages passing adventurers to collect dry branches for her camp fire. Eleanor Shackleton prides herself on surviving the blighted wilderness of Tirisfal alone. Despite being undead, the Forsaken still feel the damp, bitter chill that rolls off the northern moors. Eleanor's philosophy on wood gathering is simple: whenever you think you have collected enough firewood, collect five times more. Grateful for the extra timber, she lets the courier keep Bartholomew's basket and shares the warmth of her fire.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_86784-85ade27ec32d2bfeb749/1-0000.mp3", duration = 60.395102, start = 0},
  },
}
P.transport["quest:8680"] = {
  hash = "22a31e",
  fullHash = "22a31e",
  text = "Windtotem the Elder. During the Lunar Festival, Windtotem the Elder receives travelers on a bluff above Ratchet. She welcomes those who honor the wisdom of ages past and offers an ancestral blessing and guidance to other elders across Kalimdor. On a grassy hill just northwest of Ratchet’s flight master, Windtotem the Elder watches over the goblin docks and open sea. Iron, gunpowder, and coin pass through the harbor below, while quiet Barrens winds and a shaft of celestial light reach the elder. During the Lunar Festival, Windtotem the Elder guides wandering mortals, as do the other ancestral spirits. Those who seek her receive her blessing and a token of her favor, along with whispers pointing to nearby elders across the continent, including Elder Runetotem and Elder Bloodhoof.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8680-61d9e8e02cba0bbdf909/1-0000.mp3", duration = 43.9379592, start = 0},
  },
}
P.transport["quest:869"] = {
  hash = "c99048",
  fullHash = "c99048",
  text = "Raptor Thieves. A raptor has stolen the guards' payroll from the Crossroads tower, leaving the defenders baffled. Gazrog calls for a cull to keep the beasts from striking again. The Crossroads depends on mercenary and grunt guards to keep trade routes open across the Barrens. Their pay matters to morale and discipline. When silver vanished from the guard tower, leaders expected Centaur raiders or Quilboar scavengers. Instead, a raptor was caught stealing in the dead of night, leaving the settlement stunned and short of coin. Gazrog does not know why wild beasts would hoard shiny coins, and he has no interest in studying their behavior. The guards are restless without their pay, so he calls for blood and deterrence. He sends hunters to take a dozen raptor heads from across the savannah, hoping to curb the predators' boldness before a full search for the silver begins.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_869-a96df47033e0c2ecd93e/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["quest:87"] = {
  hash = "a7315b",
  fullHash = "a7315b",
  text = "Goldtooth. Near Fargodeep Mine, Auntie Bernice Stonefield's necklace is missing, and the Stonefield and Maclure families blame each other. Billy Maclure admits he lost it while playing nearby, and you follow the trail to the kobold Goldtooth. Auntie Bernice Stonefield's missing necklace has stirred up trouble between the Stonefield and Maclure families. Bernice suspects her rivals, but Billy Maclure lost the trinket while playing near Fargodeep Mine. He tries to hide his guilt, saying he only found the necklace before a creature snatched it away. Billy says a large kobold with gleaming fangs took the shiny necklace and ran to a den above Fargodeep Mine. Goldtooth actually lurks on the mine's lower level. Slaying the kobold brings Bernice's necklace back, settles the families' dispute, and earns you an old campaign keepsake left by Bernice's late husband.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_87-dd512be7e25cdc15af26/1-0000.mp3", duration = 49.684898, start = 0},
  },
}
P.transport["quest:870"] = {
  hash = "c7f71f",
  fullHash = "c7f71f",
  text = "The Forgotten Pools. At the Forgotten Pools, life surges through the dry Barrens for reasons the Cenarion Circle cannot explain. Tonga Runetotem at the Crossroads sends Horde adventurers to inspect the oasis northwest of the settlement, where druids sense unseen forces beneath the earth. The Barrens once flourished as fertile land before ages of war and the Sundering shattered the continent. The region became sun-baked scrubland, but lush oases have recently begun taking root in its dry basin. Druids of the Cenarion Circle find this sudden growth unnatural. They sense powers beneath the earth pressing upward, stirring vegetation and wildlife into life in scattered pockets across the wastes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_870-d4f199bc07c7fbe5f6cc/1-0000.mp3", duration = 40.4897959, start = 0},
  },
}
P.transport["quest:871"] = {
  hash = "072afc",
  fullHash = "072afc",
  text = "Disrupt the Attacks. Thork needs the Crossroads defended as Razormane quilboar cut its supply roads. Their ambushes have halted caravans from Durotar, and the outpost is running short on food and gear. You strike at the quilboar while scouts search for the one directing their warband. The Crossroads guards a key junction for Horde traffic through central Kalimdor. Freight wagons and caravans bring food, iron, and equipment west from Durotar, and the outpost depends on those supplies. Razormane ambushes along the northeast trails have stopped the deliveries. Stores are running low, and Thork cannot wait for peaceful talks. Thork sends you against the quilboar bramble dens northeast of the settlement before they can assault the town walls. Striking their Water Seekers, Thornweavers, and Hunters weakens the Razormane scouting perimeter and deprives raiding parties of magical and logistical support. These skirmishes buy time while Horde trackers search the brush for the one organizing the raids.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_871-2fefa4c2584138bc85cb/1-0000.mp3", duration = 55.275102, start = 0},
  },
}
P.transport["quest:8717"] = {
  hash = "44358b",
  fullHash = "44358b",
  text = "Moonwarden the Elder. At the Crossroads, Moonwarden the Elder receives travelers beneath a beam of light. During the Lunar Festival, people honor ancestral spirits and seek his wisdom and directions to elders across Kalimdor. At the Crossroads, a column of light falls around Elder Moonwarden. He is one of the ancient spirits honored during the Lunar Festival, when mortals set aside their conflicts to seek the wisdom of generations past. Elder Moonwarden looks to the stars for answers to earthly mysteries. He offers ancestral blessings and directs seekers to other elders across Kalimdor, including Elder Bloodhoof, Elder High Mountain, Elder Morningdew, and Elder Runetotem.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8717-27e6d80f1cbd20831c18/1-0000.mp3", duration = 38.4261224, start = 0},
  },
}
P.transport["quest:8718"] = {
  hash = "47e494",
  fullHash = "47e494",
  text = "Bladeswift the Elder. During the Lunar Festival, Bladeswift the Elder's ancient spirit is honored in Darnassus. In the Cenarion Enclave, travelers seek his wisdom beneath the stars and a blessing tied to night elven tradition. During the Lunar Festival, revered ancestral spirits appear across Azeroth to share wisdom and bless travelers. In Darnassus, Bladeswift the Elder appears among the boughs of the Cenarion Enclave. This ancient spirit turns his gaze to the night sky and its mysteries, while the living face the trials of the present. Night elves have long looked to the heavens as reflections of Elune and signs of deeper truths. Bladeswift urges the wise and fortunate to seek answers among the stars. Those who honor him receive a Coin of Ancestry and join a ceremony that links the living with spirits of the past.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8718-0358a385eff388437c9f/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["quest:872"] = {
  hash = "bb7559",
  fullHash = "bb7559",
  text = "The Disruption Ends. Thork orders a strike against the Razormane raids on the Horde road. Kreenig Snarlsnout leads the attacks from the northern Barrens, and his death is meant to break the warband's hold on the route between Durotar and the Crossroads. The road between Durotar and the Crossroads carries provisions and reinforcements through the northern Barrens. Razormane quilboar ambushes have kept it under threat. Scout reports name their leader as Kreenig Snarlsnout, whose raiding party organizes the attacks. Thork orders a strike against Kreenig, hoping to break the warband's unity and secure the road. Kreenig's war party is entrenched in craggy hills northeast of the Crossroads. Hardy Razormane Defenders and geomancers who manipulate the arid earth shield his position. Thork's order is to break through that guard and strike Kreenig in his redoubt, sending a warning across the plains. His tusk will prove the leader's death and show that the Horde will not accept attacks on its lifelines.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_872-5fe51284c0089ab536c8/1-0000.mp3", duration = 54.804898, start = 0},
  },
}
P.transport["quest:8721"] = {
  hash = "0675cd",
  fullHash = "0675cd",
  text = "Starweave the Elder. During the Lunar Festival, Elder Starweave receives visitors in Auberdine. Travelers come to honor Kalimdor's ancestral spirits and seek her wisdom and blessing. During the Lunar Festival, ancestral spirits appear across Azeroth beneath pillars of celestial light. Elder Starweave joins the night elves in Auberdine, a harbor on Darkshore's coast. Travelers come to honor her and seek guidance from ages past. Elder Starweave looks to the heavens above Kalimdor. She tells visitors that the stars hold answers to mortal doubts and worldly riddles. Those who seek her counsel are urged to look skyward for truth and receive ancestral favor, along with tidings of other wandering spirits across the wild frontier.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8721-0e2dd79f8a88bf1d1da4/1-0000.mp3", duration = 40.96, start = 0},
  },
}
P.transport["quest:875"] = {
  hash = "805272",
  fullHash = "805272",
  text = "Harpy Lieutenants. At the Crossroads, Darsok Swiftdagger sends Horde champions against the Witchwing coven in the northern Barrens. In the Dry Hills, the aim is to kill the flock’s front-line officers and break its chain of command. After the first clashes with Witchwing raiders, Darsok Swiftdagger turns the offensive toward the harpies roosting in the Dry Hills. Horde scouts are sent after the Witchwing Slayers who lead the flock. These officers keep the lesser harpies in line and coordinate raids against Horde supply paths. Their deaths are critical to securing the northern approaches of the Barrens. Witchwing Slayers lead through strength and dominance, and only the most vicious among them carry ornate rings that mark their authority within the matriarchy. Taking the rings proves the lieutenants are dead, disrupts the roost’s coordination, and sends the coven a clear message: attacks on Horde territory will meet decisive retribution.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_875-016540540a43952a1b85/1-0000.mp3", duration = 50.0767347, start = 0},
  },
}
P.transport["quest:877"] = {
  hash = "59091e",
  fullHash = "59091e",
  text = "The Stagnant Oasis. Tonga Runetotem sends you southeast from the Crossroads to search the Stagnant Oasis. He wants to know if the hidden fissure beneath the Forgotten Pools has a match in its murky waters. Tonga Runetotem sends you to the Stagnant Oasis after a strange fissure is found beneath the Forgotten Pools. He suspects the sudden patches of lush growth across the Barrens have a cause beneath the earth. You search the oasis's murky shallows for another opening, among predators that haunt the water.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_877-072182b95c37112dac3e/1-0000.mp3", duration = 26.6710204, start = 0},
  },
}
P.transport["quest:88"] = {
  hash = "d2799d",
  fullHash = "d2799d",
  text = "Princess Must Die!. At Stonefield Farm, Ma Stonefield wants Princess Must Die! before Princess ruins the harvest. The enormous prize-winning sow from Brackwell Pumpkin Patch keeps raiding the Stonefields’ vegetables, and Ma wants the family to gather their crops in peace. Princess has put the Stonefield harvest at risk. The prize-winning sow belongs to the Brackwells, but she has grown enormous by crossing onto the Stonefield plots and devouring their vegetables. Ma Stonefield has had enough of the sow eating the crops she worked to grow. She wants Princess put down before the pig ruins the season’s yield. Princess does not roam alone. At Brackwell Pumpkin Patch, east beyond the Maclure homestead, protective boars surround her. To prove the sow will trouble the Stonefield fields no more, you need to get past her guards and bring back the distinctive brass collar from her neck.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_88-e09e57f67fd1c5bb370e/1-0000.mp3", duration = 50.8081633, start = 0},
  },
}
P.transport["quest:880"] = {
  hash = "18a148",
  fullHash = "18a148",
  text = "Altered Beings. At the Crossroads, Tonga Runetotem studies strange changes in the Barrens' oasis waters. Fissures beneath the pools may be changing the creatures that live there, and he asks you to bring him shells from altered snapjaws. Tonga Runetotem is searching for the cause of strange changes in the Barrens' oases. Though the savanna is dry, a handful of pools support fertile ground. Tonga found peculiar fissures beneath those waters, sending out potent energies. He does not know whether the force came from outside or rose from deep within the earth. Now he studies the creatures that drink from and live in the pools, hoping to learn what the fissures are doing to them. You are sent to the Lushwater Oasis and the Stagnant Oasis to gather altered snapjaw shells. Snapjaws live in the shallows, where they take in the strange essence through food and exposure. Their carapaces have changed, offering Tonga a sign of how the fissures affect local wildlife. He hopes the shells will help him understand the disturbance before it spreads farther across Kalimdor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_880-daf8b4c2a8a44a06cf9c/1-0000.mp3", duration = 57.1036735, start = 0},
  },
}
P.transport["quest:881"] = {
  hash = "bfbcc6",
  fullHash = "bfbcc6",
  text = "Echeyakee. At the Crossroads, hunters prepare to face Whitemist in the northern Barrens. Sergra Darkthorn sends young Horde hunters to summon the legendary white lion and test their strength. Across the central plains, a white-maned lion rules the savannah cats. Taur-ahe speakers call him Echeyakee, or Whitemist. Legend says he moves so silently that he seems like morning mist gliding over the red earth. His strikes come swiftly, leaving prey no time for fear or suffering. Local hunters revere him as a sign of mercy and swift death. At the Crossroads, Sergra Darkthorn trains fledgling warriors. The experienced orc shaman sends her pupils to challenge the king of beasts after they have proven themselves against lesser savannah prowlers. With a special horn, you travel northeast past the mountain ridges to a graveyard of massive kodo bones. Sound the horn to challenge Echeyakee and draw the elusive predator from hiding for a test of strength and cunning.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_881-ef6fa4db000c4e844173/1-0000.mp3", duration = 56.084898, start = 0},
  },
}
P.transport["quest:882"] = {
  hash = "efe2d2",
  fullHash = "efe2d2",
  text = "Ishamuhale. At Camp Taurajo, Jorn Skyseer sends you to face Ishamuhale, the fiercest sunscale raptor in the Barrens. The hunt tests your skill and respect for nature's deadliest predators. Sunscale raptors hunt the Barrens in cunning, vicious packs, but none inspires more dread than Speartooth. Jorn Skyseer says Ishamuhale kills by instinct and passion, not for food or territory. He hunts because killing is his nature. To face him is to test whether you can withstand a predator's unbridled ferocity. Ishamuhale will not be found resting in a nest. To draw him out, you follow the plains' natural rhythm. Jorn tells you to kill a fresh zhevra and carry its carcass to a lone, withered dead tree on the plains northwest of Ratchet. The scent of blood on the arid wind brings Ishamuhale swiftly to claim his prey. When you bring Ishamuhale's fang back to Camp Taurajo, Jorn Skyseer sees it as a profound spiritual milestone, not merely a sign of victory. Tauren belief holds that overcoming so fierce a predator lets you absorb some of its raw strength. The test then turns inward: you must carry that might with temperance, honor, and restraint, rather than surrender to blind bloodlust.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_882-06727eae73e495c2919b/1-0000.mp3", duration = 72.4636735, start = 0},
  },
}
P.transport["quest:8828"] = {
  hash = "1ded3e",
  fullHash = "1ded3e",
  text = "Winter's Presents. In Orgrimmar, Winter's Presents await beneath the festive tree during the Feast of Winter Veil. Holiday organizers and goblin apparatus tenders direct Horde heroes to Great-father Winter, where gifts have been prepared for them. The Feast of Winter Veil brings a pause for celebration to Orgrimmar as the chill winds of late year sweep across Durotar. Promoters from Smokywood Pastures and holiday enthusiasts spread word through the capital that gifts wait beneath the decorated tree. Warriors, hunters, and wanderers resting in the city are all invited to share in the season’s generosity. Great-father Winter sits among holiday ribbons and packaged cartons near the Smokywood Pastures market. The ancient figure marks the season’s renewal, while goblin merchants nearby offer seasonal wares and festive treats to visitors.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8828-5d794a612b0f0280573d/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:8851"] = {
  hash = "6affc8",
  fullHash = "6affc8",
  text = "Five Signets for War Supplies. Orgrimmar's stores gather supplies for the Horde's campaign across Kalimdor. Workers earn commendation signets for their contributions, and Warlord Gorchuk exchanges them for supplies to equip the fighters. Across Kalimdor, the Horde gathers raw goods, weapons, and provisions for a vast campaign. Gatherers and tradesfolk bring bandages, metals, and herbs into the cities, where military overseers award commendation signets for their work. The tokens mark each contribution to the stockpile growing along Orgrimmar's central avenues. Warlord Gorchuk knows the wider war effort needs supplies, but each warrior also needs gear and provisions to survive the march into battle. Fighters can trade their commendation signets back into the Horde's stores for field supplies and surplus materiel, giving up personal recognition for what they need on the front.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_8851-9df01d2305b8e39c9dd1/1-0000.mp3", duration = 49.3714286, start = 0},
  },
}
P.transport["quest:886"] = {
  hash = "b7ed7e",
  fullHash = "b7ed7e",
  text = "The Barrens Oases. High on the Elder Rise of Thunder Bluff, Arch Druid Hamuul Runetotem senses an unsettling surge of power flowing into the arid soils of the Barrens. To uncover the truth, he dispatches promising travelers eastward past Mulgore's gates to rendezvous with his kinsman, Tonga Runetotem, at the Crossroads. This mission marks the beginning of an investigation into the unnatural waters springing up across the sun-baked plains. While the plains of Mulgore flourish under the watchful gaze of the Earth Mother, the vast savannas of the Barrens to the east have remained harsh, scorched, and dry for generations. Recently, however, the tauren druids meditating atop Thunder Bluff's Elder Rise have detected strange currents of energy waking deep beneath the parched plains. Life is stirring where it ought not to be, and the Cenarion Circle fears that whatever force is causing this surge may harbor hidden peril for the land and its creatures. To investigate these strange occurrences, Arch Druid Hamuul Runetotem dispatched Tonga Runetotem into the field. Recognizing that the vast wilderness holds dangers too great for one investigator alone, Hamuul enlists travelers leaving Mulgore to hasten after Tonga. Following the road east past Bloodhoof Village and through the mountain passes leads straight to the Crossroads—the dusty, bustling heart of Horde territory in the Barrens—where Tonga awaits answers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_886-356032a82b6f4dc3bd58/1-0000.mp3", duration = 81.1885714, start = 0},
  },
}
P.transport["quest:887"] = {
  hash = "fc8f2a",
  fullHash = "fc8f2a",
  text = "Southsea Freebooters. Along the Merchant Coast south of Ratchet, Southsea Freebooters strike goblin trading vessels. Gazlowe hires adventurers to attack their camp and curb the raids. Ratchet's trade suffers from pirates on the Merchant Coast. The port sits in central Kalimdor, where merchant vessels travel between Kalimdor and the eastern continents. South of town, Southsea Freebooters hold a fortified beach camp. From there, they attack goblin cargo ships arriving and departing, cutting into profits and disrupting local shipping lanes. Gazlowe blames the pirates and the Steamwheedle Cartel's naval leaders. The Trade Princes have spent immense sums on defensive fleets, yet Vice Admiral Grezzlik has failed to patrol the waters effectively. Frustrated by Undermine's slow response, Gazlowe hires independent mercenaries to thin the pirate brigands and cannoneers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_887-2c74243345483d3782d6/1-0000.mp3", duration = 49.5281633, start = 0},
  },
}
P.transport["quest:888"] = {
  hash = "589d90",
  fullHash = "589d90",
  text = "Stolen Booty. Pirate cargo off Ratchet’s coast has left Gazlowe choosing what matters most. Stolen Booty brings him two vital goods: boots for local laborers and a delicate telescopic lens needed to complete his observatory. The Southsea Freebooters have troubled merchant lanes across the Great Sea for years. Their fortified camp just south of Ratchet brought them into direct conflict with Gazlowe. Pirates intercepted merchant vessels bound for the port and took valuable supplies from the Steamwheedle Cartel. Some goods could be written off as a cost of shipping. Specialized cargo mattered enough for Gazlowe to hire mercenaries to break into the pirate stronghold. Gazlowe has two practical priorities. Drizzlik sent a needed shipment of boots from Booty Bay for local laborers. The other item is specialized: a ground telescopic lens made for the observatory tower overlooking Ratchet. Its twin arrived safely by caravan through Durotar, but pirates seized this lens at sea. Until it is recovered, the observatory remains an empty frame.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_888-815639b5fb20d7886af0/1-0000.mp3", duration = 59.924898, start = 0},
  },
}
P.transport["quest:890"] = {
  hash = "91f634",
  fullHash = "91f634",
  text = "The Missing Shipment. In Ratchet, Gazlowe waits for goods sent from Booty Bay across the Great Sea. He sends couriers to Wharfmaster Dizzywig to check the dock records, while the Southsea Freebooters remain a possible cause of the delay. Ratchet is the Steamwheedle Cartel's trading port on Kalimdor. Ships cross the Great Sea from Booty Bay with manufactured goods, exotic supplies, and heavy freight for the town's building and trade. When cargo goes missing, business suffers. Chief Engineer Gazlowe keeps close track of every crate brought into port. The Southsea Freebooters haunt the coast south of Ratchet and often intercept merchant ships. Gazlowe checks his records before accusing the pirates or sending anyone into a fight. He sends his inventory ledger to Wharfmaster Dizzywig at the docks. Dizzywig oversees the unloading and storage of ship cargo, and can check whether goods were lost at sea or misplaced in a warehouse.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_890-4325dd5434800c0c07a3/1-0000.mp3", duration = 51.3828571, start = 0},
  },
}
P.transport["quest:892"] = {
  hash = "ed2b58",
  fullHash = "ed2b58",
  text = "The Missing Shipment. At Ratchet’s docks, Dizzywig’s ledger points away from harbor graft and toward the Southsea Freebooters. Gazlowe receives the records and prepares to reclaim his lost cargo. Ratchet’s trade and its port bring constant logistical headaches. When a shipment fails to arrive, Gazlowe suspects bad harbor accounts or foul play on the piers. Wharfmaster Dizzywig examines the manifest and insists his books are clean. The intake records account for everything, so the missing merchandise never made it onto the dock.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_892-173dc229611cf3e7a0cb/1-0000.mp3", duration = 30.9028571, start = 0},
  },
}
P.transport["quest:894"] = {
  hash = "7d9f57",
  fullHash = "7d9f57",
  text = "Samophlange. At a Venture Company outpost in the northern Barrens, Sputtervalve wants a device called a samophlange. He sends you southwest of the Sludge Fen to find it. In the northern Barrens, Sputtervalve cannot explain what the Venture Company is building. The goblin engineer and tinker works in Ratchet, while the rival company experiments southwest of the Sludge Fen. Its people call one device a samophlange. Sputtervalve does not know its purpose or value, but wants to study its design before his competitors can profit from it. The Venture Company guards its research site with armed overseers, deforesters, and machinery. Sputtervalve gives you an intercepted operating manual to help shut down the rig safely. At the central control station, you find a locked console with levers, lights, and gauges. Three control valves keep the rig's pressure in order.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_894-b8f60c632e3adf99bc0d/1-0000.mp3", duration = 47.7779592, start = 0},
  },
}
P.transport["quest:895"] = {
  hash = "76f4a2",
  fullHash = "76f4a2",
  text = "WANTED: Baron Longshore. On Ratchet's docks, Chief Engineer Gazlowe posts a bounty for Baron Longshore. The pirate captain hails from Gilneas and commands vessels of the Southsea Freebooters. His presence along the Merchant Coast threatens goblin merchant shipping across the region. South of Ratchet, the Southsea Freebooters hold fortified camps along the Merchant Coast. Their pirates harass merchant vessels and disrupt the sea lanes the Steamwheedle Cartel relies on between Ratchet, Booty Bay, and points beyond. Under captains such as Baron Longshore, the raids drain the local goblin administration and threaten trade along the coast. Baron Longshore comes from Gilneas, the isolated human kingdom across the sea. On Kalimdor, he commands the pirate vessel Heedless and leads crews ashore just north of Northwatch Hold. Chief Engineer Gazlowe answers with a bounty, calling for Longshore's identifiable head.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_895-b2dbf97a4c6a53f21362/1-0000.mp3", duration = 53.6816327, start = 0},
  },
}
P.transport["quest:896"] = {
  hash = "cfac34",
  fullHash = "cfac34",
  text = "Miner's Fortune. Wharfmaster Dizzywig has heard of a fist-sized emerald at the Venture Company's Boulder Lode Mine. He hires you to take the Cats Eye Emerald from the mine's supervisors and share the profits. Wharfmaster Dizzywig hears the merchants who pass through Ratchet's harbor on the routes between Ratchet and Booty Bay. Word reaches him of a huge gem found deep in the Boulder Lode Mine. The Venture Company strips the northern Barrens for its own gain, so few are likely to ask questions if its finest recent find disappears. Northeast of the Sludge Fen, laborers fill the Boulder Lode Mine's rocky shaft. The Venture Co. Overseers and Enforcers have taken the Cats Eye Emerald, and an ordinary digger cannot claim a prize so rare. You need to face the armed managers, secure the stone, and bring it to Dizzywig. He can judge its value against the market in Undermine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_896-d89a756782dac2aa1abb/1-0000.mp3", duration = 49.2146939, start = 0},
  },
}
P.transport["quest:900"] = {
  hash = "166a2d",
  fullHash = "166a2d",
  text = "Samophlange. At the Sludge Fen, Samophlange machinery keeps the Venture Company's digging rig running. Three valves must be sealed before the central apparatus can be shut down safely. At the Sludge Fen, the Venture Company's machinery is complex and dangerous. The central console makes clear that the core cannot be stopped with a single switch. Its feed lines must be handled by hand first, or the apparatus could fail or explode. Three valves control the flow into the rig: the Main Control Valve, the Fuel Control Valve, and the Regulator Valve. Each must be sealed by hand against high pressure. As they close, the console's green indicators fade to yellow, making it safe to engage the central shutoff.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_900-d916655f1285e0e7deaa/1-0000.mp3", duration = 41.2212245, start = 0},
  },
}
P.transport["quest:901"] = {
  hash = "ebaa7b",
  fullHash = "ebaa7b",
  text = "Samophlange. At the Sludge Fen, the Venture Company’s machinery waits with its valves shut and its pressure relieved. Tinkerer Sniggles holds the key to open the control unit and free the samophlange within. You have relieved the pressure by turning the auxiliary valves, and the dials and gauges have settled. The housing remains locked against tampering. Its key rests with the goblin engineer overseeing the drilling site. Tinkerer Sniggles oversees the Venture Company’s equipment at the Sludge Fen. He keeps the console key in a hut just northeast of the main rig. You need that key to open the housing and reach the samophlange.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_901-5245e9ff66a880632098/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["quest:902"] = {
  hash = "f3058a",
  fullHash = "f3058a",
  text = "Samophlange. At the Venture Company console, you uncover the elusive samophlange and carry it to Ratchet. You have shut down the controls and their defenses; now the delicate device is ready for Sputtervalve to examine. Behind the Venture Company console's faceplate, wiring and purposeless tubing crowd around strange engineering. Deep inside lies the samophlange, a core component that has baffled engineers across the region. With a firm tug, you free the device from its housing and carry it back to the goblin who began the recovery effort.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_902-4ded61e9df447e3e631d/1-0000.mp3", duration = 29.7795918, start = 0},
  },
}
P.transport["quest:903"] = {
  hash = "745a33",
  fullHash = "745a33",
  text = "Prowlers of the Barrens. At the Crossroads, Sergra Darkthorn sends you after the savannah prowlers. Their claws will show whether you can face the Barrens' greatest beasts. Sergra Darkthorn tests hunters who have already faced the plainstriders and zhevras. Southwest of the Crossroads, savannah prowlers vanish into the central Barrens' gold and ochre scrub. These great cats hunt instead of grazing with the herds. They wait in tall grass, then ambush their prey, and unwary travelers can fall to them. Sergra warns you that prowlers know how to hunt. Read the grasses and strike before a cat leaps if you mean to claim its paws and claws. Bring back seven prowler claws to show you have the cunning and quick reflexes to survive against Kalimdor's deadliest wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_903-f19cf476f7a6ae23475c/1-0000.mp3", duration = 43.1281633, start = 0},
  },
}
P.transport["quest:905"] = {
  hash = "746669",
  fullHash = "746669",
  text = "The Angry Scytheclaws. South of the Crossroads, Sergra Darkthorn sends hunters to face the savage scytheclaws stalking the Barrens. Bring sunscale raptor feathers to their breeding nests, and prove your courage in a land that gives little quarter. Sergra Darkthorn tests hunters against the beasts of the Barrens. After lesser trials, she sends you south of the Crossroads to hunt vicious sunscale raptors and take their feathers. Then you carry those feathers southwest of the Stagnant Oasis, into the heart of raptor territory. Placing them in the nests is the true test: it shows you can face the scytheclaws without fear. Three raptor nests lie southwest of the Stagnant Oasis, near the Gold Road. Red, blue, and yellow eggs mark the separate clutches. Scytheclaws defend their nests fiercely against anything that comes near. Place the feathers of fallen raptors among the eggs, and you make your challenge clear to the beasts. Return to the Crossroads after entering the nests, and Sergra can see you have faced the danger and lived. Walking out of a raptor den takes raw courage. The Barrens test every hunter; each fight may harden you, or leave your bones among the kodo ribs scattered across the dirt.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_905-edc1f4e1a8a77cfd2d57/1-0000.mp3", duration = 68.1534694, start = 0},
  },
}
P.transport["quest:907"] = {
  hash = "c0870e",
  fullHash = "c0870e",
  text = "Enraged Thunder Lizards. In the southern Barrens, thunder lizards roam the plains around Camp Taurajo. Jorn Skyseer calls hunters to face the great beasts and bring back their blood as part of a wider rite of passage. After defeating the raptor Ishamuhale, you return to Camp Taurajo. The tauren elder Jorn Skyseer now tests your strength against the largest grazers of the land. Stormsnouts and Thunderheads roam the southern Barrens, their heavy strides able to crush an unwary hunter beneath them. Tauren and orc hunters prize poise, position, and strength when facing a thunder lizard. Jorn asks you to bring back samples of their potent blood, proof that you stood in the path of the rumbling beasts and survived with your bones unbroken. The trophy opens the way to Jorn's final quarry in the skies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_907-3ea53f9e5a917c7ce209/1-0000.mp3", duration = 46.3412245, start = 0},
  },
}
P.transport["quest:90902"] = {
  hash = "cea1ca",
  fullHash = "cea1ca",
  text = "Rediscovering the Light. Offered by Aramis Hammerhand in Deathknell, this task challenges newly raised Forsaken paladins to embrace the Holy Light once more. Calling upon holy powers inflicts intense agony upon undead flesh, requiring fledgling paladins to channel healing into injured Deathguards despite the burning torment. For former champions of the Silver Hand and fallen knights of Lordaeron, awakening in undeath means confronting a horrifying reality: the Holy Light still answers their call, but it burns their withered bodies from within. Aramis Hammerhand instructs newly risen Forsaken paladins that abilities once practiced as second nature now bring excruciating pain. Because holy energy naturally conflicts with the foul magic sustaining undeath, channeling the Light requires raw willpower and agonizing perseverance. Rather than allowing this torment to deter them, Forsaken paladins view the pain as an enduring testament of faith. Deathguard throughout Deathknell suffer grievous wounds combating mindless zombies, and it falls upon these undead knights to restore them. Aramis teaches that pushing through the burning pain is like exercising an atrophied muscle—the agony itself is treated as a badge of honor and living proof that the Light has not forsaken them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_90902-4d1fe03abaaf0a96e2f9/1-0000.mp3", duration = 72.0457143, start = 0},
  },
}
P.transport["quest:91208"] = {
  hash = "73b928",
  fullHash = "73b928",
  text = "Coming to Terms. Offered by Aramis Hammerhand in Deathknell, this quest tasks newly risen paladins with reaching out to a fellow knight struggling to accept undeath. Fleeing into the hills in terror, the newly returned warrior faces the agonizing realization of becoming what she once fought against. Awakening from death into the ranks of the Forsaken is jarring for anyone, but for former paladins of the Silver Hand, the shock is visceral. Having dedicated their mortal lives to destroying the undead in service to the Holy Light, these individuals suddenly find their souls tethered back to decomposing flesh. While some adapt under the guidance of Aramis Hammerhand, others are overwhelmed by horror and confusion, fleeing into the Tirisfal wilderness rather than confronting their grim new existence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_91208-59e75b870749be883ed5/1-0000.mp3", duration = 44.4865306, start = 0},
  },
}
P.transport["quest:91209"] = {
  hash = "28665e",
  fullHash = "28665e",
  text = "Continue Your Training. This quest directs newly risen Forsaken paladins to leave Deathknell and travel to Brill for advanced instruction. Entrusted by Aramis Hammerhand, the journey introduces the fledgling holy warrior to the wider perils of Tirisfal Glades. It also serves as a stark warning about the deep suspicion that holy practitioners face among the undead. Once a newly awakened soul has mastered the rudiments of martial combat and channelled holy power within Deathknell's cloistered graveyard, Aramis Hammerhand sends them east into the broader expanse of Tirisfal Glades. Their destination is Brill, a bustling regional outpost serving as the administrative hub for central Tirisfal. There, Shari Stilwell oversees the advancement of those who dare walk the path of the paladin in undeath. Aramis offers parting advice that underlines the fraught reality of being an undead paladin. While Lordaeron still requires defenders against external threats, wielding the Holy Light under Sylvanas Windrunner's banner draws bitter suspicion. Countless Forsaken suffered agony or death at the hands of holy zealots, and the mere presence of the Light breeds distrust among their undead peers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_91209-c572398c6b32eb62a419/1-0000.mp3", duration = 67.5265306, start = 0},
  },
}
P.transport["quest:916"] = {
  hash = "512570",
  fullHash = "512570",
  text = "Webwood Venom. In Shadowglen, Gilshalan Windwalker studies the giant webwood spiders of Shadowthread Cave. He asks young night elves to gather venom sacs so he can learn how Teldrassil's growth has affected the forest's wildlife. Gilshalan Windwalker has come to Shadowglen to study the webwood spiders in Shadowthread Cave. They are far larger and more aggressive than their cousins elsewhere. He suspects Teldrassil's immense magical energies are changing the local wildlife. He asks for venom sacs to compare with those of ordinary spiders and learn what has changed. Webwood spiders live in and around Shadowthread Cave, where they threaten young night elves in the glen. Gathering their venom can help thin their numbers and give Darnassian researchers evidence of Teldrassil's effect on the wild.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_916-96fba3580e336246ee4a/1-0000.mp3", duration = 43.2065306, start = 0},
  },
}
P.transport["quest:917"] = {
  hash = "564f59",
  fullHash = "564f59",
  text = "Webwood Egg. In Shadowglen, Gilshalan Windwalker seeks an unhatched Webwood Egg for his study of Teldrassil’s wildlife. After gathering venom samples, he needs a living specimen to examine the unnatural aggression afflicting the forest’s creatures. An egg can be studied safely without subduing a full-grown spider. Gilshalan Windwalker needs live subjects to understand the unnatural corruption affecting the Webwood spiders around Shadowglen. You have secured raw venom from the aggressive spiders, but carrying a thrashing giant out of the depths would be deadly for a novice. Gilshalan asks you to bring back an unhatched egg from the brooding clutches inside Shadowthread Cave. Webwood spiders brood in Shadowthread Cave, where the forest’s increasingly hostile arachnids make their nests. An intact egg gives scholars a controlled subject that can hatch under containment. Gilshalan plans to bundle it with his venom samples and send both to Darnassus for examination. With his local study complete, he directs recruits toward higher duties in the boughs of Aldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_917-8c31594d62e633f32994/1-0000.mp3", duration = 62.3020408, start = 0},
  },
}
P.transport["quest:918"] = {
  hash = "91ca70",
  fullHash = "91ca70",
  text = "Timberling Seeds. At Lake Al'Ameth, botanist Denalan studies the growing hostility of Teldrassil's nature elementals. He seeks to harvest Timberling Seeds and test whether enriched soil can help them grow calmer. His work is one quiet effort by night elf herbalists to understand the subtle afflictions troubling the World Tree. Timberlings are nature elementals native to Teldrassil's boughs, closely bound to the health and vitality of the surrounding flora. They are usually peaceful reflections of the forest's balance, but their recent hostility has alarmed the local night elves, and no cause is known. Botanist Denalan hopes to learn what has stirred them rather than simply cull them. Denalan suspects the blemish lies deep in the ground. He hopes to sprout fresh timberlings, a gentler generation of elementals, in enriched and carefully treated loam. By harvesting seeds from wandering timberlings near Lake Al'Ameth, he aims to learn whether the land's corruption can be countered from the roots up.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_918-b55907ee0c7bf21a1b9a/1-0000.mp3", duration = 57.4432653, start = 0},
  },
}
P.transport["quest:919"] = {
  hash = "512bc7",
  fullHash = "512bc7",
  text = "Timberling Sprouts. Around Lake Al'Ameth, Timberling Sprouts are spreading across Teldrassil. Denalan asks you to uproot them before they grow into hostile timberlings. Corrupted sprouts are spreading along Lake Al'Ameth's banks. Denalan lives beside the lake and knows these young plants cannot be healed. Left alone, they quickly grow into aggressive, bark-covered timberlings that threaten wildlife and travelers. Uprooting the sprouts helps protect the grove. Denalan is troubled by how quickly new sprouts appear across Teldrassil. Their spread points to a sickness in the World Tree's roots and soil, and Denalan and the druids of Darnassus seek its cause.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_919-1407521be1b5196a778a/1-0000.mp3", duration = 36.8065306, start = 0},
  },
}
P.transport["quest:920"] = {
  hash = "480fce",
  fullHash = "480fce",
  text = "Tenaron's Summons. In Shadowglen, Tenaron's Summons calls you to Aldrassil. After helping Gilshalan Windwalker with woodland dangers, you are asked to meet Tenaron Stormgrip high in the great tree. The call draws you from local troubles toward the spiritual afflictions touching Teldrassil. Your work against the venomous spiders and corrupted wildlife in the glen has reached Tenaron Stormgrip. Gilshalan Windwalker tells you the elder has asked for your presence. Even night elves, with their long lives, know better than to keep an elder waiting atop Aldrassil. Tenaron waits in Aldrassil's highest chamber, looking across Shadowglen's boughs. Meeting him brings you into wider concerns of stewardship, including the cleansing of Teldrassil's moonwells and the corruption spreading through the young World Tree's ecosystem.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_920-8a3d56b81d4152ad0b3a/1-0000.mp3", duration = 45.5314286, start = 0},
  },
}
P.transport["quest:921"] = {
  hash = "cd7bbd",
  fullHash = "cd7bbd",
  text = "Crown of the Earth. At Aldrassil, Tenaron Stormgrip asks young night elves to draw sacred water before they leave Shadowglen. The rite recalls Mount Hyjal and the immortality their people gave up there. Before young night elves leave Shadowglen, their elders teach them what their people lost. At the Battle of Mount Hyjal, the kaldorei sacrificed the World Tree Nordrassil to defeat Archimonde and banish the Burning Legion. The blast cost them their ageless immortality and sacred shield. Tenaron Stormgrip teaches this history as he gives novices a rite, preparing them with humility and purpose for a changing world. To complete the rite, you draw water from the moonwell north of Aldrassil with a crystal phial. Moonwell waters carry remnants of the ancient Well of Eternity. Druids channel their restorative power into the wild, while Sentinels honor the wells as tranquil shrines to Elune. The kaldorei remain wary: arcane sorcery is forbidden, and the wellspring that sustains their land recalls the reckless magic that nearly broke the world.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_921-7d24fc76fe350d229750/1-0000.mp3", duration = 59.8987755, start = 0},
  },
}
P.transport["quest:92124"] = {
  hash = "d874ac",
  fullHash = "d874ac",
  text = "Book Inventory. At Northshire Abbey, Brother Paxton is frustrated by misplaced and missing tomes. He asks young adventurers to find Daniel, his daydreaming assistant, and take stock of the library archives, but Daniel's thoughts keep wandering to local tradeskills, making a straight answer hard to get. Northshire Abbey preserves old scholarly works, spiritual writings, and historical records that survived the First War in the Kingdom of Stormwind. Brother Paxton, a meticulous monk, takes great pride in the collection. Lately, books have gone missing from the shelves, and Paxton needs a clear inventory to learn how widespread the loss is. He has little patience to chase after his daydreaming helper. Daniel works as Brother Paxton's assistant in the abbey library, but his thoughts rarely stay with parchment and catalog numbers. He is fascinated by the practical trades of Elwynn Forest: smithing, leatherworking, tailoring, and herbal craft. Paxton grows exasperated as inventory work leads Daniel to ramble about local crafters instead of locating lost scriptures.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92124-f3ef6c5a9550d233427c/1-0000.mp3", duration = 61.5967347, start = 0},
  },
}
P.transport["quest:922"] = {
  hash = "0e90f8",
  fullHash = "0e90f8",
  text = "Rellian Greenspyre. At Denalan's lakeside retreat in Teldrassil, you carry a timberling seed to Rellian Greenspyre in Darnassus. The handoff brings news of trouble spreading through the World Tree's boughs. Denalan has studied the plants and elemental life around Lake Al'Ameth. After gathering seeds from the local timberlings, he sends you to Darnassus with a sample for his colleague, Rellian Greenspyre. Rellian is a druid who walks the Cenarion Enclave's terraces. He had shown interest in Denalan's research and hopes to grow a timberling of his own.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_922-8b7acdb32712ba450d63/1-0000.mp3", duration = 31.3730612, start = 0},
  },
}
P.transport["quest:923"] = {
  hash = "8a2d3d",
  fullHash = "8a2d3d",
  text = "Tumors. In Darnassus, the Cenarion Circle seeks to contain the sickness spreading through Teldrassil. You are sent to Wellspring Lake to gather mossy tumors from afflicted timberlings, so druids can study the poison and burn the growths safely. Teldrassil’s native plants and animals are being twisted by a strange affliction. Its timberlings, usually placid nature spirits with bark for skin, have grown hostile and erratic. Grotesque mossy tumors spread across their living wood, pulsing with unnatural poison. Cenarion scholars Denalan and Rellian Greenspyre search for the cause, while timberlings already lost to the sickness must be culled to protect the rest of the boughs. Wellspring Lake in northern Teldrassil has become a focal point of the outbreak, and its timberlings are among the most tainted on the World Tree. Rellian Greenspyre asks you to kill these corrupted guardians and cut away their tumors. Bring the growths to the druids in Darnassus, where they can be burned safely. The night elves hope this will slow the contagion while they search for the disease’s source.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_923-b038171e9bf700d55592/1-0000.mp3", duration = 62.6938776, start = 0},
  },
}
P.transport["quest:924"] = {
  hash = "f14639",
  fullHash = "f14639",
  text = "The Demon Seed. Neeru Fireblade's orders reach Ak'Zeloth, who sends Horde travelers to destroy the Demon Seed atop Dreadmist Peak. An unstable Flawed Power Stone can break the Burning Legion's conduit before its influence spreads farther through the Barrens. High in a cave on Dreadmist Peak, the Demon Seed hangs above an altar of fire. The artifact anchors demonic power in the heart of the Barrens for the Burning Legion. The orc Ak'Zeloth prepares specialized power stones to break its link to the Nether. One must reach the peak before the stone's unstable energy runs out.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_924-3eb37bf2a53dcc741b6f/1-0000.mp3", duration = 30.484898, start = 0},
  },
}
P.transport["quest:92460"] = {
  hash = "9930e1",
  fullHash = "9930e1",
  text = "Coming of Age. Coming of Age marks the initial rite of passage for young Skyborne taking their first steps beyond Thendal Village on Zephras Isle. Guided by Ailee Farheart, novices report to village leader Rorian the Dayseeker to receive an ancestral relic and formally pledge their aid to the shen'dorei. For every young Skyborne coming into adulthood, the journey begins in Thendal Village. Guided forward by Ailee Farheart, fledglings make their way just west to the greatfather tree where the village elder awaits. Passing into maturity among the shen'dorei is not merely a social milestone, but a ceremonial commitment to serve their community amid rising local troubles. At the entrance of the greatfather tree, Rorian the Dayseeker presides over the ceremony. He formally bestows an ancestral relic upon the initiate—an heirloom passed through generations of shen'dorei. Borne by many who came before, the relic serves as a lasting token of the winds of home, destined to return to the people only when its bearer's ashes are scattered to the breeze.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92460-f9923eac0cc3cc33f28c/1-0000.mp3", duration = 61.9885714, start = 0},
  },
}
P.transport["quest:92461"] = {
  hash = "094d0d",
  fullHash = "094d0d",
  text = "Harmony in Balance. Harmony in Balance is an early rite of duty given to fledgling adventurers on Zephras Isle by Rorian the Dayseeker. It tasks the player with culling juvenile vuldren in Thendal Grove to preserve the natural equilibrium of the island. Through this mundane necessity, novices learn how sensitive local beasts are to the shifting magical currents around them. Even in an era defined by uncertain futures and mounting peril, daily survival on Zephras Isle requires humble diligence. In Thendal Grove, the local vuldren population has grown at an unsustainable rate, threatening the delicate environmental harmony that sustains the island's wildlife. Rorian the Dayseeker assigns young protectors the sober task of thinning their numbers to avert widespread ecological strain. While culling wild beasts may appear to be ordinary gamekeeping, the vuldren's surge reflects deeper concerns. Though typically docile creatures, the wildlife of Zephras is attuned to the island's atmosphere and reacts sharply when the magic carried on the winds falls out of balance. Correcting imbalances early prevents docile creatures from degenerating into unpredictable and dangerous pests.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92461-61ddce747caad133537e/1-0000.mp3", duration = 69.0416327, start = 0},
  },
}
P.transport["quest:92462"] = {
  hash = "564dfe",
  fullHash = "564dfe",
  text = "Infestation Investigation. Infestation Investigation is an early task given to young adventurers stepping out into Thendal Grove on Zephras Isle. Ranger Elatrell Featherlight orders a cull of pesky cirrusflies that have begun swarming the eastern groves. Left unchecked, the fast-breeding insects threaten to destabilize the peaceful grove and endanger local settlements. Thendal Grove has long maintained a delicate balance, but recent reports by local rangers indicate a sudden population surge of pesky cirrusflies on the eastern edge of the woods. While individual cirrusflies are minor pests, their swarms quickly turn aggressive and destructive when numbers balloon. Ranger Elatrell Featherlight wastes no time dispatching capable youth to cull the flying insects before their presence completely overwhelms the grove. Following their initial coming of age, young defenders are thrust directly into the practical upkeep of Zephras Isle. Clearing out pests might seem like menial labor, but keeping the woodlands safe from creeping wildlife outbreaks is vital to safeguarding the settlements nearby. The sheer abundance of entrails and insects clinging to returning hunters proves that the swarm's scale is far worse than initially feared.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92462-73d54ed7ee18132cfafc/1-0000.mp3", duration = 70.1387755, start = 0},
  },
}
P.transport["quest:92463"] = {
  hash = "1e356c",
  fullHash = "1e356c",
  text = "The Cirrusfly Queen. The Cirrusfly Queen is a hunt targeting the matriarch of the aggressive insect hive dwelling in Thendal Grove on Zephras Isle. Following early reconnaissance of the infestation, Elatrell Featherlight directs recruits into the heart of the grove to eliminate the queen and cull the swarm at its source. Ending her reign provides immediate relief to the local rangers working to keep the wilderness manageable. Initial efforts against the cirrusflies revealed that simply swatting away stray worker drones would never curb the infestation spreading across Thendal Grove. Elatrell Featherlight tasks capable wanderers with penetrating deeper into the southeastern reaches of the grove where the main hive lies. There, the queen directs the colony under the vigilant protection of heavier soldier drones. While common cirrusflies might seem like petty pests from a distance, their larger breeds pose a serious physical danger to anyone passing beneath the boughs of Zephras. By hunting down the matriarch and withstanding her guards, novices prove their martial mettle, earning high praise and a nod of respect from Featherlight's ranger cadre.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92463-f854fe796e25a9d3c492/1-0000.mp3", duration = 62.8767347, start = 0},
  },
}
P.transport["quest:92464"] = {
  hash = "6b57ba",
  fullHash = "6b57ba",
  text = "Elemental Unrest. Elemental Unrest is an introductory task given by Rorian the Dayseeker on Zephras Isle. Following the departure of the island's sentient elemental benefactors, the lesser wind spirits near the Thendal Standing Stones have grown agitated and unpredictable. You are sent into Thendal Grove to find Rorian's apprentice, Yala Windwatcher, and discover what is unsettling the local breeze. For generations, the people of Zephras lived alongside powerful, sentient wind spirits who guided and protected them. With those elemental benefactors gone, the island has drifted into persistent imbalance. The air is no longer tended by benevolent minds, leaving only simple sprites that reflect the volatile emotions and forces lingering across the landscape. Northeast of Rorian's post, near the ancient Thendal Standing Stones, the air has grown sharply hostile. Because these lesser manifestations lack true self-awareness, their turbulence is not born of malice, but of reaction. Rorian sent his apprentice, Yala Windwatcher, to monitor their erratic behavior from the edge of the grove and deduce what unseen tension is disturbing them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92464-48bcf241866209ecc48c/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["quest:92465"] = {
  hash = "e28b54",
  fullHash = "e28b54",
  text = "Agitators. Agitators is an early task on Zephras Isle issued by Yala Windwatcher. The aggressive Al'Aketh cult has pushed into Thendal Grove, agitating the peaceful native wind sprites into hostile elementals. Adventurers are sent to disperse the roiling winds and clear out the cultist converts threatening the area. Thendal Grove has fallen under the shadow of the Al'Aketh cult. Known for their unsettling designs on Zephras Isle, the cultists have encroached on the grove and actively riled the delicate wind spirits dwelling there. Once peaceful sprites have turned violent, forming volatile roiling winds that threaten anyone passing through the region. Yala Windwatcher tasks passing champions with subduing both the enraged elementals and the Al'Aketh converts fomenting the unrest. While putting down the wind creatures restores a fragile calm to the grove, dealing with the cultists is a somber duty: Yala laments the shedding of shen'dorei blood among their own people, yet recognizes that the cult leaves little choice.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92465-e5368364ef95b635612a/1-0000.mp3", duration = 58.4620408, start = 0},
  },
}
P.transport["quest:92469"] = {
  hash = "616e72",
  fullHash = "616e72",
  text = "Return to Rorian. Return to Rorian is a mission carrying urgent reports from the field back to Thendal Grove on Zephras Isle. After aiding Yala Windwatcher against encroaching forces, an adventurer is dispatched to inform Rorian the Dayseeker that the Al'Aketh cult has actively escalated their presence by disturbing the local wind spirits. Following the disruption dealt to the agitators harassing Zephras Isle, Yala Windwatcher stays behind to mop up remaining hostiles while tasking you with an essential duty: delivering intelligence. Thendal Grove needs to know that the mysterious Al'Aketh are no longer operating purely in the shadows.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92469-b4384e26b230413d44a3/1-0000.mp3", duration = 35.3697959, start = 0},
  },
}
P.transport["quest:92470"] = {
  hash = "ff6349",
  fullHash = "ff6349",
  text = "Foul Matriarch. Foul Matriarch is a trial of survival assigned by Aetheen of the Gales to budding initiates in Thendal Village. The task demands delving into the southern caves to cull the scavenging ursera and slay their vicious den mother, Urs'anah. Completing the hunt proves that an adventurer possesses the resolve required to face greater perils across Zephras Isle. Aetheen of the Gales maintains a watchful eye on newcomers finding their footing around Thendal Village. Once an initiate demonstrates early competence, Aetheen issues a dangerous rite of passage: a direct assault against the predatory wildlife threatening the perimeter. Rather than simply fighting on the open paths, the initiate is sent directly into the dark caves to the south to thin the local ursera packs and confront their broodmother. The local rangers have long noted the ferocity of the ursera, but none poses a greater threat to the haven than Urs'anah, their formidable matriarch. Sheltered deep within Thendal Cave, she directs her scavengers and aggressively defends her lair. Bringing back her severed head serves as definitive proof that an adventurer is capable of handling ferocious beasts and is ready to push beyond the borders of the starting grove.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92470-64235a94980696296443/1-0000.mp3", duration = 70.9485714, start = 0},
  },
}
P.transport["quest:92471"] = {
  hash = "02a230",
  fullHash = "02a230",
  text = "Aetheen of the Gales. This quest marks a rite of passage for young adventurers on Zephras Isle, directing them to report to one of the island's leading authorities. After completing early trials under Rorian the Dayseeker, promising youths are sent into Thendal Grove to meet Aetheen of the Gales, an elder who reads the winds and evaluates the next generation. The early tasks set before novitiates on Zephras Isle are not merely mundane chores; they serve as informal tests to evaluate whether rising youths possess the grit and spirit needed to defend their homeland. Recognizing that island life faces growing trials, mentors such as Rorian the Dayseeker keep a watchful eye on candidates who prove capable of handling greater responsibility. Deep within Thendal Grove sits Aetheen of the Gales, a respected member of the Council of Elders governing Zephras Isle. Aetheen spends her time reading the currents of the air and assessing young shen'dorei as they come of age. Stepping before her signifies that an initiate has outgrown minor perimeter duties and is ready to tackle direct threats facing the community.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92471-6e408f0e29f3f43027f0/1-0000.mp3", duration = 62.6155102, start = 0},
  },
}
P.transport["quest:92472"] = {
  hash = "0867fe",
  fullHash = "0867fe",
  text = "The Next Step. Following the resolution of the immediate beast threats near Thendal Village, Elder Aetheen of the Gales directs travelers southward toward Shen'dar Village. The journey marks a shift from clearing wild fauna to confronting the organized zealotry of the Al'Aketh Cult, who revere the Windlord Al'Akir. After proving capable against the local predators and the matriarchs plaguing the northern wilderness of Zephras Isle, adventurers are called to broader duties. Elder Aetheen of the Gales recognizes that simple pest control is secondary to the true peril taking root across the island. To protect the isle's inhabitants, capable defenders must be dispatched to support the outlying settlements. The primary danger facing southern Zephras is the Al'Aketh Cult. Described as ruthless zealots, the cultists dedicate themselves to Al'Akir the Windlord, ruler of the elemental realm of Skywall. Their growing power poses an immediate menace to Shen'dar Village. In response, Aetheen sends travelers southward down the road, past lurking ambushers in the highlands, to reinforce Constable Aonda's local guard.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92472-b633abd70029b790818c/1-0000.mp3", duration = 62.0930612, start = 0},
  },
}
P.transport["quest:92473"] = {
  hash = "0fa4dc",
  fullHash = "0fa4dc",
  text = "Aggressive Encroachment. Aggressive Encroachment is a task issued by Valreaa Valewind to protect the local settlement from desperate wildlife. Ursera from a nearby den have grown increasingly bold, wandering into the village and threatening its inhabitants. The ursera population nesting southwest of the village has become an urgent safety hazard. Recently, a hungry adolescent beast strayed right up to the base of the village's central elder tree, nearly mauling a young child playing nearby. The settlement's rangers were forced to cut the creature down before tragedy struck. Recognizing that hunger and starvation are driving these predators to attack civilized grounds, the rangers have ordered a cull of the scrawniest ursera in Thendal Grove. By eliminating the desperate and malnourished beasts prowling outside the dens, the Rangers of the Grove hope to halt further encroachment until they can uncover what is disturbing the local wildlife.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92473-1c12cdd4c71e45170a84/1-0000.mp3", duration = 49.8416327, start = 0},
  },
}
P.transport["quest:92474"] = {
  hash = "447612",
  fullHash = "447612",
  text = "Falling With Style. \"Falling With Style\" is an introductory rite of passage for young Skyborne in Thendal Village. Offered atop the local watchtower by the mischievous Myriaal Mistwake, it challenges novices to test their innate slow-fall ability by leaping from the platform toward Rorian the Dayseeker below. Perched high above Thendal Village on Zephras Isle, Myriaal Mistwake invites young Skyborne to test their heritage through a game of daring. Rather than treating their innate magical gifts as sacred relics kept under strict restraint, Myriaal encourages newcomers to leap into the open air from the watchtower ledge. The purpose is practical as well as playful: mastering the instinctive art of walking upon air before life beyond the grove demands it in perilous situations. The exercise serves as a vivid demonstration of two contrasting Skyborne attitudes. While Myriaal delights in sudden descents and startles onlookers for amusement, Rorian the Dayseeker embodies traditional caution. When novices glide down to land squarely before him, Rorian admonishes the reckless display, warning that thoughtlessly exhausting one's magical gifts can leave a traveler helpless when danger strikes. Even so, he concedes that controlled practice within the safety of the village has its place.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92474-8587fbcfc40e7aba5bfc/1-0000.mp3", duration = 73.2734694, start = 0},
  },
}
P.transport["quest:92481"] = {
  hash = "dd3287",
  fullHash = "dd3287",
  text = "A Student of the Arcane. A Student of the Arcane is an introductory trial and summons for novice spellcasters on Zephras Isle. Initiated by Rorian the Dayseeker after newcomers prove their basic mettle, it directs budding mages to review a Glowing Recall Crystal and report to the local mentor, Dorii Brightwhisper. After helping manage the troublesome vuldren lurking near Thendal Grove, fledgling mages are entrusted with a curious artifact: a Glowing Recall Crystal. Left behind by Dorii Brightwhisper, the island's resident arcane instructor, the crystal serves as a magically recorded missive designed to test an initiate's aptitude and welcome them into deeper mystical study. According to Dorii Brightwhisper, mastery of the arcane has slowly dwindled among their people during their long millennia spent secluded high in the clouds. Dorii views each new practitioner not merely as a student, but as an essential pioneer meant to recover lost knowledge and restore their people's once-mighty magical heritage.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92481-4656948d9fa855a4feb6/1-0000.mp3", duration = 59.1934694, start = 0},
  },
}
P.transport["quest:92482"] = {
  hash = "d9add5",
  fullHash = "d9add5",
  text = "The Way of the Hunter. The Way of the Hunter is an introductory training quest for fledgling hunters in Thendal Grove on Zephras Isle. After proving their mettle against the local vuldren threat, young trackers are directed by Rorian the Dayseeker to present themselves to Tai'ree Farsight to begin their formal tutelage. Upon returning from thinning the disruptive vuldren prowling the outskirts of Thendal Grove, young hunters find that their practical skills have caught local attention. Rorian the Dayseeker passes along a scribbled summons from Tai'ree Farsight, the grove's resident hunter trainer. For novice rangers setting out into the wider wilds of Zephras Isle, this marked the shift from simple island defense to true martial and survival instruction. Found near the center of the village, Tai'ree Farsight welcomes promising pupils with stern realism. Emphasizing that thriving in untamed nature demands sharp senses and lightning reflexes, she offers guidance born of her own long years of experience. Her mentorship marks the foundational steps for any island tracker looking to hone their marksmanship and survival skills.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92482-7374d2c7b2907337b97e/1-0000.mp3", duration = 63.4253061, start = 0},
  },
}
P.transport["quest:92483"] = {
  hash = "30406e",
  fullHash = "30406e",
  text = "At Home in the Shadows. \"At Home in the Shadows\" is an introductory rogue quest on Zephras Isle. After aiding Rorian the Dayseeker in Thendal Grove, budding rogues are directed to read a summons and meet their local class mentor, Akeri Duskblade. The quest marks the moment young rogues transition from general village chores to serious stealth and combat training. While handling basic threats around Thendal Grove, young rogues draw the attention of Akeri Duskblade, the grove's resident rogue trainer. Rather than mingling openly in the settlement, Akeri passes a simple note through Rorian the Dayseeker. Rorian recognizes that despite Akeri's suspicious demeanor, the mentor understands the practical skills needed to survive outside the grove's sheltered boundaries. Tucked away inside the village watchtower, Akeri Duskblade wastes no time mincing words. He evaluates every newcomer's footing and awareness immediately upon their arrival, warning that sloppy footwork outside Thendal Grove leads straight to an early grave. By surviving Akeri's scrutiny, a rogue takes their first formal step into mastering stealth, precision, and survival on Zephras Isle.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92483-3b40e768d9aaa66b0cf6/1-0000.mp3", duration = 67.1346939, start = 0},
  },
}
P.transport["quest:92484"] = {
  hash = "d3e117",
  fullHash = "d3e117",
  text = "Embracing the Elements. Embracing the Elements is an introductory shaman quest in Thendal Grove on Zephras Isle. Initiated by Rorian the Dayseeker, the task directs young practitioners to Windshaper Boro, the local shaman trainer. It introduces the silent rift between the local people and the elemental spirits of the winds. After helping manage the vuldren pest problem around the village, aspiring shamans are approached by Rorian the Dayseeker. During their time afield, Windshaper Boro left behind a humming recall crystal, signaling that it is time for formal elemental instruction to begin in the center of the grove. Upon meeting Windshaper Boro, he explains the difficult state of local shamanism. The spirits of the four winds abruptly severed communication years ago, abandoning their former communion. Zephras shamans now dedicate themselves to deep study of the natural world, striving through rigorous training to bridge the silence and coax the spirits into dialogue once more.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92484-6159046c8fec65e24e3c/1-0000.mp3", duration = 58.7755102, start = 0},
  },
}
P.transport["quest:92485"] = {
  hash = "9cd6f0",
  fullHash = "9cd6f0",
  text = "A Student of Nature. A Student of Nature marks a fledgling druid's introduction to formal training on Zephras Isle. After helping restore local harmony, novice druids are summoned by Xyton Silverwind beneath the boughs of Thendal Grove. It serves as the opening gateway into understanding the deeper balance between flora and fauna on the isle. Following the resolution of local disturbances caused by overzealous wildlife, Rorian the Dayseeker delivers a personal summons to young initiates. Left behind by the local mentor Xyton Silverwind, the folded parchment invites aspiring druids to step forward and dedicate themselves to the deeper mysteries of the wild. It signals that an initiate's natural talents have caught the eye of the grove's elders. Meeting Xyton Silverwind on the lower level of the great tree in Thendal Grove anchors a novice to their calling. Silverwind regards the vibrant flora and fauna of Zephras Isle as an intricate living tapestry, one that demands constant preservation and vigilant balance. To walk the path of the fang, claw, feather, and branch requires enduring mentorship, and this meeting marks the true beginning of that lifelong stewardship.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92485-a513fc8967ad5c8c56d8/1-0000.mp3", duration = 65.7502041, start = 0},
  },
}
P.transport["quest:92532"] = {
  hash = "f41fec",
  fullHash = "f41fec",
  text = "The Warrior's Path. The Warrior's Path is an introductory martial quest offered to budding fighters on Zephras Isle. Following instructions delivered through Rorian the Dayseeker, young warriors are directed to Blademaster Ren in the Thendal Village watchtower. Ren stands ready to offer combat instruction and discipline to those prepared to shield their people. Upon returning to Rorian the Dayseeker in Thendal Village after restoring balance nearby, aspiring fighters receive word that the settlement's blademaster has taken notice of them. Rorian delivers a crumpled note penned by Ren herself, asking the novice to seek her out directly. Elevated above the settlement within the village watchtower, Ren keeps an observant eye over both the island's borders and the recruits who may one day defend them. Reaching the watchtower introduces the warrior to Blademaster Ren's philosophy of combat. To Ren, martial mastery is not simply an exercise in brute strength, but a vital duty to lead, endure, and protect in an increasingly uncertain world. She pledges her guidance to the recruit as they hone their skills, offering rigorous training as they grow strong enough to face the greater perils threatening their home.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92532-4c157fbe8b72d360b64e/1-0000.mp3", duration = 68.7020408, start = 0},
  },
}
P.transport["quest:92544"] = {
  hash = "36e415",
  fullHash = "36e415",
  text = "Al'Aketh Thugs. The peaceful roads around Thendal Grove are threatened by a violent band of Al'Aketh cultists occupying the nearby temple ruins. Dispatched from the Shrine of Akir under orders to harass wayfarers and force recruits into their ranks, these zealots pose an immediate danger to local travelers. Hanaa Nightwind tasks adventurers with breaking their hold and slaying their brutish commander. Just southwest of Thendal Grove lie ancient temple ruins that should offer quiet shelter to wanderers. Instead, the grounds have been overtaken by the Al'Aketh, an aggressive cult driven by fanatical ambition. Far from peaceful worshipers, these cultists act as highwaymen and enforcers, preying upon those traveling along the outskirts of the grove. The Rangers stationed nearby suspect these ruffians were sent directly by High Priestess Lorthuna from the Shrine of Akir to bully and coerce the populace into bowing to the cult's influence. Heading the rabble at the temple ruins is Malduko Cloudcrush, a brutal leader who uses violence and fear to keep both his initiates and unsuspecting wayfarers in line. With brutes and newly indoctrinated neophytes answering his commands, Malduko has established an aggressive outpost right on the doorstep of Thendal Grove. By striking down Cloudcrush and scattering his underlings, Hanaa Nightwind hopes to shatter the cult's confidence and send a clear warning that zealotry and coercion will not be tolerated in these lands.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92544-211e5939843ea8af511c/1-0000.mp3", duration = 82.8604082, start = 0},
  },
}
P.transport["quest:92597"] = {
  hash = "000a92",
  fullHash = "000a92",
  text = "Reading the Ley Lines. Reading the Ley Lines is a rite of passage for young Skyborne discovering their Highborne magical heritage. Entrusted by Falorne Fallwind on Zephras Isle, novitiates travel to the standing stones in Thendal Grove to sense and draw upon the raw arcane currents surging through the elemental terrain. Even within the windswept confines of the elemental plane, latent arcane conduits run beneath the earth. While strange elementals and the hostile Al'Aketh drift across Zephras Isle, subterranean ley lines have begun pushing toward the surface. To practitioners of magic, these ruptures provide direct access to untamed arcane reservoirs, offering strength to any who possess the bloodline and knowledge necessary to channel them. Falorne Fallwind urges initiates to embrace their Highborne ancestry rather than supplicate themselves to wind spirits like the local Windshapers or the zealots of the Al'Aketh. In Fallwind's view, survival against the harsh powers of the elemental plane depends not on begging foreign creatures for mercy, but on mastering the intrinsic arcane power running beneath their boots. Northeast of the settlement lies Thendal Grove, where ancient standing stones mark a potent ley line convergence. Surrounded by roiling winds and Al'Aketh converts, this exposed point of magical flux allows initiates to attune their senses, harmonizing with the pulse of the ley line and unleashing the full potential of their natural racial abilities.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92597-f778cf47b1afc191c19b/1-0000.mp3", duration = 81.0057143, start = 0},
  },
}
P.transport["quest:92598"] = {
  hash = "8118d1",
  fullHash = "8118d1",
  text = "The Gift of Skysight. The Gift of Skysight is an early rite of passage for young Windshapers learning to harness their innate connection to the spiritual realm. Under the direction of Ventaari Brightwish, initiates travel to an Elemental Convergence to awaken their perception and listen directly to the whispers of the spirits. Windshapers possess an inherent bond with the elemental forces that shape their world, embodied by the sacred faculty known as Skysight. This gift allows mortal senses to attune to spiritual wavelengths, bridging the physical gap between the living and the unseen. While a Windshaper can invoke this inner vision across the wilds, doing so near points of concentrated power deepens the connection, unlocking resonant boons and hidden wisdom whispered on the wind. Northeast of the settlement, amidst ancient standing stones, lies an Elemental Convergence in Thendal Grove. Places such as these act as focal points where raw energies gather and spirit entities linger. Ventaari Brightwish sends novices to this sacred site not simply to complete a task, but to test their spiritual constitution. Like any faculty of body or mind, Skysight requires deliberate exercise to mature, ensuring that a growing Windshaper can interpret the shifting omens of the elements upon which their people's survival depends.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92598-de993c71951eca3eb903/1-0000.mp3", duration = 74.3183673, start = 0},
  },
}
P.transport["quest:926"] = {
  hash = "518b09",
  fullHash = "518b09",
  text = "Flawed Power Stone. Across the Barrens, Flawed Power Stone rests on arcane tables, charged with arcane energy. Its makers left it fatally flawed, so it consumes its own power soon after it is moved. In the Barrens, flawed power stones hold arcane essence within compromised structures. Their makers deliberately left them unstable, so they decay into inert matter moments after someone handles them. A stone begins consuming its power as soon as it leaves the ritual table where it rests. Its energy burns away too quickly for anyone to carry it far.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_926-75f019b38b825887ad8b/1-0000.mp3", duration = 33.3844898, start = 0},
  },
}
P.transport["quest:9260"] = {
  hash = "3ab23b",
  fullHash = "3ab23b",
  text = "Investigate the Scourge of Stormwind. Scourge forces press against Stormwind, with necropolises looming beyond its walls. Lieutenant Orrin calls defenders to strike their camps, gather Necrotic Stones, and study the runes there. Scourge forces have reached the outskirts of Stormwind City. Necropolises float overhead as undead and cultists take hold near the kingdom’s greatest bastion. Lieutenant Orrin gathers defenders outside the city to drive them back before they threaten the capital. Glowing runes mark the dirt around Scourge camps, and their purpose remains unclear. The circles crackle with magic like that of the necropolises and carry eerie whispers. Lieutenant Orrin can only guess who, if anyone, hears those unnatural voices.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9260-e42c943f21ba1256d9a6/1-0000.mp3", duration = 44.0163265, start = 0},
  },
}
P.transport["quest:9261"] = {
  hash = "5ab47d",
  fullHash = "5ab47d",
  text = "Investigate the Scourge of Ironforge. Lieutenant Nevell of the Argent Dawn calls upon brave defenders as the Scourge arrives directly outside the gates of Ironforge. Undead troops and ominous runic circles threaten the snowy passes of Dun Morogh beneath a hovering necropolis. Defenders are tasked with destroying the walking corpses and deciphering the purpose behind these strange glowing sigils. The Scourge invasion does not stop at Lordaeron or the plagued lands of the north. Floating necropolises cast grim shadows across Azeroth, including the frigid heights of Dun Morogh right outside Ironforge's mountain entrance. The Argent Dawn has stationed observers such as Lieutenant Nevell to monitor and counter this creeping blight before it can breach the fortress of the Bronzebeards.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9261-fe81a8b540b6ee4045f3/1-0000.mp3", duration = 41.6914286, start = 0},
  },
}
P.transport["quest:9262"] = {
  hash = "650a1a",
  fullHash = "650a1a",
  text = "Investigate the Scourge of Darnassus. Lieutenant Beitha calls for help as the Scourge encampments press close to Darnassus. The Argent Dawn needs defenders to strike the undead and learn what the runes outside the gates are for. The Scourge has reached Teldrassil, and floating necropolises loom above the invasion camps near Darnassus. Ghouls, skeletons, and other undead horrors spill from them. Lieutenant Beitha of the Argent Dawn coordinates the city's defense, calling on volunteers to slow the attack and gather information before the undead overwhelm the night elven homeland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9262-eace40797b4003545edf/1-0000.mp3", duration = 31.5297959, start = 0},
  },
}
P.transport["quest:9263"] = {
  hash = "b93590",
  fullHash = "b93590",
  text = "Investigate the Scourge of Orgrimmar. Outside Orgrimmar, the Scourge has raised a camp beneath a floating necropolis. Lieutenant Dagel calls on defenders to repel the undead, recover necrotic stones, and examine runic circles charged with necromantic energy. The attack brings the Lich King's reach to Durotar. The Scourge now threatens lands far from Lordaeron and the northern ice. Floating necropolises cast their shadows across Azeroth, even over Durotar. Undead forces have gathered at Orgrimmar's threshold, raising camps that threaten the Horde capital. Lieutenant Dagel and the Argent Dawn coordinate the defense, calling on local champions to drive the invaders back before they can secure a siege.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_9263-13d87fd3d07acf957725/1-0000.mp3", duration = 40.8032653, start = 0},
  },
}
P.transport["quest:927"] = {
  hash = "9245ff",
  fullHash = "9245ff",
  text = "The Moss-twined Heart. Near Lake Al'Ameth, Denalan studies a strange heart taken from Blackmoss the Fetid. Dark, oily moss covers the core, yet it keeps beating after being cut from the timberling. Blackmoss the Fetid's heart still pulses after being cut from the timberling. Dark, oily moss hides nearly all of the timberling's core, but a slow rhythm continues within it. That pulse points to a corruption reaching beyond ordinary rot in Teldrassil's wild plants. Denalan, a researcher of local flora near Lake Al'Ameth, takes a keen interest in the heart and recognizes its troubling corruption. Timberlings should be gentle beings tied to the boughs of the World Tree, yet this core bears a virulent blight. Troubled by what he sees and eager to understand it, Denalan plans to plant and study the organ, hoping to learn how foul moss takes root in the island's soil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_927-a89c67e36b3691c3964f/1-0000.mp3", duration = 51.5395918, start = 0},
  },
}
P.transport["quest:92742"] = {
  hash = "aa173a",
  fullHash = "aa173a",
  text = "Testing the Wells. Alba Fairmoon sends you across Westfall to test the farm wells. The samples may reveal what is poisoning the soil and groundwater. Alba Fairmoon asks you to test Westfall's groundwater. Neglect and banditry have already hurt the open plains, and poison beneath the earth threatens the farmland that remains. You collect samples from farm wells so Alba can learn what is tainting the soil and water. You take samples from the wells at Jansen Stead and Molsen Farm. These homesteads lie among scattered farms exposed to Defias outlaws and feral wildlife. Their well water can show whether the blight is rising from the ground, caused by magic, or deliberately put into the water that feeds the region.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92742-d34ff06406af75675ace/1-0000.mp3", duration = 39.444898, start = 0},
  },
}
P.transport["quest:92744"] = {
  hash = "f4374d",
  fullHash = "f4374d",
  text = "Murloc Gills. Alba Fairmoon sends Alliance help to Westfall's Longshore to gather murloc gills. She fears the crop blight may reach the Great Sea, and the gills could reveal whether the coastal waters are tainted. Westfall is already near ruin, with crops failing, farmers displaced, and bandits roaming the roads. Alba Fairmoon fears the blight may be draining from inland fields into the Great Sea. If the coast is tainted, the fish that feed Westfall's poor and grace Stormwind City's tables could vanish. That loss could tip an already strained kingdom into outright famine. Murlocs are stubborn and violent, but their amphibious bodies make them natural signs of water quality. Their breathing constantly filters seawater, leaving their gills exceptionally receptive to poisons, blight, and unnatural pollutants. Alba Fairmoon hopes to gauge the contamination by studying fresh gills from the murlocs prowling the Longshore.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92744-68ee609ef1f290e0c47c/1-0000.mp3", duration = 51.3044898, start = 0},
  },
}
P.transport["quest:92745"] = {
  hash = "a83140",
  fullHash = "a83140",
  text = "The State of the Mines. Alba Fairmoon finds toxic metals in Westfall's wells and fears for its farmland. She suspects the mines seized by the Defias and warns the soil could fail for decades. You head to Jangolode Mine and Gold Coast Quarry to disrupt the mining. Alba Fairmoon finds dangerous levels of toxic metals in Westfall's wells. Once Stormwind's main breadbasket, the region now faces a threat to its crops. Alba suspects the mines seized by the Defias Brotherhood are poisoning the water. If the contamination continues, the surrounding earth could lie barren for decades. The Defias put local creatures to work alongside their highwaymen, stripping Westfall of its resources. Riverpaw gnolls dig for stone and minerals at Gold Coast Quarry, while kobold diggers tunnel through Jangolode Mine. Disrupting their labor weakens the Defias' ability to process and distribute contaminated minerals.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92745-23a6bb3f4d8e1fc964d6/1-0000.mp3", duration = 52.0097959, start = 0},
  },
}
P.transport["quest:92747"] = {
  hash = "892b29",
  fullHash = "892b29",
  text = "Moonbrook Espionage. Alba Fairmoon sends you to scout Moonbrook, where signs of industry trouble the Alliance. The poison found across Westfall does not seem to come from the lesser mines, so attention turns to the Deadmines beneath the town. The mines already examined across Westfall offer no answer to the poison spreading through the region. No known surface excavation appears to be its source. One major site remains unexplored: the vast shafts of the Deadmines, directly beneath Moonbrook’s ruined streets.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92747-c8c9b1659d8c7c0d65c8/1-0000.mp3", duration = 28.5257143, start = 0},
  },
}
P.transport["quest:92748"] = {
  hash = "82d31d",
  fullHash = "82d31d",
  text = "Explosive Consultation. In Westfall, toxic industry beneath the Deadmines is poisoning the farmland. You travel to Stormwind's Dwarven District to seek an engineer who can supply heavy explosives. Westfall faces displaced vagrants and banditry under the Defias Brotherhood. Evidence from across the region points to a coordinated, mechanised threat underground. Industrial refuse and caustic toxins foul the soil, and their trail leads into the Deadmines, where an organized operation works below the earth. Fortified tunnels and machinery in the Deadmines call for more than ordinary weapons. To stop the poison reaching Westfall's fields, you seek help in Stormwind City's Dwarven District. Roaring forges, tinkerers, and merchants selling blasting powder fill the district. There you look for Sprite Jumpsprocket, an engineer who can devise explosives for the work.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92748-e98e4d7e680cbb31f0c9/1-0000.mp3", duration = 48.9012245, start = 0},
  },
}
P.transport["quest:92749"] = {
  hash = "5dda95",
  fullHash = "5dda95",
  text = "A Dynamite Plan. Sprite Jumpsprocket is eager to put dynamite to work in Stormwind. The inventive tinkerer in the Dwarven District has heard talk of industrial sabotage and wants a supply of coarse dynamite to begin her plan. Sprite Jumpsprocket, a gnome engineer in Stormwind's Dwarven District, welcomes talk of industrial sabotage. Rather than urge caution, she asks passing mercenaries to bring her a bundle of coarse dynamite. You can make coarse dynamite at an engineering workbench or trade with the city's craftsmen. Sprite asks for ten sticks, enough to disrupt the industrial schemes unfolding in the surrounding territories. Her plan shows the practical, perilous methods gnomes favor when facing mechanical and political disruptions.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92749-e5fc91a6de294c68f4c1/1-0000.mp3", duration = 44.6432653, start = 0},
  },
}
P.transport["quest:92750"] = {
  hash = "c28190",
  fullHash = "c28190",
  text = "Detonation at a Distance. Sprite Jumpsprocket needs a safer way to set off explosives, and Stormwind holds the answer. She sends you to Stormwind Intelligence for a remote detonator. Sprite Jumpsprocket wants to set off explosives from a safe distance. Goblins and gnomes are known for handling volatile chemicals recklessly, but some blasts demand care. A standard fuse can put the person lighting it in danger. Sprite knows a controlled explosion needs a special trigger, the kind common tinkerers do not keep on hand. Sprite sends you to Stormwind Intelligence in Old Town instead of to local dwarven blasters or ordinary engineering suppliers. The network is known as SI:7, and its covert agents handle sabotage, stealth, and targeted demolitions. Jasper Fel works among them in the capital and can provide discreet, dangerous equipment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92750-5253cb081d10e0275f9d/1-0000.mp3", duration = 48.5877551, start = 0},
  },
}
P.transport["quest:92751"] = {
  hash = "d3f03c",
  fullHash = "d3f03c",
  text = "Detonation at a Distance. In Moonbrook, explosions beneath Westfall draw SI:7's attention. Jasper Fel, a Stormwind operative, sends a remote detonator kit to help handle the work from a safe distance. Jasper Fel and SI:7 watch events across Stormwind's lands, including Westfall's troubled border. When word reaches him of explosive work in Moonbrook, Fel already knows what is happening in the abandoned mining tunnels beneath the countryside.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92751-3551df7d0c67178a252d/1-0000.mp3", duration = 25.7044898, start = 0},
  },
}
P.transport["quest:92752"] = {
  hash = "a8da44",
  fullHash = "a8da44",
  text = "Explosive Consultation. In Westfall, Sprite Jumpsprocket sends a volatile charge to Alba Fairmoon. The primed explosives must reach her safely, with the detonator undisturbed. Sprite Jumpsprocket has finished a bundle of Extra-Destructive Explosives for Alba Fairmoon. Carrying a live charge through wartime Westfall adds danger to a road already threatened by Defias bandits and feral beasts. Sprite Jumpsprocket warns you to mind the detonator. The cargo is meant to destroy the hidden industrial operation in the Deadmines, which is poisoning Westfall's farmland. Alba Fairmoon needs the explosives intact before she can use them.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92752-14f599bd02f139834463/1-0000.mp3", duration = 36.3363265, start = 0},
  },
}
P.transport["quest:92753"] = {
  hash = "da8101",
  fullHash = "da8101",
  text = "Destruction in Deadmines. Deep beneath Moonbrook, Defias industry is poisoning the land. Alba Fairmoon suspects their metallurgical forge is the source of the blight and sends you to destroy it with explosives. Beneath Moonbrook, the Deadmines shelter a fortified complex that powers the Defias Brotherhood. Its heavy forge smelts metal and builds machinery. Alba Fairmoon believes this forge is the likely origin of the contamination blighting the area. Destroying it is her aim.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92753-9dfa4c61c837127a34ae/1-0000.mp3", duration = 27.4808163, start = 0},
  },
}
P.transport["quest:928"] = {
  hash = "22c8af",
  fullHash = "22c8af",
  text = "Crown of the Earth. In Shadowglen, you set out with moonwell water for Corithras Moonrage in Dolanaar. The journey carries you from secluded training into the wider work of protecting Teldrassil. After tasting the enchanted water of Shadowglen's moonwell, you meet Tenaron Stormgrip at the crown of Aldrassil. He seals the gathered water in a larger vessel and sends you beyond the sheltered glade. The road runs south toward Dolanaar, through woods where danger has grown harder to predict. Dolanaar is the first major village beyond Shadowglen, along the cobblestone paths through central Teldrassil. Its own moonwell lies at the heart of the village. Corithras Moonrage, an elder who oversees preservation across the boughs, waits there. The vessel you bring places you in the wider effort to protect the World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_928-43a12a9103825ee0034d/1-0000.mp3", duration = 46.08, start = 0},
  },
}
P.transport["quest:92819"] = {
  hash = "68f337",
  fullHash = "68f337",
  text = "Destruction in Deadmines. In Westfall, Alba Fairmoon sends an operative to destroy the Defias forge in the Deadmines. The explosives are already planted, and Alba waits in the hills behind Moonbrook for the detonator. The Deadmines hold the Defias Brotherhood's strength beneath Westfall. Alba Fairmoon directs you to sabotage the forge hidden in the mines. The explosives are already planted beside it, and you return to Alba in the hills behind Moonbrook to set them off from a safe distance. She hopes destroying the forge will let Westfall's poisoned land begin to heal. The charge sits beside the forge deep in the Deadmines. A remote detonator lets you set it off from outside the caves, after you rejoin Alba Fairmoon in the hills behind Moonbrook. She hopes that with the forge destroyed, Westfall's poisoned land can begin to heal.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_92819-e551409cb27940147f4a/1-0000.mp3", duration = 47.2032653, start = 0},
  },
}
P.transport["quest:929"] = {
  hash = "9a2e66",
  fullHash = "9a2e66",
  text = "Crown of the Earth. Near Starbreeze Village, you draw sacred water for Darnassus. Corithras Moonrage in Dolanaar asks young night elves to replenish the city's moonwell, and the work teaches the history behind their care for Teldrassil's great boughs. You carry a jade phial made by druids to Starbreeze Village, where a lesser moonwell holds sanctified water. Its refined craft lets you draw and carry the luminous water without disturbing its purity. Darnassus's central moonwell depends on these scattered fonts, and the elders send initiates on foot so the city's fountains stay full of Elune's grace. The journey also teaches the young what it takes to nourish Teldrassil. Corithras Moonrage tells you of the sorrow that followed the Battle of Mount Hyjal. The sacrifice of Nordrassil, the ancestral World Tree, cost the night elves their immortality. Illidan Stormrage was unleashed amid the ruin, while Shan'do Malfurion Stormrage disappeared. Grief and isolation marked the days that followed, as the kaldorei turned to Teldrassil.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_929-815528e1a086be1e8f39/1-0000.mp3", duration = 60.7869388, start = 0},
  },
}
P.transport["quest:931"] = {
  hash = "8fff4b",
  fullHash = "8fff4b",
  text = "The Shimmering Frond. Across Teldrassil, a curious plant shimmers among the roots and canopy. Travelers bring a cutting to Denalan at Lake Al'Ameth, hoping the botanist can explain its origin. In Teldrassil's boughs, a strange plant catches the light. Its fronds twist with a pulsing shimmer unlike the island's usual foliage. The glow draws the eye amid Teldrassil's young forest life.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_931-bd5049150809da765f29/1-0000.mp3", duration = 23.1444898, start = 0},
  },
}
P.transport["quest:932"] = {
  hash = "13b384",
  fullHash = "13b384",
  text = "Twisted Hatred. Tallonkai Swiftroot sends trusted champions into Fel Rock to stop Lord Melenas. The satyr has rallied the cave’s grell into an organized force, threatening night elf settlements near Teldrassil. Satyrs recall an ancient betrayal that still stains kaldorei history. They were Highborne who gave themselves to the Burning Legion during the War of the Ancients. Now one has made a foothold on Teldrassil, the young World Tree meant to be a sanctuary. For defenders like Tallonkai Swiftroot, that presence is a bitter disgrace. Fel Rock lies north of the nearby paths, its corrupted caverns crawling with feral grell. Lord Melenas has gathered the chaotic creatures into a hostile force under his will. Tallonkai fears what the satyr may unleash on the World Tree’s boughs, and demands a swift, quiet end. He wants Melenas eliminated and his severed head brought back.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_932-4cadbd976ca02b32a684/1-0000.mp3", duration = 53.3681633, start = 0},
  },
}
P.transport["quest:933"] = {
  hash = "c8b78f",
  fullHash = "c8b78f",
  text = "Crown of the Earth. Corithras Moonrage sends you to the Pools of Arlithrien for water as Gnarlpine furbolgs turn violent. His account of Teldrassil begins with Malfurion Stormrage's disappearance after the Third War. Corithras Moonrage sends you with a tourmaline phial to a moonwell southeast of Darnassus's entrance, along the Pools of Arlithrien. The Gnarlpine furbolgs, once peaceful, now lash out with sudden violence. They ambush travelers and harry Sentinel patrols across the region. What seemed like isolated skirmishes has become a threat to the night elves' new home. When you return with the filled phial, Corithras tells you how Teldrassil came to be. After the Third War, Shan'do Malfurion Stormrage vanished, leaving the Cenarion druids without a leader and divided. Arch Druid Fandral Staghelm took the mantle of leadership in his absence. He urged the Circle of Ancients in Darkshore to set aside their mourning. The night elves, he argued, had to regain their lost immortality and heal their civilization by planting a vast new World Tree.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_933-37ba180898b5656be2e3/1-0000.mp3", duration = 59.5069388, start = 0},
  },
}
P.transport["quest:934"] = {
  hash = "b7d1d8",
  fullHash = "b7d1d8",
  text = "Crown of the Earth. At the Oracle Glade, Corithras Moonrage sends you to gather water from Teldrassil’s sacred moonwell. The journey reveals the truth behind the World Tree’s creation. Corithras Moonrage sends you northwest across Teldrassil to the Oracle Glade. Beneath the Oracle Tree’s great boughs lies the first and most powerful moonwell raised on the island. You draw water into an Amethyst Phial from its sacred pool. The moonwell is the sanctuary where druids and the tree itself watch over the health of their new homeland.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_934-9c763b7df8b84dbcdac7/1-0000.mp3", duration = 29.7795918, start = 0},
  },
}
P.transport["quest:935"] = {
  hash = "3adeae",
  fullHash = "3adeae",
  text = "Crown of the Earth. In Teldrassil, moonwell waters are gathered to tend the World Tree’s sickness. The rites lead to Arch Druid Fandral Staghelm in Darnassus, where concern grows over a tree raised without blessings. Teldrassil rose after the Third War to give the night elves a new home and restore their lost immortality. The Great Aspects Alexstrasza and Nozdormu withheld their blessings and refused to sanction its creation. Without their divine protection, sickness spreads through the tree. Strange creatures emerge from its boughs, and once-peaceful furbolg tribes fall into madness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_935-d32bb99fe9a293326b50/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["quest:93552"] = {
  hash = "da977e",
  fullHash = "da977e",
  text = "Harvesting Windstones. Harvesting Windstones is a task offered by Dalia the Collector in Thendal Grove on Zephras Isle. As the ancient elemental energies sustaining the island slowly fade, raw windstones have become an essential magical fuel source. Adventurers are sent across the grove to harvest crystalline windstone clusters before their power is lost. Zephras Isle relies heavily on lingering wind magic to sustain itself, but its natural defenses are dwindling. Centuries ago, the native wind elementals who shared the island with the local elves vanished entirely. Since their departure, the ambient magic upholding the land and the great anchor pylons has been in a slow, steady decline. For the residents of Thendal Grove, surviving this depletion requires securing every possible reserve of raw energy. Windstones are vibrant blue crystalline formations scattered naturally throughout Thendal Grove. Within their brittle shells lies dense, concentrated wind magic left behind from ages past. While not an endless solution, they provide a reliable and invaluable source of arcane sustenance and utility for the island's elves, making the collection of raw clusters a vital daily endeavor.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93552-514caa9c1f67ccef4662/1-0000.mp3", duration = 70.4, start = 0},
  },
}
P.transport["quest:937"] = {
  hash = "e01640",
  fullHash = "e01640",
  text = "The Enchanted Glade. Bloodfeather harpies threaten the Oracle Glade on northwestern Teldrassil, where Sentinel Arynia Cloudsbreak guards the ancient Oracle Tree. After harpies kill a runner bound for Darnassus, Arynia calls for their nests to be thinned and their belts brought back as proof. Sentinel Arynia Cloudsbreak watches over the Oracle Glade with an escort of warriors. The sacred retreat centers on the colossal Oracle Tree, an ancient rooted among Teldrassil's boughs. Bloodfeather harpies have spread through the surrounding canopy, nesting in the hollows and threatening anyone who comes near. A runner carrying an urgent report from the Oracle Tree never reaches Darnassus. Bloodfeather harpies ambush and kill the messenger before the runner can leave the glade. Arynia calls on you to thin their flock and bring back Bloodfeather belts as proof that their nests have been weakened.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_937-797165fb0b478f2237f0/1-0000.mp3", duration = 49.7632653, start = 0},
  },
}
P.transport["quest:93746"] = {
  hash = "053548",
  fullHash = "053548",
  text = "A Firm Response. \"A Firm Response\" is a Horde quest on Zephras Isle issued by Ayessa Dawnsinger. Tensions are boiling over as the mysterious High Order intrudes upon the territory and dealings of the local Windshapers. Ayessa orders a preemptive strike against Belathaan Brightwish on the road to the Shrine of Akir to establish clear boundaries through force. The Windshapers of Zephras Isle do not tolerate uninvited scrutiny, especially from an organization as secretive and calculating as the High Order. Prior warnings have gone unheeded, forcing Ayessa Dawnsinger to escalate the matter. To safeguard their interests, she chooses to intercept Belathaan Brightwish in the isolated stretch of road leading north toward the Shrine of Akir, ensuring the altercation stays away from prying eyes in town.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_93746-9a17af788898a96660a9/1-0000.mp3", duration = 46.8114286, start = 0},
  },
}
P.transport["quest:938"] = {
  hash = "bece63",
  fullHash = "bece63",
  text = "Mist. In Teldrassil's shaded boughs, Mist lies wounded and separated from her companion. She needs a safe path back to Sentinel Arynia Cloudsbreak at a nearby moon well. A gray sabercat named Mist lies wounded among Teldrassil's undergrowth. Deep slashes mark her back and belly. Her blue eyes are bright, and she stays calm rather than acting like a feral beast. She looks to friendly travelers for guidance and protection.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_938-1b90874d0b67e49f9d13/1-0000.mp3", duration = 24.842449, start = 0},
  },
}
P.transport["quest:940"] = {
  hash = "120b23",
  fullHash = "120b23",
  text = "Teldrassil. After the harpies are driven back, Arynia Cloudsbreak sends you with a report to Darnassus. The inscribed bark tells Arch Druid Fandral Staghelm about the boughs and the corruption still troubling the World Tree. Sentinel Arynia Cloudsbreak entrusts you with a piece of inscribed bark after you clear the harpies from their nests in the Oracle Glade. The Oracle Tree watches over the forest, and with the harpies gone, Arynia can send word to the kaldorei leadership. You carry her report through the wilderness to Darnassus, the great forest of stone, and deliver it to Arch Druid Fandral Staghelm. Fandral Staghelm receives the report with mixed feelings. He is grateful to hear that the harpies have been pushed back, but the report shows how one threat gives way to another across Teldrassil. Staghelm championed the planting of the new World Tree to reclaim the night elves' lost immortality. The afflictions in its boughs remind him that his work remains far from finished.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_940-c2954f9b73d8554612de/1-0000.mp3", duration = 56.8685714, start = 0},
  },
}
P.transport["quest:941"] = {
  hash = "9e971f",
  fullHash = "9e971f",
  text = "Planting the Heart. At Lake Al'Ameth, you help Denalan tend a wooden heart taken from a corrupted timberling. After clearing away its moss, he asks you to place it in his planter and see whether it can be healed. Denalan has scraped the foul moss from the wooden heart taken from Blackmoss the Fetid, a corrupted timberling. Yet an unnatural taint still pulses within the wood. Trusting his years of botany and soil tending, the herbalist asks you to bury the heart directly in his personal planter. He hopes the rich nutrients he blended can draw its remaining natural vitality back toward health.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_941-da17dd6f48104281e7fb/1-0000.mp3", duration = 34.0114286, start = 0},
  },
}
P.transport["quest:944"] = {
  hash = "85191d",
  fullHash = "85191d",
  text = "The Master's Glaive. In southern Darkshore, Onu sends Alliance scouts to investigate the Master's Glaive. He fears the Twilight's Hammer cult may have reached the fallen ancient horror. Along Darkshore, Onu sees corruption linger and wildlife driven from its homes. The naga on the coast trouble him, but signs of the Twilight's Hammer are worse. Its followers worship primal lords who ruled the world before they were overthrown in ages past. South of Onu, the Master's Glaive is a grim excavation around a colossal creature pierced by a great stone weapon. Onu gives you a Phial of Scrying and asks you to enter the pit and learn whether the cultists have gathered there. The behemoth has been dead for eons, yet corruptive power still clings to its bones. The Twilight's Hammer may seek to claim it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_944-3791d22e399657a8005b/1-0000.mp3", duration = 44.0946939, start = 0},
  },
}
P.transport["quest:94414"] = {
  hash = "f046e2",
  fullHash = "f046e2",
  text = "The Anchors of Zephras. The Anchors of Zephras is an introductory quest offered by Halaan Hawk-Eye on Zephras Isle. Halaan invites travelers to borrow his far-reaching vision to observe the ancient anchor pylons that tether and preserve the floating island. Though the soaring monoliths appear untouched from a distance, Halaan warns that the wind spirits' stabilizing magic has begun to waver. The anchor pylons of Zephras are ancient, towering monoliths gifted by the spirits of the winds. Deeply woven into the isle's mystical foundation, they serve to bind, steady, and sustain the landmass amidst the churning skies. To look upon one is to witness the fragile balance keeping Zephras aloft, relying continuously on the benevolence of the wind spirits. Despite standing proud and undamaged to the naked eye, the anchor pylons have grown erratic. Halaan Hawk-Eye notes that the magical harmony sustaining them has become unstable and inconsistent in recent times. Without clear signs of physical distress, this subtle decay raises quiet alarm among those who watch over the groves, hinting at deeper imbalances threatening the isle. Lacking the innate skysight that peers across worlds or the arcane prowess to tap Zephras's deep ley lines, Halaan possesses a simpler, sharper natural gift: keen, unclouded vision over immense distances. By lending this perspective, he allows others to observe the distant pylons in fine detail, encouraging newcomers to cultivate gratitude for the present while staying alert to their homeland's shifting fate.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_94414-506693026a4e7a016008/1-0000.mp3", duration = 89.6522449, start = 0},
  },
}
P.transport["quest:947"] = {
  hash = "f44a92",
  fullHash = "f44a92",
  text = "Cave Mushrooms. Barithras Moonshade sends you behind Cliffspring Falls for rare fungi. In Auberdine, the night elf prepares a specialized potion and asks you to investigate troubling warnings from the Grove of the Ancients. Barithras Moonshade needs scaber stalks and a death cap for a potent mixture. Both grow in a damp cavern hidden behind Cliffspring Falls in northeastern Darkshore. Gathering these fungi is more dangerous than picking ordinary woodland herbs.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_947-7e04c3a34513bb01f548/1-0000.mp3", duration = 25.3910204, start = 0},
  },
}
P.transport["quest:948"] = {
  hash = "91cf4c",
  fullHash = "91cf4c",
  text = "Onu. Barithras Moonshade sends you south from Auberdine to speak with Onu. Your findings in Cliffspring Falls have drawn the attention of one of Darkshore's oldest guardians. Barithras Moonshade sees more than strange fungi in the samples you brought back to Auberdine. The caves beneath Cliffspring Falls are tainted, and word of them reaches Onu, an Ancient of Lore in the Grove of the Ancients south of town. The corruption in Darkshore's waterways may reach beyond anything a naturalist can explain. Onu wants counsel, and even an Ancient's patient nature cannot hide the weight of that summons. The road south from Auberdine turns inland, away from the coastal ruins and toward the mountain slopes. The Grove of the Ancients shelters an old refuge of nature, set apart from the decay along the shore. Onu waits among stone barrows and kindred spirits, ready to guide allies toward the blights stirring at the edge of the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_948-17548f6535bb86c8ecfd/1-0000.mp3", duration = 52.5844898, start = 0},
  },
}
P.transport["quest:949"] = {
  hash = "63fc12",
  fullHash = "63fc12",
  text = "The Twilight Camp. Cultists gather around the Master's Glaive in southern Darkshore, and Alliance scouts seek to learn why. A scrying bowl has shown their ritual site; now you enter the excavation to discover what the Twilight's Hammer seeks beneath the earth. The Twilight's Hammer has made the Master's Glaive an active threat. After a scrying bowl reveals the cultists' fortifications, you enter their camp to learn their designs before the Alliance can prepare its defenses.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_949-32c4703802b1c51a6526/1-0000.mp3", duration = 24.9208163, start = 0},
  },
}
P.transport["quest:950"] = {
  hash = "1c0c85",
  fullHash = "1c0c85",
  text = "Return to Onu. You carry a page from the Twilight Tome back to Onu in Darkshore. The scribbles are all you could bear to take from the cultists’ book. The Twilight Tome overwhelms anyone who tries to read it. Its words swim across the page, and its ornate scrollwork twists into grotesque figures. You tear out a single page of scribbles before the strain brings on vertigo.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_950-0f0d189946d1388a581b/1-0000.mp3", duration = 20.7673469, start = 0},
  },
}
P.transport["quest:95041"] = {
  hash = "5b1281",
  fullHash = "5b1281",
  text = "Data Hoarders. Data Hoarders is a task given by Jemma Quikswitch, an exiled gnome residing in Ironforge. During the desperate evacuation of Gnomeregan, she copied her family's most prized archives onto punch cards, only to lose several in the freezing drifts outside the city gates. Recovering these lost data cards means salvaging everything from advanced naval engineering schematics to irreplaceable family recipes. When the trogg invasion and subsequent radiation disaster forced the gnomes out of Gnomeregan, thousands fled with whatever belongings they could snatch up in the chaos. Jemma Quikswitch took the prudent step of transcribing generations of family knowledge into physical punch card archives. Tragically, a damaged satchel spilled several key cards into the snowfields surrounding the fallen city. Without these missing punch cards, the remaining data registers as indecipherable gibberish, threatening to erase her family's intellectual legacy. Gnomish data archives reflect the peculiar breadth of their civilization's priorities. The Quikswitch family records include profound arcanotechnical field equations, vital Second War submarine hull blueprints, and Grandma Quikswitch's secret chili recipe. To an outsider, combining military engineering with household cooking might seem odd, but to surviving refugees in Ironforge, preserving domestic comforts matters just as much as preserving technological marvels.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95041-fe74ce3855ee4931370f/1-0000.mp3", duration = 80.8489796, start = 0},
  },
}
P.transport["quest:95065"] = {
  hash = "c8c5b3",
  fullHash = "c8c5b3",
  text = "Fishin' Time. At Stormwind harbor, Gilbert Gray's bait runs low as the fish begin to bite. He asks passersby to fetch supplies from a shop along the city's canals. Gilbert Gray spends quiet days fishing at the edge of Stormwind harbor. He watches his bobber on the water, but a good run of biting fish can empty his bait tin. With his supplies gone and the fish still biting, the elderly angler asks passersby to bring him more. Catherine Leland runs a tackle shop along the stone canals, just west of the Trade District. She supplies fishermen across Stormwind with lures and bait, including regulars like Gilbert Gray.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95065-d15947e1c3dae1c8a069/1-0000.mp3", duration = 36.4930612, start = 0},
  },
}
P.transport["quest:952"] = {
  hash = "377f7c",
  fullHash = "377f7c",
  text = "Grove of the Ancients. A dispatch carries you from Darnassus to Darkshore, where Onu waits in the Grove of the Ancients. Arch Druid Fandral Staghelm sends you across the sea with correspondence for the Ancient of Lore, who lives south of Auberdine. After you help with matters at the Oracle Glade atop Teldrassil, Arch Druid Fandral Staghelm summons you for another duty. He sends you across the sea to Darkshore with an urgent dispatch for Onu. From Darnassus, you can book a flight aboard a hippogryph. South of Auberdine, you reach the Grove of the Ancients and deliver the missive to Onu. The towering Ancient of Lore accepts it quietly and remarks on Staghelm's impatience. Onu and the forest's ancient keepers believe all things unfold in their proper time. Shan'do Malfurion Stormrage embodied that patient wisdom, while Staghelm lacks it.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_952-98cb269266ff8c23f7d5/1-0000.mp3", duration = 47.6995918, start = 0},
  },
}
P.transport["quest:953"] = {
  hash = "59a093",
  fullHash = "59a093",
  text = "The Fall of Ameth'Aran. Sentinel Tysha Moonblade sends you to explore Ameth'Aran's ruins in Darkshore and read its ancient stone tablets. Their inscriptions tell of the Highborne city's ruin during the Sundering, preserving history largely lost in the War of the Ancients for the Circle of Ancients in Auberdine. Ameth'Aran was a flourishing settlement of Queen Azshara's elite sorcerers, who practiced powerful arcane magic. After the Well of Eternity was destroyed ten thousand years ago, the city lay in broken marble and cracked pillars. Restless, anguished spirits of the Highborne who died there still haunt the ruins. Few written accounts survived the Great Sundering intact, as the War of the Ancients drove night elves into a struggle for survival. Sentinel Tysha Moonblade surveyed the ruins and found two large engraved tablets, the Lay of Ameth'Aran and the Fall of Ameth'Aran. Ghostly Highborne specters forced her to retreat. The readings can carry the ancient disaster's history to the scholars of the Circle of Ancients in Auberdine.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_953-0542f6b617ced058c1ff/1-0000.mp3", duration = 59.3240816, start = 0},
  },
}
P.transport["quest:95314"] = {
  hash = "d3fee6",
  fullHash = "d3fee6",
  text = "That Shadowvale Green Elixir. Carolai Anise in Brill seeks salvage from the abandoned settlement of Shadowvale, tucked deep within the secluded Whispering Forest. Before the kingdom fell, the village was infamous for distilling Whispering Elixir from strange local herbs—a potent draught that remained prized on the black market even after being outlawed in Lordaeron. Long before the Third War and the arrival of the Scourge, the reclusive inhabitants of Shadowvale brewed a distinct concoction known as Whispering Elixir. Distilled from rare herbs unique to Tirisfal Glades, the draught gained notoriety across northern Lordaeron. Despite being officially outlawed within the Capital City, its unusual properties made it eagerly sought after by mystics, poisoners, and practicing apothecaries willing to skirt royal decrees. Shadowvale sits hidden deep within the Whispering Forest of western Tirisfal. The villagers were historically an insular and distrustful people who rarely welcomed outsiders. Following the Scourge invasion, the settlement fell into ruin, but forgotten stores of the aged green elixir remain among the wreckage. Carolai Anise operates out of Brill, taking advantage of persistent underworld demand to pay adventurers willing to brave the forest's unsettling silence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_95314-ecc3e600e912bd64640b/1-0000.mp3", duration = 71.7583673, start = 0},
  },
}
P.transport["quest:954"] = {
  hash = "bf871a",
  fullHash = "bf871a",
  text = "Bashal'Aran. Demonic satyrs and grells shun one shrine in Bashal'Aran, where an unearthly blue aura burns. Thundris Windweaver, Auberdine's elder, sends you to find its source. Bashal'Aran once flourished under the ancient Kaldorei Empire. Now demonic taint fills its broken marble halls and overgrown arches. Twisted satyrs and corrupt grells feed on the ruins' lingering magic, growing more malicious by the day. Yet Thundris Windweaver in Auberdine has noticed a mystery: atop a western bluff, a blue aura shines above a shrine that no demon will approach.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_954-f228f39a3398eca0e5e0/1-0000.mp3", duration = 35.4481633, start = 0},
  },
}
P.transport["quest:955"] = {
  hash = "f1d77c",
  fullHash = "f1d77c",
  text = "Bashal'Aran. At Bashal'Aran, Asterion seeks release from the magic binding his ghostly form. He suspects the grells have touched the seal that holds him, and asks travelers to gather their earrings so he can trace its lingering magic. Asterion waits among Bashal'Aran's shattered marble, bound there for centuries. The ancient night elf spirit is trapped between life and true death beneath Darkshore's canopy. Arcane craft ties him to the ruined settlement, and he cannot break free alone. Solitude and despair have worn down his mind through all those years. Asterion believes an ancient seal hidden in the ruins may hold the key to his release. Though he cannot search the brush and fallen stones himself, the feral grells of Bashal'Aran forage there and steal small baubles. He asks travelers to gather their earrings, hoping the trinkets' lingering magic will lead him to the seal that torments his soul.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_955-7dc2aeb6052ca4d82dca/1-0000.mp3", duration = 51.7746939, start = 0},
  },
}
P.transport["quest:956"] = {
  hash = "ae2d64",
  fullHash = "ae2d64",
  text = "Bashal'Aran. Asterion seeks release from his prison among the ruined pillars of Bashal'Aran. He has traced the binding magic to the satyrs who command the grells and asks travelers to recover the Ancient Moonstone Seal. For more than a thousand years, Asterion has remained bound to the ruins of Bashal'Aran. The marble pillars around him mark the limits of his prison, beyond the reach of his fading strength and ancient magic. A cursed relic holds him here. Through the centuries, he has watched Darkshore's canopy and wondered whether the wearing stone could ever set him free. Nearby grells carried traces of the magic that binds Asterion, and he deduced that the Ancient Moonstone Seal was the source of the enchantment. The satyrs who command the grells now hold the seal. These demonic night elves wander the ancient groves, keeping watch over the relic. Asterion needs the seal recovered before its binding power can be broken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_956-318ce6f17dc8dc28cccc/1-0000.mp3", duration = 52.5844898, start = 0},
  },
}
P.transport["quest:960"] = {
  hash = "b91b96",
  fullHash = "b91b96",
  text = "Onu is meditating. At the Master's Glaive in southern Darkshore, Onu enters a deep trance over a growing threat. The ancient of lore weighs the alliance and motives of the Twilight's Hammer cult and the naga. If you lose your scrying phial, you can speak to him for another. In the Grove of the Ancients, Onu is an Ancient of Lore and a living repository of Kalimdor's history. Ominous reports of dark excavations at the Master's Glaive draw his immense consciousness inward. He ponders what brings the fanatical Twilight's Hammer cultists and the naga to the petrified remains of an ancient behemoth. For adventurers carrying out his reconnaissance, Onu remains within reach and can replace a scrying phial misplaced in the wild. Onu uses nature-attuned divination to watch the ruins without risking his physical presence. He entrusts adventurers with a phial of scrying, which conjures a scrying bowl at the excavation site so he can commune from afar. The journey south through Darkshore is perilous, with hostile wildlife and cultist patrols, so mishaps can happen. Onu's trance is an attentive vigil, not unbroken slumber. He readily offers another vial of sacred waters so the investigation of the Master's Glaive can continue.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_960-d32e140dfe7fa3ed9c44/1-0000.mp3", duration = 73.2734694, start = 0},
  },
}
P.transport["quest:96047"] = {
  hash = "13e75d",
  fullHash = "13e75d",
  text = "Camping 101: First Aid. This task directs novice medics in Dun Morogh to expand their survival craft beyond simple bandages. By seeking out Thamner Pol in Kharanos, adventurers learn how to assemble a dedicated First Aid Kit to keep campers alive in the field. Adventurers braving the frozen reaches of Dun Morogh quickly discover that linen scraps and hasty stitches are only the beginning of survival medicine. True wilderness survival often depends on having established supplies at a resting site. Those who show aptitude in basic treatment are steered toward local craft instructors in Kharanos who can teach them how to turn raw medical supplies into complete kits tailored for camp survival. In the bustling hamlet of Kharanos, Thamner Pol passes along practical techniques for outfitting expedition sites with emergency supplies. Knowing how to construct a proper field kit ensures that an entire party can bandage lacerations and recover their stamina together around the hearth fire before venturing back into the biting cold.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96047-33e51bca2dacf21a2444/1-0000.mp3", duration = 56.6334694, start = 0},
  },
}
P.transport["quest:963"] = {
  hash = "faa61e",
  fullHash = "faa61e",
  text = "For Love Eternal. In Auberdine, Cerellean Whiteclaw asks you to free Anaya Dawnrunner's spirit from torment in Ameth'Aran. His grief has endured since the city's fall. Ten thousand years ago, the War of the Ancients tore ancient Kalimdor apart around the Well of Eternity. The catastrophe destroyed Ameth'Aran and took Anaya Dawnrunner from Cerellean Whiteclaw. Stricken with grief, Cerellean followed Shan'do Malfurion Stormrage into the druids' long hibernation. He hoped that walking the Emerald Dream through the ages would quiet his aching heart, but sorrow remained with him. After awakening, Cerellean wandered Darkshore in a stupor until he reached Ameth'Aran's melancholy ruins. Among the ancient stones, he saw Anaya's tortured ghost. He cannot raise a weapon against the woman he loved, so he asks passing travelers to destroy her tormented form, retrieve her pendant, and grant her troubled soul peace.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_963-bbe21e7e71b530c79cee/1-0000.mp3", duration = 53.1330612, start = 0},
  },
}
P.transport["quest:96390"] = {
  hash = "5cf700",
  fullHash = "5cf700",
  text = "Nip 'Em in the Bud. Nip 'Em in the Bud is a mission directed by Earthseer Farsen to eliminate Dark Iron spies infiltrating Dun Morogh. The clandestine operatives have been spotted lurking near Ironband's Compound, threatening the security of the Bronzebeard homeland. Dun Morogh has long been a fortified sanctuary for the Ironforge dwarves, but the ancient enmity between the dwarven clans never truly sleeps. Dark Iron infiltrators have slipped through the high passes and snowy crags, skulking suspiciously close to vital excavations and settlements. Earthseer Farsen recognizes that even a few hidden observers can presage a devastating strike, calling on stalwart defenders of the Alliance to root them out before their schemes take hold.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96390-5e0876be5f577b1fef2b/1-0000.mp3", duration = 42.1093878, start = 0},
  },
}
P.transport["quest:96392"] = {
  hash = "16b337",
  fullHash = "16b337",
  text = "Farsen's Watch. Farsen's Watch is an observational task given by Earthseer Farsen, a visiting Wildhammer shaman stationed high above Gol'Bolar Quarry. Using the earthseer's shamanic far sight, adventurers witness firsthand the growing infiltration of Dark Iron dwarves into the heart of Dun Morogh. This crucial survey marks an early step along the path toward the Hall of Thanes. Perched above the snowblown excavation of Gol'Bolar Quarry, Earthseer Farsen keeps a vigilant watch over the lower reaches of Dun Morogh. Having journeyed south from the crags of Aerie Peak, the Wildhammer visitor brings a keen spiritual awareness to lands usually patrolled by Ironforge mountaineers. Rather than relying on simple scouts, Farsen uses the traditional arts of his clan to monitor subterranean rumblings and unexpected movement along the hillsides. To convince travelers of the imminent danger, Farsen lends them his farsight—a shamanic gift that projects one's awareness across vast distances. Looking through the spiritual lens, it becomes obvious that Dun Morogh's troubles extend far beyond unruly troggs and wild beasts. Dark Iron dwarves have slipped close to Ironforge's industrial center, entrenching themselves for an operation that demands immediate confrontation before it takes root.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96392-cbadfb71ff9ea3f6f25d/1-0000.mp3", duration = 71.5232653, start = 0},
  },
}
P.transport["quest:96408"] = {
  hash = "a26af1",
  fullHash = "a26af1",
  text = "A Visitor to Dun Morogh. A Visitor to Dun Morogh is an investigative task offered by Beldin Steelgrill outside Kharanos. Mountaineers reported an unfamiliar campfire high on the cliffs overlooking Gol'Bolar Quarry, prompting a scout to check whether the stranger poses a threat to the local dwarves. Dun Morogh's mountaineers keep a diligent watch over the crags and snowy valleys surrounding Ironforge. When a campfire suddenly appeared high above Gol'Bolar Quarry, it raised eyebrows in Kharanos. Beldin Steelgrill, concerned by the unusual encampment situated directly above a vital dwarven excavation, recruits travelers to scale the ridges and determine whether the mysterious stranger is a benign traveler or an intruder.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96408-8fd02c48206dae846e74/1-0000.mp3", duration = 39.3665306, start = 0},
  },
}
P.transport["quest:965"] = {
  hash = "6504a8",
  fullHash = "6504a8",
  text = "The Tower of Althalaxx. North of Auberdine, Sentinel Elissa Starbreeze fears trouble at an ancient ruin. She sent Balthule Shadowstrike to watch the Tower of Althalaxx, but he has missed his report. Sentinel Elissa Starbreeze watches for danger around Auberdine. Suspicious activity near the Tower of Althalaxx in northern Darkshore drew her notice, so she sent Balthule Shadowstrike to watch the ancient ruin. Days have passed without word from him. Elissa asks you to travel north, find Balthule, and make sure he has not met an untimely end.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_965-bfada3e8f902027f5fb8/1-0000.mp3", duration = 32.8881633, start = 0},
  },
}
P.transport["quest:966"] = {
  hash = "b1a385",
  fullHash = "b1a385",
  text = "The Tower of Althalaxx. Warlocks gather at the Tower of Althalaxx in northern Darkshore, drawing the scout Balthule Shadowstrike’s attention. He asks travelers to recover parchment scraps from the fanatics camped outside the ruins, hoping to learn who they are and what they seek. Balthule Shadowstrike watches the misty shore of northern Darkshore, keeping sight of the ancient Tower of Althalaxx. Auberdine sent him to monitor the ruin and warn Delgren the Purifier if danger grew. But leaving his post to report might mean missing the dark spellcasters moving among the stones. So Balthule asks passing travelers to scout the camps around the tower.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_966-1633f9906222b092da7e/1-0000.mp3", duration = 36.6497959, start = 0},
  },
}
P.transport["quest:96607"] = {
  hash = "137ce5",
  fullHash = "137ce5",
  text = "The Great Outdoors. You learn how rest and preparation help you survive beyond city walls. Travelers across Azeroth teach new wanderers to rest by a campfire and prepare for the wilds. Even a sharp blade or potent magic cannot protect you from the wilds if you neglect the basics of survival. Seasoned wanderers near roadside clearings share this lesson with travelers leaving their home valleys. Resting by a campfire eases sore boots, settles the mind, and readies you for the road ahead. Regular rest and preparation give you a better chance of surviving long enough to find fortune and glory. Once you understand the value of a fire and proper rest, your instructors point you toward town tradesfolk. A field camp needs more than an ember and a bedroll; survival also calls for practical crafts. You can forge replacement rivets, cook trail rations, or stitch torn gear under the stars. Each profession offers camp fixtures that can help turn a bare hillside into a self-sufficient outpost.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96607-0b6356b357d532dc74d4/1-0000.mp3", duration = 57.6783673, start = 0},
  },
}
P.transport["quest:96627"] = {
  hash = "0de6b9",
  fullHash = "0de6b9",
  text = "The Adventurer. In Northshire Valley, Marshal McBride sends The Adventurer toward Goldshire to find Sam Sarsaparilla. You have shown your skill defending the abbey, and McBride wants you to look into the newcomer. As threats from the local Defias and vermin ease, Marshal McBride turns his attention to the road beyond Northshire Valley. Stormwind's regular forces are stretched thin across the kingdom, so the local garrison relies on promising fighters to watch travelers and wanderers in the surrounding woods. Marshal McBride asks you to check on Sam Sarsaparilla, a newcomer spotted near Goldshire. It is an unusual request, not a military order or a bounty hunt, and it leads you from Northshire's secluded valley into the wider wilds of Elwynn Forest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96627-b6ab4ca855df53f3a12f/1-0000.mp3", duration = 43.4416327, start = 0},
  },
}
P.transport["quest:96628"] = {
  hash = "88db27",
  fullHash = "88db27",
  text = "The Adventurer. The Adventurer is a local errand given by Mountaineer Thalos at the southern gate of Dun Morogh. Before sending travelers through the mountain tunnel toward Kharanos, Thalos asks them to carry a bundle of supplies to Eric Brighthammer, a newcomer camped just outside the village. Guarding the high passes and tunnels between Coldridge Valley and the broader snowy expanses of Dun Morogh is demanding work for the Ironforge Mountaineers. Stationed at the border gate, Mountaineer Thalos keeps an eye out for both local dangers and travelers passing along the beaten trail. When word reaches the post about a lone adventurer arriving near Kharanos, Thalos uses trusted passersby to haul necessary supplies onward to support newcomers venturing into the frozen crags. The road descending from the southern pass winds into the settlement of Kharanos, the primary hub for dwarven craft and travel in central Dun Morogh. Eric Brighthammer has recently established himself just on the outskirts of the village. By delivering the Mountaineers' bundle of provisions to him, travelers help establish a vital link between the outlying ridge sentries and those actively wandering the wilderness.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96628-d0479919665222dd8f3a/1-0000.mp3", duration = 66.2987755, start = 0},
  },
}
P.transport["quest:96630"] = {
  hash = "2b7777",
  fullHash = "2b7777",
  text = "The Adventurer. In Teldrassil, a lost journal waits to be carried to Lyreena Duskblade near Dolanaar. Its pages record an unknown traveler's simple journeys and camping outings. You find a journal among Teldrassil's boughs and roots. Its nameless writer records modest wanderings and the simple pleasure of making camp beneath the twilight canopy. The journal can be carried toward Dolanaar instead of left in the wilderness. Lyreena Duskblade waits near the night elf settlement to receive the lost pages.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96630-81c9084929449f8e5c99/1-0000.mp3", duration = 29.8057143, start = 0},
  },
}
P.transport["quest:96638"] = {
  hash = "85e725",
  fullHash = "85e725",
  text = "The Adventurer. \"The Adventurer\" is an introductory journey quest on Zephras Isle. Given by Aetheen of the Gales in Thendal Grove, it directs newly seasoned wanderers southwest toward Shen'dar Village to meet Raan Wildwind, a veteran camper who knows the wilds. While Thendal Grove provides shelter and quiet refuge, the wider expanses of Zephras Isle remain wild and perilous. Aetheen of the Gales watches over the initiates and sees when an aspiring traveler is ready to step beyond familiar borders. For those seeking fame, fortune, or purpose, remaining behind the grove's sheltered perimeter is no longer enough. Southwest of the grove along the road toward Shen'dar Village, another traveler has already made his camp. Raan Wildwind has spent time navigating the perils outside the safe haven. Seeking him out provides burgeoning wanderers a pragmatic introduction to survival beyond Thendal Grove, learning from someone who has already braved the open paths.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96638-0a0ca66343ecfad51254/1-0000.mp3", duration = 57.4432653, start = 0},
  },
}
P.transport["quest:96652"] = {
  hash = "c18364",
  fullHash = "c18364",
  text = "The Adventurer. In Durotar, The Adventurer finds a lost journal among the red wastes. Its pages tell of quiet travels and nights beneath the stars, and it is meant for Brakk near Razor Hill. A lost journal lies in Durotar's red dirt, far from the bloody battles and grand campaigns that mark the land. Its unknown writer fills the pages with day-to-day travels and the simple pleasure of making camp beneath the open sky. The book offers a quiet glimpse of life on the road through a harsh country. The journal is meant for Brakk, an adventurer camped near Razor Hill. Its pages connect an unknown traveler to someone watching the dusty roads, and carrying it to Brakk may help keep the writer's travels remembered.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96652-c476ad0a3e66f6b7dcf7/1-0000.mp3", duration = 40.724898, start = 0},
  },
}
P.transport["quest:96656"] = {
  hash = "9b849a",
  fullHash = "9b849a",
  text = "The Adventurer. The Adventurer is an introductory task given by Executor Arren to seasoned young Forsaken champions outside Deathknell. Having proven reliable in strikes against the Scarlet Crusade, you are dispatched up the road toward Brill to investigate a stranger lingering near the settlement. Rather than uncovering another zealot spy, the task introduces you to Eleanor Shackleton, an independent traveler eager to teach the practical survival skills of the wild. Executor Arren maintains a vigilant watch over Deathknell and the surrounding approaches. With Scarlet Crusaders actively spying on the region and infiltrating northern Lordaeron, any newcomer spotted wandering near Brill warrants immediate scrutiny. Having demonstrated your dedication by eliminating crusader threats along the border, Arren turns to you to investigate the unknown figure quietly, determining whether she poses a hidden danger to the Forsaken. Upon tracking down Eleanor Shackleton along the roadside near Brill, her intentions prove far removed from Crusade fanatical plots or Scourge necromancy. A fellow Forsaken pausing before her next journey into the wilds, Eleanor is simply an adventurer. Instead, she recognizes the spark of an adventurer in those sent to check on her, offering to share the practical essentials of surviving open wilderness and making camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96656-dc8faaf99fdc6969f7a8/1-0000.mp3", duration = 73.8220408, start = 0},
  },
}
P.transport["quest:96658"] = {
  hash = "a89c66",
  fullHash = "a89c66",
  text = "Camping 101: Cooking. At nearby settlements, new adventurers learn to cook and kindle a Basic Campfire for life in the wild. The lesson is offered across Alliance and Horde lands. Every traveler needs to know how to build a fire beyond the safety of fortified walls. A campfire can boil water and roast meat, and it anchors a campsite in unfamiliar country. Apprentice cooks can kindle only modest fires with few surroundings. Greater skill in cooking lets them light larger fires that support more elaborate campsites. Other practical trades also teach ways to make useful furnishings for a camp.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96658-26c510c011bff1429502/1-0000.mp3", duration = 33.6979592, start = 0},
  },
}
P.transport["quest:96659"] = {
  hash = "eb78a9",
  fullHash = "eb78a9",
  text = "The Adventurer. As young tauren prepare to depart their ancestral training grounds on Red Cloud Mesa, Chief Hawkwind asks them to perform a final favor. He entrusts them with a bundle of essential supplies meant for Kaga Wildhoof, a seasoned wanderer camped near Bloodhoof Village who once aided the chief in his own past. Before travelers descend the mesa path toward the broader plains of Mulgore, Chief Hawkwind pauses to address unfinished personal debts. Long before guiding new generations of hunters and shamans on Camp Narache, Hawkwind crossed paths with Kaga Wildhoof. Described by the chief as an accomplished adventurer, Wildhoof provided vital aid when he needed it most. Hearing that she has pitched camp just outside Bloodhoof Village, Hawkwind uses the departure of newly proven novices to send provisions to his old benefactor. This errand marks a pivotal rite of passage for young Horde champions leaving Red Cloud Mesa. The trail down the plateau leads directly toward Bloodhoof Village, the cultural and logistical heart of central Mulgore. Carrying the supply bundle across the plains bridges the sheltered training life of the mesa with the wider, wilder struggles of the United Tauren Tribes.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_96659-b6ef98e4ae27db1e4f0a/1-0000.mp3", duration = 70.8702041, start = 0},
  },
}
P.transport["quest:967"] = {
  hash = "6550c2",
  fullHash = "6550c2",
  text = "The Tower of Althalaxx. At the Tower of Althalaxx, Dark Strand cultists are gathering, and Balthule Shadowstrike needs help. He sends an Alliance courier to Maestra's Post in Ashenvale with a warning for his mentor, Delgren the Purifier. Balthule Shadowstrike sees that the Dark Strand threat is too great for one scout to face alone. After clashing with cultists near the Tower of Althalaxx, he writes a report and entrusts it to an Alliance messenger bound for his master, Delgren the Purifier. The cult's summoners are growing bolder, and Balthule needs seasoned leaders to direct a response. Balthule's dispatch takes you south along Darkshore's coastal road, then across the wooded border into Ashenvale. Delgren the Purifier is stationed at Maestra's Post, beside the western road. The human paladin works to cleanse demons and undead from the woodland. Though night elven customs were once unfamiliar to him, he has earned the Sentinels' deep respect as an indispensable ally.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_967-2ee11b38214f4b982ca1/1-0000.mp3", duration = 56.6595918, start = 0},
  },
}
P.transport["quest:968"] = {
  hash = "5316e4",
  fullHash = "5316e4",
  text = "Tools of the Highborne. Thundris Windweaver sends help from Auberdine to the ruins of Ameth'Aran. Restless Highborne spirits still carry enchanted relics through the shattered settlement, and he wants them taken away. South of Auberdine and east of the coastal highway, Ameth'Aran's stone foundations lie overgrown. Ten thousand years ago, the settlement was a stronghold of the Highborne, the privileged aristocracy of the ancient night elven empire. Their unchecked use of arcane magic helped bring about the Sundering, which shattered Ameth'Aran. The inhabitants never truly left. Sentinels patrolling Darkshore report that the Highborne ghosts still haunt the sunken plazas, clutching the enchanted tools and trinkets they held in life. For the kaldorei, arcane magic carries the memory of a danger that nearly destroyed life on Azeroth. Thundris Windweaver fears that leaving the Highborne implements in ghostly hands could invite corruption. He sends adventurers to wrest the relics from the restless spirits, intending to have them destroyed so their tainted magic cannot fuel another disaster.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_968-74817a2c89e33ee62e8c/1-0000.mp3", duration = 59.4285714, start = 0},
  },
}
P.transport["quest:97279"] = {
  hash = "36b4bb",
  fullHash = "36b4bb",
  text = "Wayward Weapons. At the Valley of Trials, Gornek sends new recruits to recover weapons for the encampment. With young warriors arriving to serve the Horde, supplies run thin, and the weaponsmith needs old arms returned to use. New recruits face harsh trials in Durotar's red wastes. Many arrive ready to pledge their blades to the warchief, straining the encampment's weapon stocks. Weaponsmith Kzan Thornslash struggles to meet demand, especially when early lessons prove fatal or humiliating for the unready. Overseer Gornek makes the shortage a practical trial. He sends fresh arrivals to recover abandoned blades and blunt training weapons left by recruits who fell or fled. Bring the recovered arms to Kzan, and he can repair and temper them for the next wave. New recruits learn that survival in the Horde calls for scavenging as well as swinging steel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97279-3cd70755893b3a86c43f/1-0000.mp3", duration = 49.2930612, start = 0},
  },
}
P.transport["quest:97558"] = {
  hash = "af0954",
  fullHash = "af0954",
  text = "Hides for the Forsaken. A grim necessity of undead existence in Tirisfal Glades, where the Forsaken must scavenge animal hides to replace their decaying flesh. Shelene Rhobart tasks adventurers with gathering darkhound hides, duskbat wing membranes, and murloc skin to patch damaged bodies. Forsaken flesh does not heal naturally. Sustaining physical wounds leaves rotting gaps that cannot regenerate through normal biological means. To maintain their forms and keep their corpses functional, the Forsaken must source organic material from the living world and stitch replacement pieces over their injuries. Not every hide serves the same anatomical purpose. Thick darkhound hide offers durability for broad, sturdy repairs. Delicate duskbat wing membranes are light and pliable enough to cover faces and fingers without creating stiff, clumsy layers. Meanwhile, the pliable skin of Vile Fin murlocs is gathered to line internal membranes and sensitive areas such as inner cheeks and mouths.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97558-81f5ac8cd7489690a6a7/1-0000.mp3", duration = 57.4432653, start = 0},
  },
}
P.transport["quest:97894"] = {
  hash = "bcaf40",
  fullHash = "bcaf40",
  text = "Business in Auberdine. Borgus Steelhand seeks news of his brother Gorbold in Auberdine. The dwarven merchant asks travelers sailing west to check on Gorbold, who recently began trading in the night elven port. Their route links Stormwind Harbor with the shores of northern Kalimdor. Borgus Steelhand trusts his family's name among traders. His brother, Gorbold Steelhand, crossed the Great Sea recently to work a merchant stall in Auberdine. Gorbold hoped to profit by supplying ships that call at Darkshore. Weeks have passed without a word, and Borgus worries about how his brother fares so far from Ironforge and Stormwind. Travel from the Eastern Kingdoms to Kalimdor once meant a winding passage through Menethil Harbor or neutral goblin ports such as Booty Bay. Borgus directs travelers to a vessel at the southern-most dock of Stormwind Harbor. It sails directly to Auberdine's long wooden piers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97894-d577a3b66aad353b2e31/1-0000.mp3", duration = 51.3044898, start = 0},
  },
}
P.transport["quest:97914"] = {
  hash = "cb5ea6",
  fullHash = "cb5ea6",
  text = "Expanding Horizons. Thundris Windweaver sends word from Auberdine across the Great Sea to Stormwind. The letter asks City Architect Baros Alexston to recognize Auberdine's work and its home. Auberdine now links Darkshore to Stormwind by sea. Night elves once kept to Kalimdor's forests, apart from the Eastern Kingdoms, but after the Third War they joined the Grand Alliance. The new passage gives the northern port a direct tie to the human kingdom. Local leaders want the shipping route secured and Auberdine connected to the wider Alliance. Ameth'Aran and Bashal'Aran, ruined cities nearby, have long drawn more notice than the living coastal settlement. The letter crossing the Great Sea is addressed to Baros Alexston, Stormwind's City Architect. He oversees construction and infrastructure in the human capital, including public works and logistics. Thundris Windweaver wants Auberdine's work recognized and its home made known.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97914-7094f0ca70ebb8676768/1-0000.mp3", duration = 53.524898, start = 0},
  },
}
P.transport["quest:97919"] = {
  hash = "a95445",
  fullHash = "a95445",
  text = "Camping 101: First Aid. At the Lion's Pride Inn, Michelle Belle shows travelers how to prepare for camp. In Goldshire, you can learn to make a First Aid Kit for the road ahead. Travel across Elwynn Forest can leave you wounded, far from a town healer or inn. First Aid lets you tend your own injuries and care for yourself without relying on others. Bandages offer help with bleeding and trauma, without arcane rituals or holy supplication. A campsite offers a place to rest amid the dangers of the wild. At the Lion's Pride Inn in Goldshire, Michelle Belle teaches skilled practitioners to assemble First Aid Kits. Keep medical supplies at camp so a weary party can treat injuries and regain strength before facing the perils ahead.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97919-f2486e517ed799b5bc51/1-0000.mp3", duration = 43.3632653, start = 0},
  },
}
P.transport["quest:97920"] = {
  hash = "c05ff8",
  fullHash = "c05ff8",
  text = "Camping 101: Fishing. In Elwynn Forest, novice anglers seek ways to make camp life more comfortable. Near Goldshire, fishing expert Lee Brown teaches travelers how angling can add simple comforts to a campsite. Fishing gives you food, but camp life asks for more than food and shelter. A fish bowl can bring comfort and lift the spirits of weary travelers between excursions. Sound minds and high spirits help make formidable fighters. Lee Brown waits beside the waters outside Goldshire to help novice fishermen broaden their craft. Travelers who show skill with rod and line can learn how simple catches and basic materials become useful additions to a campsite.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97920-7b879f20967eece84b92/1-0000.mp3", duration = 37.7730612, start = 0},
  },
}
P.transport["quest:97957"] = {
  hash = "924070",
  fullHash = "924070",
  text = "Camping 101: Herbalism. Camping 101: Herbalism directs budding herbalists to local profession trainers across Azeroth, such as Faruza in Brill, to master the craft of Incense Candles. These aromatic creations provide vital restorative aid to spellcasters resting in wilderness camps. While herbalism is commonly seen as the groundwork for alchemy, practical field survival relies just as heavily on gathered roots and blossoms. Experienced travelers point aspiring foragers toward regional master herbalists to learn how to prepare Incense Candles. In the Tirisfal Glades, Eleanor Shackleton directs promising foragers to visit Faruza in Brill once they demonstrate fundamental skill. Life on the road takes a heavy mental toll on spellcasters and spiritualists. Incense Candles release restorative fragrances meant to lift spirits and soothe weary minds. By infusing dried plants into candles, gatherers provide crucial aid to the healers and mages whose magical reserves falter during extended travel.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97957-b3bb8e3ccd2dad56c144/1-0000.mp3", duration = 58.4620408, start = 0},
  },
}
P.transport["quest:97960"] = {
  hash = "6bf4ad",
  fullHash = "6bf4ad",
  text = "Camping 101: Skinning. Camping 101: Skinning is an introductory wilderness instruction given to novice gatherers in Tirisfal Glades and across Azeroth. It directs skinners who have practiced their trade to regional craftsmen to learn how to fashion a durable camp chair out of harvested hides. Survival in the wilds demands more than a sharp blade; it requires knowing how to husband your strength between trials. Adventurers like Eleanor Shackleton emphasize that harvesting beast pelts provides more than raw trade goods. By developing basic field proficiency, skinners can fashion essential camp comforts like chairs out of treated skins, allowing weary wanderers to rest and recover properly before their next perilous encounter. In Tirisfal Glades, young Forsaken skinners who reach initial competency are pointed toward Rand Rhobart, who plies his trade along the road linking Brill to the Capital ruins of the Undercity. Rhobart shares practical techniques for turning rough leather into functional campsite seating, an art mirrored by skinning masters throughout the lands of both the Horde and the Alliance.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_97960-82c975708c27e09497b0/1-0000.mp3", duration = 60.4734694, start = 0},
  },
}
P.transport["quest:982"] = {
  hash = "293126",
  fullHash = "293126",
  text = "Deep Ocean, Vast Sea. North of Auberdine, the Silver Dawning and Mist Veil lie beneath the waves. Murlocs ambushed both night elf vessels as they sailed into port, and their surviving crews seek a way to mourn their lost captains. Murlocs overwhelmed the Silver Dawning and Mist Veil as the ships approached Auberdine. Both vessels sank in the shallows north of the settlement. Their surviving crews reached shore, but the loss of the ships and their captains weighs on the port. Gorbold Steelhand, a dwarf in Auberdine, seeks to honor the fallen night elf captains. Murlocs now occupy the underwater wrecks, but the captains' lockboxes remain in the flooded holds. Their logs and personal effects could help the surviving sailors mourn their commanders and lay their spirits to rest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_982-13040412df82db195bf3/1-0000.mp3", duration = 45.3746939, start = 0},
  },
}
P.transport["quest:983"] = {
  hash = "affd86",
  fullHash = "affd86",
  text = "Buzzbox 827. Along Darkshore's coast, Buzzbox 827 waits silent for repairs. Wizbang Cranktoggle built it as the first of a chain of voice relays, each made to use parts from local wildlife. Restoring it lets Wizbang test his network from Auberdine. In Auberdine, gnomish engineer Wizbang Cranktoggle is trying to bridge Darkshore's wild coast with a chain of voice relays called Buzzboxes. Their levers and gears carry speech across great distances, a sharp contrast with the ancient ruins and somber forests around them. The machines break down often, and each needs constant care to keep working. Buzzbox 827 lies on the misty shore just south of Auberdine. Wizbang built each relay to use parts from nearby wildlife, so repairs do not depend on carrying refined iron gears and copper pins through the wilderness. This unit takes the sturdy, jointed legs of local tide and reef crawlers. Put the legs in its receiver hopper, and the machine assembles itself and carries Wizbang's voice through its speakers.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_983-daddce493fc5ec9c062d/1-0000.mp3", duration = 65.28, start = 0},
  },
}
P.transport["quest:98389"] = {
  hash = "27397f",
  fullHash = "27397f",
  text = "A Light in the Darkness. Offered by Aramis Hammerhand in Deathknell, this quest tasks Forsaken adventurers with rescuing newly raised undead trapped in Night's Web Hollow. It highlights the delicate relationship between undead wielders of the Holy Light and a populace that deeply distrusts them. By aiding their fallen kin, these holy practitioners hope to prove their loyalty to Sylvanas and the Forsaken cause. The Holy Light is notoriously agonizing and hazardous to the undead, yet some Forsaken retain their connection to the sacred magic they wielded in life. In Deathknell, figures like Aramis Hammerhand strive to demonstrate that their faith has not turned them against their people. To combat the suspicion that holy practitioners will turn on other undead as monstrosities, they actively use their abilities and compassion to safeguard their kin. Northwest of Deathknell lies Night's Web Hollow, a dank cavern crawling with vicious spiders. Freshly raised undead, still disoriented by their awakening and lacking the wits to defend themselves, frequently stumble into the hollow and end up cocooned in sticky webbing. Rescuing these unfortunate Forsaken serves a dual purpose: saving new recruits for the Dark Lady and proving to leaders like Executor Arren that practitioners of the Light are devoted servants of the Forsaken.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98389-be8303e1cbb7f7722fb3/1-0000.mp3", duration = 73.9004082, start = 0},
  },
}
P.transport["quest:984"] = {
  hash = "8e1498",
  fullHash = "8e1498",
  text = "How Big a Threat?. Terenthis asks scouts in Auberdine to learn whether furbolg corruption has reached Darkshore. After madness takes hold among furbolgs in Teldrassil, the night elf druid sends them to inspect mainland settlements across the sea. Night elves across northern Kalimdor have long lived peacefully with the furbolg tribes. Since the Third War, strange corruption has unhinged furbolg minds in Teldrassil. They have kidnapped and attacked their former allies. Terenthis, a druid stationed in Auberdine, fears the affliction has spread beyond the World Tree to the mainland tribes along Darkshore’s coast.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_984-2eb5c3d953dcc45162e5/1-0000.mp3", duration = 34.0114286, start = 0},
  },
}
P.transport["quest:985"] = {
  hash = "cfd0d7",
  fullHash = "cfd0d7",
  text = "How Big a Threat?. Terenthis in Auberdine sends you against the Blackwood furbolgs south of town. Their corrupted camp threatens the settlement, and the Sentinels want its pathfinders and windtalkers culled. The Sentinels see the Blackwood furbolgs as an immediate danger to Darkshore’s refugees and defenders. After you scout south of Auberdine, Terenthis sends you to strike their camp. Killing Blackwood Pathfinders and Windtalkers may break their attack before it reaches the settlement. Night elves have long regarded furbolgs as spiritual kin and allies of the wilderness. Fel moss and demonic taint have spread across northern Kalimdor, driving the Blackwood tribe mad. No known remedy can restore their minds, so Auberdine’s defenders see a grim choice: stop them before innocent people die.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_985-958776f88ae789ba6371/1-0000.mp3", duration = 44.9828571, start = 0},
  },
}
P.transport["quest:98576"] = {
  hash = "602467",
  fullHash = "602467",
  text = "Glyphic Parchment. In the Valley of Trials, Glyphic Parchment points young mages toward their first lessons. Gornek delivers the runed notice, which sends them to Mai'ah near the Den to begin learning the arcane. New recruits test their strength against Durotar's local pests, but those drawn to magic need more than brute force. Gornek passes along a notice marked with runes. It directs novice spellcasters to Mai'ah, who guides the Horde's newest recruits through their first lessons in magic. Mai'ah waits just outside the Den, where she teaches young spellweavers to temper ambition with patience and thought. She urges them to choose their moment instead of hurling raw sorcery without care. In her lessons, novices learn to weave delicate strands of the cosmos rather than unleash an unruly tempest.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98576-ef4a15d8878b5894df38/1-0000.mp3", duration = 46.1061224, start = 0},
  },
}
P.transport["quest:98601"] = {
  hash = "4ced59",
  fullHash = "4ced59",
  text = "A Difficult Path. A Difficult Path marks the formal beginning of a Forsaken paladin's training in Deathknell. After dealing with the mindless undead rising from the crypts, newly awakened champions of the Light are directed to Aramis Hammerhand within the village church to confront the agonizing reality of wielding holy energy in undeath. When a freshly awakened Forsaken paladin finishes culling the feral undead outside the crypt, Shadow Priest Sarvis hands over an unexpected delivery. The Consecrated Scroll radiates holy energy so intensely that the shadow priest visibly recoils, bluntly asking the bearer to step aside. To a practitioner of shadow and decay, the very aura of the Holy Light feels like an open flame. Inside the desecrated church of Deathknell awaits Aramis Hammerhand, the Forsaken paladin trainer. Where other races wield the Light naturally and joyfully, undead who call upon it endure searing, visceral agony. Aramis makes no attempt to soften the blow: channeling holy power through a rotting vessel is sheer torment, but he demands his disciples embrace the pain rather than flinch away, using it as a crucible to temper their newfound resolve.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_98601-0e2f61a140d4fda59068/1-0000.mp3", duration = 67.7616327, start = 0},
  },
}
P.transport["quest:99"] = {
  hash = "3b3331",
  fullHash = "3b3331",
  text = "Arugal's Folly. Arugal's Folly culminates in a dangerous investigation into the curse gripping Pyrewood Village. Dalar Dawnweaver tasks Horde operatives with obtaining enchanted shackles from the villagers to decode Archmage Arugal's twisted handiwork. Unraveling these bindings exposes the tragic magic holding the settlement under the shadow of the worgen. South of the Sepulcher lies Pyrewood Village, a settlement caught in an uncanny state of existence. Under the daylight sun, its residents go about their lives as ordinary human peasants, fearful and insular. Yet as twilight falls over the forest, their human forms tear apart into savage Moonrage worgen, roaming the streets under Arugal's sway. Dalar Dawnweaver seeks to unravel the exact arcane bindings causing this diurnal horror.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99-1b01590e46be032428cb/1-0000.mp3", duration = 47.3861224, start = 0},
  },
}
P.transport["quest:99134"] = {
  hash = "9521ca",
  fullHash = "9521ca",
  text = "Discipline. Discipline is a task issued by Executor Zygand in Tirisfal Glades. Unimpressed by the competence of the local Deathguard garrison, Zygand commissions outside adventurers to administer physical punishment to slackening undead sentries. The Deathguard form the military spine of the Forsaken across Lordaeron, but freedom from the Lich King's iron will brings its own complications: apathy, fatigue, and negligence. Taskmasters like Executor Zygand have little patience for slackening discipline, especially with threats from the Scarlet Crusade and Scourge prowling Tirisfal's borders. To keep the troops sharp, officers rely on blunt instruments and aggressive oversight to maintain military readiness. Executor Zygand deliberately employs independent operators rather than ranks from within the garrison to administer his punishments. Using the Executor's Motivator, outsiders remind negligent Deathguards that survival in service to the Dark Lady requires absolute vigilance. Those who fail in their duties quickly learn that unlife offers no shelter from consequence.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99134-4df08b1f5ef96d2804b4/1-0000.mp3", duration = 62.72, start = 0},
  },
}
P.transport["quest:99141"] = {
  hash = "f85e1b",
  fullHash = "f85e1b",
  text = "Patience. Patience is a task assigned by Executor Zygand in Tirisfal Glades, demanding strict military accountability for the Dark Lady. With routine field reports overdue, Zygand dispatches an adventurer to collect updates from nearby Deathguards and an unusual sentry. The assignment highlights the rigorous, uncompromising discipline enforced across Forsaken holdings. Executor Zygand holds command over local security in Tirisfal Glades and tolerates no lapses in vigilance. To Zygand, serving Lady Sylvanas requires nothing less than absolute efficiency. When regular field dispatches fail to arrive at his post on schedule, he sees it as an unacceptable breach of duty rather than a minor delay. Rather than abandon his post to investigate, he sends incoming Forsaken agents to rein in delinquent subordinates and ensure that the borders remain secure. The dispatches involve sentries stationed at critical vantage points surrounding Brill. Deathguard Dillinger keeps watch over the graveyard to the west, where rogue undead and Scourge remnants often stir. To the east, Deathguard Kristof oversees a waystation guarding the approaches to the Capital City and the eastern roads. Most unusual among them is Gordo, a hulking abomination wandering near Stillwater Pond whose simple mind makes military record-keeping a deeply dubious expectation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99141-48e540c85f420baea124/1-0000.mp3", duration = 79.7518367, start = 0},
  },
}
P.transport["quest:99142"] = {
  hash = "fb1f0e",
  fullHash = "fb1f0e",
  text = "Tomb Weed. Tomb Weed is an alchemical quest assigned by Junior Apothecary Holland in Tirisfal Glades. Holland has been modifying wild doom weed and replanting it at the haunted Balnir Farmstead, cultivating a potent new specimen that unexpectedly attracts the local Scourge. Junior Apothecary Holland is not content simply harvesting native herbs for the Royal Apothecary Society; he harbors grand ambitions of his own. By gathering doom weed and subjecting it to minor alchemical alterations, he replanted the strains across the soil of the Balnir Farmstead to cultivate an evolved specimen he christened tomb weed. Holland views this hybrid flora as the centerpiece of his work and a herald of his personal destiny. While Holland anticipated alchemical potency, the transplanting of tomb weed into the Balnir Farmstead yielded an unforeseen side effect. The wandering Scourge remnants infesting the blighted fields have shown an uncanny, pervasive attraction to the burgeoning flora. Holland relies on passing travelers to push past these encroaching undead and harvest the matured crop so he can continue his experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99142-d80823a613aede112c9a/1-0000.mp3", duration = 64.8620408, start = 0},
  },
}
P.transport["quest:99156"] = {
  hash = "a14c15",
  fullHash = "a14c15",
  text = "Rear Guard Patrol. Rear Guard Patrol is a critical defense assignment given by Deathguard Linnea in Tirisfal Glades. Rather than fighting off mere wandering ghouls, patrollers are tasked with hunting down Riptear, an abomination roaming near Venomweb Vale that should never have made it past the Bulwark. The Bulwark stands as the sole fortified barrier separating Tirisfal Glades from the horrors of the Western Plaguelands. The strategy of the Forsaken military hinges upon a strictly one-front war. If mindless undead slip behind the lines, the supply routes feeding the front can be strangled in an instant. While stray spirits or ghouls occasionally bypass the barricades, reports of an abomination roaming the glades signal a severe failure of containment.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_99156-d1e9e2db8eaf1c5a3357/1-0000.mp3", duration = 41.8481633, start = 0},
  },
}
P.transport["quest:997"] = {
  hash = "96ea65",
  fullHash = "96ea65",
  text = "Denalan's Earth. In Dolanaar, Syral Bladeleaf sends a late shipment of rare earth south to Denalan at Lake Al'Ameth. The night elf researcher studies Teldrassil's young plants. Syral Bladeleaf stops travelers in Dolanaar with a special shipment of rare earth for Denalan. The soil came from Darnassus to support his botanical studies, but delays kept it from reaching Dolanaar until now. Syral seeks a courier to carry the parcel south along the forest trail to Denalan's campsite by Lake Al'Ameth. Denalan works alone at a station on Lake Al'Ameth's eastern shore, watching Teldrassil's young ecosystem take root. The tree grew quickly after the Battle of Mount Hyjal, and its plants behave in unexpected ways. Denalan tests the vitality and behavior of timberlings and native plants with unique soil mixtures and specimens. The rare earth shipment will support those experiments.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_997-0f43b446261e5e198237/1-0000.mp3", duration = 50.4946939, start = 0},
  },
}
P.transport["quest:cutting-teeth"] = {
  hash = "90fcee",
  fullHash = "90fcee",
  text = "Cutting Teeth. In the Valley of Trials, fresh recruits face a first test against mottled boars. Overseer Gornek sends aspiring warriors and spellcasters to thin the boars around the cactus dirt farms, where they can prove their fighting skill and readiness to serve the Horde. The Valley of Trials leaves little room for grand dreams. Young recruits may imagine hunting great beasts in the Barrens or winning glory on a battlefield, but overseer Gornek begins with the farms. Thinning the mottled boars is a grounded test of a recruit’s first skills with a weapon or spell. It shows whether they can face a wild attacker and have the sense to survive their first skirmish. Feral swine roam the red desert settlement’s dirt farms north and northeast of camp. They root through cactus patches and threaten the few supplies grown in Durotar’s harsh soil. Sending aspirants to clear them keeps local pests in check while shaping young orcs and trolls into defenders of the new nation.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_cutting-teeth-0da4ee99837d7008d764/1-0000.mp3", duration = 56.32, start = 0},
  },
}
P.transport["quest:galgar-s-cactus-apple-surprise"] = {
  hash = "ce8bc1",
  fullHash = "ce8bc1",
  text = "Galgar's Cactus Apple Surprise. In the Valley of Trials, Galgar sends fresh recruits to gather cactus apples for his cooling treat. The work teaches them to forage and survive in Durotar's arid land. Young orcs and Darkspear trolls take their first steps as defenders of the Horde in the Valley of Trials. Combat drills and fierce trials against native beasts quickly bring exhaustion and thirst. Learning to live off the land matters as much as learning to swing an axe. Cacti across the valley bear ripe, water-rich apples that offer relief from the desert sun. Galgar tends his cooking in the training grounds, where he has made an art of foraging. His Cactus Apple Surprise is known among the valley's people for cooling a person faster than a plunge into river water. He sends eager recruits to gather prickly fruit from nearby cacti, keeping his kitchen stocked and ensuring new wanderers do not set out into Durotar hungry.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_galgar-s-cactus-apple-surprise-67196681e330cf03c338/1-0000.mp3", duration = 50.155102, start = 0},
  },
}
P.transport["quest:lazy-peons"] = {
  hash = "2c051e",
  fullHash = "2c051e",
  text = "Lazy Peons. Foreman Thazz'ril sends new Horde recruits across the Valley of Trials to wake sleeping peons. Their work keeps lumber moving to Durotar's settlements. Durotar's new homes need timber, stone, and hard labor. Peons, orcs with little skill in battle, carry much of that burden and keep the Horde supplied with workers. In the Valley of Trials, the heat and grueling work leave Foreman Thazz'ril's crews seeking shade beneath trees for unauthorized naps. Foreman Thazz'ril gives new Horde recruits his blackjack and sends them across the valley to wake the sleeping workers. The startled peons return to chopping wood, keeping lumber flowing for Durotar's survival.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_lazy-peons-e1f4549ed07a7a356cd0/1-0000.mp3", duration = 38.9746939, start = 0},
  },
}
P.transport["quest:sarkoth"] = {
  hash = "1f82b8",
  fullHash = "1f82b8",
  text = "Sarkoth. On a southern plateau in the Valley of Trials, Sarkoth has left a young Darkspear hunter near death. Wounded beneath a tree, Hana'zua asks a passing warrior to kill the scorpid and bring back its mangled claw, so his last strike will count for something. In the Valley of Trials, the Horde tests aspiring warriors against Durotar's harsh desert. While hunting the valley's venomous creatures, young troll scout Hana'zua met a scorpid far larger and deadlier than the rest. He struck hard enough to mangle one pincer, but Sarkoth drove its tail into his chest. Now Hana'zua bleeds in the red dirt, fearing his life is near its end. He wants the beast dead before it can outlive him. Sarkoth roams a high mesa above the southern Valley of Trials. Hana'zua's blow left one claw shattered, but the scorpid still rules the ridge and attacks anyone who climbs the rocky path. Bring the scarred claw back to the wounded scout, and he will have proof that his last strike weakened the monster enough for someone to bring it down.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_sarkoth-20060013096d74538276/1-0000.mp3", duration = 60.1077551, start = 0},
  },
}
P.transport["quest:your-place-in-the-world"] = {
  hash = "443855",
  fullHash = "443855",
  text = "Your Place In The World. In the Valley of Trials, untested recruits take their first steps toward honor and survival in Durotar. Kaltunk sends them straight to Gornek for basic combat training, beginning their service to the Horde. In Durotar's arid Valley of Trials, young orcs and Darkspear trolls prove their worth before entering the wider world. Under Warchief Thrall, life demands strength, vigilance, and discipline. Kaltunk evaluates every eager recruit, tempering dreams of wrestling demons and dragons with the practical duties ahead. Training begins in the canyon, where recruits learn humility before claiming glory. Gornek waits beside the camp fire, only steps away from Kaltunk. The gruff veteran regards fresh arrivals with a skeptical eye and often grumbles about the meager stock reaching camp. His duty is to harden these young fighters through trials, starting with the vermin that threaten the encampment's supplies.",
  ["1"] = {
    {file = "Audio/Transport/full_quest_your-place-in-the-world-1ef823643435b6a7deea/1-0000.mp3", duration = 55.04, start = 0},
  },
}
